# ⚡ DEVICE HARDWARE AUTO-DETECTION & SYSTEM AUTO-TUNING ENGINE
# ═══════════════════════════════════════════════════════════════════════════

class DeviceScanner:
    """Probes local hardware (GPU, VRAM, RAM, CPU, Disk) and calculates auto-tuned studio profiles."""

    @staticmethod
    def scan():
        # v7.1: platform/shutil were referenced below but never imported
        # anywhere in this file - this class would raise NameError on
        # its very first two lines the moment anything ever called
        # scan() (currently unreachable - no menu/button wires to
        # open_device_autotune_dialog yet, so this had never actually
        # been exercised). Local imports here match this file's existing
        # lazy-import convention (see numpy/PIL usage throughout).
        import platform
        import shutil
        info = {
            "os": f"{platform.system()} {platform.release()}",
            "cpu_cores": os.cpu_count() or 4,
            "ram_gb": 16.0,
            "disk_free_gb": 50.0,
            "gpu_name": "Generic GPU / CPU Fallback",
            "vram_gb": 0.0,
            "cuda_available": False,
            "compute_cap": "N/A",
            "fp16_supported": False
        }

        # System RAM
        try:
            import psutil
            info["ram_gb"] = round(psutil.virtual_memory().total / (1024**3), 1)
        except Exception: pass

        # Free Disk Space
        try:
            info["disk_free_gb"] = round(shutil.disk_usage(".").free / (1024**3), 1)
        except Exception: pass

        # v7.1: removed a torch-based CUDA probe that used to sit here
        # (`import torch; torch.cuda.is_available()/get_device_name/...`).
        # PyInstaller's static analysis bundles the full torch+CUDA
        # runtime for ANY reachable `import torch`, regardless of
        # whether it's ever actually executed - this alone ballooned the
        # shipped exe from ~78MB to ~2.9GB (the same class of bug fixed
        # once already this session for core/hardware_scanner.py). The
        # nvidia-smi fallback immediately below already reports the same
        # gpu_name/vram_gb/cuda_available/fp16_supported fields via a
        # plain subprocess call, so nothing is lost except compute_cap
        # (left as "N/A", matching this function's own default).

        # GPU probing via nvidia-smi
        if not info["cuda_available"] or info["vram_gb"] == 0:
            try:
                out = subprocess.check_output(
                    ["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader,nounits"],
                    encoding="utf-8", timeout=3
                ).strip()
                if out:
                    parts = out.split(",")
                    if len(parts) >= 2:
                        info["gpu_name"] = parts[0].strip()
                        info["vram_gb"] = round(float(parts[1].strip()) / 1024, 2)
                        info["cuda_available"] = True
                        info["fp16_supported"] = True
            except Exception: pass

        # Calculate Recommended Profile Tier
        vram = info["vram_gb"]
        if vram >= 15.5:
            info["tier"] = "Ultra High VRAM (24GB+ Class)"
            info["recommended_profile"] = {
                "profile_name": "🚀 Ultra Quality (FP32 + Tiled Upscale)",
                "batch_size": 2,
                "default_width": 1216,
                "default_height": 1216,
                "steps": 28,
                "cfg": 7.5,
                "gpu_profile": "Ultra Quality (FP32 + Tiling)",
                "quality_boost": "Auto-Harmonize (Recommended)",
                "freeu_enabled": True,
                "ollama_recommendation": "qwen2.5-abliterate:7b"
            }
        elif vram >= 7.5:
            info["tier"] = "Balanced Mid VRAM (8GB - 12GB)"
            info["recommended_profile"] = {
                "profile_name": "⚡ Balanced Performance (FP16)",
                "batch_size": 1,
                "default_width": 1024,
                "default_height": 1024,
                "steps": 22,
                "cfg": 7.0,
                "gpu_profile": "Balanced (Default)",
                "quality_boost": "Auto-Harmonize (Recommended)",
                "freeu_enabled": True,
                "ollama_recommendation": "mlabonne_gemma-3-4b-it-abliterated"
            }
        else:
            info["tier"] = "Speed / Low VRAM (< 8GB)"
            info["recommended_profile"] = {
                "profile_name": "🏎️ Speed Demon (Low-VRAM Guard)",
                "batch_size": 1,
                "default_width": 832,
                "default_height": 1216,
                "steps": 16,
                "cfg": 6.5,
                "gpu_profile": "Speed Demon (FP16)",
                "quality_boost": "Disabled",
                "freeu_enabled": False,
                "ollama_recommendation": "mlabonne_gemma-3-4b-it-abliterated"
            }

        return info


