# 🎨 DYNAMIC LOCAL THEMES & ANALYTICS TRACKER
# ═══════════════════════════════════════════════════════════════════════════

class LocalAnalyticsTracker:
    """Manages offline studio analytics and generation telemetry locally."""
    def __init__(self, data_file="analytics_history.json"):
        self.data_file = Path(data_file)
        self.data = self._load()

    def _load(self):
        if self.data_file.exists():
            try:
                with open(self.data_file, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception: pass
        return {
            "total_generations": 0,
            "total_runtime_sec": 0.0,
            "top_personas": {},
            "top_styles": {},
            "top_models": {},
            "quality_scores": [],
            "history": []
        }

    def save(self):
        try:
            with open(self.data_file, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2)
        except Exception: pass

    def record_generation(self, persona: str, style: str, model: str, runtime: float, quality_score: float = 0.0):
        self.data["total_generations"] += 1
        self.data["total_runtime_sec"] += round(runtime, 2)
        
        if persona:
            self.data["top_personas"][persona] = self.data["top_personas"].get(persona, 0) + 1
        if style:
            self.data["top_styles"][style] = self.data["top_styles"].get(style, 0) + 1
        if model:
            self.data["top_models"][model] = self.data["top_models"].get(model, 0) + 1
        if quality_score > 0:
            self.data["quality_scores"].append(round(quality_score, 1))

        self.data["history"].append({
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "persona": persona,
            "style": style,
            "model": model,
            "runtime": round(runtime, 2),
            "quality": round(quality_score, 1)
        })
        self.save()

    def export_csv(self, export_path: str) -> bool:
        try:
            with open(export_path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(["Timestamp", "Persona", "Style", "Model", "Runtime (s)", "Quality Score"])
                for item in self.data.get("history", []):
                    writer.writerow([
                        item.get("timestamp", ""),
                        item.get("persona", ""),
                        item.get("style", ""),
                        item.get("model", ""),
                        item.get("runtime", 0.0),
                        item.get("quality", 0.0)
                    ])
            return True
        except Exception:
            return False

