# ── Crash Logging & Error Handling ──────────────────────────────────────────
def get_crash_log_path():
    return app_dir() / "crash.log"


def log_crash(exc_type, exc_value, exc_traceback):
    """Log crash to file for debugging."""
    try:
        crash_log = get_crash_log_path()
        with open(crash_log, "a", encoding="utf-8") as f:
            f.write(f"\n{'='*60}\n")
            f.write(f"Crash: {datetime.now()}\n")
            f.write(f"{'='*60}\n")
            f.write("".join(traceback.format_exception(exc_type, exc_value, exc_traceback)))
            f.write("\n")
    except Exception:
        pass


# v8.7: self-healing bad-checkpoint blocklist. _is_not_a_checkpoint's
# hardcoded substring list only catches junk files known at the time it
# was written - a genuinely new one (e.g. a corrupt download, an odd
# LoRA/embedding someone dropped in checkpoints/) still slips through
# and aborts ~1/5 generations on whichever machine happens to have it,
# exactly as documented in that function. Rather than requiring another
# manual substring added per new junk file per machine, any checkpoint
# that ComfyUI itself reports as unloadable ("Could not detect model
# type of: X") gets persisted to bad_checkpoints.json (self-creating,
# next to the exe) and is never auto-picked again - this is what makes
# the fix actually portable to a machine I've never seen the model
# folder of.
_BAD_CHECKPOINTS_CACHE = None


def _bad_checkpoints_path() -> Path:
    return app_dir() / "bad_checkpoints.json"


def _load_bad_checkpoints() -> set:
    global _BAD_CHECKPOINTS_CACHE
    if _BAD_CHECKPOINTS_CACHE is None:
        data = safe_json_load(_bad_checkpoints_path(), [])
        _BAD_CHECKPOINTS_CACHE = set(data) if isinstance(data, list) else set()
    return _BAD_CHECKPOINTS_CACHE


def _mark_checkpoint_bad(name: str, log=None):
    bad = _load_bad_checkpoints()
    if name in bad:
        return
    bad.add(name)
    safe_json_save(_bad_checkpoints_path(), sorted(bad))
    (log or print)(f"⚠️ Blocklisted unloadable checkpoint file: {name} "
                   "(not a real SD checkpoint - won't be auto-picked "
                   "again on this machine)")


_BAD_CHECKPOINT_RE = re.compile(
    r"could not detect model type of:\s*([^\s,'\"]+\.(?:safetensors|ckpt|pt))",
    re.IGNORECASE)


def _detect_and_mark_bad_checkpoint(err_str: str, log=None) -> bool:
    """v10.1: same regex-detection _queue_and_wait_impl already uses,
    factored out so the several call sites that talk to ComfyUI directly
    (bypassing that wrapper - Remix, best-of-N's _gen_one, etc.) can also
    self-heal instead of silently never blocklisting a bad checkpoint
    file they hit. Returns True if a checkpoint was newly blocklisted."""
    m = _BAD_CHECKPOINT_RE.search(err_str)
    if not m:
        return False
    _mark_checkpoint_bad(Path(m.group(1)).name, log=log)
    return True


def safe_json_load(path, default=None):
    """Safely load JSON with graceful fallback."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except json.JSONDecodeError:
        return default if default is not None else {}
    except FileNotFoundError:
        return default if default is not None else {}
    except Exception:
        return default if default is not None else {}


def safe_json_save(path, data):
    """Safely save JSON with error handling."""
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        return True
    except Exception:
        return False
CANDIDATE_PORTS = [8188, 8189, 8190, 8191, 8000, 8080, 7860, 9000, 8888]  # candidate standalone, desktop, & remote ports
def _find_comfy_desktop() -> str:
    """Locate the Comfy Desktop executable on THIS machine.

    v7.0: this was a hardcoded C:\\Users\\phase\\... literal. Every use is
    guarded by .exists(), so it degraded safely elsewhere - but that
    meant ComfyUI auto-launch and the crash self-heal silently never
    fired on any machine but the original dev box. Resolve it from the
    real environment instead, keeping the original path as the last
    fallback so behaviour here is unchanged."""
    rel = r"Programs\Comfy Desktop\Comfy Desktop.exe"
    for base in (os.environ.get("LOCALAPPDATA"),
                 os.environ.get("PROGRAMFILES"),
                 os.environ.get("PROGRAMFILES(X86)")):
        if base:
            candidate = Path(base) / rel
            if candidate.exists():
                return str(candidate)
    # Nothing found - return the conventional LOCALAPPDATA location so
    # the .exists() guards at the call sites still read false cleanly.
    base = os.environ.get("LOCALAPPDATA")
    if base:
        return str(Path(base) / rel)
    return r"C:\Users\phase\AppData\Local\Programs\Comfy Desktop\Comfy Desktop.exe"


COMFY_DESKTOP_EXE = _find_comfy_desktop()


def _find_comfyui_venv_python() -> str:
    """v9.5: locates ComfyUI Desktop's own Python venv (which already
    has torch+CUDA installed for running SDXL) - reused by the AnimeGAN
    photo-to-anime feature so THIS app's own process/PyInstaller build
    never needs to import torch itself (a documented constraint - see
    DeviceScanner's nvidia-smi-not-torch comment - any reachable `import
    torch` here would balloon the exe from ~80MB to ~2.9GB).

    The per-install folder name (e.g. "3k") is chosen by the user at
    ComfyUI Desktop install time, so unlike COMFY_DESKTOP_EXE this can't
    be a fixed relative path - glob for whichever install(s) exist and
    take the first with a real venv. Returns "" if none found (callers
    must guard with a truthiness/exists check, same convention as
    COMFY_DESKTOP_EXE)."""
    base = os.environ.get("LOCALAPPDATA")
    if not base:
        return ""
    try:
        matches = sorted(Path(base).glob(
            "Comfy-Desktop/ComfyUI-Installs/*/ComfyUI/.venv/Scripts/python.exe"))
        return str(matches[0]) if matches else ""
    except Exception:
        return ""


COMFYUI_VENV_PYTHON = _find_comfyui_venv_python()

