# ── FutureProofingEngine (v3.3) ─────────────────────────────────────────────
class FutureProofingEngine:
    """Self-healing, forward-compatible environment manager and auto-discovery engine.
    Ensures zero-breakage on model directory changes, API schema shifts, or corrupted configs."""
    
    @staticmethod
    def auto_discover_models(comfy_dir: Path) -> dict:
        """Dynamically scans local ComfyUI folders to discover newly added models on-the-fly."""
        discovered = {"checkpoints": [], "loras": [], "vaes": []}
        if not comfy_dir or not comfy_dir.exists():
            return discovered
            
        ckpt_dir = comfy_dir / "models" / "checkpoints"
        lora_dir = comfy_dir / "models" / "loras"
        
        if ckpt_dir.exists():
            discovered["checkpoints"] = [
                f.name for f in ckpt_dir.glob("*.*") 
                if f.suffix.lower() in [".safetensors", ".ckpt"]
            ]
        if lora_dir.exists():
            discovered["loras"] = [
                f.name for f in lora_dir.glob("*.*") 
                if f.suffix.lower() in [".safetensors", ".ckpt"]
            ]
        return discovered

    @staticmethod
    def sanitize_prompt(prompt: str) -> str:
        """Future-proofs prompt syntax by normalizing quotes, whitespace, and bracket weights."""
        if not prompt:
            return ""
        p = prompt.replace("“", '"').replace("”", '"').replace("’", "'")
        p = re.sub(r'\s+', ' ', p).strip()
        return p

    @staticmethod
    def verify_and_repair_configs():
        """Verifies JSON databases exist and are valid; recreates emergency fallbacks if corrupted."""
        # v7.2: two compounding bugs here silently destroyed the entire
        # 1361-persona list (and style_presets.json) on first launch of
        # a fresh dist/ folder - this is what "we are missing the entire
        # persona list" traced back to.
        #
        # 1. `Path(fn)` is relative to the process's CURRENT WORKING
        #    DIRECTORY, not the exe's own directory - unlike every other
        #    file access in this app, which correctly uses app_dir().
        #    Depending on how the exe is launched (double-click,
        #    shortcut, a different starting folder), this could resolve
        #    almost anywhere.
        # 2. `not p.exists()` was treated as "corrupted, needs repair" -
        #    but a brand-new dist/ folder legitimately has NO external
        #    personas.json next to the exe on first run; the real 1361
        #    personas ship bundled INSIDE the exe, reached via
        #    resource_path()'s fallback. This function ran at MODULE
        #    IMPORT TIME, before anything else, and wrote a bare "{}"
        #    the instant it saw that normal, expected absence - creating
        #    a bogus external file that resource_path() then preferred
        #    over the bundled data FOREVER after, since resource_path()
        #    always prefers an external (user-editable) file over the
        #    bundled fallback.
        #
        # Fixed: resolve the same way app_dir() does elsewhere in this
        # file, and only actually repair a file that EXISTS but is too
        # small to be real data (genuine corruption/truncated write) -
        # never treat simple absence as corruption when a bundled
        # fallback exists. Resolved inline rather than calling app_dir()
        # directly: this staticmethod runs at MODULE IMPORT time (see
        # the call site right below this class), which is line ~511 -
        # long before app_dir()'s own def at line ~954 - so calling it
        # here would raise NameError and crash the app before it even
        # reached main().
        try:
            base = Path(sys.executable).parent if getattr(sys, "frozen", False) \
                else Path(__file__).parent
        except NameError:
            base = Path.cwd()
        for fn in ["personas.json", "style_presets.json", "wildcards.json"]:
            p = base / fn
            if p.exists() and p.stat().st_size < 10:
                p.write_text("{}", encoding="utf-8")
                print(f"FutureProofingEngine: Repaired corrupted {fn}")

# Run initial verification on module import
FutureProofingEngine.verify_and_repair_configs()

# ── SmartPromptDoctor & AITasteLearner (v3.4 Smart Upgrades) ───────────────
class SmartPromptDoctor:
    """Intelligent prompt analyzer that detects conflicting tags and optimizes prompt structure."""
    
    CONFLICTING_PAIRS = [
        ("photorealistic", "cel shading"),
        ("monochrome", "vibrant colors"),
        ("dark atmosphere", "bright sunny day"),
        ("3d render", "2d linework"),
    ]

    @classmethod
    def optimize(cls, positive_prompt: str) -> str:
        """Analyzes prompt for conflicts and injects high-impact quality boosters."""
        if not positive_prompt:
            return positive_prompt
            
        p_lower = positive_prompt.lower()
        cleaned = positive_prompt
        
        for c1, c2 in cls.CONFLICTING_PAIRS:
            if c1 in p_lower and c2 in p_lower:
                cleaned = cleaned.replace(c2, "")
                
        # Inject master detail boosters if missing
        boosters = ["masterpiece", "best quality", "highly detailed"]
        missing = [b for b in boosters if b not in p_lower]
        if missing:
            cleaned = f"{', '.join(missing)}, {cleaned}"
            
        return re.sub(r',\s*,', ',', cleaned).strip()


