def _pick_artist_influences(style: str, n: int = 2) -> str:
    """v9.12: keyword-matches `style` against ARTIST_INFLUENCES' bucket
    names/content, returns a comma-joined string of `n` picked artist
    tags. Falls back to a broad mixed pool when nothing matches, so this
    never returns empty."""
    s = style.lower()
    bucket_keywords = {
        "anime": ("anime", "shonen", "shoujo", "cel-shaded", "chibi",
                 "studio", "kyoto", "trigger", "mappa", "bones",
                 "cloverworks"),
        "manga_comic": ("manga", "comic", "superhero", "graphic novel",
                       "noir", "panel"),
        "painterly_classical": ("oil painting", "baroque", "portraiture",
                                "classical", "art nouveau", "renaissance"),
        "fantasy_concept": ("fantasy", "concept art", "tarot", "wuxia",
                            "mythic", "medieval", "epic"),
        "scifi_cyberpunk": ("cyberpunk", "sci-fi", "mecha", "futurism",
                           "y2k", "chrome"),
        "horror_dark": ("horror", "gothic", "eldritch", "cosmic horror",
                        "body horror", "psychological"),
        "photorealistic": ("photorealistic", "hyperrealistic", "editorial",
                          "studio lighting", "photography", "photo"),
        "graphic_poster": ("poster", "flat design", "graphic", "album cover"),
    }
    matched = [bucket for bucket, kws in bucket_keywords.items()
              if any(kw in s for kw in kws)]
    pool = []
    for bucket in (matched or list(ARTIST_INFLUENCES)):
        pool.extend(ARTIST_INFLUENCES.get(bucket, []))
    if not pool:
        pool = [n for names in ARTIST_INFLUENCES.values() for n in names]
    picked = random.sample(pool, min(n, len(pool)))
    return "in the style of " + ", ".join(picked)

