def app_dir() -> Path:
    """Directory of the exe (frozen) or this script."""
    if getattr(sys, "frozen", False):
        return Path(sys.executable).parent
    try:
        return Path(__file__).parent
    except NameError:
        return Path.cwd()


def resource_path(name: str) -> Path:
    """Prefer a file next to the exe (user-editable), fall back to bundled copy."""
    external = app_dir() / name
    if external.exists():
        return external
    bundled = Path(getattr(sys, "_MEIPASS", app_dir())) / name
    return bundled


