class FavoritesManager:
    """Manage starred personas, sessions, and LoRAs."""

    def __init__(self, data_dir: Path):
        self.path = data_dir / "favorites.json"
        self.data = safe_json_load(self.path, {
            "personas": [],
            "sessions": [],
            "loras": []
        })

    def save(self):
        """Persist favorites to disk."""
        safe_json_save(self.path, self.data)

    def add_persona(self, name: str):
        """Add persona to favorites."""
        if name not in self.data["personas"]:
            self.data["personas"].append(name)
            self.save()

    def remove_persona(self, name: str):
        """Remove persona from favorites."""
        if name in self.data["personas"]:
            self.data["personas"].remove(name)
            self.save()

    def is_persona_favorite(self, name: str) -> bool:
        return name in self.data["personas"]

    def get_personas(self) -> list:
        return self.data.get("personas", [])

    def add_session(self, name: str):
        if name not in self.data["sessions"]:
            self.data["sessions"].append(name)
            self.save()

    def remove_session(self, name: str):
        if name in self.data["sessions"]:
            self.data["sessions"].remove(name)
            self.save()

    def is_session_favorite(self, name: str) -> bool:
        return name in self.data["sessions"]

    def get_sessions(self) -> list:
        return self.data.get("sessions", [])

    def add_lora(self, name: str):
        if name not in self.data["loras"]:
            self.data["loras"].append(name)
            self.save()

    def remove_lora(self, name: str):
        if name in self.data["loras"]:
            self.data["loras"].remove(name)
            self.save()

    def is_lora_favorite(self, name: str) -> bool:
        return name in self.data["loras"]

    def get_loras(self) -> list:
        return self.data.get("loras", [])


class GenerationHistory:
    """Track last N generations for replay."""

    def __init__(self, data_dir: Path, max_history: int = 20):
        self.path = data_dir / "history.json"
        self.max_history = max_history
        self.history = safe_json_load(self.path, [])

    def save(self):
        """Persist history to disk."""
        safe_json_save(self.path, self.history)

    def add(self, state: dict):
        """Add generation state to history (newest first)."""
        self.history.insert(0, {
            "timestamp": datetime.now().isoformat(),
            "state": state
        })
        # Keep only last N entries
        self.history = self.history[:self.max_history]
        self.save()

    def get_all(self) -> list:
        """Return history list with timestamps."""
        return self.history

    def get(self, index: int) -> dict:
        """Get state at history index."""
        if 0 <= index < len(self.history):
            return self.history[index].get("state", {})
        return None

    def clear(self):
        """Clear all history."""
        self.history = []
        self.save()


# ── SPRINT 4: Caching & Performance ──────────────────────────────────────────
class CacheManager:
    """Simple cache for expensive operations."""

    def __init__(self):
        self.cache = {}
        self.timestamps = {}

    def get(self, key: str, max_age_seconds: int = 60) -> any:
        """Get cached value if exists and not expired."""
        if key not in self.cache:
            return None
        import time
        age = time.time() - self.timestamps.get(key, 0)
        if age > max_age_seconds:
            del self.cache[key]
            del self.timestamps[key]
            return None
        return self.cache[key]

    def set(self, key: str, value: any):
        """Set cache value with timestamp."""
        import time
        self.cache[key] = value
        self.timestamps[key] = time.time()

    def invalidate(self, key: str = None):
        """Clear specific or all cache."""
        if key:
            self.cache.pop(key, None)
            self.timestamps.pop(key, None)
        else:
            self.cache.clear()
            self.timestamps.clear()


class BackgroundTask:
    """Wrapper for background operations with error handling."""

    def __init__(self, app_log_func):
        self.log = app_log_func

    def run_safe(self, func, *args, **kwargs):
        """Run function in background with error handling."""
        def wrapper():
            try:
                result = func(*args, **kwargs)
                return result
            except Exception as e:
                self.log(f"Background task error: {e}")
                return None

        thread = threading.Thread(target=wrapper, daemon=True)
        thread.start()
        return thread


class SessionBackup:
    """Auto-backup sessions before destructive operations."""

    def __init__(self, data_dir: Path):
        self.backup_dir = data_dir / "session_backups"
        self.backup_dir.mkdir(parents=True, exist_ok=True)

    def backup_session(self, session_data: dict, name: str) -> bool:
        """Create backup before deletion/modification."""
        try:
            import time
            timestamp = int(time.time())
            backup_path = self.backup_dir / f"{name}_{timestamp}.json"
            safe_json_save(backup_path, session_data)
            return True
        except Exception:
            return False

    def restore_backup(self, name: str) -> dict:
        """Restore from most recent backup."""
        try:
            backups = sorted(self.backup_dir.glob(f"{name}_*.json"), reverse=True)
            if backups:
                return safe_json_load(backups[0])
        except Exception:
            pass
        return None

    def list_backups(self, name: str = None) -> list:
        """List available backups."""
        if name:
            return [f.name for f in self.backup_dir.glob(f"{name}_*.json")]
        return [f.name for f in self.backup_dir.glob("*.json")]

    def clean_old_backups(self, max_backups: int = 10):
        """Keep only recent backups."""
        try:
            all_backups = sorted(self.backup_dir.glob("*.json"), reverse=True)
            for backup in all_backups[max_backups:]:
                backup.unlink()
        except Exception:
            pass


# ── PHASE 2: System Profiling & Quality Orchestration ─────────────────────────
class SystemProfiler:
    """Detect GPU/VRAM/CUDA; recommend optimal hardware-aware profiles and models."""

    def __init__(self, comfy_client=None):
        self.comfy_client = comfy_client
        self.gpu_name = None
        self.vram_gb = None
        self.cuda_enabled = False
        self.cuda_version = None
        self.compute_capability = None
        self.model_registry = {}
        self.style_presets = {}
        self._load_registries()

    def _load_registries(self):
        """Load model and style registries from config files.
        Uses resource_path()/app_dir() (not Path(__file__).parent, which
        resolves inside PyInstaller's temp _MEIPASS extraction dir in a
        frozen build - a real bug found in a full-system audit that made
        these registries silently stay empty in the shipped exe)."""
        for name, attr, key in (
            ("model_registry.json", "model_registry", "models"),
            ("style_presets.json", "style_presets", "styles"),
        ):
            try:
                with open(resource_path(name), "r", encoding="utf-8") as f:
                    setattr(self, attr, json.load(f).get(key, {}))
            except Exception as e:
                print(f"SystemProfiler: could not load {name}: {e}")

    def profile_from_comfyui(self) -> dict:
        """Query ComfyUI's system_stats() to extract GPU/VRAM/CUDA info."""
        if not self.comfy_client:
            return self._fallback_profile()

        try:
            stats = self.comfy_client.system_stats()
            system = stats.get("system", {})

            # Parse GPU info
            devices = system.get("devices", {})
            self.cuda_enabled = devices.get("cuda", {}).get("enabled", False)

            if self.cuda_enabled and devices.get("cuda"):
                gpu_info = devices["cuda"]
                # VRAM in bytes → GB
                vram_bytes = gpu_info.get("vram_total", 0)
                if vram_bytes:
                    self.vram_gb = vram_bytes / (1024 ** 3)
                self.gpu_name = gpu_info.get("name", "NVIDIA GPU")
                self.compute_capability = gpu_info.get("compute_capability")

            # Try to extract CUDA version
            self.cuda_version = system.get("cuda_version")

            # Fallback: parse from device string
            if not self.vram_gb:
                device_info = str(system.get("devices", ""))
                import re as regex_module
                match = regex_module.search(r"(\d+\.?\d*)\s*(?:GB|gb)", device_info)
                if match:
                    self.vram_gb = float(match.group(1))

            return {
                "gpu_name": self.gpu_name or "Unknown GPU",
                "vram_gb": self.vram_gb or 4,
                "cuda_enabled": self.cuda_enabled,
                "cuda_version": self.cuda_version,
                "compute_capability": self.compute_capability,
                "full_stats": system
            }
        except Exception:
            return self._fallback_profile()

    def _fallback_profile(self) -> dict:
        """Return fallback profile when ComfyUI unavailable."""
        return {
            "gpu_name": "Unknown",
            "vram_gb": 4,
            "cuda_enabled": False,
            "cuda_version": None,
            "compute_capability": None,
            "full_stats": {}
            }

    def get_optimal_steps(self, quality_preference: str = "quality") -> int:
        """Suggest step count based on VRAM and quality preference."""
        vram = self.vram_gb or 4
        if quality_preference == "speed":
            return 20
        elif quality_preference == "quality":
            if vram >= 12:
                return 40
            elif vram >= 8:
                return 35
            else:
                return 25
        elif quality_preference == "fidelity":
            if vram >= 16:
                return 50
            elif vram >= 10:
                return 45
            elif vram >= 6:
                return 35
            else:
                return 25
        else:  # showcase / premium
            if vram >= 20:
                return 60
            elif vram >= 12:
                return 55
            elif vram >= 8:
                return 50
            else:
                return 40

    def get_optimal_resolution(self) -> tuple:
        """Suggest resolution based on available VRAM."""
        vram = self.vram_gb or 4
        if vram >= 16:
            return (1216, 1216)  # high-end: max resolution
        elif vram >= 10:
            return (1024, 1024)  # mid-high: standard 1K
        elif vram >= 6:
            return (832, 832)  # mid: 832x832
        else:
            return (768, 768)  # low-end: 768x768

    def recommend_best_model(self) -> str:
        """Recommend best model based on VRAM and CUDA availability."""
        if not self.vram_gb:
            return "illustrious-xl"

        # CUDA-optimized models preferred if CUDA enabled
        if self.cuda_enabled:
            if self.vram_gb >= 12:
                return "illustrious-xl"
            elif self.vram_gb >= 10:
                return "animagine-xl-4-alpha"
            elif self.vram_gb >= 8:
                return "animagine-xl-3-1"
            elif self.vram_gb >= 6:
                return "counterfeit-v3"
            else:
                return "counterfeit-v3"
        else:
            # CPU-based, recommend smaller models
            if self.vram_gb >= 8:
                return "animagine-xl-3-1"
            else:
                return "counterfeit-v3"

    def recommend_quality_profile(self) -> str:
        """Recommend quality profile based on VRAM and compute capability."""
        if not self.vram_gb:
            return "speed"

        if self.vram_gb >= 12:
            return "showcase"
        elif self.vram_gb >= 10:
            return "best-fidelity"
        elif self.vram_gb >= 8:
            return "quality"
        else:
            return "speed"

    def get_cuda_summary(self) -> str:
        """Return human-readable CUDA status summary."""
        if self.cuda_enabled:
            msg = f"✓ CUDA Enabled: {self.gpu_name} ({self.vram_gb:.1f}GB VRAM)"
            if self.cuda_version:
                msg += f" | CUDA {self.cuda_version}"
            if self.compute_capability:
                msg += f" | Compute {self.compute_capability}"
            return msg
        else:
            return "✗ CUDA Disabled - running on CPU (slower)"

    def get_style_for_persona(self, persona_name: str) -> str:
        """Recommend style based on persona name/category."""
        persona_lower = persona_name.lower()

        # Match against style keywords
        style_map = {
            "anime_standard": ["anime", "standard", "classic"],
            "manga_style": ["manga", "lineart"],
            "cel_shaded": ["cel", "cartoon"],
            "cyberpunk": ["cyber", "neon", "robot", "mecha"],
            "gothic_dark": ["dark", "gothic", "vampire"],
            "kawaii_cute": ["cute", "kawaii", "chibi"],
            "mecha_industrial": ["mecha", "robot", "machine"],
            "fantasy_medieval": ["fantasy", "knight", "wizard"],
            "shoujo_romance": ["shoujo", "romance", "girl"],
            "shounen_action": ["shounen", "action", "fight"],
            "supernatural": ["ghost", "spirit", "supernatural"],
        }

        for style, keywords in style_map.items():
            for kw in keywords:
                if kw in persona_lower:
                    return style

        return "anime_standard"  # default


class QualityOrchestrator:
    """Coordinate model, LoRA, sampler, steps for maximum visual fidelity."""

    # Model quality ranking (higher = better fidelity)
    MODEL_QUALITY_TIERS = {
        "illustrious": 10,
        "illustrious-xl": 10,
        "animagine-xl-4": 8,
        "animagine-xl-3": 7,
        "animagine-xl": 7,
        "majic-mix": 6,
        "realistic": 5,
    }

    def __init__(self, comfy_client=None):
        self.comfy_client = comfy_client
        self.available_models = []
        self.available_loras = []
        self.lora_registry = {}
        self.model_registry = {}
        self.style_presets = {}
        self._load_lora_registry()
        self._load_model_and_style_registries()

    def _load_lora_registry(self):
        """Load LoRA registry from lora_registry.json.
        Uses resource_path() (not Path(__file__).parent, which resolves
        inside PyInstaller's temp _MEIPASS dir in a frozen build - a real
        bug found in a full-system audit that silently stopped LoRA
        recommendations from working in the shipped exe)."""
        try:
            with open(resource_path("lora_registry.json"), "r",
                       encoding="utf-8") as f:
                self.lora_registry = json.load(f)
        except Exception as e:
            print(f"QualityOrchestrator: could not load lora_registry.json: {e}")

    def _load_model_and_style_registries(self):
        """Load model and style registries. Same resource_path() fix as
        _load_lora_registry (see its docstring)."""
        try:
            with open(resource_path("model_registry.json"), "r",
                       encoding="utf-8") as f:
                self.model_registry = json.load(f).get("models", {})
        except Exception as e:
            print(f"QualityOrchestrator: could not load model_registry.json: {e}")
        try:
            with open(resource_path("style_presets.json"), "r",
                       encoding="utf-8") as f:
                self.style_presets = json.load(f).get("styles", {})
        except Exception as e:
            print(f"QualityOrchestrator: could not load style_presets.json: {e}")

    def refresh_available(self):
        """Refresh lists of available models and LoRAs from ComfyUI.
        Filtered the same way as CompanionApp.director.models: SD1.5
        checkpoints are video-only in this app, and Turbo/Lightning/LCM
        checkpoints need a drastically different CFG/step regime than
        this class's registry-tier ranking has any way to know about -
        select_best_model() picking either as "best" would drive it with
        normal SDXL settings and produce broken output, not a clean
        error (found live via Auto-Pilot picking a Turbo checkpoint)."""
        if self.comfy_client:
            ckpts = self.comfy_client.get_checkpoints() or []
            self.available_models = [
                c for c in ckpts if not CompanionApp._is_sd15(c)
                and not CompanionApp._is_turbo_distilled(c)
                # v7.0: VAEs/ControlNets/encoders sitting in checkpoints/
                # are not loadable models - see _is_not_a_checkpoint.
                and not CompanionApp._is_not_a_checkpoint(c)]
            self.available_loras = self.comfy_client.get_loras() or []

    def select_best_model(self) -> str:
        """Rank available models by registry quality tier and return the best."""
        if not self.available_models:
            return self.available_models[0] if self.available_models else "model.safetensors"

        best_model = self.available_models[0]
        best_score = 0

        for model in self.available_models:
            model_key = model.lower().replace(".safetensors", "").replace(".ckpt", "")

            # Try to find in registry first
            score = 0
            for reg_key, reg_info in self.model_registry.items():
                if reg_key.lower() in model_key or model_key in reg_key.lower():
                    score = reg_info.get("quality_tier", 5)
                    break

            # Fallback to hardcoded tiers
            if score == 0:
                if "illustrious" in model_key:
                    score = 10
                elif "animagine-xl-4" in model_key:
                    score = 9
                elif "animagine-xl" in model_key:
                    score = 8
                else:
                    score = 5

            if score > best_score:
                best_score = score
                best_model = model

        return best_model

    def get_model_info(self, model_name: str) -> dict:
        """Get detailed info about a model from registry."""
        model_key = model_name.lower().replace(".safetensors", "").replace(".ckpt", "")
        for reg_key, info in self.model_registry.items():
            if reg_key.lower() in model_key:
                return info
        return {}

    def select_best_loras(self, categories: list = None, max_count: int = 3) -> list:
        """Suggest high-quality LoRAs from registry (curated Civitai collection)."""
        if not self.lora_registry:
            return []

        if not categories:
            categories = ["detail", "character"]

        selected = []
        for category in categories:
            if category in self.lora_registry:
                registry_loras = self.lora_registry[category]
                for lora_info in registry_loras[:2]:  # Top 2 per category
                    lora_name = lora_info.get("name", "")
                    if lora_name and len(selected) < max_count:
                        selected.append(lora_name)
                        if len(selected) >= max_count:
                            break

        return selected[:max_count]

    def get_loras_by_category(self, category: str) -> list:
        """Get all LoRAs in a category from registry with metadata."""
        return self.lora_registry.get(category, [])

    def get_registry_categories(self) -> list:
        """Get all available LoRA categories from registry."""
        return sorted(self.lora_registry.keys())

    def build_quality_prompt(self, positive_prompt: str) -> str:
        """Add quality modifiers to prompt for fidelity."""
        quality_tokens = "masterpiece, best score, high fidelity, detailed, intricate"
        if quality_tokens not in positive_prompt:
            return quality_tokens + ", " + positive_prompt
        return positive_prompt

    def recommend_sampler_for_quality(self) -> tuple:
        """Return (sampler, scheduler) tuple optimized for quality."""
        return ("dpm++ 2m sde", "karras")

    def calculate_optimal_steps(self, vram_gb: float, quality_level: str = "quality") -> int:
        """Calculate optimal step count based on VRAM and quality preference."""
        if quality_level == "speed":
            return 20
        elif quality_level == "quality":
            return 40 if vram_gb >= 8 else 30
        elif quality_level == "fidelity":
            return 50 if vram_gb >= 12 else 40
        else:  # showcase
            return 55 if vram_gb >= 16 else 50

    def suggest_cfg_scale(self, art_style: str = "anime") -> float:
        """Suggest optimal CFG scale based on style."""
        # Higher CFG for anime/character work, lower for realistic
        cfg_map = {
            "anime": 8.5,
            "photorealistic": 7.0,
            "painting": 7.5,
            "digital-art": 8.0,
            "cel-shaded": 8.0,
            "manga": 8.5,
        }
        return cfg_map.get(art_style.lower(), 8.0)


# ── PHASE 2, TIER 3: UGC Ecosystem ────────────────────────────────────────────
class CharacterSectionManager:
    """Organize personas into anime genres and source series."""

    # Order matters: earlier sections win keyword ties.
    SECTIONS = {
        "pokemon": {
            "label": "⚡ Pokémon",
            "description": "The Pokémon roster",
            "keywords": ["pokemon", "pokémon", "pokémon"]
        },
        "magical_girl": {
            "label": "🌙 Magical Girls",
            "description": "Magical girls and transformation heroines",
            "keywords": ["magical girl", "sailor", "madoka", "transformation",
                          "puella", "moon prism"]
        },
        "mecha": {
            "label": "🤖 Mecha & Cyberpunk",
            "description": "Pilots, androids, and neon futures",
            "keywords": ["mecha", "eva pilot", "cyberpunk", "android", "cyborg",
                          "netrunner", "plugsuit", "yorha", "ghost in the shell",
                          "robot", "edgerunner"]
        },
        "shonen": {
            "label": "🔥 Shonen & Battle",
            "description": "Big battle-series heroes and rivals",
            "keywords": ["shinobi", "ninja", "pirate", "soul reaper", "saiyan",
                          "hero academia", "jujutsu", "sorcerer", "hunter x",
                          "alchemist", "titan", "quirk", "nen", "chakra",
                          "devil hunter", "demon slayer"]
        },
        "fantasy": {
            "label": "✨ Fantasy & Isekai",
            "description": "Mages, elves, demons, and other worlds",
            "keywords": ["fantasy", "magic", "mage", "elf", "wizard", "witch",
                          "dragon", "demon", "isekai", "spirit", "kitsune",
                          "adventurer", "dungeon", "wolf god"]
        },
        "romance": {
            "label": "💘 Romance & Slice of Life",
            "description": "School, romance, idols, and everyday charm",
            "keywords": ["romance", "school uniform", "idol", "band", "guitar",
                          "cafe", "slice of life", "crush", "senpai",
                          "seamstress", "cosplay"]
        },
        "action": {
            "label": "⚔️ Action & Adventure",
            "description": "Warriors, bounty hunters, and blades",
            "keywords": ["action", "warrior", "fighter", "battle", "combat",
                          "samurai", "knight", "bounty", "assassin", "sword"]
        },
        "scifi": {
            "label": "🚀 Sci-Fi & Space",
            "description": "Space operas and future frontiers",
            "keywords": ["space", "sci-fi", "futuristic", "cosmic", "star",
                          "galaxy", "bebop"]
        },
        "cute": {
            "label": "💗 Cute & Chibi",
            "description": "Adorable and charming characters",
            "keywords": ["cute", "chibi", "kawaii", "sweet", "innocent"]
        },
        "movies": {
            "label": "🎬 Anime Films",
            "description": "Shinkai, Ghibli, and film icons",
            "keywords": ["your name", "weathering", "shinkai", "ghibli",
                          "sunshine girl", "comet"]
        },
        "community": {
            "label": "🌐 Community",
            "description": "User-shared community creations",
            "keywords": ["community", "shared", "public"]
        },
        "other": {
            "label": "🎨 Other Anime",
            "description": "Everything else in the roster",
            "keywords": []
        },
    }

    def __init__(self, personas_source):
        """personas_source: a PersonaPrompts instance (reads its live
        `.personas` via the property below) or a plain dict (legacy).
        PersonaPrompts.load() replaces `.personas` with a brand-new dict
        rather than mutating it in place, so storing the dict itself here
        would go stale after any reload (e.g. adding a new character) -
        storing the source object and reading `.personas` each time keeps
        this in sync."""
        self._personas_source = personas_source

    @property
    def personas_dict(self):
        src = self._personas_source
        return src.personas if hasattr(src, "personas") else src

    def categorize_persona(self, persona_name: str, persona_data: dict) -> str:
        """Determine which genre section a persona belongs to."""
        # Explicit category field always wins
        explicit = persona_data.get("category", "")
        if explicit in self.SECTIONS:
            return explicit

        combined = " ".join([
            persona_name.lower(),
            persona_data.get("name", "").lower(),
            persona_data.get("series", "").lower(),
            persona_data.get("backstory", "").lower(),
            persona_data.get("visual_details", "").lower(),
        ])

        for section_key, section_info in self.SECTIONS.items():
            for keyword in section_info["keywords"]:
                if keyword in combined:
                    return section_key
        return "other"

    def get_series(self, persona_name: str, persona_data: dict) -> str:
        """Determine source series (explicit field first, then name hints)."""
        if persona_data.get("series"):
            return persona_data["series"]
        display = persona_data.get("name", persona_name)
        if "pok" in display.lower():
            return "Pokémon"
        return "Original / Other"

    def get_sections(self, group_by: str = "genre") -> dict:
        """Group personas by 'genre' or 'series'."""
        if group_by == "series":
            groups = {}
            for persona_name, persona_data in self.personas_dict.items():
                series = self.get_series(persona_name, persona_data)
                entry = groups.setdefault(series, {"label": f"📺 {series}", "personas": []})
                entry["personas"].append({
                    "name": persona_name,
                    "display": persona_data.get("name", persona_name),
                    "data": persona_data
                })
            # Sort by size (biggest series first), "Original / Other" last
            return dict(sorted(groups.items(),
                               key=lambda kv: (kv[0] == "Original / Other",
                                               -len(kv[1]["personas"]))))

        sections = {key: {"label": info["label"], "personas": []}
                   for key, info in self.SECTIONS.items()}
        for persona_name, persona_data in self.personas_dict.items():
            section = self.categorize_persona(persona_name, persona_data)
            sections.get(section, sections["other"])["personas"].append({
                "name": persona_name,
                "display": persona_data.get("name", persona_name),
                "data": persona_data
            })
        return sections


class PersonaPublisher:
    """Manage persona publishing, versioning, and community discovery."""

    def __init__(self, data_dir: Path):
        self.data_dir = data_dir
        self.community_dir = Path(app_dir()) / "personas_community"
        self.community_dir.mkdir(parents=True, exist_ok=True)
        self.community_file = self.community_dir / "personas_community.json"

    def load_community_personas(self) -> dict:
        """Load all public/community personas."""
        if not self.community_file.exists():
            return {}
        try:
            with open(self.community_file, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            # Genuine corruption of an EXISTING file - never return {} here,
            # publish_persona() would then write that {} straight back over
            # disk and wipe every other published persona (same bug class
            # as the fixed FutureProofingEngine/_save_persona issue).
            backup = self.community_file.with_suffix(
                f".corrupt-{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
            try:
                self.community_file.replace(backup)
                print(f"personas_community.json was corrupted ({e}) - "
                      f"backed up to {backup.name}")
            except Exception:
                print(f"personas_community.json was corrupted ({e}) - "
                      f"could not back up, starting fresh")
            return {}

    def publish_persona(self, persona: dict, author: str, tags: list,
                       sample_paths: list = None) -> bool:
        """Publish a persona to community library."""
        try:
            community = self.load_community_personas()

            key = re.sub(r"[^\w\-]+", "_", persona.get("name", "persona")).lower()
            community[key] = {
                "name": persona.get("name", ""),
                "author": author,
                "created_date": datetime.now().isoformat(),
                "version": "1.0.0",
                "public": True,
                "tags": tags,
                "visual_details": persona.get("visual_details", ""),
                "psychology": persona.get("psychology", ""),
                "backstory": persona.get("backstory", ""),
                "signature_quote": persona.get("signature_quote", ""),
                "downloads": 0,
                "sample_generations": sample_paths or [],
                "creator_id": self._generate_creator_id(author),
            }

            with open(self.community_file, "w", encoding="utf-8") as f:
                json.dump(community, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False

    def search_community(self, query: str = "", tags: list = None) -> list:
        """Search community personas by name or tags."""
        community = self.load_community_personas()
        results = []

        query_lower = query.lower()
        for key, persona in community.items():
            if not persona.get("public"):
                continue

            name_match = query_lower in persona.get("name", "").lower()
            tag_match = tags and any(t in persona.get("tags", []) for t in tags)

            if query and (name_match or tag_match):
                results.append({**persona, "key": key})
            elif not query:
                results.append({**persona, "key": key})

        # Sort by downloads (trending first)
        return sorted(results, key=lambda p: p.get("downloads", 0), reverse=True)

    def increment_download(self, persona_key: str):
        """Track persona downloads for trending."""
        try:
            community = self.load_community_personas()
            if persona_key in community:
                community[persona_key]["downloads"] = community[persona_key].get("downloads", 0) + 1
                with open(self.community_file, "w", encoding="utf-8") as f:
                    json.dump(community, f, indent=2, ensure_ascii=False)
        except Exception:
            pass

    def update_persona_rating(self, persona_key: str, star_rating: int) -> bool:
        """Update persona ratings and aggregate metrics."""
        try:
            community = self.load_community_personas()
            if persona_key not in community:
                return False

            persona = community[persona_key]
            if "quality_metrics" not in persona:
                persona["quality_metrics"] = {
                    "avg_rating": 0.0,
                    "total_ratings": 0,
                    "avg_quality_score": 0.0,
                    "trending_score": 0.0
                }

            # Update rating
            metrics = persona["quality_metrics"]
            old_avg = metrics.get("avg_rating", 0.0)
            old_count = metrics.get("total_ratings", 0)
            new_count = old_count + 1
            new_avg = ((old_avg * old_count) + star_rating) / new_count

            metrics["avg_rating"] = round(new_avg, 2)
            metrics["total_ratings"] = new_count

            # Recalculate trending score
            metrics["trending_score"] = self._calculate_trend_score(
                downloads=persona.get("downloads", 0),
                avg_rating=metrics["avg_rating"],
                ratings_count=metrics["total_ratings"]
            )

            with open(self.community_file, "w", encoding="utf-8") as f:
                json.dump(community, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False

    def update_generation_stats(self, persona_key: str, model: str, style: str,
                               gen_time: float) -> bool:
        """Track generation statistics per persona."""
        try:
            community = self.load_community_personas()
            if persona_key not in community:
                return False

            persona = community[persona_key]
            if "generation_stats" not in persona:
                persona["generation_stats"] = {
                    "total_generations": 0,
                    "preferred_models": [],
                    "preferred_styles": [],
                    "avg_generation_time": 0.0
                }

            stats = persona["generation_stats"]
            stats["total_generations"] = stats.get("total_generations", 0) + 1

            # Track model usage
            if model:
                models = stats.get("preferred_models", [])
                model_entry = next((m for m in models if m["name"] == model), None)
                if model_entry:
                    model_entry["uses"] += 1
                else:
                    models.append({"name": model, "uses": 1})
                stats["preferred_models"] = sorted(models, key=lambda x: x["uses"], reverse=True)[:3]

            # Track style usage
            if style:
                styles = stats.get("preferred_styles", [])
                style_entry = next((s for s in styles if s["name"] == style), None)
                if style_entry:
                    style_entry["uses"] += 1
                else:
                    styles.append({"name": style, "uses": 1})
                stats["preferred_styles"] = sorted(styles, key=lambda x: x["uses"], reverse=True)[:3]

            # Update average generation time
            old_avg = stats.get("avg_generation_time", 0.0)
            old_count = stats["total_generations"] - 1
            if old_count > 0:
                new_avg = ((old_avg * old_count) + gen_time) / stats["total_generations"]
            else:
                new_avg = gen_time
            stats["avg_generation_time"] = round(new_avg, 1)

            with open(self.community_file, "w", encoding="utf-8") as f:
                json.dump(community, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False

    def get_trending_personas(self, limit: int = 10) -> list:
        """Get trending personas by trend score."""
        community = self.load_community_personas()
        personas = [{"name": v.get("name"), "trend_score": v.get("quality_metrics", {}).get("trending_score", 0.0),
                     "rating": v.get("quality_metrics", {}).get("avg_rating", 0.0),
                     "downloads": v.get("downloads", 0)}
                   for v in community.values() if v.get("public")]
        return sorted(personas, key=lambda p: p["trend_score"], reverse=True)[:limit]

    @staticmethod
    def _calculate_trend_score(downloads: int, avg_rating: float, ratings_count: int) -> float:
        """Calculate trend score: weighted combination of activity metrics."""
        # Formula: (downloads * 0.3) + (avg_rating * 2.5) + (sqrt(ratings_count) * 0.5)
        trend = (downloads * 0.3) + (avg_rating * 2.5) + (ratings_count ** 0.5 * 0.5)
        return round(min(1.0, trend / 10.0), 3)

    @staticmethod
    def _generate_creator_id(author: str) -> str:
        """Generate unique creator ID from author name."""
        import hashlib
        return hashlib.md5(author.encode()).hexdigest()[:12]


class ContentShareManager:
    """Manage image sharing with rich metadata."""

    METADATA_VERSION = "1.0"

    def __init__(self, data_dir: Path):
        self.data_dir = data_dir

    def create_share_metadata(self, image_path: Path, persona_name: str,
                             mode: str, style: str, model: str,
                             sampler: str, steps: int, cfg: float,
                             loras: list = None, quality_profile: str = None,
                             quality_score: float = None) -> dict:
        """Create rich metadata for sharing an image.

        v10.0: `quality_score` is a new, separate field from
        `quality_profile` (a preset-name string) - a real numeric score
        from QualityMetricsCalculator, so get_trending_styles() can
        compute a genuine average instead of its old hardcoded 7.0
        fallback. Optional/None-default so existing callers are
        unaffected."""
        return {
            "share_version": self.METADATA_VERSION,
            "shared_date": datetime.now().isoformat(),
            "content_id": self._generate_content_id(image_path),
            "creator_id": None,  # Will be set when published
            "image_filename": image_path.name,
            "persona": persona_name,
            "generation_mode": mode,
            "style": style,
            "model": model,
            "sampler": sampler,
            "steps": steps,
            "cfg": cfg,
            "loras_used": loras or [],
            "quality_profile": quality_profile,
            "quality_score": quality_score,
            "hashtags": self._generate_hashtags(persona_name, mode, style),
            "portfolio_flag": False,
            "share_status": "private",  # private, friends, public
        }

    def export_share_metadata(self, image_path: Path, metadata: dict) -> bool:
        """Save metadata alongside image as {name}_share.json."""
        try:
            metadata_path = image_path.with_stem(image_path.stem + "_share")
            metadata_path = metadata_path.with_suffix(".json")

            with open(metadata_path, "w", encoding="utf-8") as f:
                json.dump(metadata, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False

    def load_share_metadata(self, image_path: Path) -> dict:
        """Load metadata from {name}_share.json if it exists."""
        metadata_path = image_path.with_stem(image_path.stem + "_share")
        metadata_path = metadata_path.with_suffix(".json")

        if metadata_path.exists():
            try:
                with open(metadata_path, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                pass
        return {}

    @staticmethod
    def _generate_content_id(image_path: Path) -> str:
        """Generate unique content ID from image file."""
        import hashlib
        with open(image_path, "rb") as f:
            return hashlib.sha256(f.read()).hexdigest()[:16]

    @staticmethod
    def _generate_hashtags(persona: str, mode: str, style: str) -> list:
        """Auto-generate hashtags for discoverability."""
        tags = [
            f"#{persona.lower().replace(' ', '')}",
            f"#{mode.lower().replace(' ', '')}",
            f"#{style.lower().replace(' ', '')}",
            "#anime", "#aiart", "#comfyui"
        ]
        return list(set(tags))[:8]  # Limit to 8 unique tags


class UGCDiscoveryManager:
    """Handle UGC discovery: trending, featured, recent content."""

    def __init__(self, data_dir: Path):
        self.data_dir = data_dir
        self.discovery_file = data_dir / "ugc_discovery.json"

    def load_discovery_index(self) -> dict:
        """Load UGC discovery index (trending, featured, recent)."""
        if self.discovery_file.exists():
            try:
                with open(self.discovery_file, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                pass
        return {"featured": [], "trending": [], "recent": []}

    def save_discovery_index(self, index: dict) -> bool:
        """Save discovery index."""
        try:
            with open(self.discovery_file, "w", encoding="utf-8") as f:
                json.dump(index, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False

    def add_to_recent(self, content_metadata: dict, max_recent: int = 100) -> bool:
        """Add shared content to recent list.

        v10.0: was dropping `style`/`quality_score` entirely before
        persisting - get_trending_styles() reads exactly those two
        fields from these "recent" entries, so trending styles could
        never surface real data no matter what create_share_metadata
        was given; every entry silently failed its `if style:` check."""
        try:
            index = self.load_discovery_index()
            index["recent"].insert(0, {
                "content_id": content_metadata.get("content_id"),
                "persona": content_metadata.get("persona"),
                "style": content_metadata.get("style"),
                "quality_score": content_metadata.get("quality_score"),
                "timestamp": datetime.now().isoformat(),
                "hashtags": content_metadata.get("hashtags", []),
            })
            index["recent"] = index["recent"][:max_recent]
            return self.save_discovery_index(index)
        except Exception:
            return False

    def get_trending_personas(self, limit: int = 10) -> list:
        """Get trending personas by share count."""
        index = self.load_discovery_index()
        persona_counts = {}

        for content in index.get("recent", []):
            persona = content.get("persona")
            if persona:
                persona_counts[persona] = persona_counts.get(persona, 0) + 1

        trending = sorted(persona_counts.items(), key=lambda x: x[1], reverse=True)
        return [{"name": p[0], "shares": p[1]} for p in trending[:limit]]

    def get_trending_styles(self, limit: int = 10) -> list:
        """Get trending styles by usage count."""
        index = self.load_discovery_index()
        style_counts = {}

        for content in index.get("recent", []):
            style = content.get("style")
            if style:
                if style not in style_counts:
                    style_counts[style] = {"count": 0, "quality_sum": 0.0}
                style_counts[style]["count"] += 1
                quality = content.get("quality_score", 7.0)
                style_counts[style]["quality_sum"] += quality

        # Calculate average quality per style and create trending list
        trending = []
        for style, data in style_counts.items():
            avg_quality = data["quality_sum"] / data["count"] if data["count"] > 0 else 0.0
            trending.append({
                "style": style,
                "usage_count": data["count"],
                "avg_quality": round(avg_quality, 1),
                "trend_score": self._calculate_style_trend(data["count"], avg_quality)
            })

        return sorted(trending, key=lambda s: s["trend_score"], reverse=True)[:limit]

    def get_featured_personas(self) -> list:
        """Get featured personas from discovery index."""
        index = self.load_discovery_index()
        featured = []
        for persona_data in index.get("featured", []):
            featured.append({
                "name": persona_data.get("name"),
                "curator_note": persona_data.get("curator_note", ""),
                "rank": persona_data.get("rank", 999)
            })
        return sorted(featured, key=lambda p: p["rank"])

    def add_featured_persona(self, persona_name: str, curator_note: str = "") -> bool:
        """Add or update a featured persona."""
        try:
            index = self.load_discovery_index()
            featured = index.get("featured", [])

            # Check if already featured
            existing = next((f for f in featured if f.get("name") == persona_name), None)
            if existing:
                existing["curator_note"] = curator_note
            else:
                featured.append({
                    "name": persona_name,
                    "curator_note": curator_note,
                    "rank": len(featured) + 1
                })

            index["featured"] = featured
            return self.save_discovery_index(index)
        except Exception:
            return False

    def remove_featured_persona(self, persona_name: str) -> bool:
        """Remove a persona from featured list."""
        try:
            index = self.load_discovery_index()
            featured = index.get("featured", [])
            index["featured"] = [f for f in featured if f.get("name") != persona_name]
            return self.save_discovery_index(index)
        except Exception:
            return False

    def update_community_stats(self, total_personas: int = 0, total_images: int = 0,
                              total_users: int = 0, avg_rating: float = 0.0) -> bool:
        """Update community statistics."""
        try:
            index = self.load_discovery_index()
            if "stats" not in index:
                index["stats"] = {}

            stats = index["stats"]
            if total_personas > 0:
                stats["total_personas"] = total_personas
            if total_images > 0:
                stats["total_images"] = total_images
            if total_users > 0:
                stats["total_users"] = total_users
            if avg_rating > 0:
                stats["avg_rating"] = round(avg_rating, 2)

            return self.save_discovery_index(index)
        except Exception:
            return False

    @staticmethod
    def _calculate_style_trend(count: int, avg_quality: float) -> float:
        """Calculate trend score for a style."""
        # Combination of usage frequency and quality
        trend = (count * 0.4) + (avg_quality * 0.6)
        return round(min(1.0, trend / 10.0), 3)


class PerImageMetadataManager:
    """Manage per-image metadata: ratings, views, downloads, quality scores."""

    def __init__(self, data_dir: Path):
        self.data_dir = data_dir

    def create_image_metadata(self, image_path: Path, persona: str,
                             model: str, sampler: str, steps: int, cfg: float,
                             loras: list = None, quality_score: float = 0.0) -> dict:
        """Create metadata for a generated image."""
        return {
            "generator": "3klipz Studio",
            "image_filename": image_path.name,
            "content_id": self._generate_content_id(image_path),
            "persona": persona,
            "generation_date": datetime.now().isoformat(),
            "generation_params": {
                "model": model,
                "sampler": sampler,
                "steps": steps,
                "cfg": cfg,
                "loras": loras or []
            },
            "quality_tracking": {
                "quality_score": quality_score,
                "user_rating": None,
                "rating_count": 0,
                "views": 0,
                "downloads": 0,
                "shares": 0
            },
            "quality_metrics": {
                "detail_score": 0.0,
                "color_accuracy": 0.0,
                "character_consistency": 0.0,
                "lighting_quality": 0.0,
                "composition": 0.0
            }
        }

    def save_image_metadata(self, image_path: Path, metadata: dict) -> bool:
        """Save metadata to {image}_meta.json."""
        try:
            metadata_path = image_path.with_stem(image_path.stem + "_meta")
            metadata_path = metadata_path.with_suffix(".json")
            with open(metadata_path, "w", encoding="utf-8") as f:
                json.dump(metadata, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False

    def load_image_metadata(self, image_path: Path) -> dict:
        """Load metadata from {image}_meta.json if it exists."""
        metadata_path = image_path.with_stem(image_path.stem + "_meta")
        metadata_path = metadata_path.with_suffix(".json")
        if metadata_path.exists():
            try:
                with open(metadata_path, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                pass
        return {}

    def update_image_rating(self, image_path: Path, star_rating: int) -> bool:
        """Update user rating for an image (1-5 stars)."""
        try:
            metadata = self.load_image_metadata(image_path)
            if metadata:
                metadata["quality_tracking"]["user_rating"] = star_rating
                metadata["quality_tracking"]["rating_count"] += 1
                return self.save_image_metadata(image_path, metadata)
        except Exception:
            pass
        return False

    def increment_view_count(self, image_path: Path) -> bool:
        """Increment view count for an image."""
        try:
            metadata = self.load_image_metadata(image_path)
            if metadata:
                metadata["quality_tracking"]["views"] += 1
                return self.save_image_metadata(image_path, metadata)
        except Exception:
            pass
        return False

    def increment_download_count(self, image_path: Path) -> bool:
        """Increment download count for an image."""
        try:
            metadata = self.load_image_metadata(image_path)
            if metadata:
                metadata["quality_tracking"]["downloads"] += 1
                return self.save_image_metadata(image_path, metadata)
        except Exception:
            pass
        return False

    @staticmethod
    def _generate_content_id(image_path: Path) -> str:
        """Generate unique content ID from image file."""
        import hashlib
        try:
            with open(image_path, "rb") as f:
                return hashlib.sha256(f.read()).hexdigest()[:16]
        except Exception:
            return str(uuid.uuid4())[:16]


class QualityMetricsCalculator:
    """Analyze images and calculate quality metrics using heuristics."""

    def __init__(self, client=None, bbox_model=None):
        self.thresholds = {
            "detail": 0.7,
            "color": 0.65,
            "character": 0.75,
            "lighting": 0.6,
            "composition": 0.7
        }
        # v6.0 Stage 5: optional Impact Pack detector wiring for a real
        # anatomy signal. None until _probe_capabilities resolves it
        # (server offline / Impact Pack absent) -> anatomy_score stays at
        # its neutral default, zero regression to the pure-heuristic path.
        self.client = client
        self.bbox_model = bbox_model

    def calculate_image_quality(self, image_path: Path) -> dict:
        """Calculate quality metrics for an image."""
        try:
            from PIL import Image
            img = Image.open(image_path)

            return {
                "detail_score": self._calculate_detail_score(img),
                "color_accuracy": self._calculate_color_accuracy(img),
                "character_consistency": self._calculate_character_consistency(img),
                "lighting_quality": self._calculate_lighting_quality(img),
                "composition": self._calculate_composition_score(img),
                "anatomy_score": self._calculate_anatomy_score(image_path),
            }
        except Exception:
            return self._default_metrics()

    def _calculate_detail_score(self, img) -> float:
        """Estimate detail score via edge detection."""
        try:
            import numpy as np
            arr = np.array(img.convert('L'))
            edges = np.gradient(arr)
            edge_density = np.mean(np.abs(edges))
            score = min(10.0, 4.0 + (edge_density / 50.0))
            return round(min(10.0, max(1.0, score)), 1)
        except Exception:
            return 7.0

    def _calculate_color_accuracy(self, img) -> float:
        """Estimate color accuracy via saturation analysis."""
        try:
            import numpy as np
            hsv_img = img.convert('HSV')
            arr = np.array(hsv_img)
            saturation = arr[:,:,1].mean()
            score = 4.0 + (saturation / 25.5)
            return round(min(10.0, max(1.0, score)), 1)
        except Exception:
            return 7.5

    def _calculate_character_consistency(self, img) -> float:
        """Estimate character consistency (heuristic-based)."""
        # For anime, consistency is judged by edge coherence and structure
        try:
            import numpy as np
            arr = np.array(img.convert('L'))
            # High-pass filter to detect edges
            kernel_x = np.array([[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]])
            kernel_y = np.array([[-1, -2, -1], [0, 0, 0], [1, 2, 1]])
            # Simplified: use variance of edges as measure of consistency
            variance = np.var(arr)
            score = 5.0 + (variance / 1000.0)
            return round(min(10.0, max(1.0, score)), 1)
        except Exception:
            return 7.5

    def _calculate_lighting_quality(self, img) -> float:
        """Estimate lighting quality via brightness distribution."""
        try:
            import numpy as np
            arr = np.array(img.convert('L'))
            brightness = arr.mean()
            # Ideal lighting is around 128 (mid-gray)
            distance_from_ideal = abs(brightness - 128) / 128.0
            score = 10.0 - (distance_from_ideal * 3.0)
            return round(min(10.0, max(1.0, score)), 1)
        except Exception:
            return 7.0

    def _calculate_anatomy_score(self, image_path: Path) -> float:
        """Face-count-based anatomy signal via Impact Pack's Ultralytics
        detector: exactly one detected face scores well; zero or 2+
        signals a likely defect (missing/obscured face, or a duplicated/
        malformed one) for a single-character portrait. This is
        confidence-as-proxy for "something's structurally wrong" - not a
        true finger-count or deformity check. Ultralytics detects
        face-shaped regions; it doesn't verify anatomical correctness.
        Returns the neutral default when no detector is wired (server
        offline / Impact Pack absent) - zero regression to the pure-
        heuristic scores above."""
        if not self.client or not self.bbox_model:
            return 7.0
        try:
            image_name = self.client.upload_image(image_path)
            wf = {
                "1": {"class_type": "LoadImage",
                      "inputs": {"image": image_name}},
                "2": {"class_type": "UltralyticsDetectorProvider",
                      "inputs": {"model_name": self.bbox_model}},
                "3": {"class_type": "BboxDetectorSEGS",
                      "inputs": {"bbox_detector": ["2", 0], "image": ["1", 0],
                                 "threshold": 0.5, "dilation": 10,
                                 "crop_factor": 3.0, "drop_size": 10,
                                 "labels": "all"}},
                "4": {"class_type": "ImpactCount_Elts_in_SEGS",
                      "inputs": {"segs": ["3", 0]}},
                "5": {"class_type": "PreviewAny", "inputs": {"source": ["4", 0]}},
            }
            prompt_id = self.client.queue_prompt(wf)
            entry = self.client.wait_for_result(prompt_id, timeout_s=60)
            count = int(entry["outputs"]["5"]["text"][0])
            if count == 1:
                return 9.0
            elif count == 0:
                return 4.0
            else:
                return 5.0
        except Exception:
            return 7.0

    def _calculate_composition_score(self, img) -> float:
        """Estimate composition via aspect ratio and symmetry."""
        try:
            import numpy as np
            width, height = img.size
            aspect_ratio = width / height if height > 0 else 1.0
            # Ideal aspect ratios for anime: 1:1, 4:5, 16:9
            ideal_ratios = [1.0, 0.8, 1.78]
            min_distance = min(abs(aspect_ratio - r) for r in ideal_ratios)
            score = 8.0 - (min_distance * 2.0)
            return round(min(10.0, max(1.0, score)), 1)
        except Exception:
            return 7.5

    def calculate_overall_quality_score(self, metrics: dict) -> float:
        """Calculate overall quality score (1-10) from component metrics."""
        try:
            scores = [
                metrics.get("detail_score", 7.0),
                metrics.get("color_accuracy", 7.5),
                metrics.get("character_consistency", 7.5),
                metrics.get("lighting_quality", 7.0),
                metrics.get("composition", 7.5),
                metrics.get("anatomy_score", 7.0)
            ]
            average = sum(scores) / len(scores)
            return round(min(10.0, max(1.0, average)), 1)
        except Exception:
            return 7.0

    @staticmethod
    def _default_metrics() -> dict:
        """Return default metrics when calculation fails."""
        return {
            "detail_score": 7.0,
            "color_accuracy": 7.5,
            "character_consistency": 7.5,
            "lighting_quality": 7.0,
            "composition": 7.5,
            "anatomy_score": 7.0
        }


class PromptOptimizer:
    """Suggest improvements to generation settings based on quality metrics."""

    def __init__(self, model_registry_path: Path, lora_registry_path: Path):
        self.model_registry = safe_json_load(model_registry_path, {})
        self.lora_registry = safe_json_load(lora_registry_path, {})

    def analyze_generation(self, image_path: Path, params: dict,
                          metrics: dict) -> dict:
        """Analyze generation and return quality report."""
        quality_score = metrics.get("overall_score", 7.0)
        suggestions = self.suggest_improvements(metrics, params)

        return {
            "quality_score": quality_score,
            "suggestions": suggestions,
            "metrics": metrics
        }

    def suggest_improvements(self, metrics: dict, params: dict) -> list:
        """Generate suggestions based on quality gaps."""
        suggestions = []

        # Detail score improvement
        if metrics.get("detail_score", 7.0) < 7.0:
            suggestions.append({
                "issue": "Low detail score ({:.1f})".format(metrics.get("detail_score", 7.0)),
                "suggestion": "Add LoRA: Anime Detail Tuner XL",
                "expected_improvement": "+0.8 to detail score",
                "action": "add_lora"
            })

        # Lighting improvement
        if metrics.get("lighting_quality", 7.0) < 7.5:
            suggestions.append({
                "issue": "Lighting could be improved",
                "suggestion": "Try DPM++ 2M SDE (better for lighting)",
                "expected_improvement": "More dramatic, professional lighting",
                "action": "change_sampler"
            })

        # Character consistency
        if metrics.get("character_consistency", 7.0) < 7.5:
            suggestions.append({
                "issue": "Character consistency could improve",
                "suggestion": 'Add prompt token: "consistent character design"',
                "expected_improvement": "+1.2 to consistency",
                "action": "add_prompt_token"
            })

        # Color improvement
        if metrics.get("color_accuracy", 7.5) < 7.0:
            suggestions.append({
                "issue": "Color accuracy needs work",
                "suggestion": "Increase CFG scale to 7.5-8.0",
                "expected_improvement": "More saturated, vibrant colors",
                "action": "adjust_cfg"
            })

        return suggestions

    def get_model_recommendation(self, params: dict) -> str:
        """Recommend best model for current settings."""
        quality_profile = params.get("quality_profile", "quality")
        if quality_profile in ["showcase", "best_fidelity"]:
            return "illustrious-xl"
        elif quality_profile == "quality":
            return "animagine-xl-4"
        else:
            return "counterfeit-v3"


