# Brand Kit - stamp your brand (handle/name/logo) inside every image
# ════════════════════════════════════════════════════════════════════════════

class BrandKit:
    """User brand configuration + PIL stamping. Config lives in
    brand_kit.json next to the exe; edited via Creator Studio > Brand."""

    DEFAULTS = {
        "enabled": False,
        "brand_name": "",
        "handle": "",            # e.g. @mystudio - preferred watermark text
        "logo_path": "",         # optional PNG (alpha respected)
        "position": "bottom-right",
        "opacity": 0.85,
        "size_pct": 3.5,         # text height as % of image height
        "color": "#FFFFFF",
        "brand_products": False,  # also stamp Printify exports
        "brand_generations": False,  # also stamp raw GENERATE output
    }
    POSITIONS = ["bottom-right", "bottom-left", "bottom-center",
                 "top-right", "top-left"]

    def __init__(self):
        self.path = app_dir() / "brand_kit.json"
        data = safe_json_load(self.path, {})
        self.cfg = {**self.DEFAULTS,
                    **(data if isinstance(data, dict) else {})}

    def save(self):
        safe_json_save(self.path, self.cfg)

    def active(self) -> bool:
        return bool(self.cfg["enabled"] and
                    (self.cfg["handle"] or self.cfg["brand_name"] or
                     self.cfg["logo_path"]))

    def apply(self, img):
        """Return a branded copy of a PIL image (mode preserved).
        No-op when the kit is disabled or empty."""
        if not self.active():
            return img
        try:
            from PIL import Image, ImageDraw
            mode = img.mode
            base = img.convert("RGBA")
            overlay = Image.new("RGBA", base.size, (0, 0, 0, 0))
            draw = ImageDraw.Draw(overlay)

            text = self.cfg["handle"] or self.cfg["brand_name"]
            h = max(16, int(base.height * float(self.cfg["size_pct"]) / 100))
            font = find_bold_font(h)
            opacity = max(0, min(255, int(255 * float(self.cfg["opacity"]))))
            hexc = str(self.cfg["color"]).lstrip("#")
            try:
                rgb = tuple(int(hexc[i:i + 2], 16) for i in (0, 2, 4))
            except Exception:
                rgb = (255, 255, 255)

            tw = draw.textbbox((0, 0), text, font=font)[2] if text else 0
            th = h
            logo, lw = None, 0
            lp = self.cfg.get("logo_path", "")
            if lp and Path(lp).exists():
                logo = Image.open(lp).convert("RGBA")
                lh = int(h * 1.5)
                logo = logo.resize(
                    (max(1, int(logo.width * lh / logo.height)), lh),
                    Image.LANCZOS)
                a = logo.getchannel("A").point(
                    lambda v: int(v * opacity / 255))
                logo.putalpha(a)
                lw = logo.width + (h // 3 if text else 0)

            total_w = lw + tw
            margin = max(12, h // 2)
            pos = self.cfg.get("position", "bottom-right")
            if "right" in pos:
                x = base.width - total_w - margin
            elif "center" in pos:
                x = (base.width - total_w) // 2
            else:
                x = margin
            y = margin if pos.startswith("top") else \
                base.height - max(th, int(h * 1.5)) - margin

            if logo:
                overlay.alpha_composite(logo, (x, y - (logo.height - th) // 2))
            if text:
                draw.text((x + lw, y), text, font=font,
                          fill=rgb + (opacity,),
                          stroke_width=max(1, h // 14),
                          stroke_fill=(0, 0, 0, int(opacity * 0.8)))
            out = Image.alpha_composite(base, overlay)
            return out if mode == "RGBA" else out.convert(mode)
        except Exception:
            return img


class LutGrader:
    """Cinematic color-grade LUTs (.cube files in luts/), applied via
    trilinear interpolation. Pure PIL/numpy - no ComfyUI round-trip."""

    def __init__(self):
        self.dir = resource_path("luts")
        self._cache = {}

    def available(self) -> list:
        if not self.dir.exists():
            return []
        return sorted(p.stem for p in self.dir.glob("*.cube"))

    def _load(self, name: str):
        if name in self._cache:
            return self._cache[name]
        import numpy as np
        path = self.dir / f"{name}.cube"
        size = None
        rows = []
        for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
            line = line.strip()
            if not line or not (line[0].isdigit() or line[0] == "-"):
                if line.startswith("LUT_3D_SIZE"):
                    size = int(line.split()[1])
                continue
            parts = line.split()
            if len(parts) == 3:
                try:
                    rows.append([float(x) for x in parts])
                except ValueError:
                    pass
        if not size or len(rows) != size ** 3:
            raise ValueError(f"malformed or unsupported LUT: {name}")
        # .cube ordering: R fastest, then G, then B -> reshape (B, G, R, 3)
        lut = np.array(rows, dtype=np.float32).reshape(size, size, size, 3)
        self._cache[name] = (lut, size)
        return lut, size

    def apply(self, img, name: str, strength: float = 1.0):
        """Return a color-graded copy of a PIL image. No-op if the LUT is
        missing or strength <= 0; mode/alpha preserved."""
        if strength <= 0 or name not in self.available():
            return img
        import numpy as np
        from PIL import Image
        lut, size = self._load(name)
        mode = img.mode
        rgb = img.convert("RGB")
        arr = np.asarray(rgb, dtype=np.float32) / 255.0
        scaled = arr * (size - 1)
        r, g, b = scaled[..., 0], scaled[..., 1], scaled[..., 2]
        r0 = np.clip(np.floor(r).astype(np.int32), 0, size - 2)
        g0 = np.clip(np.floor(g).astype(np.int32), 0, size - 2)
        b0 = np.clip(np.floor(b).astype(np.int32), 0, size - 2)
        r1, g1, b1 = r0 + 1, g0 + 1, b0 + 1
        fr = (r - r0)[..., None]
        fg = (g - g0)[..., None]
        fb = (b - b0)[..., None]

        def sample(bi, gi, ri):
            return lut[bi, gi, ri]

        c00 = sample(b0, g0, r0) * (1 - fr) + sample(b0, g0, r1) * fr
        c10 = sample(b0, g1, r0) * (1 - fr) + sample(b0, g1, r1) * fr
        c01 = sample(b1, g0, r0) * (1 - fr) + sample(b1, g0, r1) * fr
        c11 = sample(b1, g1, r0) * (1 - fr) + sample(b1, g1, r1) * fr
        c0 = c00 * (1 - fg) + c10 * fg
        c1 = c01 * (1 - fg) + c11 * fg
        out = np.clip(c0 * (1 - fb) + c1 * fb, 0, 1)
        if strength < 1.0:
            out = arr * (1 - strength) + out * strength
        graded = Image.fromarray((out * 255).astype(np.uint8), "RGB")
        if mode == "RGBA":
            graded = graded.convert("RGBA")
            graded.putalpha(img.getchannel("A"))
            return graded
        return graded if mode == "RGB" else graded.convert(mode)


# ════════════════════════════════════════════════════════════════════════════
# Taste memory - the system learns which styles score best per context
# ════════════════════════════════════════════════════════════════════════════

class TasteMemory:
    """Exponential-moving-average of quality scores per (context, style).
    Future style picks are weighted toward what historically scored well,
    so the system adapts to this machine and this user over time."""

    def __init__(self):
        self.path = app_dir() / "taste_memory.json"
        self.data = safe_json_load(self.path, {})
        if not isinstance(self.data, dict):
            self.data = {}

    @staticmethod
    def _key(context: str, style: str) -> str:
        return f"{context}|{style.split(',')[0][:40]}"

    def record(self, context: str, style: str, score: float):
        key = self._key(context, style)
        prev = self.data.get(key, {"ema": 7.0, "n": 0})
        alpha = 0.3
        prev["ema"] = round(prev["ema"] * (1 - alpha) + score * alpha, 3)
        prev["n"] = prev.get("n", 0) + 1
        self.data[key] = prev
        safe_json_save(self.path, self.data)

    def pick_style(self, context: str, styles: list) -> str:
        """Weighted random pick - higher historical EMA, higher chance.
        Unseen styles get a neutral 7.0 so exploration continues."""
        weights = []
        for s in styles:
            ema = self.data.get(self._key(context, s), {}).get("ema", 7.0)
            weights.append(max(0.5, ema - 5.0) ** 2)
        return random.choices(styles, weights=weights, k=1)[0]

    def report(self, context: str = None, top: int = 8) -> list:
        """Best (context|style, ema, n) rows, optionally filtered."""
        rows = [(k, v["ema"], v.get("n", 0)) for k, v in self.data.items()
                if not context or k.startswith(context + "|")]
        return sorted(rows, key=lambda r: -r[1])[:top]

    def delete_key(self, key: str):
        """v10.0: remove one learned row - lets a user correct a single
        bad entry (e.g. a style that scored high by pixel-heuristic luck,
        not real preference) without wiping everything."""
        self.data.pop(key, None)
        safe_json_save(self.path, self.data)

    def reset(self, context: str = None):
        """v10.0: clear all learned data, or only one context's rows if
        given. Mirrors .record()'s own save pattern."""
        if context:
            self.data = {k: v for k, v in self.data.items()
                        if not k.startswith(context + "|")}
        else:
            self.data = {}
        safe_json_save(self.path, self.data)


