def find_bold_font(size: int):
    """Best available bold display font on Windows, PIL default otherwise."""
    from PIL import ImageFont
    for name in ("impact.ttf", "arialbd.ttf", "segoeuib.ttf"):
        try:
            return ImageFont.truetype(rf"C:\Windows\Fonts\{name}", size)
        except Exception:
            continue
    return ImageFont.load_default()


def wrap_text_pil(draw, text: str, font, max_width: int) -> list:
    """Greedy word-wrap using actual rendered widths."""
    words, lines, cur = text.split(), [], ""
    for w in words:
        trial = f"{cur} {w}".strip()
        if draw.textbbox((0, 0), trial, font=font)[2] <= max_width or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def render_meme(src_path, top: str, bottom: str, style: str = "classic"):
    """Overlay meme text on an image. Returns a PIL Image.
    styles: classic (impact top/bottom) | modern (white caption bar)"""
    from PIL import Image, ImageDraw
    img = Image.open(src_path).convert("RGB")

    if style == "modern":
        caption = (top + " " + bottom).strip()
        font = find_bold_font(max(24, img.width // 18))
        probe = ImageDraw.Draw(img)
        lines = wrap_text_pil(probe, caption, font, img.width - 60)
        lh = int(font.size * 1.25)
        bar_h = lh * len(lines) + 50
        canvas = Image.new("RGB", (img.width, img.height + bar_h),
                           (255, 255, 255))
        draw = ImageDraw.Draw(canvas)
        y = 25
        for line in lines:
            w = draw.textbbox((0, 0), line, font=font)[2]
            draw.text(((img.width - w) // 2, y), line,
                      font=font, fill=(15, 15, 15))
            y += lh
        canvas.paste(img, (0, bar_h))
        return canvas

    # classic: white impact text w/ black stroke, top & bottom
    draw = ImageDraw.Draw(img)
    font = find_bold_font(max(28, img.width // 9))
    stroke = max(2, font.size // 14)

    def block(text, anchor_top: bool):
        if not text:
            return
        lines = wrap_text_pil(draw, text.upper(), font, img.width - 40)
        lh = int(font.size * 1.12)
        y = 14 if anchor_top else img.height - lh * len(lines) - 20
        for line in lines:
            w = draw.textbbox((0, 0), line, font=font,
                              stroke_width=stroke)[2]
            draw.text(((img.width - w) // 2, y), line, font=font,
                      fill=(255, 255, 255), stroke_width=stroke,
                      stroke_fill=(0, 0, 0))
            y += lh
    block(top, True)
    block(bottom, False)
    return img


def render_quote_card(quote: str, author: str = "", style: str = "Dark",
                      bg_path=None, size=(1000, 1500)):
    """Pinterest-format (2:3) quote card. Returns a PIL Image."""
    from PIL import Image, ImageDraw, ImageEnhance
    W, H = size
    spec = QUOTE_CARD_STYLES.get(style, QUOTE_CARD_STYLES["Dark"])

    if bg_path:
        img = Image.open(bg_path).convert("RGB")
        img = fit_exact(img, W, H)
        img = ImageEnhance.Brightness(img).enhance(0.45)  # darken for text
        fg, accent = (250, 250, 252), (255, 220, 160)
    else:
        bg = spec["bg"]
        if isinstance(bg, str) and bg.startswith("gradient:"):
            # v8.4: ast.literal_eval, not eval() - QUOTE_CARD_STYLES is
            # hardcoded today, but this is the safe default regardless of
            # future changes (e.g. a user-editable style config).
            import ast
            c1, c2 = [ast.literal_eval(c) for c in bg[9:].split("-")]
            img = Image.new("RGB", (W, H))
            for y in range(H):
                t = y / H
                img.paste(tuple(int(a + (b - a) * t)
                                for a, b in zip(c1, c2)), (0, y, W, y + 1))
        else:
            img = Image.new("RGB", (W, H), bg)
        fg, accent = spec["fg"], spec["accent"]

    draw = ImageDraw.Draw(img)
    font = find_bold_font(72)
    lines = wrap_text_pil(draw, quote, font, W - 160)
    # shrink until it fits the middle band
    while len(lines) * font.size * 1.3 > H * 0.55 and font.size > 34:
        font = find_bold_font(font.size - 6)
        lines = wrap_text_pil(draw, quote, font, W - 160)
    lh = int(font.size * 1.3)
    total = lh * len(lines)
    y = (H - total) // 2 - 40
    draw.text((W // 2 - 30, y - 110), "“", font=find_bold_font(140),
              fill=accent)
    for line in lines:
        w = draw.textbbox((0, 0), line, font=font)[2]
        draw.text(((W - w) // 2, y), line, font=font, fill=fg)
        y += lh
    if author:
        afont = find_bold_font(40)
        text = f"- {author}"
        w = draw.textbbox((0, 0), text, font=afont)[2]
        draw.text(((W - w) // 2, y + 40), text, font=afont, fill=accent)
    return img


def load_lora_registry() -> dict:
    """Real LoRA catalog (category -> [entries]), rebuilt from actual
    files + Civitai metadata rather than a fictional wishlist."""
    return safe_json_load(resource_path("lora_registry.json"), {})


def pick_lora_for_style(style: str, available_files: list = None):
    """Best real LoRA (file, strength) for a given art style, matched
    against each registry entry's recommended_styles. None if no match,
    if the matched file isn't actually present on the server, or if its
    declared base_model isn't SDXL-family. This app's checkpoints are all
    SDXL (animagine/Illustrious/DreamShaper) - a LoRA whose base_model
    names a different architecture (e.g. the registry's own
    ZIT_CPA_FREE.safetensors, tagged "ZImageTurbo") would still get
    style-matched here since recommended_styles overlap has nothing to do
    with architecture, and LoraLoader doesn't cleanly error on a shape
    mismatch - it can produce corrupted output, the same failure mode as
    an SD1.5/SDXL checkpoint mismatch. Entries with no base_model field
    (older registry entries) are allowed through unchanged."""
    registry = load_lora_registry()
    style_l = style.lower()
    best, best_hits = None, 0
    for entries in registry.values():
        for entry in entries:
            base = str(entry.get("base_model", "")).lower()
            if base and "sdxl" not in base:
                continue
            hits = sum(1 for s in entry.get("recommended_styles", [])
                      if s.lower() in style_l or style_l in s.lower())
            if hits > best_hits:
                if available_files is not None and \
                        entry["file"] not in available_files:
                    continue
                best_hits = hits
                best = (entry["file"], entry.get("recommended_strength", 0.75))
    return best


