# Designer Suite - palette, colorways, moodboards, tiling, multi-export
# ════════════════════════════════════════════════════════════════════════════

def extract_palette(img, n: int = 6) -> list:
    """Dominant colors of an image, most-used first. Returns [(r,g,b)]."""
    from PIL import Image
    small = img.convert("RGB").resize((128, 128), Image.LANCZOS)
    mediancut = getattr(getattr(Image, "Quantize", Image), "MEDIANCUT", 0)
    q = small.quantize(colors=n, method=mediancut)
    pal = q.getpalette()
    counts = sorted(q.getcolors() or [], reverse=True)
    return [(pal[i * 3], pal[i * 3 + 1], pal[i * 3 + 2])
            for _, i in counts[:n]]


def render_palette_card(colors: list, source_name: str = "",
                        size=(1000, 560)):
    """Shareable palette card: swatches + hex codes."""
    from PIL import Image, ImageDraw
    W, H = size
    img = Image.new("RGB", (W, H), (18, 18, 26))
    draw = ImageDraw.Draw(img)
    n = max(1, len(colors))
    sw = (W - 40 - (n - 1) * 12) // n
    font = find_bold_font(max(16, sw // 7))
    title_font = find_bold_font(34)
    if source_name:
        draw.text((20, 18), f"PALETTE - {source_name[:40]}",
                  font=title_font, fill=(240, 240, 245))
    y0 = 80
    for i, (r, g, b) in enumerate(colors):
        x = 20 + i * (sw + 12)
        draw.rounded_rectangle([x, y0, x + sw, H - 90], radius=14,
                               fill=(r, g, b))
        hexc = f"#{r:02X}{g:02X}{b:02X}"
        tw = draw.textbbox((0, 0), hexc, font=font)[2]
        draw.text((x + (sw - tw) // 2, H - 70), hexc, font=font,
                  fill=(220, 220, 230))
    return img


def palette_exports(colors: list) -> dict:
    """Palette as hex list, CSS variables and Procreate-style text."""
    hexes = [f"#{r:02X}{g:02X}{b:02X}" for r, g, b in colors]
    css = ":root {\n" + "\n".join(
        f"  --color-{i + 1}: {h};" for i, h in enumerate(hexes)) + "\n}"
    return {"hex": hexes, "css": css,
            "text": "\n".join(hexes)}


def make_colorway(img, hue_shift_deg: float):
    """Hue-rotated variant (saturation/brightness preserved)."""
    from PIL import Image
    mode = img.mode
    rgb = img.convert("RGB")
    h, s, v = rgb.convert("HSV").split()
    shift = int(hue_shift_deg / 360 * 256) % 256
    h = h.point(lambda x: (x + shift) % 256)
    out = Image.merge("HSV", (h, s, v)).convert("RGB")
    if mode == "RGBA":
        out.putalpha(img.getchannel("A"))
        return out
    return out


def make_moodboard(paths: list, cols: int = 3, cell: int = 480,
                   pad: int = 16, bg=(16, 16, 24)):
    """Contact-sheet grid from a list of image paths."""
    from PIL import Image
    n = len(paths)
    cols = max(1, min(cols, n))
    rows = -(-n // cols)
    W = cols * cell + (cols + 1) * pad
    H = rows * cell + (rows + 1) * pad
    board = Image.new("RGB", (W, H), bg)
    for i, p in enumerate(paths):
        try:
            tile = fit_exact(Image.open(p).convert("RGB"), cell, cell)
        except Exception:
            continue
        r, c = divmod(i, cols)
        board.paste(tile, (pad + c * (cell + pad), pad + r * (cell + pad)))
    return board


def tile_preview(img, reps: int = 2):
    """reps x reps repeat - reveals whether a design tiles seamlessly."""
    from PIL import Image
    rgb = img.convert("RGB")
    W, H = rgb.size
    out = Image.new("RGB", (W * reps, H * reps))
    for r in range(reps):
        for c in range(reps):
            out.paste(rgb, (c * W, r * H))
    return out


