# Coloring Book Creator - line-art pages + print-ready PDF assembly
# ════════════════════════════════════════════════════════════════════════════

COLORING_PAGE_SIZES = {
    "US Letter 8.5x11 (2550x3300)": (2550, 3300),
    "A4 (2480x3508)": (2480, 3508),
}

# Draw-then-trace pipeline: generate ordinary vivid art (the model's
# strength), then extract edges server-side and clean them into thick,
# continuous, colorable outlines. Direct "line art" generation from anime
# checkpoints proved unreliable (blank pages or solid-black fills).
COLORING_MODES = {
    "Kids (simple, thick lines)": {
        "prompt": "solo, {subject}, chibi, cute, full body, centered, "
                  "vibrant colors, bold outlines, simple background, "
                  "white background",
        "negative": "lowres, bad anatomy, cropped, multiple subjects, "
                    "cluttered background, text, watermark, signature",
        "canny": (0.30, 0.70),   # only strong edges -> simple shapes
        "thicken": 2,            # chunky crayon-friendly lines
    },
    "Adult (intricate detail)": {
        "prompt": "solo, {subject}, highly detailed, intricate, full "
                  "body, centered, ornate, simple background, "
                  "white background",
        "negative": "lowres, bad anatomy, cropped, multiple subjects, "
                    "text, watermark, signature",
        "canny": (0.15, 0.45),   # keep fine detail
        "thicken": 1,
    },
}


def black_fraction(img) -> float:
    """Fraction of pure-black pixels - a colorable page should be mostly
    white with line detail; heavy fills mean the gen failed as line art."""
    hist = img.convert("L").histogram()
    total = sum(hist)
    return hist[0] / total if total else 0.0


def to_coloring_page(img, thicken: int = 1):
    """Clean edge/line imagery into thick, continuous black-on-white
    outlines. Adaptive percentile threshold (so faint lines survive),
    then morphological dilation for crayon-friendly line weight."""
    from PIL import Image, ImageOps, ImageFilter
    import numpy as np
    g = ImageOps.autocontrast(img.convert("L"))
    arr = np.asarray(g)
    # threshold at the 10th-percentile brightness, clamped sane - keeps
    # thin/faint lines as ink without flooding the page
    t = int(np.clip(np.percentile(arr, 10) + 30, 90, 210))
    bw = g.point(lambda x, t=t: 0 if x < t else 255)
    for _ in range(max(0, thicken)):
        bw = bw.filter(ImageFilter.MinFilter(3))   # dilate the ink
    bw = bw.filter(ImageFilter.MedianFilter(3))    # despeckle after
    return bw.convert("RGB")


def make_coloring_canvas(art_bw, page_size, margin_frac: float = 0.06):
    """Center line art on a white print page with breathing-room margins.
    Auto-crops to the ink bounding box first so the subject fills the
    page instead of floating small in empty white."""
    from PIL import Image, ImageOps
    inv = ImageOps.invert(art_bw.convert("L"))
    bbox = inv.getbbox()
    if bbox:
        pad = int(max(art_bw.size) * 0.03)
        bbox = (max(0, bbox[0] - pad), max(0, bbox[1] - pad),
                min(art_bw.width, bbox[2] + pad),
                min(art_bw.height, bbox[3] + pad))
        art_bw = art_bw.crop(bbox)
    W, H = page_size
    m = int(min(W, H) * margin_frac)
    inner = art_bw.copy()
    inner = inner.resize(
        (lambda s: (int(inner.width * s), int(inner.height * s)))(
            min((W - 2 * m) / inner.width, (H - 2 * m) / inner.height)),
        Image.LANCZOS)
    page = Image.new("RGB", (W, H), (255, 255, 255))
    page.paste(inner, ((W - inner.width) // 2, (H - inner.height) // 2))
    return page


def render_book_cover(title: str, subtitle: str, page_size,
                      art_bw=None):
    """Simple typographic cover; optionally previews one page's art."""
    from PIL import Image, ImageDraw
    W, H = page_size
    page = Image.new("RGB", (W, H), (255, 255, 255))
    draw = ImageDraw.Draw(page)
    font = find_typo_font("Impact (bold poster)", W // 10)
    text = title.upper()
    lines = wrap_text_pil(draw, text, font, W - 300)
    y = int(H * 0.10)
    for line in lines:
        w = draw.textbbox((0, 0), line, font=font)[2]
        draw.text(((W - w) // 2, y), line, font=font, fill=(20, 20, 20))
        y += int(font.size * 1.15)
    if subtitle:
        sfont = find_typo_font("Georgia (elegant serif)", W // 26)
        w = draw.textbbox((0, 0), subtitle, font=sfont)[2]
        draw.text(((W - w) // 2, y + 30), subtitle, font=sfont,
                  fill=(70, 70, 70))
        y += int(sfont.size * 1.6)
    if art_bw is not None:
        art = art_bw.copy()
        art.thumbnail((int(W * 0.66), int(H * 0.52)))
        page.paste(art, ((W - art.width) // 2, int(H * 0.38)))
    draw.rectangle([60, 60, W - 60, H - 60], outline=(30, 30, 30), width=8)
    return page


