def load_api_keys() -> dict:
    return safe_json_load(app_dir() / "api_keys.json", {}) or {}


def save_api_keys(keys: dict):
    safe_json_save(app_dir() / "api_keys.json", keys)


class PinterestClient:
    """Minimal Pinterest API v5 client. Requires a user access token
    (developers.pinterest.com - create an app, generate a token with
    boards:read + pins:write scopes)."""
    BASE = "https://api.pinterest.com/v5"

    def __init__(self, token: str):
        self.token = token.strip()

    def _call(self, method, path, body=None):
        req = urllib.request.Request(
            self.BASE + path,
            data=json.dumps(body).encode() if body else None,
            method=method,
            headers={"Authorization": f"Bearer {self.token}",
                     "Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode())

    def list_boards(self) -> list:
        data = self._call("GET", "/boards?page_size=50")
        return [(b["id"], b.get("name", "?"))
                for b in data.get("items", [])]

    def create_pin(self, board_id: str, image_path, title: str,
                   description: str, link: str = None) -> str:
        import base64
        b64 = base64.b64encode(Path(image_path).read_bytes()).decode()
        body = {"board_id": board_id, "title": title[:100],
                "description": description[:800],
                "media_source": {"source_type": "image_base64",
                                 "content_type": "image/png",
                                 "data": b64}}
        if link:
            body["link"] = link
        return self._call("POST", "/pins", body).get("id", "")


class PrintifyClient:
    """Minimal Printify client - uploads designs to your media library
    (product creation is best finished in Printify's own designer).
    Token: printify.com -> My Profile -> Connections -> API token."""
    BASE = "https://api.printify.com/v1"

    def __init__(self, token: str):
        self.token = token.strip()

    def _call(self, method, path, body=None):
        req = urllib.request.Request(
            self.BASE + path,
            data=json.dumps(body).encode() if body else None,
            method=method,
            headers={"Authorization": f"Bearer {self.token}",
                     "Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=60) as resp:
            return json.loads(resp.read().decode())

    def upload_design(self, image_path) -> str:
        import base64
        p = Path(image_path)
        b64 = base64.b64encode(p.read_bytes()).decode()
        data = self._call("POST", "/uploads/images.json",
                          {"file_name": p.name, "contents": b64})
        return data.get("id", "")


# ════════════════════════════════════════════════════════════════════════════
# Semantic gallery search - find your own images by meaning
# ════════════════════════════════════════════════════════════════════════════

class EmbeddingIndex:
    """Embeds every generation's prompt/persona text with nomic-embed-text
    (local, via Ollama) and searches the library by cosine similarity."""

    MODEL = "nomic-embed-text"

    def __init__(self, store_dir: Path):
        self.path = Path(store_dir) / "embedding_index.json"
        self.data = safe_json_load(self.path, {})
        if not isinstance(self.data, dict):
            self.data = {}
        self.available = None  # unknown until first probe

    def _embed(self, text: str):
        body = json.dumps({"model": self.MODEL,
                           "prompt": text[:2000]}).encode()
        req = urllib.request.Request(
            "http://127.0.0.1:11434/api/embeddings", data=body,
            headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=60) as resp:
            vec = json.loads(resp.read().decode()).get("embedding")
        return [round(v, 5) for v in vec] if vec else None

    def probe(self) -> bool:
        try:
            self.available = self._embed("probe") is not None
        except Exception:
            self.available = False
        return self.available

    def add(self, image_path, text: str, save: bool = True) -> bool:
        # v6.6: unlike max_similarity(), this had no self.available check -
        # every normal generation spawned a background thread that made a
        # real HTTP call to Ollama's embedding endpoint (up to 60s timeout)
        # even when Ollama was never confirmed reachable (available is
        # only ever set by probe(), which most users never trigger).
        if self.available is False:
            return False
        try:
            vec = self._embed(text)
            if not vec:
                return False
            self.data[str(image_path)] = {"text": text[:400], "vec": vec}
            if save:
                self.save()
            return True
        except Exception:
            return False

    def save(self):
        safe_json_save(self.path, self.data)

    def backfill(self, root_dir: Path) -> int:
        """Index every un-indexed PNG under root_dir using the best text
        available: _meta.json prompts > .pin.txt copy > json sidecars >
        the descriptive filename + folder path as a last resort."""
        added = 0
        root_dir = Path(root_dir)
        metas = {}
        for meta_p in root_dir.rglob("*_meta.json"):
            try:
                m = json.loads(meta_p.read_text(encoding="utf-8"))
                stamp = meta_p.name.replace("_meta.json", "")
                metas[(meta_p.parent, stamp)] = (
                    f"{m.get('persona', '')} | "
                    f"{m.get('mode', m.get('style', ''))} | "
                    f"{str(m.get('positive', ''))[:300]}")
            except Exception:
                continue
        for img in root_dir.rglob("*.png"):
            if str(img) in self.data or img.name.startswith("_"):
                continue
            text = None
            for (folder, stamp), t in metas.items():
                if img.parent == folder and img.name.startswith(stamp):
                    text = t
                    break
            if not text:
                pin = img.with_suffix(".pin.txt")
                if pin.exists():
                    try:
                        raw = pin.read_text(encoding="utf-8")
                        text = " ".join(
                            ln.strip() for ln in raw.splitlines()
                            if ln.strip() and not ln.strip().endswith(":")
                        )[:350]
                    except Exception:
                        pass
            if not text:
                side = img.with_suffix(".json")
                if side.exists():
                    try:
                        d = json.loads(side.read_text(encoding="utf-8"))
                        if isinstance(d, dict):
                            text = " | ".join(
                                str(d.get(k, "")) for k in
                                ("character", "persona", "style",
                                 "positive") if d.get(k))
                    except Exception:
                        pass
            if not text:
                # descriptive filename + folder path still carry meaning
                rel = img.relative_to(root_dir)
                text = re.sub(r"[_\-]+", " ",
                              " ".join(rel.with_suffix("").parts))
                text = re.sub(r"\d{8,}", " ", text).strip()
            if text and self.add(img, text, save=False):
                added += 1
        self.save()
        return added

    def search(self, query: str, top_k: int = 24) -> list:
        """[(score, path, text)] best-first; drops entries whose file
        no longer exists."""
        try:
            q = self._embed(query)
        except Exception:
            return []
        if not q:
            return []
        import math
        qn = math.sqrt(sum(x * x for x in q))
        scored = []
        stale = []
        for path, entry in self.data.items():
            if not Path(path).exists():
                stale.append(path)
                continue
            v = entry["vec"]
            dot = sum(a * b for a, b in zip(q, v))
            vn = math.sqrt(sum(x * x for x in v))
            if qn and vn:
                scored.append((dot / (qn * vn), path, entry["text"]))
        for p in stale:
            del self.data[p]
        if stale:
            self.save()
        return sorted(scored, reverse=True)[:top_k]

    def max_similarity(self, text: str, recent_k: int = 50) -> float:
        """Cosine similarity of text vs the most recent recent_k indexed
        entries (dict insertion order = chronological). Used as a novelty
        gate in Auto-Pilot v2 - returns 0.0 (never blocks) when the
        embedding model is unreachable."""
        try:
            v1 = self._embed(text)
        except Exception:
            return 0.0
        if not v1:
            return 0.0
        import math
        recent = list(self.data.values())[-recent_k:]
        if not recent:
            return 0.0
        n1 = math.sqrt(sum(x * x for x in v1))
        best = 0.0
        for entry in recent:
            v2 = entry["vec"]
            dot = sum(a * b for a, b in zip(v1, v2))
            n2 = math.sqrt(sum(x * x for x in v2))
            if n1 and n2:
                best = max(best, dot / (n1 * n2))
        return best


# ════════════════════════════════════════════════════════════════════════════
# Storybook Creator - illustrated children's books with a consistent hero
# ════════════════════════════════════════════════════════════════════════════

STORYBOOK_SIZES = {
    "Square picture book (2550x2550)": (2550, 2550),
    "US Letter portrait (2550x3300)": (2550, 3300),
}


def render_story_page(art_img, text: str, page_size, page_num: int):
    """Classic picture-book layout: art fills the top, warm text band
    below in a friendly serif, page number bottom-center."""
    from PIL import Image, ImageDraw
    W, H = page_size
    page = Image.new("RGB", (W, H), (252, 250, 245))
    art_h = int(H * 0.66)
    art = fit_exact(art_img.convert("RGB"), W - 120, art_h)
    page.paste(art, (60, 60))
    draw = ImageDraw.Draw(page)
    draw.rectangle([60, 60, W - 60, 60 + art_h], outline=(60, 50, 40),
                   width=6)
    font = find_typo_font("Georgia (elegant serif)", max(40, W // 32))
    lines = []
    for para in text.split("\n"):
        lines.extend(wrap_text_pil(draw, para.strip(), font, W - 260)
                     if para.strip() else [""])
    lh = int(font.size * 1.35)
    y = 60 + art_h + max(40, (H - art_h - 200 - lh * len(lines)) // 2)
    for line in lines:
        w = draw.textbbox((0, 0), line, font=font)[2]
        draw.text(((W - w) // 2, y), line, font=font, fill=(45, 40, 35))
        y += lh
    nfont = find_typo_font("Georgia (elegant serif)", max(24, W // 70))
    num = str(page_num)
    w = draw.textbbox((0, 0), num, font=nfont)[2]
    draw.text(((W - w) // 2, H - 90), num, font=nfont, fill=(120, 110, 100))
    return page


