def _build_world_prompt(world: dict) -> tuple:
    """v9.10: assembles the positive/negative prompt for one WORLD_BIBLES
    entry from its layered scene description, following the exact
    structured shape supplied for this feature (character/camera/
    foreground/midground/background/atmosphere/palette). Returns
    (positive, negative). Motion cues are NOT included here - they get
    appended separately at the AnimateDiff call site, matching how
    _run_lofi_loop_pipeline already separates base scene from its own
    idle-motion suffix."""
    fg = ", ".join(world["foreground"])
    mg = ", ".join(world["midground"])
    bg = ", ".join(world["background"])
    atmo = ", ".join(world["atmosphere"])
    positive = (
        f"{QUALITY}, {world['character']}, {world['camera']}, {mg}, "
        f"foreground {fg}, background {bg}, {atmo}, {world['palette']}, "
        "cinematic composition with foreground midground and deep "
        "background, premium anime-inspired editorial illustration, "
        "painterly precision, volumetric lighting"
    )
    negative = (SAFETY_FLOOR_NEGATIVE + ", text, watermark, signature, logo, "
               "jitter, flicker, static")
    return positive, negative


def render_flats_sheet(front_img, back_img, side_img, title: str = ""):
    """Fashion tech-pack layout: front/back/side technical flats side by
    side on a white sheet with labels, like a real garment spec sheet."""
    from PIL import Image, ImageDraw
    panel_w, panel_h = 700, 1000
    pad, header_h = 30, 70
    imgs = [(front_img, "FRONT"), (back_img, "BACK"), (side_img, "SIDE")]
    W = panel_w * 3 + pad * 4
    H = panel_h + header_h + pad * 2 + (60 if title else 0)
    sheet = Image.new("RGB", (W, H), (255, 255, 255))
    draw = ImageDraw.Draw(sheet)
    y0 = pad
    if title:
        font = find_bold_font(34)
        w = draw.textbbox((0, 0), title, font=font)[2]
        draw.text(((W - w) // 2, y0), title, font=font, fill=(20, 20, 20))
        y0 += 60
    font = find_bold_font(26)
    for i, (img, label) in enumerate(imgs):
        x = pad + i * (panel_w + pad)
        if img is not None:
            tile = fit_exact(img.convert("RGB"), panel_w, panel_h)
            sheet.paste(tile, (x, y0 + header_h))
        draw.rectangle([x, y0 + header_h, x + panel_w, y0 + header_h + panel_h],
                       outline=(200, 200, 200), width=2)
        lw = draw.textbbox((0, 0), label, font=font)[2]
        draw.text((x + (panel_w - lw) // 2, y0 + 15), label, font=font,
                  fill=(40, 40, 40))
    return sheet


def pixelate_sprite(img, target_px=64, colors=32):
    """Downscale to a small resolution then upscale back with nearest-
    neighbor (chunky pixels) + palette quantization - the actual retro
    game-sprite look, since raw SDXL output has none of that on its own
    even when the prompt says 'pixel art'. Preserves alpha (a cutout
    transparent PNG stays transparent). Returns a new PIL Image, same
    size as the input."""
    from PIL import Image
    orig_size = img.size
    has_alpha = img.mode == "RGBA"
    small = img.resize((target_px, target_px), Image.LANCZOS)
    if has_alpha:
        rgb, alpha = small.convert("RGB"), small.split()[-1]
        rgb = rgb.quantize(colors=colors, method=Image.MEDIANCUT).convert("RGB")
        small = rgb.convert("RGBA")
        small.putalpha(alpha.resize((target_px, target_px), Image.NEAREST))
    else:
        small = small.quantize(colors=colors, method=Image.MEDIANCUT).convert("RGB")
    return small.resize(orig_size, Image.NEAREST)


def make_sprite_sheet(frames: list, labels: list, cell=256):
    """Arrange cutout (RGBA, transparent-background) sprite frames in a
    single row on a transparent canvas - the standard flat sprite-sheet
    layout most 2D game engines expect. `frames` entries may be None
    (a failed pose) - skipped, not blank-padded, so the sheet only ever
    contains real frames."""
    from PIL import Image, ImageDraw
    pairs = [(f, l) for f, l in zip(frames, labels) if f is not None]
    if not pairs:
        return None
    pad, label_h = 10, 28
    W = len(pairs) * (cell + pad) + pad
    H = cell + label_h + pad * 2
    sheet = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    draw = ImageDraw.Draw(sheet)
    font = find_bold_font(18)
    for i, (frame, label) in enumerate(pairs):
        x = pad + i * (cell + pad)
        # contain-fit, not fit_exact's cover+crop - a full-body sprite
        # must stay entirely visible in its cell, not have its head/feet
        # cropped off to fill a square
        f = frame.convert("RGBA")
        scale = min(cell / f.width, cell / f.height)
        tw, th = max(1, round(f.width * scale)), max(1, round(f.height * scale))
        tile = f.resize((tw, th), Image.LANCZOS)
        ox, oy = x + (cell - tw) // 2, pad + (cell - th) // 2
        sheet.paste(tile, (ox, oy), tile)
        lw = draw.textbbox((0, 0), label, font=font)[2]
        draw.text((x + (cell - lw) // 2, pad + cell + 4), label,
                  font=font, fill=(255, 255, 255, 255))
    return sheet


def render_story_cover(title: str, author: str, art_img, page_size):
    """Full-bleed art cover with a title plate."""
    from PIL import Image, ImageDraw
    W, H = page_size
    page = fit_exact(art_img.convert("RGB"), W, H)
    draw = ImageDraw.Draw(page, "RGBA")
    font = find_typo_font("Georgia (elegant serif)", W // 12)
    lines = wrap_text_pil(draw, title.title(), font, W - 300)
    lh = int(font.size * 1.15)
    block_h = lh * len(lines) + 60
    draw.rounded_rectangle([100, 100, W - 100, 100 + block_h + 40],
                           radius=40, fill=(252, 250, 245, 235))
    y = 130
    for line in lines:
        w = draw.textbbox((0, 0), line, font=font)[2]
        draw.text(((W - w) // 2, y), line, font=font, fill=(45, 40, 35))
        y += lh
    if author:
        afont = find_typo_font("Georgia (elegant serif)", W // 34)
        text = author
        w = draw.textbbox((0, 0), text, font=afont)[2]
        draw.rounded_rectangle(
            [W // 2 - w // 2 - 40, H - 200, W // 2 + w // 2 + 40, H - 100],
            radius=30, fill=(252, 250, 245, 235))
        draw.text(((W - w) // 2, H - 180), text, font=afont,
                  fill=(45, 40, 35))
    return page


def render_bio_page(blueprint: dict, size) -> "Image":
    """Plain text page: backstory + personality, for the Auto Character
    Designer blueprint PDF. Pure text layout - no art required."""
    from PIL import Image, ImageDraw
    W, H = size
    page = Image.new("RGB", (W, H), (250, 249, 246))
    draw = ImageDraw.Draw(page)
    margin = int(W * 0.1)
    y = int(H * 0.08)
    header_font = find_bold_font(int(W / 22))
    body_font = find_typo_font("Georgia (elegant serif)", int(W / 34))

    def section(label, text):
        nonlocal y
        if not text:
            return
        draw.text((margin, y), label, font=header_font, fill=(180, 60, 60))
        y += int(header_font.size * 1.4)
        for line in wrap_text_pil(draw, text, body_font, W - margin * 2):
            draw.text((margin, y), line, font=body_font, fill=(40, 38, 35))
            y += int(body_font.size * 1.25)
        y += int(body_font.size * 1.2)

    section("BACKSTORY", blueprint.get("backstory", ""))
    section("PERSONALITY", blueprint.get("psychology", ""))
    section("SIGNATURE OUTFIT", blueprint.get("hero_outfit", ""))
    section("ALTERNATE OUTFIT", blueprint.get("wardrobe_alt", ""))
    return page


def render_character_blueprint_sheet(hero_img, turnaround_path, alt_path,
                                     variant_paths, blueprint, out_dir,
                                     name: str):
    """Assemble the Auto Character Designer's PDF: cover (hero + name +
    quote) -> turnaround composite -> bio text -> style/outfit moodboard.
    Tolerates missing pieces (a failed generation step) - only skips that
    one page rather than raising."""
    from PIL import Image
    size = hero_img.size if hero_img is not None else (1024, 1024)
    pages = []
    if hero_img is not None:
        pages.append(render_story_cover(
            name, blueprint.get("signature_quote", ""), hero_img, size))
    if turnaround_path and Path(turnaround_path).exists():
        pages.append(Image.open(turnaround_path).convert("RGB"))
    pages.append(render_bio_page(blueprint, size))
    board_paths = [p for p in ([alt_path] + list(variant_paths))
                   if p and Path(p).exists()]
    if board_paths:
        pages.append(make_moodboard([str(p) for p in board_paths],
                                    cols=min(3, len(board_paths)),
                                    cell=420, bg=(250, 250, 250)))
    if not pages:
        return None
    safe_name = re.sub(r"[^\w\-]+", "_", name)[:40]
    pdf_path = Path(out_dir) / f"{safe_name}_blueprint.pdf"
    pages[0].save(pdf_path, save_all=True, append_images=pages[1:],
                 resolution=300)
    return pdf_path


def render_banner(art_img, spec_name: str, title: str, tagline: str = "",
                  typo_preset: str = "Impact (bold poster)",
                  show_guides: bool = False):
    """Compose a platform banner: art fitted full-bleed, text centered in
    the platform's safe area, optional guide overlay for preview."""
    from PIL import Image, ImageDraw, ImageEnhance
    spec = BANNER_SPECS[spec_name]
    W, H = spec["size"]
    sx, sy, sw, sh = spec["safe"]
    img = fit_exact(art_img.convert("RGB"), W, H)
    draw = ImageDraw.Draw(img, "RGBA")

    if title:
        # subtle scrim behind the text so typography stays readable
        title_size = max(28, sh // 4)
        font = find_typo_font(typo_preset, title_size)
        text = typo_text(typo_preset, title)
        while draw.textbbox((0, 0), text, font=font)[2] > sw * 0.94 and \
                title_size > 20:
            title_size -= 6
            font = find_typo_font(typo_preset, title_size)
        tw = draw.textbbox((0, 0), text, font=font)[2]
        tag_font = find_typo_font(typo_preset, max(16, title_size // 3))
        tag = typo_text(typo_preset, tagline) if tagline else ""
        tag_w = draw.textbbox((0, 0), tag, font=tag_font)[2] if tag else 0
        block_h = title_size + (tag_font.size + 14 if tag else 0)
        ty = sy + (sh - block_h) // 2
        scrim_pad = title_size // 2
        draw.rounded_rectangle(
            [sx + (sw - max(tw, tag_w)) // 2 - scrim_pad, ty - scrim_pad // 2,
             sx + (sw + max(tw, tag_w)) // 2 + scrim_pad,
             ty + block_h + scrim_pad // 2],
            radius=scrim_pad // 2, fill=(0, 0, 0, 110))
        draw.text((sx + (sw - tw) // 2, ty), text, font=font,
                  fill=(255, 255, 255),
                  stroke_width=max(2, title_size // 16),
                  stroke_fill=(0, 0, 0))
        if tag:
            draw.text((sx + (sw - tag_w) // 2, ty + title_size + 14), tag,
                      font=tag_font, fill=(235, 235, 235),
                      stroke_width=1, stroke_fill=(0, 0, 0))

    if show_guides:
        draw.rectangle([sx, sy, sx + sw, sy + sh],
                       outline=(0, 255, 140, 255), width=4)
        gfont = find_bold_font(max(18, H // 40))
        draw.text((sx + 12, sy + 8), "SAFE AREA (all devices)",
                  font=gfont, fill=(0, 255, 140))
    return img


# ════════════════════════════════════════════════════════════════════════════
# v9.7: Pack Cover Studio compositing primitives - genuinely new effects
# (perspective/shadow/glow/reflection/badge/stack) with no prior
# equivalent in this file. Each takes/returns a plain PIL Image and does
# one effect, matching this file's established render_*() convention, so
# each is independently testable on a synthetic image before wiring into
# the full pipeline.
# ════════════════════════════════════════════════════════════════════════════

def apply_box_perspective(face_img, skew_pct: float = 0.12):
    """Warps a flat square/rect face image into a 'viewed slightly from
    the side' box-front quad - the near (right) edge stays full height,
    the far (left) edge is pulled in vertically by skew_pct, giving a
    believable 3D box-front look without a full 3D renderer."""
    from PIL import Image
    w, h = face_img.size
    inset = int(h * skew_pct)
    # destination quad corners (top-left, bottom-left, bottom-right,
    # top-right) mapped FROM the source rectangle - the far edge (left)
    # is inset top+bottom, simulating it receding away from the viewer.
    quad = (
        0, inset,          # top-left
        0, h - inset,      # bottom-left
        w, h,              # bottom-right
        w, 0,              # top-right
    )
    return face_img.transform((w, h), Image.QUAD, quad, resample=Image.BICUBIC)


def render_drop_shadow(img, offset=(20, 30), blur_radius=24, opacity=0.5):
    """Returns a new, larger RGBA canvas with a soft blurred black shadow
    (derived from img's own alpha silhouette) behind the original image,
    offset down-right. img must be RGBA (transparent outside the box
    shape) for the silhouette to be meaningful."""
    from PIL import Image, ImageFilter
    img = img.convert("RGBA")
    pad = blur_radius * 2 + max(abs(offset[0]), abs(offset[1]))
    canvas_w, canvas_h = img.width + pad * 2, img.height + pad * 2
    shadow_layer = Image.new("RGBA", (canvas_w, canvas_h), (0, 0, 0, 0))
    alpha = img.split()[-1]
    solid_black = Image.new("RGBA", img.size, (0, 0, 0, int(255 * opacity)))
    solid_black.putalpha(alpha)
    shadow_layer.paste(solid_black, (pad + offset[0], pad + offset[1]), solid_black)
    shadow_layer = shadow_layer.filter(ImageFilter.GaussianBlur(blur_radius))
    out = Image.new("RGBA", (canvas_w, canvas_h), (0, 0, 0, 0))
    out.alpha_composite(shadow_layer)
    out.alpha_composite(img, (pad, pad))
    return out


def render_rim_glow(img, color: tuple, blur_radius: int = 34, strength: float = 0.6):
    """Colored rim/edge glow: dilates the image's alpha silhouette
    slightly, colorizes it, blurs it into a soft halo, and composites
    that BEHIND the original image so only the edges show through.
    Pads onto a larger transparent canvas FIRST (like render_drop_shadow
    does) - dilating/blurring a silhouette that already fills its own
    canvas edge-to-edge has no transparent margin to bleed into and
    produces no visible glow at all, confirmed via a synthetic-image
    test where the un-padded version was a silent no-op."""
    from PIL import Image, ImageFilter
    img = img.convert("RGBA")
    pad = blur_radius * 2
    padded = Image.new("RGBA", (img.width + pad * 2, img.height + pad * 2), (0, 0, 0, 0))
    padded.alpha_composite(img, (pad, pad))
    alpha = padded.split()[-1]
    dilated = alpha.filter(ImageFilter.MaxFilter(9))
    glow_color = Image.new("RGBA", padded.size, (*color, 255))
    glow_color.putalpha(dilated.point(lambda a: int(a * strength)))
    glow_color = glow_color.filter(ImageFilter.GaussianBlur(blur_radius))
    canvas = Image.new("RGBA", padded.size, (0, 0, 0, 0))
    canvas.alpha_composite(glow_color)
    canvas.alpha_composite(padded)
    return canvas


def render_reflection(img, fade_to: float = 0.0, height_pct: float = 0.35):
    """Vertically-flipped, top-to-bottom fading copy of img for a faint
    floor reflection under a box/stack. Returns an RGBA image of height
    img.height * height_pct (the reflection strip only, caller pastes it
    below the original)."""
    from PIL import Image
    img = img.convert("RGBA")
    strip_h = max(1, int(img.height * height_pct))
    flipped = img.transpose(Image.FLIP_TOP_BOTTOM).crop((0, 0, img.width, strip_h))
    alpha = flipped.split()[-1]
    gradient = Image.new("L", (1, strip_h), color=0)
    grad_px = gradient.load()
    for y in range(strip_h):
        t = y / max(1, strip_h - 1)
        grad_px[0, y] = int(255 * (1 - t) * (1 - fade_to) + 255 * fade_to * t)
    gradient = gradient.resize((img.width, strip_h))
    from PIL import ImageChops
    faded_alpha = ImageChops.multiply(alpha, gradient)
    flipped.putalpha(faded_alpha)
    return flipped


def render_badge(text: str, size=(200, 60), bg=(255, 255, 255), fg=(0, 0, 0)):
    """Small rounded-rect pill with centered bold text - for content-count
    / format labels like 'WAV + MIDI', '24-BIT', '100 LOOPS'. Reuses this
    file's existing find_bold_font/wrap_text_pil helpers rather than
    introducing new font-loading code."""
    from PIL import Image, ImageDraw
    w, h = size
    badge = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    draw = ImageDraw.Draw(badge)
    draw.rounded_rectangle([0, 0, w - 1, h - 1], radius=h // 2,
                           fill=(*bg, 235))
    font_size = h // 2
    font = find_bold_font(font_size)
    while draw.textbbox((0, 0), text, font=font)[2] > w * 0.85 and font_size > 10:
        font_size -= 2
        font = find_bold_font(font_size)
    tw, th = draw.textbbox((0, 0), text, font=font)[2:4]
    draw.text(((w - tw) // 2, (h - th) // 2 - 2), text, font=font, fill=fg)
    return badge


def stack_boxes(box_imgs: list, canvas_size: tuple, overlap_pct: float = 0.18,
                 bg_color=(8, 8, 12), content_width: int = None):
    """Positions N already-perspective-warped(+shadowed/glowed) box
    images in an overlapping cascade centered on a canvas of the
    template's bg_color. Pastes back-to-front so the last (front) box
    ends up visually on top - callers should pass box_imgs ordered
    back-to-front.

    content_width: the VISIBLE box content's width (before any
    shadow/glow padding was added around it) - overlap_pct is computed
    against this, not box_imgs[0].width. Effects like render_drop_shadow/
    render_rim_glow inflate each image's actual pixel width well beyond
    its visible content (e.g. a 900px box becomes ~1150px once glow-
    padded) - computing the stacking step against the padded width
    barely overlaps the VISIBLE boxes at all, confirmed via a live test
    render that showed clear gaps between boxes instead of a stack.
    Defaults to box_imgs[0].width (old behavior) if not given."""
    from PIL import Image
    canvas = Image.new("RGBA", canvas_size, (*bg_color, 255))
    n = len(box_imgs)
    if n == 0:
        return canvas
    box_w = box_imgs[0].width
    ref_w = content_width or box_w
    step = int(ref_w * (1 - overlap_pct))
    total_w = box_w + step * (n - 1)
    start_x = (canvas_size[0] - total_w) // 2
    for i, box in enumerate(box_imgs):
        x = start_x + step * i
        y = (canvas_size[1] - box.height) // 2
        canvas.alpha_composite(box, (x, y))
    return canvas


