def render_cover_text(img, artist: str, title: str,
                      layout: str = "classic"):
    """Album cover typography over a square image. Returns PIL Image."""
    from PIL import Image, ImageDraw, ImageEnhance
    base = img.convert("RGB")
    W, H = base.size
    draw = ImageDraw.Draw(base)

    if layout == "minimal":
        # small centered text near bottom
        f_artist = find_bold_font(max(20, W // 28))
        f_title = find_bold_font(max(28, W // 18))
        y = int(H * 0.82)
        for text, font, fill in ((title.upper(), f_title, (255, 255, 255)),
                                 (artist, f_artist, (220, 220, 220))):
            if not text:
                continue
            w = draw.textbbox((0, 0), text, font=font)[2]
            draw.text(((W - w) // 2, y), text, font=font, fill=fill,
                      stroke_width=max(1, font.size // 16),
                      stroke_fill=(0, 0, 0))
            y += int(font.size * 1.3)
        return base

    # classic: artist top, big title bottom
    f_artist = find_bold_font(max(24, W // 20))
    f_title = find_bold_font(max(40, W // 10))
    if artist:
        text = artist.upper()
        w = draw.textbbox((0, 0), text, font=f_artist)[2]
        draw.text(((W - w) // 2, int(H * 0.06)), text, font=f_artist,
                  fill=(255, 255, 255),
                  stroke_width=max(1, f_artist.size // 14),
                  stroke_fill=(0, 0, 0))
    if title:
        lines = wrap_text_pil(draw, title.upper(), f_title, W - 80)
        lh = int(f_title.size * 1.1)
        y = H - int(H * 0.08) - lh * len(lines)
        for line in lines:
            w = draw.textbbox((0, 0), line, font=f_title)[2]
            draw.text(((W - w) // 2, y), line, font=f_title,
                      fill=(255, 255, 255),
                      stroke_width=max(2, f_title.size // 14),
                      stroke_fill=(0, 0, 0))
            y += lh
    return base


def find_ffmpeg() -> str:
    """ffmpeg.exe next to the app, on PATH, or via imageio_ffmpeg."""
    local = app_dir() / "ffmpeg.exe"
    if local.exists():
        return str(local)
    import shutil as _sh
    exe = _sh.which("ffmpeg")
    if exe:
        return exe
    try:
        import imageio_ffmpeg
        return imageio_ffmpeg.get_ffmpeg_exe()
    except Exception:
        return ""


def _decode_audio_mono(audio_path, ffmpeg: str, sr: int = 22050):
    """Any audio file -> float32 mono numpy array via ffmpeg."""
    import numpy as np
    flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000)
    cmd = [ffmpeg, "-v", "error", "-i", str(audio_path),
           "-f", "f32le", "-ac", "1", "-ar", str(sr), "-"]
    raw = subprocess.run(cmd, capture_output=True, check=True, creationflags=flags).stdout
    return np.frombuffer(raw, dtype=np.float32), sr


def distribute_lyrics(lyrics_text: str, duration_s: float) -> list:
    """Turn raw lyric lines into [(start, end, text)] timings, allocating
    time proportionally to word count. Blank lines are real instrumental
    gaps - they consume a proportional slice of the timeline (so the
    surrounding lines don't get packed back-to-back) but produce no
    displayed entry."""
    raw_lines = [ln.strip() for ln in lyrics_text.splitlines()]
    if not any(raw_lines):
        return []
    PAUSE_WEIGHT = 2  # a blank line "counts" as a short 2-word pause
    weights = [max(len(ln.split()), 1) if ln else PAUSE_WEIGHT
               for ln in raw_lines]
    total_w = sum(weights)
    timings, t = [], 0.0
    for ln, w in zip(raw_lines, weights):
        dur = duration_s * w / total_w
        if ln:
            timings.append((t, t + dur, ln))
        t += dur
    return timings


def render_visualizer(audio_path, image_path, out_path, style: str = "bars",
                      size=(1280, 720), fps: int = 30, max_seconds=None,
                      log=print, brand=None, lyrics=None,
                      lyric_font: str = "Impact (bold poster)") -> Path:
    """Audio-reactive video: FFT spectrum + bass pulse over artwork.
    `image_path` may be a single path OR a list of paths - a list renders
    a music-video slideshow, crossfading between artworks on beat-aligned
    section boundaries. Styles: bars | ring | galaxy | waveform.
    Encodes H.264 MP4 with the original audio muxed in."""
    import numpy as np
    from PIL import Image, ImageDraw, ImageEnhance, ImageFilter

    ffmpeg = find_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found - place ffmpeg.exe next to "
                           "the app")
    W, H = size
    audio, sr = _decode_audio_mono(audio_path, ffmpeg)
    if max_seconds:
        audio = audio[:int(sr * max_seconds)]
    n_frames = max(1, int(len(audio) / sr * fps))
    hop = len(audio) / n_frames
    win = 2048
    hann = np.hanning(win).astype(np.float32)

    # pre-render backgrounds at 116% so the pulse zoom never shows edges
    paths = list(image_path) if isinstance(image_path, (list, tuple)) \
        else [image_path]
    bigs = []
    for p in paths:
        art = Image.open(p).convert("RGB")
        b = fit_exact(art, int(W * 1.16), int(H * 1.16))
        bigs.append(ImageEnhance.Brightness(b).enhance(0.6))
    seg_frames = max(1, n_frames // len(bigs))   # frames per artwork
    fade_frames = min(int(fps * 0.7), seg_frames // 3)  # crossfade window

    # galaxy style: deterministic starfield (depth-layered)
    star_rng = random.Random(42)
    stars = [(star_rng.random(), star_rng.random(),
              star_rng.uniform(0.3, 1.0), star_rng.uniform(0, 6.283))
             for _ in range(220)]

    # lyric timings: accept raw text (auto-distributed) or explicit
    # [(start, end, text)] tuples
    lyric_lines = []
    if lyrics:
        duration = len(audio) / sr
        lyric_lines = (distribute_lyrics(lyrics, duration)
                       if isinstance(lyrics, str) else list(lyrics))
        lfont_big = find_typo_font(lyric_font, max(24, W // 16))
        lfont_small = find_typo_font(lyric_font, max(16, W // 30))
    n_bars = 48
    freqs = np.fft.rfftfreq(win, 1 / sr)
    edges = np.geomspace(40, sr / 2.2, n_bars + 1)
    bins = [(freqs >= edges[i]) & (freqs < edges[i + 1])
            for i in range(n_bars)]
    smooth = np.zeros(n_bars, dtype=np.float32)

    enc = subprocess.Popen(
        [ffmpeg, "-y", "-v", "error",
         "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", f"{W}x{H}",
         "-r", str(fps), "-i", "-",
         "-i", str(audio_path),
         "-map", "0:v", "-map", "1:a", "-shortest",
         "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
         "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k",
         "-t", str(len(audio) / sr),
         str(out_path)],
        stdin=subprocess.PIPE,
        creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000))

    t0 = time.time()
    try:
        for f in range(n_frames):
            i0 = int(f * hop)
            seg = audio[i0:i0 + win]
            if len(seg) < win:
                seg = np.pad(seg, (0, win - len(seg)))
            mag = np.abs(np.fft.rfft(seg * hann))
            levels = np.array([mag[b].mean() if b.any() else 0.0
                               for b in bins], dtype=np.float32)
            levels = np.log1p(levels * 40)
            peak = levels.max()
            if peak > 0:
                levels = levels / max(peak, 4.0)
            smooth = np.maximum(levels, smooth * 0.78)
            bass = float(np.clip(smooth[:6].mean(), 0, 1))
            mids = float(np.clip(smooth[8:24].mean(), 0, 1))

            # music-video slideshow: pick artwork for this frame, crossfading
            # across the boundary between consecutive segments
            seg = min(f // seg_frames, len(bigs) - 1)
            big = bigs[seg]
            into_next = f - (seg + 1) * seg_frames + fade_frames
            if 0 < into_next <= fade_frames and seg + 1 < len(bigs):
                alpha = into_next / fade_frames
                big = Image.blend(bigs[seg], bigs[seg + 1], alpha)

            # bass-driven pulse zoom
            zoom = 1.0 + 0.10 * bass
            zw, zh = int(W * zoom), int(H * zoom)
            frame = big.resize((max(zw, W), max(zh, H)),
                               Image.BILINEAR)
            left = (frame.width - W) // 2
            top = (frame.height - H) // 2
            frame = frame.crop((left, top, left + W, top + H))
            draw = ImageDraw.Draw(frame, "RGBA")

            if style == "ring":
                cx, cy = W // 2, H // 2
                r0 = min(W, H) * 0.22 * (1 + 0.08 * bass)
                for b in range(n_bars):
                    ang = 2 * np.pi * b / n_bars - np.pi / 2
                    ln = r0 * 0.15 + smooth[b] * min(W, H) * 0.20
                    x0 = cx + np.cos(ang) * r0
                    y0 = cy + np.sin(ang) * r0
                    x1 = cx + np.cos(ang) * (r0 + ln)
                    y1 = cy + np.sin(ang) * (r0 + ln)
                    draw.line([x0, y0, x1, y1], width=max(2, W // 240),
                              fill=(255, 255, 255, 210))
                draw.ellipse([cx - r0 * 0.92, cy - r0 * 0.92,
                              cx + r0 * 0.92, cy + r0 * 0.92],
                             outline=(255, 255, 255, 160),
                             width=max(2, W // 300))
            elif style == "galaxy":
                # starfield that breathes with the mids + rotating spectrum ring
                cx, cy = W // 2, H // 2
                spread = 1.0 + 0.25 * bass
                for sx, sy, depth, phase in stars:
                    px = cx + (sx - 0.5) * W * spread
                    py = cy + (sy - 0.5) * H * spread
                    tw_ = 0.5 + 0.5 * np.sin(phase + f * 0.15 * depth)
                    bright = int(120 + 135 * min(1.0, tw_ * (0.35 + mids)))
                    r = max(1, int(depth * (1.5 + 2.5 * bass)))
                    draw.ellipse([px - r, py - r, px + r, py + r],
                                 fill=(bright, bright, 255, bright))
                rot = f * 0.02
                r0 = min(W, H) * 0.26 * (1 + 0.06 * bass)
                for b in range(n_bars):
                    ang = 2 * np.pi * b / n_bars + rot
                    ln = smooth[b] * min(W, H) * 0.14
                    x0 = cx + np.cos(ang) * r0
                    y0 = cy + np.sin(ang) * r0
                    x1 = cx + np.cos(ang) * (r0 + ln)
                    y1 = cy + np.sin(ang) * (r0 + ln)
                    draw.line([x0, y0, x1, y1], width=max(2, W // 320),
                              fill=(200, 180, 255, 190))
            elif style == "waveform":
                # actual audio waveform scrolling along the lower third
                span = int(sr * 1.2)
                w0 = max(0, i0 - span // 2)
                seg_audio = audio[w0:w0 + span]
                if len(seg_audio) > W:
                    idx = np.linspace(0, len(seg_audio) - 1, W).astype(int)
                    pts = seg_audio[idx]
                else:
                    pts = np.pad(seg_audio, (0, W - len(seg_audio)))
                base_y = int(H * 0.80)
                amp = H * 0.14 * (0.5 + 0.8 * bass)
                line = [(x, base_y + float(pts[x]) * amp) for x in range(W)]
                draw.line(line, width=max(2, H // 300),
                          fill=(255, 255, 255, 220))
                draw.line([(0, base_y), (W, base_y)], width=1,
                          fill=(255, 255, 255, 60))
            else:  # bars
                bw = W / n_bars
                base_y = H - int(H * 0.06)
                max_h = H * 0.34
                for b in range(n_bars):
                    bh = 4 + smooth[b] * max_h
                    x0 = b * bw + bw * 0.18
                    x1 = (b + 1) * bw - bw * 0.18
                    draw.rectangle([x0, base_y - bh, x1, base_y],
                                   fill=(255, 255, 255, 200))

            if lyric_lines:
                t_now = f / fps
                active_i = next((j for j, (a, b, _) in enumerate(lyric_lines)
                                 if a <= t_now < b), None)
                if active_i is not None:
                    a, b, text = lyric_lines[active_i]
                    # fade in/out over 0.25s at line boundaries
                    fade = min(1.0, (t_now - a) / 0.25, (b - t_now) / 0.25)
                    alpha = int(255 * max(0.0, fade))
                    text = typo_text(lyric_font, text)
                    l_lines = wrap_text_pil(draw, text, lfont_big, W - 160)
                    lh = int(lfont_big.size * 1.15)
                    base_y = int(H * 0.60) - lh * len(l_lines) // 2
                    for li, line in enumerate(l_lines):
                        tw = draw.textbbox((0, 0), line, font=lfont_big)[2]
                        draw.text(((W - tw) // 2, base_y + li * lh), line,
                                  font=lfont_big, fill=(255, 255, 255, alpha),
                                  stroke_width=max(2, lfont_big.size // 14),
                                  stroke_fill=(0, 0, 0, alpha))
                    # preview of the next line, small and dim
                    if active_i + 1 < len(lyric_lines):
                        nxt = typo_text(lyric_font,
                                        lyric_lines[active_i + 1][2])
                        if len(nxt) > 60:
                            nxt = nxt[:57] + "..."
                        tw = draw.textbbox((0, 0), nxt, font=lfont_small)[2]
                        draw.text(((W - tw) // 2,
                                   base_y + len(l_lines) * lh + 14), nxt,
                                  font=lfont_small, fill=(220, 220, 220, 140),
                                  stroke_width=1, stroke_fill=(0, 0, 0, 140))

            if brand is not None:
                frame = brand.apply(frame)
            enc.stdin.write(frame.tobytes())
            if f % (fps * 5) == 0 and f:
                done = f / n_frames
                log(f"Visualizer: {done * 100:.0f}% "
                    f"({(time.time() - t0) / done * (1 - done):.0f}s left)")

        enc.stdin.close()
        enc.wait(timeout=300)
        if enc.returncode != 0:
            raise RuntimeError("ffmpeg encode failed")
    except Exception:
        # a corrupt frame/BrokenPipeError mid-loop must not leak the
        # ffmpeg child process or its stdin pipe
        enc.kill()
        try:
            enc.wait(timeout=10)
        except Exception:
            pass
        raise
    log(f"Visualizer done: {Path(out_path).name} "
        f"({n_frames} frames, {time.time() - t0:.0f}s)")
    return Path(out_path)


# ════════════════════════════════════════════════════════════════════════════
# MasterMind - goal-driven production orchestrator with a lifecycle ledger
# ════════════════════════════════════════════════════════════════════════════

class MasterMind:
    """Owns the production goal. Tracks every asset through
    produced -> approved -> posted (or rejected), computes per-niche
    buffer deficits, and drives unattended production cycles."""

    GOALS_DEFAULTS = {
        "niches": ["Motivational", "Anime", "Funny/Sarcastic"],
        "buffer_target": 10,          # unposted ready assets per niche
        "mix": ["quote_card", "art_pin", "meme"],
        "max_items_per_cycle": 12,    # safety cap per run
    }

    def __init__(self):
        self.goals_path = app_dir() / "goals.json"
        self.ledger_path = app_dir() / "production_ledger.json"
        g = safe_json_load(self.goals_path, {})
        self.goals = {**self.GOALS_DEFAULTS,
                      **(g if isinstance(g, dict) else {})}
        led = safe_json_load(self.ledger_path, [])
        self.ledger = led if isinstance(led, list) else []

    def save_goals(self):
        safe_json_save(self.goals_path, self.goals)

    def save_ledger(self):
        safe_json_save(self.ledger_path, self.ledger)

    def add_asset(self, niche: str, ctype: str, file: str,
                  style: str = "", score=None) -> dict:
        asset = {"id": f"{datetime.now():%Y%m%d%H%M%S}_{len(self.ledger)}",
                 "date": datetime.now().isoformat(timespec="seconds"),
                 "niche": niche, "type": ctype, "file": str(file),
                 "style": style.split(",")[0][:40] if style else "",
                 "score": score, "stage": "produced", "posted_date": None}
        self.ledger.append(asset)
        self.save_ledger()
        return asset

    def set_stage(self, asset_id: str, stage: str):
        for a in self.ledger:
            if a["id"] == asset_id:
                a["stage"] = stage
                if stage == "posted":
                    a["posted_date"] = datetime.now().isoformat(
                        timespec="seconds")
                self.save_ledger()
                return a
        return None

    def buffer(self) -> dict:
        """Per-niche counts by stage."""
        out = {n: {"produced": 0, "approved": 0, "posted": 0, "rejected": 0}
               for n in self.goals["niches"]}
        for a in self.ledger:
            if a["niche"] in out and a["stage"] in out[a["niche"]]:
                out[a["niche"]][a["stage"]] += 1
        return out

    def deficits(self) -> dict:
        """How many new assets each niche needs to hit buffer_target
        (counting produced+approved as the unposted-ready buffer)."""
        buf = self.buffer()
        target = int(self.goals["buffer_target"])
        return {n: max(0, target - buf[n]["produced"] - buf[n]["approved"])
                for n in self.goals["niches"]}

    def pending_approval(self) -> list:
        return [a for a in self.ledger if a["stage"] == "produced"]

    def approved_queue(self) -> list:
        return [a for a in self.ledger if a["stage"] == "approved"]

    def stats_text(self) -> str:
        buf = self.buffer()
        lines = [f"{'NICHE':<20} {'ready':>6} {'posted':>7} {'need':>5}"]
        def_ = self.deficits()
        for n, b in buf.items():
            ready = b["produced"] + b["approved"]
            lines.append(f"{n:<20} {ready:>6} {b['posted']:>7} "
                         f"{def_[n]:>5}")
        return "\n".join(lines)


class ChannelLedger:
    """v9.3: tracks every Channel Studio package produced (video +
    thumbnail + metadata) through a simple review stage - produced ->
    reviewed -> uploaded. Deliberately mirrors MasterMind's ledger
    shape/conventions exactly (same safe_json_load/save pattern, same
    flat-list-of-dicts shape, same file-per-collection convention) since
    that class already solved this exact problem for a different asset
    type - no reason to invent a second pattern."""

    def __init__(self):
        self.path = app_dir() / "channel_ledger.json"
        items = safe_json_load(self.path, [])
        self.items = items if isinstance(items, list) else []

    def save(self):
        safe_json_save(self.path, self.items)

    def add_package(self, niche: str, mechanism: str, pkg: dict) -> dict:
        entry = {
            "id": f"{niche}_{datetime.now():%Y%m%d%H%M%S}_{len(self.items)}",
            "date": datetime.now().isoformat(timespec="seconds"),
            "niche": niche, "mechanism": mechanism,
            "title": pkg.get("title", ""), "video": str(pkg["video"]),
            "thumbnail": (str(pkg["thumbnail"])
                         if pkg.get("thumbnail") else None),
            "tags": pkg.get("tags", []), "stage": "produced",
        }
        self.items.append(entry)
        self.save()
        return entry

    def set_stage(self, item_id: str, stage: str):
        for it in self.items:
            if it["id"] == item_id:
                it["stage"] = stage
                self.save()
                return it
        return None

    def by_stage(self, stage: str) -> list:
        return [it for it in self.items if it["stage"] == stage]

    def stats_by_niche(self) -> dict:
        out = {}
        for it in self.items:
            n = it["niche"]
            out.setdefault(n, {"produced": 0, "reviewed": 0, "uploaded": 0})
            if it["stage"] in out[n]:
                out[n][it["stage"]] += 1
        return out


def _plan_niche_items(q, niche: str, count: int, log=print) -> list:
    """GLM plans `count` content items for a niche (top-up loop)."""
    items, attempts = [], 0
    while len(items) < count and attempts < 3:
        want = count - len(items)
        raw = q.complete(
            f"Create {want} Pinterest content plans for the {niche} niche "
            f"(tone: {NICHES[niche]['tone']}). "
            'Reply ONLY JSON: {"items": [{"text": "a short original quote '
            'max 20 words", "top": "meme top max 8 words", "bottom": '
            '"meme bottom max 8 words", "title": "pin title max 90 chars", '
            '"description": "pin description max 300 chars", "hashtags": '
            '["6 hashtags"]}]} '
            f"with exactly {want} items.",
            temperature=0.95, max_tokens=400 * want + 300, json_format=True)
        batch = []
        try:
            batch = json.loads(re.search(r"\{.*\}", raw, re.DOTALL)
                               .group(0)).get("items", [])
        except Exception:
            pass
        if not batch and raw:
            for m in re.finditer(r"\{[^{}]*\}", raw):
                try:
                    batch.append(json.loads(m.group(0)))
                except Exception:
                    continue
        items.extend(batch)
        attempts += 1
    clean = []
    for item in items[:count]:
        item = {k.lower(): v for k, v in item.items()}
        item["text"] = str(item.get("text", "")).strip(' "“”')
        item["hashtags"] = [t for t in item.get("hashtags", [])
                            if str(t).strip()]
        clean.append(item)
    return clean


def _queue_and_wait_headless(client, workflow: dict, log=print,
                             retries: int = 1) -> dict:
    """Headless equivalent of CompanionApp._queue_and_wait, for the
    module-level nightly cycle (run_mastermind_cycle has no `self` - it's
    not a CompanionApp method, so it can't reach the GUI's crash-heal).
    Same HTTPError-vs-connectivity split: HTTPError means the server
    responded (a workflow validation error), so it must not trigger a
    restart; only real connectivity failures do."""
    attempt = 0
    while True:
        try:
            pid = client.queue_prompt(workflow)
            return client.wait_for_result(pid, timeout_s=1200)
        except urllib.error.HTTPError as e:
            try:
                body = e.read().decode("utf-8", errors="replace")
            except Exception:
                body = str(e)
            raise RuntimeError(
                f"ComfyUI rejected the workflow (HTTP {e.code}): "
                f"{body[:500]}") from e
        except RuntimeError as e:
            # v10.1: this headless path never fed the self-healing bad-
            # checkpoint blocklist either - MasterMind's unattended
            # nightly cycle could hit the same junk-checkpoint file over
            # and over with no self-heal.
            _detect_and_mark_bad_checkpoint(str(e), log=log)
            raise
        except (urllib.error.URLError, ConnectionError, OSError,
                TimeoutError) as e:
            if attempt >= retries:
                raise
            attempt += 1
            log(f"MasterMind: backend down ({type(e).__name__}) - "
                "self-healing: restarting Comfy Desktop...")
            try:
                subprocess.run(["taskkill", "/IM", "Comfy Desktop.exe", "/F"],
                               capture_output=True, timeout=20)
            except Exception:
                pass
            time.sleep(5)
            if not Path(COMFY_DESKTOP_EXE).exists():
                log("MasterMind: Comfy Desktop exe not found - cannot self-heal")
                raise
            subprocess.Popen([COMFY_DESKTOP_EXE])
            deadline = time.time() + 300
            healed = False
            while time.time() < deadline:
                if client.detect():
                    healed = True
                    break
                time.sleep(8)
            if not healed:
                log("MasterMind: self-heal timed out (5 min)")
                raise
            log(f"MasterMind: self-heal OK, retrying (attempt {attempt + 1})...")


def run_mastermind_cycle(log=print) -> dict:
    """One unattended production cycle: fill each niche's buffer deficit,
    brand everything, record in the ledger, write a briefing.
    Headless-safe: no GUI required. Returns a summary dict."""
    mm = MasterMind()
    taste = TasteMemory()
    brand = BrandKit()
    q = QuoteGenerator()
    client = ComfyClient()
    wild = WildcardEngine()
    out_root = app_dir() / "generated_anime" / "mastermind_queue"
    t0 = time.time()

    deficits = {n: d for n, d in mm.deficits().items() if d > 0}
    cap = int(mm.goals["max_items_per_cycle"])
    summary = {"planned": 0, "made": 0, "niches": {}, "minutes": 0}
    if not deficits:
        log("MasterMind: all buffers full - nothing to produce")
        return summary

    # server: try to self-start Comfy Desktop if down
    server_ok = client.detect()
    if not server_ok and Path(COMFY_DESKTOP_EXE).exists():
        log("MasterMind: ComfyUI down - launching Comfy Desktop...")
        try:
            subprocess.Popen([COMFY_DESKTOP_EXE])
            deadline = time.time() + 300
            while time.time() < deadline and not server_ok:
                time.sleep(10)
                server_ok = client.detect()
        except Exception:
            pass
    if not server_ok:
        log("MasterMind: no ComfyUI - producing CPU-only quote cards")

    llm_ok = q.detect()
    if not llm_ok:
        log("MasterMind: no local LLM - cannot plan, aborting cycle")
        return summary

    mix = list(mm.goals["mix"])
    if not server_ok:
        mix = [m for m in mix if m == "quote_card"] or ["quote_card"]

    total_budget = cap
    ckpt = None
    if server_ok:
        try:
            ckpts = client.get_checkpoints()
            # v6.6: this ran unattended overnight with no SD1.5/Turbo
            # filtering on the fallback - if "animagine-xl-4" wasn't
            # found, ckpts[0] could be an incompatible checkpoint and
            # every item that night would render static/garbage with
            # nobody watching. Same filter as CompanionApp.director.models.
            safe_ckpts = [c for c in ckpts if not CompanionApp._is_sd15(c)
                         and not CompanionApp._is_turbo_distilled(c)
                         # v7.0: and not a VAE/ControlNet/encoder that merely
                         # lives in checkpoints/ - see _is_not_a_checkpoint.
                         and not CompanionApp._is_not_a_checkpoint(c)]
            ckpt = next((c for c in safe_ckpts if "animagine-xl-4" in c.lower()),
                        safe_ckpts[0] if safe_ckpts else None)
        except Exception:
            server_ok = False

    for niche, need in deficits.items():
        if total_budget <= 0:
            break
        count = min(need, total_budget)
        log(f"MasterMind: planning {count} items for {niche}...")
        items = _plan_niche_items(q, niche, count, log)
        summary["planned"] += len(items)
        q.release_vram()  # never co-resident with diffusion

        ndir = out_root / re.sub(r"[^\w\-]+", "_", niche)
        ndir.mkdir(parents=True, exist_ok=True)
        made = 0
        for i, item in enumerate(items):
            ctype = mix[i % len(mix)]
            style = taste.pick_style(niche, ART_STYLES)
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            try:
                art_path, score = None, None
                if ctype in ("art_pin", "meme") and server_ok and ckpt:
                    positive = wild.expand(
                        f"{QUALITY}, 1girl, __pose__, __setting__, "
                        f"__lighting__, {style}")
                    try:
                        lora_match = pick_lora_for_style(
                            style, client.get_loras())
                    except Exception:
                        lora_match = None
                    wf = client.build_txt2img_workflow(
                        ckpt=ckpt, positive=positive,
                        negative=DEFAULT_NEGATIVE, width=832, height=1216,
                        batch_size=1, steps=24, cfg=6.0,
                        sampler="euler_ancestral", scheduler="karras",
                        seed=random.randint(0, 2**48),
                        lora=[lora_match] if lora_match else None)
                    entry = _queue_and_wait_headless(client, wf, log)
                    info = next(x for o in entry["outputs"].values()
                                for x in o.get("images", []))
                    raw = client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    art_path = ndir / f"_{stamp}_{i}_art.png"
                    art_path.write_bytes(raw)
                    try:
                        qc = QualityMetricsCalculator()
                        score = qc.calculate_overall_quality_score(
                            qc.calculate_image_quality(art_path))
                        taste.record(niche, style, score)
                    except Exception:
                        score = None

                if ctype == "quote_card":
                    text = item.get("text", "")
                    if not text:
                        continue
                    img = brand.apply(render_quote_card(
                        text, "", random.choice(list(QUOTE_CARD_STYLES))))
                    final = ndir / f"{stamp}_{i}_card.png"
                    img.save(final)
                elif ctype == "meme" and art_path:
                    img = brand.apply(render_meme(
                        art_path, str(item.get("top", "")),
                        str(item.get("bottom", ""))))
                    final = ndir / f"{stamp}_{i}_meme.png"
                    img.save(final)
                elif ctype == "art_pin" and art_path:
                    from PIL import Image
                    pin = brand.apply(fit_exact(
                        Image.open(art_path).convert("RGB"), 1000, 1500))
                    final = ndir / f"{stamp}_{i}_pin.png"
                    pin.save(final)
                else:
                    continue

                tags = list(dict.fromkeys(
                    [str(t).lstrip("#") for t in item.get("hashtags", [])] +
                    NICHES[niche]["hashtags"]))[:15]
                final.with_suffix(".pin.txt").write_text(
                    f"TITLE:\\n{item.get('title', '')}\\n\\n"
                    f"DESCRIPTION:\\n{item.get('description', '')}\\n\\n"
                    f"HASHTAGS:\n{' '.join('#' + t for t in tags)}\n",
                    encoding="utf-8")
                mm.add_asset(niche, ctype, final, style, score)
                made += 1
                log(f"MasterMind: [{niche}] {ctype} saved"
                    + (f" (score {score:.1f})" if score else ""))
                if art_path and art_path.exists() and ctype != "meme":
                    art_path.unlink()
            except Exception as e:
                log(f"MasterMind: item failed ({e})")
        summary["niches"][niche] = made
        summary["made"] += made
        total_budget -= count

    # briefing
    summary["minutes"] = round((time.time() - t0) / 60, 1)
    brief_dir = app_dir() / "generated_anime" / "briefings"
    brief_dir.mkdir(parents=True, exist_ok=True)
    stats = mm.stats_text()
    brief = (f"MASTERMIND BRIEFING - {datetime.now():%Y-%m-%d %H:%M}\n"
             f"{'=' * 50}\n"
             f"Cycle: {summary['made']}/{summary['planned']} items in "
             f"{summary['minutes']} min\n"
             f"Per niche: {summary['niches']}\n\n"
             f"BUFFER STATUS:\n{stats}\n\n"
             f"NEXT: review mastermind_queue/, approve in the MasterMind "
             f"window, post the approved queue.\n")
    try:
        glm_note = q.complete(
            f"You are a content production manager. Given this status:\n"
            f"{stats}\nCycle produced: {summary['niches']}. "
            "Write a 3-sentence strategic note: what is on track, what "
            "needs attention, one concrete suggestion. Plain text.",
            temperature=0.7, max_tokens=160)
        if glm_note.strip():
            brief += f"\nSTRATEGIST NOTE:\n{glm_note.strip()}\n"
        q.release_vram()
    except Exception:
        pass
    (brief_dir / f"{datetime.now():%Y%m%d_%H%M}_briefing.txt").write_text(
        brief, encoding="utf-8")
    log(f"MasterMind cycle done: {summary['made']} items, "
        f"{summary['minutes']} min. Briefing written.")
    return summary


# ════════════════════════════════════════════════════════════════════════════
# Persona prompt building (4 modes, from personas.json)
# ════════════════════════════════════════════════════════════════════════════

class PersonaPrompts:
    def __init__(self):
        self.personas = {}
        self.load()

    def load(self):
        path = resource_path("personas.json")
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            self.personas = {k: v for k, v in data.items() if v.get("active", True)}
        except Exception:
            self.personas = {}

    def names(self) -> list:
        return sorted({p.get("name", k) for k, p in self.personas.items()})

    def by_name(self, name: str) -> dict:
        for p in self.personas.values():
            if p.get("name") == name:
                return p
        return {}

    def build(self, mode: str, persona: dict, style: str, other: dict = None,
             hyper: bool = False) -> str:
        """v9.12: hyper=True (default False - zero behavior change for
        every existing caller) appends 2 style-matched artist-influence
        tags (_pick_artist_influences) + 2 random HYPER_DETAIL_BOOSTERS
        phrases at the end of the built prompt, for the "hyper detailed
        with more styles, influences, genres" request - genuinely richer
        prompt text, not just a longer QUALITY constant."""
        name = persona.get("name", "anime character")
        visual = persona.get("visual_details", "")
        pose_sig = persona.get("signature_pose", "")

        if mode == "Exact":
            parts = [QUALITY, name, visual, pose_sig, style]
        elif mode == "Variant":
            parts = [QUALITY, name, visual,
                     "__pose__", "__setting__", style]
        elif mode == "Inspired":
            parts = [QUALITY, f"original character inspired by {name}", visual,
                     "__pose__", "__setting__", style]
        elif mode == "Portrait":
            parts = [QUALITY, name, visual,
                     "close-up portrait, face focus, detailed eyes, "
                     "detailed face, looking at viewer, depth of field",
                     style]
        elif mode == "Scene":
            parts = [QUALITY, name, visual,
                     "cinematic wide shot, full body, scenery focus, "
                     "detailed background, dramatic composition, atmospheric",
                     "__setting__", style]
        elif mode == "Duo":
            other = other or random.choice(list(self.personas.values()))
            parts = [QUALITY, "2 characters, duo",
                     f"{name}, {visual[:100]}",
                     f"{other.get('name', '')}, {other.get('visual_details', '')[:100]}",
                     "standing together, interacting",
                     "__setting__", style]
        else:  # Fusion
            other = other or random.choice(list(self.personas.values()))
            parts = [QUALITY,
                     f"fusion of {name} and {other.get('name', 'a mystery character')}",
                     visual[:120], other.get("visual_details", "")[:120],
                     "__setting__", style]
        if hyper:
            parts.append(_pick_artist_influences(style))
            parts.append(", ".join(random.sample(
                HYPER_DETAIL_BOOSTERS, min(2, len(HYPER_DETAIL_BOOSTERS)))))
        return ", ".join(p.strip() for p in parts if p and p.strip())


