def _pick_quote_category(persona: dict) -> str:
    """Keyword-match the persona's psychology/backstory against
    BUILTIN_QUOTE_BANK's categories - a cheap, fully offline heuristic
    (no embeddings, no LLM) so it works identically on a brand new
    machine with nothing installed. Falls back to a random category
    when nothing matches, rather than always defaulting to one bucket."""
    text = (persona.get("psychology", "") + " " +
           persona.get("backstory", "")).lower()
    keyword_map = {
        "villain": ("villain", "evil", "ruthless", "cruel", "conqueror",
                   "tyrant", "cold", "manipulat", "revenge"),
        "mentor": ("mentor", "wise", "teacher", "elder", "sage", "guide",
                  "veteran", "master"),
        "romantic": ("romantic", "love", "gentle", "tender", "devoted",
                    "affection", "yearning"),
        "comedic": ("comedic", "goofy", "silly", "clumsy", "funny",
                   "lighthearted", "playful", "chaotic good"),
        "mysterious": ("mysterious", "secretive", "enigmatic", "shadow",
                      "unknown", "cryptic", "aloof"),
        "chill": ("calm", "relaxed", "gentle", "peaceful", "chill",
                 "laid-back", "cozy"),
        "hero": ("hero", "brave", "courageous", "protector", "justice",
                "noble", "determined", "loyal"),
    }
    for category, keywords in keyword_map.items():
        if any(k in text for k in keywords):
            return category
    return random.choice(list(BUILTIN_QUOTE_BANK))

