class QuoteGenerator:
    """Local LLM gateway with two backends:
    1. Ollama (http://127.0.0.1:11434)
    2. Locally Uncensored / llama-server OpenAI-compatible API (:8080/v1)
    """

    LOCALLY_UNCENSORED_EXE = (
        r"C:\Users\phase\AppData\Local\Programs\Locally Uncensored"
        r"\locally-uncensored.exe")

    def __init__(self):
        self.ollama_url = "http://127.0.0.1:11434"
        self.openai_url = "http://127.0.0.1:8080/v1"
        self.backend = None   # "ollama" | "openai" | None (local auto-detect)
        self.model = None
        self.config = load_llm_config()

    # ── engine selection ────────────────────────────────────────────────
    def active_engine(self) -> dict:
        eid = self.config.get("active", "auto")
        return next((e for e in LLM_REGISTRY if e["id"] == eid),
                    LLM_REGISTRY[0])

    def engine_ready(self, engine: dict) -> bool:
        """Cloud engines need a key; local ones need a running server."""
        kind = engine["kind"]
        if kind in ("auto", "ollama"):
            return True
        if engine["id"] == "custom":
            return bool(self.config.get("custom_endpoint"))
        return bool(self.config.get("keys", {}).get(engine["id"]))

    def engine_label(self) -> str:
        e = self.active_engine()
        if e["kind"] == "auto":
            if self.backend == "ollama":
                return f"Auto - Ollama/{self.model}"
            if self.backend == "openai":
                return "Auto - Locally Uncensored"
            return "Auto - no local LLM"
        return e["label"]

    def _cloud_complete(self, engine, prompt, temperature, max_tokens):
        """One-shot completion against a cloud engine."""
        key = self.config.get("keys", {}).get(engine["id"], "")
        kind, model = engine["kind"], engine["model"]
        endpoint = engine.get("endpoint", "")
        if engine["id"] == "custom":
            endpoint = self.config.get("custom_endpoint", "")
            model = self.config.get("custom_model", "") or "default"
        try:
            if kind == "anthropic":
                body = {"model": model, "max_tokens": max_tokens,
                        "temperature": temperature,
                        "messages": [{"role": "user", "content": prompt}]}
                req = urllib.request.Request(
                    endpoint, data=json.dumps(body).encode("utf-8"),
                    headers={"Content-Type": "application/json",
                             "x-api-key": key,
                             "anthropic-version": "2023-06-01"})
                with urllib.request.urlopen(req, timeout=120) as resp:
                    data = json.loads(resp.read().decode("utf-8"))
                return "".join(b.get("text", "") for b in data.get("content", []))
            if kind == "gemini":
                url = (f"{endpoint}/{model}:generateContent?key={key}")
                body = {"contents": [{"parts": [{"text": prompt}]}],
                        "generationConfig": {"temperature": temperature,
                                             "maxOutputTokens": max_tokens}}
                req = urllib.request.Request(
                    url, data=json.dumps(body).encode("utf-8"),
                    headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=120) as resp:
                    data = json.loads(resp.read().decode("utf-8"))
                return data["candidates"][0]["content"]["parts"][0]["text"]
            # openai-compatible (ChatGPT, Grok, Mistral, custom)
            body = {"model": model, "temperature": temperature,
                    "max_tokens": max_tokens,
                    "messages": [{"role": "user", "content": prompt}]}
            headers = {"Content-Type": "application/json"}
            if key:
                headers["Authorization"] = f"Bearer {key}"
            req = urllib.request.Request(
                endpoint, data=json.dumps(body).encode("utf-8"),
                headers=headers)
            with urllib.request.urlopen(req, timeout=120) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            return data["choices"][0]["message"]["content"]
        except Exception:
            return ""

    # kept for backward compat with older call sites
    @property
    def url(self):
        return self.ollama_url

    def detect(self) -> bool:
        # 1) Ollama
        try:
            with urllib.request.urlopen(self.ollama_url + "/api/tags",
                                        timeout=2) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            models = [m["name"] for m in data.get("models", [])]
            if models:
                # v6.4: an explicit user override (Settings > LLM) wins
                # over everything else, including the active-engine hint
                override = self.config.get("ollama_model_override", "")
                exact = next((m for m in models
                             if override and m.lower() == override.lower()),
                             None)
                if not exact:
                    # honor an explicitly configured ollama model from the
                    # active engine (e.g. GLM-4.7 Flash) if it is pulled
                    engine = self.active_engine()
                    wanted = engine.get("model", "") if engine.get("kind") == "ollama" else ""
                    exact = next((m for m in models
                                  if wanted and m.lower() == wanted.lower()), None)
                if exact:
                    self.model = exact
                else:
                    # v9.8: this preference order used to put abliterated/
                    # uncensored models FIRST for every build, including
                    # Kids. "Abliterated" means the refusal behaviour has
                    # been deliberately trained out, which directly
                    # defeats the family-friendly system prompt the Kids
                    # build sends. Kids now prefers stock instruct models
                    # and skips safety-stripped ones entirely.
                    if IS_KIDS_MODE:
                        prefs = ("gemma3", "gemma", "qwen2.5", "qwen",
                                 "llama3", "llama", "phi4-mini", "mistral")
                        pool = [m for m in models
                                if not any(bad in m.lower() for bad in
                                           ("abliterate", "uncensored", "dolphin"))]
                    else:
                        prefs = ("gemma-3-4b-it-abliterated", "qwen2.5-abliterate",
                                 "llama3.1-8b-abliterated", "abliterate",
                                 "uncensored", "dolphin", "phi4-mini", "gemma3",
                                 "gemma", "qwen2.5", "qwen", "llama3", "llama",
                                 "glm-4.7-flash", "glm", "mistral")
                        pool = models
                    for pref in prefs:
                        match = next((m for m in pool if pref in m.lower()), None)
                        if match:
                            self.model = match
                            break
                    else:
                        # Kids: if every installed model is safety-stripped,
                        # pool is empty - fall back to models[0] but say so
                        # rather than silently using it as if it were fine.
                        self.model = pool[0] if pool else models[0]
                        if IS_KIDS_MODE and not pool:
                            print("[Kids] WARNING: only safety-stripped LLM "
                                  "models are installed; text features may "
                                  "not respect family-friendly limits.")
                self.backend = "ollama"
                return True
        except Exception:
            pass
        # 2) Locally Uncensored (llama-server, OpenAI-compatible)
        try:
            with urllib.request.urlopen(self.openai_url + "/models",
                                        timeout=2) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            entries = data.get("data", [])
            self.model = entries[0]["id"] if entries else "local-model"
            self.backend = "openai"
            return True
        except Exception:
            pass
        self.backend = None
        self.model = None
        return False

    def _ollama_generate(self, body: dict) -> str:
        """POST /api/generate; generous timeout for large-model cold loads."""
        payload = json.dumps(body).encode("utf-8")
        req = urllib.request.Request(
            self.ollama_url + "/api/generate", data=payload,
            headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=900) as resp:
            return json.loads(resp.read().decode("utf-8")).get("response", "")

    def release_vram(self):
        """Unload the Ollama model from GPU memory so diffusion has room.
        Critical on small-VRAM GPUs when a large LLM (e.g. GLM-4.7 24GB)
        is resident. No-op for non-ollama backends."""
        if self.backend != "ollama" or not self.model:
            return
        try:
            body = json.dumps({"model": self.model, "keep_alive": 0}).encode()
            req = urllib.request.Request(
                self.ollama_url + "/api/generate", data=body,
                headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=15):
                pass
        except Exception:
            pass

    def detect_vision_model(self) -> str | None:
        """v9.14: find an installed Ollama model that reports "vision" in
        its capabilities. Cached after the first successful lookup. Only
        Ollama supports this (the openai-compatible /v1 path here has no
        equivalent capabilities probe), so any other backend returns None."""
        if hasattr(self, "_vision_model_cache"):
            return self._vision_model_cache
        self._vision_model_cache = None
        try:
            with urllib.request.urlopen(self.ollama_url + "/api/tags",
                                        timeout=3) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            names = [m["name"] for m in data.get("models", [])]
        except Exception:
            return None
        vision_models = []
        for name in names:
            try:
                body = json.dumps({"name": name}).encode("utf-8")
                req = urllib.request.Request(
                    self.ollama_url + "/api/show", data=body,
                    headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=5) as resp:
                    show = json.loads(resp.read().decode("utf-8"))
                if "vision" in show.get("capabilities", []):
                    vision_models.append(name)
            except Exception:
                continue
        if not vision_models:
            return None
        preferred = next((m for m in vision_models if "gemma3" in m.lower()),
                          vision_models[0])
        self._vision_model_cache = preferred
        return preferred

    def describe_image(self, image_path, question: str) -> str | None:
        """v9.14: ask a local vision-capable Ollama model to describe/QA an
        image. Returns None on any failure (no vision model installed,
        network error, bad image) - same graceful-degrade convention as
        complete()/complete_json()."""
        model = self.detect_vision_model()
        if not model:
            return None
        try:
            with open(image_path, "rb") as f:
                b64 = base64.b64encode(f.read()).decode("ascii")
            body = {"model": model, "prompt": question, "images": [b64],
                     "stream": False, "think": False}
            payload = json.dumps(body).encode("utf-8")
            req = urllib.request.Request(
                self.ollama_url + "/api/generate", data=payload,
                headers={"Content-Type": "application/json"})
            try:
                with urllib.request.urlopen(req, timeout=180) as resp:
                    result = json.loads(resp.read().decode("utf-8")).get("response", "")
            except urllib.error.HTTPError:
                body.pop("think", None)
                payload = json.dumps(body).encode("utf-8")
                req = urllib.request.Request(
                    self.ollama_url + "/api/generate", data=payload,
                    headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=180) as resp:
                    result = json.loads(resp.read().decode("utf-8")).get("response", "")
            return result.strip() or None
        except Exception:
            return None

    def complete(self, prompt: str, temperature: float = 0.8,
                 max_tokens: int = 250, json_format: bool = False) -> str:
        """One-shot completion through whichever local LLM is alive."""
        if not self.backend:
            return ""
        try:
            if self.backend == "ollama":
                body = {"model": self.model, "prompt": prompt, "stream": False,
                        "options": {"temperature": temperature,
                                    "num_predict": max_tokens}}
                if json_format:
                    body["format"] = "json"
                # thinking models (GLM-4.7, DeepSeek-R1, Qwen3) burn the
                # token budget on reasoning - ask for the answer directly
                body["think"] = False
                try:
                    return self._ollama_generate(body)
                except urllib.error.HTTPError:
                    # non-thinking model / older Ollama rejects "think"
                    body.pop("think", None)
                    return self._ollama_generate(body)
            else:  # openai-compatible (Locally Uncensored)
                body = {"model": self.model, "temperature": temperature,
                        "max_tokens": max_tokens,
                        "messages": [{"role": "user", "content": prompt}]}
                payload = json.dumps(body).encode("utf-8")
                req = urllib.request.Request(
                    self.openai_url + "/chat/completions", data=payload,
                    headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=120) as resp:
                    data = json.loads(resp.read().decode("utf-8"))
                return data["choices"][0]["message"]["content"]
        except Exception:
            return ""

    def complete_json(self, prompt: str, temperature: float = 0.8,
                      max_tokens: int = 250):
        """Completion parsed as JSON dict, or None."""
        raw = self.complete(prompt, temperature, max_tokens, json_format=True)
        if not raw:
            return None
        try:
            match = re.search(r"\{.*\}", raw, re.DOTALL)
            return json.loads(match.group(0) if match else raw)
        except Exception:
            return None

    def generate(self, persona: dict) -> tuple:
        """Returns (quote, source). Tries local LLM, falls back to signature."""
        name = persona.get("name", "an anime character")
        if self.backend:
            prompt = (
                f"You are {name}. "
                f"Personality: {persona.get('psychology', '')[:300]}. "
                f"Backstory: {persona.get('backstory', '')[:300]}. "
                f"Write ONE short, punchy, in-character quote this character "
                f"would say (max 25 words). Reply with ONLY the quote text, "
                f"no quotation marks, no explanation."
            )
            quote = self.complete(prompt, temperature=0.9, max_tokens=60)
            quote = quote.strip().strip('"').strip()
            if quote:
                return quote, f"AI ({self.model})"
        sig = persona.get("signature_quote", "").strip()
        if sig:
            return sig, "signature quote"
        # v8.6: no LLM, no signature_quote (e.g. a fresh machine with no
        # Ollama installed) - built-in quote bank, not a placeholder, so
        # Quote Pilot still produces something real out of the box
        category = _pick_quote_category(persona)
        quote = random.choice(BUILTIN_QUOTE_BANK[category])
        return quote, f"built-in ({category})"


