def find_typo_font(preset: str, size: int):
    """Font for a TYPOGRAPHY preset with graceful fallback chain."""
    from PIL import ImageFont
    chain, _case, _track = TYPOGRAPHY.get(
        preset, (["impact.ttf", "arialbd.ttf"], "upper", 0))
    for name in chain:
        try:
            return ImageFont.truetype(rf"C:\Windows\Fonts\{name}", size)
        except Exception:
            continue
    return find_bold_font(size)


def typo_text(preset: str, text: str) -> str:
    """Apply the preset's letter-case rule."""
    case = TYPOGRAPHY.get(preset, (None, "upper", 0))[1]
    return text.upper() if case == "upper" else text.title() \
        if case == "title" else text

