class SmartDirector:
    """Chooses generation settings per persona - LLM first, heuristics fallback."""

    def __init__(self, quotes: QuoteGenerator, taste=None):
        self.quotes = quotes  # reuse its Ollama detection
        self.models = []      # installed checkpoints, set after connection
        self.taste = taste    # v5.0: TasteMemory, set post-construction
                              # (init order: director built before taste)

    def direct(self, persona: dict) -> dict:
        """Returns {mode, style, width, height, extra_tags, model, reason, brain}."""
        if self.quotes.backend:
            choice = self._llm_direct(persona)
            if choice:
                return choice
        return self._heuristic_direct(persona)

    def _pick_model_heuristic(self, text: str):
        """Keyword-based checkpoint choice from installed models."""
        if not self.models:
            return None

        def find(key):
            return next((m for m in self.models if key in m.lower()), None)

        if any(k in text for k in ("dark", "demon", "gothic", "shadow", "battle",
                                   "war", "android", "cyber")):
            pick = find("illustrious")
            if pick:
                return pick
        if any(k in text for k in ("cute", "gentle", "soft", "cheerful", "kind",
                                   "flower", "healing")):
            pick = find("animagine-xl-3.1")
            if pick:
                return pick
        return find("animagine-xl-4.0") or self.models[0]

    def _llm_direct(self, persona: dict):
        modes = ["Exact", "Variant", "Inspired", "Portrait", "Scene", "Duo"]
        style_menu = "\n".join(f"{i}: {s}" for i, s in enumerate(ART_STYLES))
        model_menu = "\n".join(f"{i}: {m} - {model_hint(m)}"
                               for i, m in enumerate(self.models))
        model_part = (
            f"Available AI models:\n{model_menu}\n\n" if self.models else "")
        model_field = (
            f'"model_index": <0-{len(self.models) - 1}>, ' if self.models else "")
        # v5.0: bias the menu with what has actually scored well for this
        # persona before, without hard-forcing a style over a good thematic
        # match
        taste_part = ""
        if self.taste:
            top = self.taste.report(persona.get("name", ""), top=5)
            if top:
                lines = "; ".join(f"{k.split('|')[1]}: {ema:.1f}/10 "
                                  f"({n} runs)" for k, ema, n in top)
                taste_part = (f"User taste history for this character "
                             f"(avg score, higher = liked): {lines}. "
                             f"Prefer high-scoring styles unless the "
                             f"character strongly suggests otherwise.\n\n")
        prompt = (
            f"You are an anime art director choosing settings for an AI image "
            f"of this character:\n"
            f"Name: {persona.get('name', '')}\n"
            f"Look: {persona.get('visual_details', '')[:250]}\n"
            f"Personality: {persona.get('psychology', '')[:200]}\n"
            f"Backstory: {persona.get('backstory', '')[:200]}\n\n"
            f"Available art styles:\n{style_menu}\n\n"
            f"{taste_part}"
            f"{model_part}"
            f"Be a BOLD art director: pick the style that best matches this "
            f"character's theme, era and mood - do NOT default to style 0, "
            f"and vary mode choices (Portrait for faces/emotion, Scene for "
            f"action/world, Variant for fresh takes, Exact only for iconic "
            f"canon looks). Pick the model whose strengths fit the chosen style.\n"
            f"Reply with ONLY compact JSON, no markdown:\n"
            f'{{"style_index": <0-{len(ART_STYLES) - 1}>, '
            f'{model_field}'
            f'"mode": <one of {modes}>, '
            f'"aspect": <"portrait"|"landscape"|"square">, '
            f'"extra_tags": "<3-6 short danbooru-style tags fitting the character>", '
            f'"reason": "<one short sentence>"}}'
        )
        try:
            data = self.quotes.complete_json(prompt, temperature=0.7,
                                             max_tokens=220)
            if not data:
                return None

            idx = int(data.get("style_index", 0))
            style = ART_STYLES[idx] if 0 <= idx < len(ART_STYLES) else ART_STYLES[0]
            mode = data.get("mode", "Variant")
            if mode not in modes:
                mode = "Variant"
            w, h = ASPECTS.get(str(data.get("aspect", "portrait")).lower(),
                               ASPECTS["portrait"])
            model = None
            if self.models:
                try:
                    midx = int(data.get("model_index", -1))
                    if 0 <= midx < len(self.models):
                        model = self.models[midx]
                except (TypeError, ValueError):
                    pass
            return {
                "mode": mode, "style": style, "width": w, "height": h,
                "extra_tags": str(data.get("extra_tags", ""))[:200],
                "model": model,
                "reason": str(data.get("reason", ""))[:200],
                "brain": f"AI ({self.quotes.model})",
            }
        except Exception:
            return None

    def _heuristic_direct(self, persona: dict) -> dict:
        text = " ".join([persona.get("name", ""), persona.get("visual_details", ""),
                         persona.get("backstory", ""),
                         persona.get("psychology", "")]).lower()
        model = self._pick_model_heuristic(text)
        for keywords, style, mode, aspect in HEURISTIC_RULES:
            if any(k in text for k in keywords):
                w, h = ASPECTS[aspect]
                return {"mode": mode, "style": style, "width": w, "height": h,
                        "extra_tags": "", "model": model, "brain": "heuristic",
                        "reason": f"matched theme: {keywords[0]}"}
        # v5.0: taste-guided default when no keyword theme matched, so the
        # heuristic fallback (used when Ollama is offline) still learns
        # from what scored well for this persona; falls back to the old
        # deterministic-but-varied random pick when there's no taste data
        rng = random.Random(persona.get("name", ""))
        w, h = ASPECTS["portrait"]
        style = (self.taste.pick_style(persona.get("name", ""), ART_STYLES)
                 if self.taste else rng.choice(ART_STYLES[:8]))
        return {"mode": rng.choice(["Variant", "Portrait"]),
                "style": style, "width": w, "height": h,
                "extra_tags": "", "model": model, "brain": "heuristic",
                "reason": "taste-guided default" if self.taste else
                "default pick"}


