class GPUOptimizer:
    """Optimize GPU utilization, mixed precision, dynamic batching."""

    def __init__(self):
        self.compute_capability = None
        self.supports_fp16 = False
        self.supports_mixed_precision = False
        self.max_batch_size = 1
        self.vram_gb = 0
        self.detect_gpu_capabilities()

    def detect_gpu_capabilities(self):
        """Detect GPU compute capability and supported features."""
        try:
            flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000)
            result = subprocess.run(
                ["nvidia-smi", "--query-gpu=compute_cap", "--format=csv,noheader"],
                capture_output=True, text=True, timeout=5, creationflags=flags
            )
            if result.returncode == 0:
                cap = result.stdout.strip().split(',')[0]
                self.compute_capability = cap
                major, minor = map(int, cap.split('.'))
                self.supports_fp16 = major >= 5
                self.supports_mixed_precision = major >= 7
        except:
            pass

    def get_optimal_batch_size(self, vram_gb, model_size_gb=5):
        """Calculate optimal batch size based on VRAM."""
        available = max(1, vram_gb - 2)  # Reserve 2GB for overhead
        batch_size = max(1, int(available / model_size_gb))
        return min(batch_size, 8)

    def enable_mixed_precision(self) -> bool:
        """Check if mixed precision can be enabled."""
        return self.supports_mixed_precision

    def get_memory_pool_size(self, vram_gb) -> int:
        """Calculate memory pool size for efficient reuse."""
        return int(vram_gb * 0.7)

    def recommend_profile(self, vram_gb) -> str:
        """Recommend generation profile based on VRAM."""
        if vram_gb >= 20:
            return "Showcase"
        elif vram_gb >= 12:
            return "Fidelity"
        elif vram_gb >= 6:
            return "Quality"
        else:
            return "Speed"


# ════════════════════════════════════════════════════════════════════════════
# v5.0: Auto-generate quality helpers (replaces the dead v3.0 loop-engine
# stubs above, which faked their scores and were never instantiated)
# ════════════════════════════════════════════════════════════════════════════

# metric -> (round1 adjustment, round2 adjustment); each adjustment is a
# function(plan: dict) -> (new_plan: dict, note: str). Composition is never
# corrected - QualityMetricsCalculator scores it purely on aspect ratio,
# which is an intentional choice, not a defect.
def _fix_detail_r1(plan):
    p = dict(plan)
    p["steps"] = min(40, p.get("steps", 24) + 8)
    p["positive"] = p["positive"] + ", intricate details, sharp focus, fine linework"
    p["negative"] = p.get("negative", "") + ", blurry, soft focus"
    return p, f"steps -> {p['steps']}, +detail tags"


def _fix_detail_r2(plan):
    p = dict(plan)
    if not p.get("hires_kwargs"):
        p["hires_kwargs"] = {"hires_fix": True, "hires_scale": 1.4,
                             "hires_denoise": 0.45}
        return p, "hires-fix enabled"
    p["steps"] = min(40, p.get("steps", 24) + 6)
    return p, f"steps -> {p['steps']}"


def _fix_lighting_r1(plan):
    p = dict(plan)
    dark = plan.get("_mean_brightness", 128) < 128
    if dark:
        p["positive"] += ", bright lighting, well-lit, soft ambient light"
        p["negative"] = p.get("negative", "") + ", dark, underexposed"
    else:
        p["positive"] += ", dim moody lighting, balanced exposure"
        p["negative"] = p.get("negative", "") + ", overexposed, blown highlights"
    return p, f"lighting tags ({'brighten' if dark else 'darken'})"


def _fix_lighting_r2(plan):
    p = dict(plan)
    p["cfg"] = min(8.5, p.get("cfg", 6.0) + 0.7)
    return p, f"cfg -> {p['cfg']}"


def _fix_color_r1(plan):
    p = dict(plan)
    p["cfg"] = min(8.5, p.get("cfg", 6.0) + 0.8)
    p["positive"] += ", vibrant colors, rich saturated palette"
    p["negative"] = p.get("negative", "") + ", washed out, desaturated, greyscale"
    return p, f"cfg -> {p['cfg']}, +color tags"


def _fix_consistency_r1(plan):
    p = dict(plan)
    p["positive"] += ", high contrast, dramatic shading, detailed shadows"
    p["negative"] = p.get("negative", "") + ", flat shading, low contrast"
    return p, "+contrast tags"


def _fix_anatomy_r1(plan):
    p = dict(plan)
    p["positive"] += ", perfect anatomy, correct hands, five fingers"
    p["negative"] = p.get("negative", "") + (
        ", bad anatomy, extra fingers, fused fingers, malformed hands, "
        "mutated hands, extra limbs, missing face")
    return p, "+anatomy-safety tags"


# metric key -> (round1 fn, round2 fn or None to fall back to an LLM rewrite)
# composition is intentionally absent - QualityMetricsCalculator scores it
# purely on aspect ratio, which is a deliberate user choice, not a defect.
QUALITY_FIX_TABLE = {
    "detail_score": (_fix_detail_r1, _fix_detail_r2),
    "lighting_quality": (_fix_lighting_r1, _fix_lighting_r2),
    "color_accuracy": (_fix_color_r1, None),
    "character_consistency": (_fix_consistency_r1, None),
    "anatomy_score": (_fix_anatomy_r1, None),
}


