class PowerAIAgent:
    """Next-generation hybrid AI Assistant for 3klipz Studio.
    Supports local Ollama, cloud LLM APIs, or native offline creative AI engine.
    Controls studio settings, aspect ratios, prompt inspiration, and batch runs.
    """
    def __init__(self, app):
        self.app = app
        self.system_prompt = (
            "You are Power AI, an intelligent creative director and AI assistant built into 3klipz Studio. "
            "Help the user craft artwork, set up scenes, choose styles, and control the app.\n"
            "Supported commands to control the app (append to response if requested):\n"
            "- /set_persona [name]\n"
            "- /set_style [style name]\n"
            "- /set_mode [mode]\n"
            "- /spark_inspiration\n"
            "- /concept_sheet\n"
            "- /generate\n"
            "- /autopilot\n"
        )
        self.history = []

    def _offline_fallback_reply(self, user_text: str) -> str:
        """Native offline rule-based creative engine when external LLM is offline."""
        text_lower = user_text.lower()
        
        if "inspire" in text_lower or "idea" in text_lower or "spark" in text_lower:
            self.app.root.after(0, self.app.spark_inspiration)
            return "✨ I've sparked a fresh creative concept for you with matching lighting and style!"
            
        if "sheet" in text_lower or "turnaround" in text_lower or "character sheet" in text_lower:
            self.app.root.after(0, self.app.create_character_sheet_prompt)
            return "📜 I've formatted your prompt into a 1344x768 multi-angle character concept sheet!"

        if "generate" in text_lower or "create" in text_lower or "make" in text_lower or "render" in text_lower:
            self.app.root.after(0, self.app.start_generation)
            return "🚀 Starting generation now!"

        if "autopilot" in text_lower or "auto-pilot" in text_lower or "auto pilot" in text_lower:
            self.app.root.after(0, self.app.start_autopilot)
            return "🎬 Launching Auto-Pilot production engine!"

        if "card" in text_lower or "tcg" in text_lower or "deck" in text_lower:
            self.app.root.after(0, getattr(self.app, "open_card_game_studio", self.app.spark_inspiration))
            return "🃏 Launching 3klipz Tabletop Card Game Engine! Creating foil card sheet..."

        if "pixel" in text_lower or "8bit" in text_lower or "16bit" in text_lower or "retro" in text_lower:
            self.app.root.after(0, getattr(self.app, "open_pixel_art_studio", self.app.spark_inspiration))
            return "👾 Launching 3klipz Discrete Pixel Art Engine!"

        # Check for persona matches
        for i, name in enumerate(self.app.prompts.personas.keys()):
            if name.lower() in text_lower:
                self.app.root.after(0, lambda idx=i: (
                    self.app.persona_list.selection_clear(0, 'end'),
                    self.app.persona_list.selection_set(idx),
                    self.app.persona_list.see(idx),
                    self.app.update_preview()
                ))
                return f"🎭 Selected persona '{name}' for you!"

        # Check for style matches
        for style in ART_STYLES:
            if style.lower() in text_lower:
                self.app.root.after(0, lambda s=style: self.app.style_var.set(s))
                return f"🎨 Applied style '{style}'!"

        return ("Hello! I am Power AI. I can help you select personas, craft prompts, "
                "switch artistic styles, generate concept sheets, or run Auto-Pilot! "
                "Try asking me to 'inspire me', 'make a character sheet', or 'set style to Cyberpunk'.")

    def chat(self, user_text: str) -> str:
        self.history.append({"role": "user", "content": user_text})
        
        # Strategy 1: Local Ollama / LLM via app.quotes
        if getattr(self.app, "quotes", None) and self.app.quotes.detect():
            try:
                import re
                prompt_text = f"{self.system_prompt}\nUser: {user_text}\nPower AI:"
                raw = self.app.quotes.complete(prompt_text, temperature=0.7, max_tokens=250)
                reply = raw.strip()
                self._execute_embedded_commands(reply)
                return re.sub(r'/(set_persona|set_style|set_mode|generate|autopilot|spark_inspiration|concept_sheet).*', '', reply).strip()
            except Exception:
                pass

        # Strategy 2: Offline intelligent fallback engine
        return self._offline_fallback_reply(user_text)

    def _execute_embedded_commands(self, reply: str):
        """Execute any slash commands parsed from AI output."""
        import re
        if '/spark_inspiration' in reply:
            self.app.root.after(0, self.app.spark_inspiration)
        if '/concept_sheet' in reply:
            self.app.root.after(0, self.app.create_character_sheet_prompt)
        if '/generate' in reply:
            self.app.root.after(0, self.app.start_generation)
        if '/autopilot' in reply:
            self.app.root.after(0, self.app.start_autopilot)
            
        m = re.search(r'/set_persona\s+(.+?)(?=/|$)', reply)
        if m:
            p_name = m.group(1).strip()
            for i, name in enumerate(self.app.prompts.personas.keys()):
                if p_name.lower() in name.lower():
                    self.app.root.after(0, lambda idx=i: (
                        self.app.persona_list.selection_clear(0, 'end'),
                        self.app.persona_list.selection_set(idx),
                        self.app.persona_list.see(idx),
                        self.app.update_preview()
                    ))
                    break
                    
        m = re.search(r'/set_style\s+(.+?)(?=/|$)', reply)
        if m:
            s_name = m.group(1).strip()
            self.app.root.after(0, lambda s=s_name: self.app.style_var.set(s))

class CompanionApp:

    def _apply_hardware_profile(self, hw: dict, rec: dict, silent: bool = False):
        """Applies DeviceScanner's recommended profile to the app's real
        settings vars and persists it to llm_config.json. Shared by the
        manual Auto-Tune dialog's Apply button and the silent first-run
        auto-tune in _finish_init.

        v9.4: extracted from the dialog's old apply_autotune() closure,
        fixing two real bugs found while wiring this up - (1) it wrote
        to the relative path "llm_config.json" instead of going through
        save_llm_config()/app_dir(), which would silently write to
        whatever the process's current working directory happened to be
        rather than next to the exe; (2) it only ever applied
        steps/cfg, never the recommended default_width/default_height/
        freeu_enabled that DeviceScanner's recommended_profile already
        computes."""
        if hasattr(self, "steps_var"):
            self.steps_var.set(rec["steps"])
        if hasattr(self, "cfg_var"):
            self.cfg_var.set(rec["cfg"])
        if hasattr(self, "width_var") and rec.get("default_width"):
            self.width_var.set(rec["default_width"])
        if hasattr(self, "height_var") and rec.get("default_height"):
            self.height_var.set(rec["default_height"])
        if hasattr(self, "freeu_var") and "freeu_enabled" in rec:
            self.freeu_var.set(bool(rec["freeu_enabled"]))
        self.llm_config["gpu_profile"] = rec["gpu_profile"]
        self.llm_config["autotuned_hardware"] = hw["gpu_name"]
        save_llm_config(self.llm_config)
        msg = (f"⚡ Auto-tuned for {hw['gpu_name']} ({hw['vram_gb']} GB "
              f"VRAM) - '{rec['profile_name']}' profile applied")
        self.log(msg)
        if not silent:
            messagebox.showinfo(
                "Auto-Tune Applied",
                f"Successfully auto-tuned Studio settings for:\n"
                f"{hw['gpu_name']} ({hw['vram_gb']} GB VRAM)")

    def open_device_autotune_dialog(self):
        """Probes local hardware specs and presents a 1-click Auto-Tune modal."""
        hw = DeviceScanner.scan()
        rec = hw["recommended_profile"]

        win = tk.Toplevel(self.root)
        win.title("⚡ Hardware Auto-Tuner & System Optimization")
        self._clamp_window(win, 480, 560)
        win.configure(bg=self.PANEL)

        tk.Label(win, text="🖥️ PROBED HARDWARE SPECS", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_heading).pack(anchor="w", padx=16, pady=(16, 6))

        spec_text = (
            f"• GPU: {hw['gpu_name']}\n"
            f"• VRAM: {hw['vram_gb']} GB  (CUDA: {'✓' if hw['cuda_available'] else '✗'}, Compute: {hw['compute_cap']})\n"
            f"• System RAM: {hw['ram_gb']} GB  |  CPU: {hw['cpu_cores']} Cores\n"
            f"• Storage Free: {hw['disk_free_gb']} GB\n"
            f"• Detected Hardware Tier: {hw['tier']}"
        )
        tk.Label(win, text=spec_text, bg=self.PANEL, fg=self.FG,
                 font=self.font_body, justify="left").pack(anchor="w", padx=16, pady=4)

        tk.Label(win, text="🎯 RECOMMENDED AUTO-TUNED PROFILE", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_heading).pack(anchor="w", padx=16, pady=(16, 6))

        rec_text = (
            f"• Profile: {rec['profile_name']}\n"
            f"• Steps: {rec['steps']}  |  CFG: {rec['cfg']}\n"
            f"• Default Canvas: {rec['default_width']}x{rec['default_height']}\n"
            f"• Recommended LLM: {rec['ollama_recommendation']}"
        )
        tk.Label(win, text=rec_text, bg=self.PANEL, fg=self.FG_MUTED,
                 font=self.font_body_bold, justify="left").pack(anchor="w", padx=16, pady=4)

        def apply_autotune():
            self._apply_hardware_profile(hw, rec, silent=False)
            win.destroy()

        ttk.Button(win, text="⚡ APPLY RECOMMENDED AUTO-TUNED PROFILE",
                    command=apply_autotune).pack(padx=16, pady=20)


    def _init_analytics_and_themes(self):
        """Initializes local analytics tracker."""
        self.analytics = LocalAnalyticsTracker()
        self.session_snapshots = []
        # v9.6: this used to also call a now-removed self._apply_theme(...)
        # here - dead code (THEME_PALETTES + _apply_theme, a narrower
        # 8-role palette-swap with zero live widget re-theming) that
        # predated the real system below. The real theming call is later
        # in __init__: self.apply_theme(self.llm_config.get("theme",
        # "dark")), which sets the full THEMES role set (~line 19930) and
        # must run before any widget is built.

    def save_session_snapshot(self):
        """Saves an automated session snapshot before generation."""
        snapshot = {
            "timestamp": datetime.now().strftime("%H:%M:%S"),
            "prompt": self.pos_text.get("1.0", "end").strip() if hasattr(self, "pos_text") else "",
            "mode": self.mode_var.get() if hasattr(self, "mode_var") else "",
            "style": self.style_var.get() if hasattr(self, "style_var") else "",
            "sampler": self.sampler_var.get() if hasattr(self, "sampler_var") else "",
            "steps": self.steps_var.get() if hasattr(self, "steps_var") else 20
        }
        self.session_snapshots.append(snapshot)
        if len(self.session_snapshots) > 20:
            self.session_snapshots.pop(0)

    def undo_last_session_snapshot(self):
        """Restores the previous configuration snapshot."""
        if not self.session_snapshots:
            messagebox.showinfo("Undo", "No previous session snapshots found.")
            return
        snapshot = self.session_snapshots.pop()
        if hasattr(self, "pos_text") and snapshot["prompt"]:
            self.pos_text.delete("1.0", "end")
            self.pos_text.insert("end", snapshot["prompt"])
        if hasattr(self, "mode_var") and snapshot["mode"]:
            self.mode_var.set(snapshot["mode"])
        if hasattr(self, "style_var") and snapshot["style"]:
            self.style_var.set(snapshot["style"])
        if hasattr(self, "sampler_var") and snapshot["sampler"]:
            self.sampler_var.set(snapshot["sampler"])
        if hasattr(self, "steps_var") and snapshot["steps"]:
            self.steps_var.set(snapshot["steps"])
        self.log(f"🔄 Snapshot Restored from {snapshot['timestamp']}")

    def export_analytics_csv(self):
        """Exports generation analytics history to CSV."""
        path = filedialog.asksaveasfilename(defaultextension=".csv", filetypes=[("CSV Files", "*.csv")])
        if path:
            if self.analytics.export_csv(path):
                messagebox.showinfo("Analytics Export", f"Successfully exported analytics to:\n{path}")
            else:
                messagebox.showerror("Analytics Export", "Failed to export CSV file.")

