    @staticmethod
    def create_skeuomorphic_button(parent, text, command, style="raised", width=15):
        """Create a 3D skeuomorphic button with depth and shadow."""
        btn_frame = tk.Frame(parent, bg=CompanionApp.PANEL_LIGHT, relief="ridge", bd=2)

        def on_press(event=None):
            btn_frame.config(relief="sunken", bd=3)
            parent.after(100, lambda: btn_frame.config(relief="ridge", bd=2))
            if command:
                command()

        def on_hover(event):
            btn_frame.config(bg=CompanionApp.PANEL_HIGHLIGHT)

        def on_leave(event):
            btn_frame.config(bg=CompanionApp.PANEL_LIGHT)

        btn_label = tk.Label(btn_frame, text=text, bg=CompanionApp.PANEL_LIGHT,
                            fg=CompanionApp.FG, font=("Segoe UI", 9, "bold"),
                            padx=12, pady=8, cursor="hand2")
        btn_label.pack()

        btn_frame.bind("<Button-1>", on_press)
        btn_label.bind("<Button-1>", on_press)
        btn_frame.bind("<Enter>", on_hover)
        btn_label.bind("<Enter>", on_hover)
        btn_frame.bind("<Leave>", on_leave)
        btn_label.bind("<Leave>", on_leave)

        return btn_frame

    def create_glass_frame(self, parent, **kwargs):
        """Create a frosted glass effect frame (theme-aware)."""
        frame = tk.Frame(parent, bg=self.GLASS_BG, relief="flat", bd=0)
        if "highlightthickness" not in kwargs:
            frame.config(highlightthickness=1, highlightbackground=self.PANEL_HIGHLIGHT)
        return frame

    @staticmethod
    def create_metallic_frame(parent, **kwargs):
        """Create a metallic panel with beveled edges."""
        frame = tk.Frame(parent, bg=CompanionApp.PANEL, relief="ridge", bd=3)
        return frame

    @staticmethod
    def create_inset_frame(parent, **kwargs):
        """Create an inset frame (recessed look)."""
        frame = tk.Frame(parent, bg=CompanionApp.BG, relief="sunken", bd=2)
        return frame

    @staticmethod
    def style_slider(slider_widget):
        """Apply skeuomorphic styling to a slider."""
        try:
            style = ttk.Style()
            style.configure("Skeuomorphic.Horizontal.TScale",
                          background=CompanionApp.PANEL,
                          troughcolor=CompanionApp.BG,
                          lightcolor=CompanionApp.PANEL_HIGHLIGHT,
                          darkcolor=CompanionApp.PANEL,
                          bordercolor=CompanionApp.ACCENT)
            slider_widget.config(style="Skeuomorphic.Horizontal.TScale")
        except Exception:
            pass

    @staticmethod
    def style_entry(entry_widget):
        """Apply skeuomorphic styling to text entry."""
        entry_widget.config(
            bg=CompanionApp.BG,
            fg=CompanionApp.FG,
            insertbackground=CompanionApp.ACCENT,
            relief="sunken",
            bd=2,
            font=("Segoe UI", 9)
        )

    @staticmethod
    def create_panel_label(parent, text, bg_color=None):
        """Create a styled panel label with accent background."""
        if bg_color is None:
            bg_color = CompanionApp.PANEL_LIGHT
        label = tk.Label(parent, text=text, bg=bg_color, fg=CompanionApp.FG,
                        font=("Segoe UI", 10, "bold"), padx=8, pady=6, relief="raised", bd=1)
        return label

    @staticmethod
    def create_info_panel(parent, title, content):
        """Create an information panel with title and content."""
        panel = CompanionApp.create_metallic_frame(parent)

        title_label = tk.Label(panel, text=title, bg=CompanionApp.PANEL, fg=CompanionApp.ACCENT,
                              font=("Segoe UI", 9, "bold"), padx=8, pady=4)
        title_label.pack(anchor="w", fill="x")

        sep = tk.Frame(panel, bg=CompanionApp.PANEL_HIGHLIGHT, height=1)
        sep.pack(anchor="w", fill="x", padx=4)

        content_label = tk.Label(panel, text=content, bg=CompanionApp.PANEL, fg=CompanionApp.FG,
                                font=("Segoe UI", 8), padx=8, pady=6, justify="left")
        content_label.pack(anchor="w", fill="both", expand=True, padx=4, pady=4)

        return panel

    def __init__(self, root: tk.Tk):
        # Set up crash logging for debugging
        sys.excepthook = log_crash

        self.root = root
        self._init_analytics_and_themes()

        # ── Modular Live Plugin Loader ──
        # Deliberately disabled: LivePluginLoader.discover_and_load_plugins()
        # does an unsandboxed importlib.import_module() on every .py file in
        # plugins/, then calls apply_plugin_hook(self) - passing the entire
        # live app object (Tk root, ComfyUI client, filesystem access) into
        # whatever that file contains, with failures silently swallowed. A
        # security evaluation of this app flagged that as a real arbitrary-
        # code-execution vector reachable via Ctrl+F5 / "Live Sync & Hot
        # Reload" - any .py dropped into plugins/ (shared drive, a "plugin
        # pack" download, etc.) would get full-privilege execution. Kept as
        # None unconditionally rather than re-adding the try/except, so a
        # future accidental re-import can't silently re-enable this without
        # a deliberate code change here.
        self.plugin_loader = None

        # v6.9: removed core.hardware_scanner.HardwareScanner - it hard-
        # imports torch at module scope (PyInstaller's static analysis
        # follows that transitively and bundles the full torch+CUDA
        # runtime, ballooning this app's exe from ~73MB to ~2.9GB), and
        # its real side effect (tuning THIS process's torch cudnn/TF32
        # backend flags) is inert anyway: this app never runs models in
        # its own process, it only talks HTTP to a separate ComfyUI
        # process that has its own independent torch/CUDA state. Its
        # human-readable report (self.hardware_report) was also never
        # displayed anywhere in the UI. Archived to core/_archived/.
        self.hardware_report = None

        self.client = ComfyClient()
        self.prompts = PersonaPrompts()
        self.quotes = QuoteGenerator()
        if NeuralTagSynthesizer:
            self.neural_brain = NeuralTagSynthesizer(app_dir())
        else:
            self.neural_brain = None
        if AgentMeshOrchestrator:
            self.agent_mesh = AgentMeshOrchestrator(app_dir())
        else:
            self.agent_mesh = None
        self.director = SmartDirector(self.quotes)
        self.wildcards = WildcardEngine()
        self.taste = TasteMemory()
        self.director.taste = self.taste  # v5.0: director built before taste
        self.channel_ledger = ChannelLedger()  # v9.3: Channel Studio tracking
        self.brand = BrandKit()
        self.lut_grader = LutGrader()
        self.gpu_optimizer = GPUOptimizer()
        self.embeddings = EmbeddingIndex(app_dir())
        self.upscale_models = []
        self.motion_models = []
        # v6.9: cached once per connection in refresh_connection() rather
        # than queried live every time open_qwen_studio() is opened - a
        # tool evaluation found that on a server without Qwen-Image's
        # node classes installed (UNETLoader/CLIPLoader/VAELoader),
        # each /object_info query takes ~7s to come back empty, and a
        # repeated query could hang entirely - all on the main thread,
        # freezing the whole app. Probing once at connect time (same
        # pattern as self.upscale_models/self.director.models below)
        # means opening the window never makes a live network call.
        self.qwen_files = (None, None, None)
        self.wan_files = (None, None, None)
        self.last_gen = None     # remembered settings for REMIX A/B
        self.preview_img = None  # keep reference so tkinter doesn't GC it
        self.last_preview_path = None  # source for Remix / Cut Out / Face Ref

        # ── v3.2: server capabilities + reference conditioning state ──
        self.caps = {"ipadapter": False, "controlnet": False,
                     "openpose_preproc": False, "canny": False,
                     "bg_removal": False, "freeu": False, "pag": False,
                     "sag": False, "controlnet_depth": False,
                     "controlnet_lineart": False, "controlnet_tile": False,
                     "detailer": False, "tiled_upscale": False}
        self.bbox_face_model = None
        self.bbox_hand_model = None
        self.sam_model_name = None
        self.ipadapter_file = None
        self.clip_vision_file = None
        self.openpose_cn = None
        self.canny_cn = None
        self.depth_cn = None
        self.lineart_cn = None
        self.tile_cn = None
        self.bg_removal_model = None
        self.face_ref_path = None
        # v6.9: was missing entirely - _reference_kwargs() (line ~7910)
        # unconditionally reads self.pose_ref_path, but it was only ever
        # set by the set/clear-pose-ref UI actions, never initialized
        # here alongside its face_ref_path counterpart. Any code path
        # reaching _reference_kwargs() before the user ever touched Pose
        # Ref crashed with AttributeError - found via a tool evaluation
        # that called _resolve_gen_plan() on a freshly-constructed app.
        self.pose_ref_path = None
        self._upload_cache = {}  # (path, mtime) -> server-side name
        self.model_connect_times = {}
        self.current_model_name = None
        self.current_run_start_time = None
        self.is_rendering = False
        self.ap_cfg = {}
        self.ap_stats = {}

        self.output_dir = app_dir() / "generated_anime"
        self.output_dir.mkdir(exist_ok=True)

        # ── PHASE 1: Sessions, Gallery, Analytics, LoRA, Theme ──
        self.session_manager = SessionManager(self.output_dir)
        self.llm_config = load_llm_config()
        # apply the saved theme before any widget is built, so boot state
        # always matches the user's preference instead of always starting
        # dark regardless of what was saved
        # v9.8: build-aware default theme - Kids starts on the bright
        # "kids" palette instead of Pro's dark neon studio look. A saved
        # user choice still wins, so this only affects a fresh install.
        self.apply_theme(self.llm_config.get(
            "theme", "kids" if IS_KIDS_MODE else "dark"))
        self._current_theme = self.llm_config.get("theme", "dark")
        # v9.6: named font objects - previously every widget hardcoded its
        # own literal ("Segoe UI", 9) etc. tuple (183 occurrences), so a
        # future size/family change meant hunting down every literal.
        # tkFont.Font objects are live references: any widget that takes
        # `font=self.font_body` picks up a change automatically if this
        # object is ever reconfigured (e.g. a future "larger text" toggle).
        # v9.16: base point sizes captured once so a UI Scale change can
        # always rescale from the true original, not compound off an
        # already-scaled value on repeated Apply clicks.
        self._BASE_FONT_SIZES = {
            "font_body": 9, "font_body_bold": 9, "font_heading": 11,
            "font_small": 8, "font_small_bold": 8, "font_mono": 10,
            "font_mono_bold": 10, "font_mono_small": 8, "font_mono_body": 9,
            "font_subheading": 10, "font_body_medium": 10,
        }
        self.font_body = tkfont.Font(family="Segoe UI", size=9)
        self.font_body_bold = tkfont.Font(family="Segoe UI", size=9, weight="bold")
        self.font_heading = tkfont.Font(family="Segoe UI", size=11, weight="bold")
        self.font_small = tkfont.Font(family="Segoe UI", size=8)
        self.font_small_bold = tkfont.Font(family="Segoe UI", size=8, weight="bold")
        self.font_mono = tkfont.Font(family="Consolas", size=10)
        self.font_mono_bold = tkfont.Font(family="Consolas", size=10, weight="bold")
        self.font_mono_small = tkfont.Font(family="Consolas", size=8)
        self.font_mono_body = tkfont.Font(family="Consolas", size=9)
        self.font_subheading = tkfont.Font(family="Segoe UI", size=10, weight="bold")
        self.font_body_medium = tkfont.Font(family="Segoe UI", size=10)
        # v9.16: apply any previously-saved UI Scale immediately, so text
        # size is correct from the very first frame, not just after the
        # user re-opens Settings.
        self.ui_scale = float(self.llm_config.get("ui_scale", 1.0))
        if self.ui_scale != 1.0:
            self.apply_ui_scale(self.ui_scale, save=False)
        # v9.6: shared spacing tiers - replaces the inconsistent mix of
        # padx=2/padx=6/pady=(10,4) literals scattered per-dialog with one
        # deliberate rhythm: tight grouping, standard inline control
        # spacing, and section-header breathing room.
        self.PAD_TIGHT = 4
        self.PAD = 8
        self.PAD_SECTION = 14
        self.bias_slider = None
        self.model_chip = None

        # ── SPRINT 2: Favorites & History ──
        self.favorites = FavoritesManager(self.output_dir)
        self.history = GenerationHistory(self.output_dir)

        # ── SPRINT 3: Image Tagging & Collections ──
        self.image_tagger = ImageTagger(self.output_dir)

        # ── SPRINT 4: Performance & Stability ──
        self.cache = CacheManager()
        self.background = BackgroundTask(self.log)
        self.session_backup = SessionBackup(self.output_dir)
        self.session_backup.clean_old_backups(max_backups=20)

        # ── PHASE 2: System Profiling & Quality Orchestration ──
        self.profiler = SystemProfiler(self.client)
        self.quality_orchestrator = QualityOrchestrator(self.client)
        self.system_profile = {}  # will be populated on connection

        # ── PHASE 2, TIER 3: UGC Ecosystem ──
        self.persona_publisher = PersonaPublisher(self.output_dir)
        self.content_share = ContentShareManager(self.output_dir)
        self.ugc_discovery = UGCDiscoveryManager(self.output_dir)

        # ── PHASE 3, TIER 1: UGC Enhancements & Quality Metrics ──
        self.meta_manager = PerImageMetadataManager(self.output_dir)
        self.quality_calculator = QualityMetricsCalculator()
        self.prompt_optimizer = PromptOptimizer(
            app_dir() / "config" / "model_registry.json",
            app_dir() / "lora_registry.json"
        )
        self.ugc_manager = self.ugc_discovery  # alias for convenience

        # ── Character Sections: Organize personas by theme ──
        self.character_sections = CharacterSectionManager(self.prompts)

        # ── SPRINT 5: Create sample sessions on first run ──
        self._create_sample_sessions()

        self.busy = False
        self.stop_flag = False

        # Live Music Polling
        if WINRT_AVAILABLE:
            def start_music_loop():
                loop = asyncio.new_event_loop()
                asyncio.set_event_loop(loop)
                loop.create_task(self._poll_music())
                loop.run_forever()
            threading.Thread(target=start_music_loop, daemon=True).start()

        sw = root.winfo_screenwidth()
        sh = root.winfo_screenheight()
        init_w = min(1280, max(800, sw - 40))
        init_h = min(850, max(600, sh - 80))
        root.geometry(f"{init_w}x{init_h}")
        root.minsize(min(960, max(600, sw - 20)), min(640, max(500, sh - 40)))
        try:
            root.state("zoomed")
        except Exception:
            pass
        root.configure(bg=self.BG)
        
        try:
            from core.auto_installer import AutoInstaller
            installer = AutoInstaller(root, self._finish_init)
            installer.check_tools()
        except Exception:
            self._finish_init()

    def _finish_init(self):
        # v9.8: root stays withdrawn until AFTER the first-run welcome
        # (if any) has already closed - see _show_first_run_welcome's
        # own docstring for why. Building the UI while withdrawn is fine
        # (Tk lays out hidden windows normally); the old code deiconified
        # immediately, which meant a live-tested Windows quirk (a
        # background process's Toplevel does not reliably win the
        # foreground/z-order fight against a window that's already
        # visible, even with transient()+lift()+topmost) could leave the
        # welcome dialog stuck behind the main window with no visible
        # sign it existed at all - confirmed by enumerating live windows
        # during this session's own verification pass.
        self._build_ui()
        # v9.9: apply the effective user level right after the UI (and
        # therefore every tab/row _apply_user_level touches) exists - it
        # was previously ONLY invoked by the combobox's own
        # <<ComboboxSelected>> binding, so a saved/Kids-default level
        # other than Professional was cosmetically shown in the
        # combobox but never actually applied until the user manually
        # re-picked it from the dropdown.
        self._apply_user_level()
        # v6.1: force a final scrollregion recompute once the whole tree
        # (including all Notebook tabs) has fully laid out - the last
        # widgets added don't always trigger a fresh <Configure> in time
        # to be reflected in the initial scrollregion.
        self.root.after(150, lambda: self.main_canvas.configure(
            scrollregion=self.main_canvas.bbox("all")))
        self.log(f"Loaded {len(self.prompts.personas)} personas")
        self.log(f"Images will be saved to: {self.output_dir}")
        # v9.4/v9.8: first-launch hardware scan + welcome - runs exactly
        # once (the profile file's existence doubles as the marker) so a
        # fresh install gets auto-tuned settings and a genuine welcome
        # without ever re-stomping on whatever the user changes
        # afterward. Scan failures (e.g. no nvidia-smi on this machine)
        # log and continue rather than blocking startup.
        profile_path = app_dir() / "hardware_profile.json"
        if not profile_path.exists():
            try:
                hw = DeviceScanner.scan()
                rec = hw["recommended_profile"]
                self._apply_hardware_profile(hw, rec, silent=True)
                safe_json_save(profile_path, {
                    "scanned_at": datetime.now().isoformat(timespec="seconds"),
                    **hw})
                self._show_first_run_welcome(hw, rec)  # blocks until closed
            except Exception as e:
                self.log(f"Hardware auto-tune skipped: {e}")
        self.root.deiconify()
        threading.Thread(target=self.refresh_connection, daemon=True).start()
        # v10.4: silent background update check - never blocks startup,
        # never errors visibly (placeholder GITHUB_REPO, no internet, no
        # releases yet, and rate-limiting all just log one line and stop).
        threading.Thread(target=self._check_for_updates, daemon=True).start()

    def check_for_updates_manual(self):
        """Help-menu entry point - unlike the silent startup check, this
        always gives feedback (found/not-found/error), since a user who
        clicked a button expects a response."""
        if "YOUR_USERNAME" in GITHUB_REPO:
            messagebox.showinfo(
                "Check for Updates",
                "Update checking isn't configured yet - GITHUB_REPO is "
                "still the placeholder value.", parent=self.root)
            return
        threading.Thread(target=self._check_for_updates,
                         args=(True,), daemon=True).start()

    def _check_for_updates(self, manual: bool = False):
        """Compares APP_VERSION against the latest GitHub release tag.
        Only ever notifies (opens the browser to the release page on
        confirm) - never auto-downloads or self-replaces the running exe.
        Silent on any failure during the automatic startup check
        (placeholder repo, offline, no releases published yet,
        rate-limited) - startup must never be able to block or error
        visibly. When manual=True (Help menu), failures and the
        already-current case are also reported."""
        if "YOUR_USERNAME" in GITHUB_REPO:
            return  # placeholder never configured - nothing to check
        try:
            req = urllib.request.Request(
                f"https://api.github.com/repos/{GITHUB_REPO}/releases/latest",
                headers={"Accept": "application/vnd.github+json",
                         "User-Agent": APP_NAME})
            with urllib.request.urlopen(req, timeout=6) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            latest_tag = str(data.get("tag_name", "")).lstrip("vV").strip()
            html_url = data.get("html_url", "")
            body = str(data.get("body", "")).strip()
            assets = data.get("assets", []) or []
            exe_name = Path(sys.executable).name
            matching_asset = next(
                (a for a in assets if a.get("name") == exe_name), None)
            if not latest_tag or not html_url:
                if manual:
                    self.root.after(0, lambda: messagebox.showinfo(
                        "Check for Updates",
                        "Couldn't read release info from GitHub.",
                        parent=self.root))
                return

            def _ver_tuple(s):
                parts = []
                for p in s.split("."):
                    digits = "".join(c for c in p if c.isdigit())
                    parts.append(int(digits) if digits else 0)
                return tuple(parts)

            if _ver_tuple(latest_tag) <= _ver_tuple(APP_VERSION):
                if manual:
                    self.root.after(0, lambda: messagebox.showinfo(
                        "Check for Updates",
                        f"You're up to date (v{APP_VERSION}).",
                        parent=self.root))
                return  # already current or somehow ahead - nothing to do

            self.log(f"Update available: {APP_NAME} v{latest_tag} "
                     f"(you have v{APP_VERSION})")

            def _notify():
                notes = (body[:400] + "...") if len(body) > 400 else body
                msg = (f"A new version is available:\n\n"
                      f"{APP_NAME} v{latest_tag}\n"
                      f"(you have v{APP_VERSION})\n")
                if notes:
                    msg += f"\nWhat's new:\n{notes}\n"
                if matching_asset:
                    msg += "\nDownload and install it now?"
                    if messagebox.askyesno("Update Available", msg,
                                           parent=self.root):
                        self._start_self_update(matching_asset["browser_download_url"],
                                                exe_name)
                else:
                    msg += "\nOpen the download page now?"
                    if messagebox.askyesno("Update Available", msg,
                                           parent=self.root):
                        import webbrowser
                        webbrowser.open(html_url)
            self.root.after(0, _notify)
        except Exception as e:
            self.log(f"Update check skipped: {e}")
            if manual:
                self.root.after(0, lambda: messagebox.showerror(
                    "Check for Updates", f"Update check failed: {e}",
                    parent=self.root))

    def _start_self_update(self, asset_url: str, exe_name: str):
        """v9.10: downloads the matching release exe with a progress
        dialog, writes a temp relauncher .bat that waits for this
        process to exit then swaps the exe and restarts it, launches
        that .bat, and hard-exits. The OLD exe is never touched until
        the download AND the move both succeed - a failure at any
        point just leaves the app running unchanged, never bricked."""
        if self.busy:
            messagebox.showinfo("Update", "Finish or stop the current "
                                "generation before updating.", parent=self.root)
            return
        win, body = self._new_toplevel("Downloading Update", 420, 150,
                                       scrollable=False)
        lbl = ttk.Label(body, text="Starting download...", font=self.font_body)
        lbl.pack(pady=(16, 8), padx=16)
        pbar = ttk.Progressbar(body, mode="determinate", maximum=100)
        pbar.pack(fill="x", padx=16, pady=8)

        def _progress(done, total):
            pct = int(done * 100 / total) if total else 0
            mb_done, mb_total = done / 1e6, total / 1e6
            self.root.after(0, lambda: (
                pbar.configure(value=pct),
                lbl.configure(text=f"Downloading... {mb_done:.1f} / "
                             f"{mb_total:.1f} MB" if total else
                             f"Downloading... {mb_done:.1f} MB")))

        def _worker():
            dest = app_dir() / "update_download" / exe_name
            ok = _download_with_progress(asset_url, dest, on_progress=_progress,
                                         timeout=60.0)
            if not ok:
                self.root.after(0, lambda: (
                    win.destroy(),
                    messagebox.showerror("Update Failed",
                        "Download failed. The current version is untouched.",
                        parent=self.root)))
                return
            target_path = Path(sys.executable)
            bat_path = Path(tempfile.gettempdir()) / f"_3klipz_update_{os.getpid()}.bat"
            bat_contents = (
                "@echo off\r\n"
                "timeout /t 2 /nobreak >nul\r\n"
                f'move /y "{dest}" "{target_path}"\r\n'
                "if errorlevel 1 (\r\n"
                "  exit /b 1\r\n"
                ")\r\n"
                f'start "" "{target_path}"\r\n'
                'del "%~f0"\r\n'
            )
            bat_path.write_text(bat_contents, encoding="utf-8")

            def _finish():
                lbl.configure(text="Restarting...")
                self.root.after(300, lambda: self._launch_relauncher_and_exit(bat_path))
            self.root.after(0, _finish)

        threading.Thread(target=_worker, daemon=True).start()

    def _launch_relauncher_and_exit(self, bat_path: Path):
        try:
            subprocess.Popen(["cmd.exe", "/c", str(bat_path)],
                             creationflags=subprocess.CREATE_NO_WINDOW,
                             close_fds=True)
        except Exception as e:
            self.log(f"Update relauncher failed to start: {e}")
            return
        self.root.destroy()
        os._exit(0)

    def _show_first_run_welcome(self, hw: dict, rec: dict):
        """v9.8: the hardware auto-tune above ran with silent=True (by
        design - a blocking dialog on every launch would be worse than
        this), which meant a brand-new user never learned it happened at
        all, on top of never being told what the product even is or that
        it needs a running ComfyUI server. This is the one time it's
        genuinely worth interrupting - the marker file above guarantees
        it only ever shows once.

        BLOCKS until closed (via wait_window) - the caller (_finish_init)
        deliberately keeps the main window withdrawn until this returns.
        An earlier version deiconified the main window first and relied
        on transient()+lift()+topmost to force this dialog above it -
        live-tested and confirmed that does not reliably win the
        foreground/z-order fight on Windows once another window is
        already visible, leaving the dialog stuck behind the main window
        with no visible sign it existed. Keeping the main window hidden
        until this closes sidesteps the fight entirely instead of trying
        to win it."""
        win, body = self._new_toplevel(f"Welcome to {APP_TITLE}", 520, 460,
                                       min_w=440, min_h=380)
        win.transient(self.root)
        win.focus_force()
        win.grab_set()
        tk.Label(body, text=f"Welcome to {APP_TITLE}", bg=self.PANEL,
                 fg=self.ACCENT, font=self.font_heading).pack(
            anchor="w", padx=self.PAD_SECTION, pady=(self.PAD_SECTION, self.PAD_TIGHT))
        tk.Label(body, text="A local AI art and content studio, powered "
                 "by your own ComfyUI installation - nothing leaves this "
                 "machine.", bg=self.PANEL, fg=self.FG, wraplength=440,
                 justify="left").pack(anchor="w", padx=self.PAD_SECTION, pady=(0, self.PAD))

        tk.Frame(body, bg=self.DIVIDER, height=1).pack(fill="x", padx=self.PAD_SECTION)

        tk.Label(body, text="Hardware detected & applied:", bg=self.PANEL,
                 fg=self.ACCENT, font=self.font_body_bold).pack(
            anchor="w", padx=self.PAD_SECTION, pady=(self.PAD, self.PAD_TIGHT))
        hw_text = (f"• GPU: {hw.get('gpu_name', 'Unknown')} "
                   f"({hw.get('vram_gb', '?')} GB VRAM)\n"
                   f"• Tier: {hw.get('tier', 'Unknown')}\n"
                   f"• Profile applied: {rec.get('profile_name', 'default')} "
                   f"(steps={rec.get('steps')}, cfg={rec.get('cfg')})")
        tk.Label(body, text=hw_text, bg=self.PANEL, fg=self.FG_DIM,
                 justify="left", font=self.font_small).pack(
            anchor="w", padx=self.PAD_SECTION, pady=(0, self.PAD))

        tk.Frame(body, bg=self.DIVIDER, height=1).pack(fill="x", padx=self.PAD_SECTION)

        connected = bool(self.client.base_url)
        status_text = ("✓ ComfyUI is already running - you're ready to go."
                       if connected else
                       "⚠ ComfyUI doesn't look like it's running yet. "
                       "Launch it before generating.")
        tk.Label(body, text=status_text, bg=self.PANEL,
                 fg=self.OK if connected else self.WARN_TEXT,
                 wraplength=440, justify="left").pack(
            anchor="w", padx=self.PAD_SECTION, pady=(self.PAD, self.PAD))

        btn_row = tk.Frame(body, bg=self.PANEL)
        btn_row.pack(fill="x", padx=self.PAD_SECTION, pady=(0, self.PAD_SECTION))
        if not connected:
            ttk.Button(btn_row, text="Launch ComfyUI Desktop",
                      command=self.launch_comfy).pack(side="left")
        ttk.Button(btn_row, text="Get Started",
                  command=win.destroy).pack(side="right")
        self.root.wait_window(win)


    async def _poll_music(self):
        try:
            manager = await GlobalSystemMediaTransportControlsSessionManager.request_async()
            while True:
                session = manager.get_current_session()
                if session:
                    info = await session.try_get_media_properties_async()
                    title = info.title if info.title else "Unknown"
                    artist = info.artist if info.artist else "Unknown"
                    text = f"🎵 Now Playing: {title} by {artist}"
                else:
                    text = "🎵 Now Playing: ---"
                
                # Update UI safely
                if hasattr(self, 'music_var'):
                    self.root.after(0, lambda t=text: self.music_var.set(t))
                
                await asyncio.sleep(2)
        except Exception as e:
            self.log(f"Music polling failed: {e}")

    # ── v6.1: app-wide responsive window helpers ────────────────────────────
    def _section_header(self, parent, text):
        """v9.6: consistent main-window section header - font_heading +
        accent color + a thin DIVIDER underline, replacing 5 near-
        identical ad hoc Label constructions (PERSONAS/POSITIVE PROMPT/
        LATEST IMAGE/QUOTE GENERATOR/ACTIVITY LOG) that previously each
        picked their own font weight/size by hand. Returns the wrapper
        frame; caller packs/grids it like any other widget."""
        wrap = tk.Frame(parent, bg=self.PANEL)
        tk.Label(wrap, text=text, bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_heading).pack(anchor="w")
        tk.Frame(wrap, bg=self.DIVIDER, height=1).pack(fill="x", pady=(2, 0))
        return wrap

    def _clamp_window(self, win, w, h, *, min_w=None, min_h=None):
        """Screen-aware sizing for a Toplevel that doesn't need the full
        scrollable-body treatment (see _new_toplevel below): clamp to the
        actual screen, set a sensible minimum, ensure it's resizable, and
        center it. Lighter-weight, zero-risk fix (only ever touches a
        window's own geometry, never re-parents its children) - use this
        for simple dialogs; use _new_toplevel for windows dense enough to
        risk real content overflow even after clamping."""
        screen_w = self.root.winfo_screenwidth()
        screen_h = self.root.winfo_screenheight()
        w = min(w, int(screen_w * 0.9))
        h = min(h, int(screen_h * 0.9))
        x = max(0, (screen_w - w) // 2)
        y = max(0, (screen_h - h) // 2)
        win.geometry(f"{w}x{h}+{x}+{y}")
        win.minsize(min_w or int(w * 0.6), min_h or int(h * 0.6))
        win.resizable(True, True)

    def _new_toplevel(self, title, w, h, *, min_w=None, min_h=None,
                      scrollable=True):
        """Create a Toplevel sized/clamped for the actual screen, with a
        sensible minimum and (by default) a scrollable body, so content
        never gets silently clipped on a smaller display - the same fix
        Stage 3.5 applied to the main window, generalized app-wide.

        Returns (win, body): pack children into `body` when
        scrollable=True (body is just `win` itself when scrollable=False,
        for the few windows with their own coordinate-sensitive canvas,
        e.g. Inpaint's paint brush - wrapping those in a scrolling parent
        would desync clicks from canvas pixels)."""
        win = tk.Toplevel(self.root)
        win.title(title)
        win.configure(bg=self.PANEL)

        screen_w = self.root.winfo_screenwidth()
        screen_h = self.root.winfo_screenheight()
        w = min(w, int(screen_w * 0.9))
        h = min(h, int(screen_h * 0.9))
        x = max(0, (screen_w - w) // 2)
        y = max(0, (screen_h - h) // 2)
        win.geometry(f"{w}x{h}+{x}+{y}")
        win.minsize(min_w or int(w * 0.6), min_h or int(h * 0.6))
        win.resizable(True, True)

        if not scrollable:
            return win, win

        container = tk.Frame(win, bg=self.BG)
        container.pack(fill="both", expand=True)
        canvas = tk.Canvas(container, bg=self.BG, highlightthickness=0)
        scrollbar = ttk.Scrollbar(container, orient="vertical",
                                  command=canvas.yview)
        body = tk.Frame(canvas, bg=self.PANEL)
        body.bind("<Configure>", lambda e: canvas.configure(
            scrollregion=canvas.bbox("all")))
        canvas_window = canvas.create_window((0, 0), window=body, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        def _on_canvas_configure(event):
            if body.winfo_reqwidth() < event.width:
                canvas.itemconfig(canvas_window, width=event.width)
        canvas.bind("<Configure>", _on_canvas_configure)

        # bound to `win` (the toplevel bindtag), not bind_all - scoped to
        # only this window, doesn't leak into or clobber other open
        # windows' own scroll bindings (unlike a shared bind_all would)
        win.bind("<MouseWheel>", lambda e: canvas.yview_scroll(
            int(-1 * (e.delta / 120)), "units"))

        win.after(150, lambda: canvas.configure(
            scrollregion=canvas.bbox("all")))
        return win, body

    # ── UI construction ────────────────────────────────────────────────────
    def _build_ui(self):
        # v9.16: previously no minsize on the main window at all - only
        # Toplevels (via _clamp_window/_new_toplevel) got one. Below this,
        # the left panel's fixed-character-width widgets (persona list,
        # search entry) have nowhere left to go and start clipping.
        self.root.minsize(1024, 700)
        # ── SKEUOMORPHIC THEME CONFIGURATION ──
        style = ttk.Style(self.root)
        style.theme_use("clam")

        # Base styling with metallic/glass effect
        style.configure(".", background=self.PANEL, foreground=self.FG,
                        fieldbackground=self.BG, bordercolor=self.PANEL_HIGHLIGHT,
                        font=self.font_body)

        # Button styling - raised 3D effect, with hover/pressed/disabled
        # feedback (v9.6 - previously only active/pressed background was
        # mapped, with no distinct disabled look and no foreground change
        # on hover, so disabled controls looked identical to enabled ones).
        style.configure("TButton", background=self.PANEL_LIGHT, foreground=self.FG,
                       borderwidth=2, focuscolor=self.ACCENT, relief="ridge",
                       padding=self.PAD, font=self.font_body_bold)
        style.map("TButton",
                 background=[("disabled", self.DISABLED_BG),
                             ("pressed", self.PRESSED), ("active", self.HOVER)],
                 foreground=[("disabled", self.DISABLED_FG),
                             ("pressed", self.FG), ("active", self.FG)])

        # Label styling
        style.configure("TLabel", background=self.PANEL, foreground=self.FG,
                       font=self.font_body)

        # Entry styling - inset effect, disabled state
        style.configure("TEntry", fieldbackground=self.BG, foreground=self.FG,
                       borderwidth=2, relief="sunken", padding=self.PAD_TIGHT)
        style.map("TEntry",
                 fieldbackground=[("disabled", self.DISABLED_BG)],
                 foreground=[("disabled", self.DISABLED_FG)])

        # Combobox styling - hover/disabled feedback
        style.configure("TCombobox", fieldbackground=self.INPUT_BG, background=self.INPUT_BG,
                       foreground=self.FG, borderwidth=2, relief="sunken",
                       padding=self.PAD_TIGHT)
        style.map("TCombobox",
                 fieldbackground=[("disabled", self.DISABLED_BG), ("readonly", self.INPUT_BG)],
                 foreground=[("disabled", self.DISABLED_FG)],
                 background=[("active", self.HOVER)])

        # Scale (slider) styling - realistic slider
        style.configure("TScale", background=self.PANEL, troughcolor=self.BG,
                       borderwidth=2, relief="sunken", lightcolor=self.PANEL_HIGHLIGHT,
                       darkcolor=self.PANEL_LIGHT)

        # Frame styling
        style.configure("TFrame", background=self.PANEL)
        style.configure("TLabelframe", background=self.PANEL, foreground=self.FG,
                       borderwidth=2, relief="ridge", padding=self.PAD)
        style.configure("TLabelframe.Label", background=self.PANEL, foreground=self.ACCENT_LIGHT,
                       font=self.font_heading)

        # Notebook (tabs) styling - clearer selected/active/hover states
        style.configure("TNotebook", background=self.PANEL, borderwidth=1)
        style.configure("TNotebook.Tab", background=self.PANEL_LIGHT, foreground=self.FG_DIM,
                       padding=[self.PAD_SECTION, self.PAD], relief="ridge", borderwidth=2,
                       font=self.font_body)
        style.map("TNotebook.Tab",
                 background=[("selected", self.PANEL_HIGHLIGHT), ("active", self.HOVER)],
                 foreground=[("selected", self.ACCENT_LIGHT), ("active", self.FG)],
                 font=[("selected", self.font_body_bold)])

        # Scrollbar styling - metallic
        style.configure("TScrollbar", background=self.PANEL_LIGHT, troughcolor=self.BG,
                       borderwidth=2, relief="ridge", darkcolor=self.PANEL_LIGHT,
                       lightcolor=self.PANEL_HIGHLIGHT)

        # v9.6: previously unstyled ttk classes - left on bare "clam"
        # defaults, which clash visually with everything above.
        style.configure("TSpinbox", fieldbackground=self.INPUT_BG, foreground=self.FG,
                       background=self.PANEL_LIGHT, borderwidth=2, relief="sunken",
                       arrowsize=12, padding=self.PAD_TIGHT)
        style.map("TSpinbox",
                 fieldbackground=[("disabled", self.DISABLED_BG)],
                 foreground=[("disabled", self.DISABLED_FG)])

        style.configure("TCheckbutton", background=self.PANEL, foreground=self.FG,
                       font=self.font_body, focuscolor=self.ACCENT)
        style.map("TCheckbutton",
                 background=[("active", self.PANEL_HIGHLIGHT)],
                 foreground=[("disabled", self.DISABLED_FG), ("active", self.ACCENT_LIGHT)],
                 indicatorcolor=[("selected", self.ACCENT), ("!selected", self.INPUT_BG)])

        style.configure("TRadiobutton", background=self.PANEL, foreground=self.FG,
                       font=self.font_body, focuscolor=self.ACCENT)
        style.map("TRadiobutton",
                 background=[("active", self.PANEL_HIGHLIGHT)],
                 foreground=[("disabled", self.DISABLED_FG), ("active", self.ACCENT_LIGHT)],
                 indicatorcolor=[("selected", self.ACCENT), ("!selected", self.INPUT_BG)])

        style.configure("TMenubutton", background=self.PANEL_LIGHT, foreground=self.FG,
                       borderwidth=2, relief="ridge", padding=self.PAD, font=self.font_body)
        style.map("TMenubutton",
                 background=[("active", self.HOVER), ("disabled", self.DISABLED_BG)],
                 foreground=[("disabled", self.DISABLED_FG)])

        style.configure("TPanedwindow", background=self.PANEL)

        # Top bar / toolbar strip: connection status + flagship suites.
        # v9.6: PANEL_HIGHLIGHT background band + a DIVIDER underline
        # give this row a deliberate "toolbar" read instead of looking
        # like a loose row of buttons floating over the same panel color
        # as everything below it.
        top_wrap = tk.Frame(self.root, bg=self.PANEL_HIGHLIGHT)
        top_wrap.pack(fill="x", padx=8, pady=(8, 0))
        top = tk.Frame(top_wrap, bg=self.PANEL_HIGHLIGHT, padx=10, pady=8)
        top.pack(fill="x")
        tk.Frame(top_wrap, bg=self.DIVIDER, height=1).pack(fill="x")
        self.top_bar = top
        self.status_var = tk.StringVar(value="Checking for ComfyUI...")
        self.status_lbl = tk.Label(top, textvariable=self.status_var,
                                   bg=self.PANEL_HIGHLIGHT, fg=self.WARN_TEXT, font=self.font_subheading)
        self.status_lbl.pack(side="left")

        # Now Playing Music Display
        self.music_var = tk.StringVar(value="Now Playing: ---")
        self.music_lbl = tk.Label(top, textvariable=self.music_var,
                                  bg=self.PANEL_HIGHLIGHT, fg=self.INFO_TEXT, font=("Segoe UI", 9, "italic"))
        self.music_lbl.pack(side="right")

        self.timer_var = tk.StringVar(value="")
        self.timer_lbl = tk.Label(top, textvariable=self.timer_var,
                                   bg=self.PANEL_HIGHLIGHT, fg=self.ACCENT, font=self.font_mono_bold)
        self.timer_lbl.pack(side="left", padx=12)

        # ── v4.0: everything lives in the menubar now; the top bar keeps
        # only connection controls + the four flagship suites. The old
        # 29-button strip overflowed off-screen at normal window widths,
        # which made most windows literally unreachable.
        self._build_menubar()
        ttk.Button(top, text="⚡ 1-Click Power AI", command=self.start_1_click_power_ai).pack(side="right", padx=4)
        ttk.Button(top, text="🤖 Agent Mesh", command=self.open_agent_mesh).pack(side="right", padx=4)
        # v9.15: Settings top-bar button removed - reachable via Help menu
        # only now (see _build_menubar), avoiding the redundant duplicate
        # entry point.
        ttk.Button(top, text="🧠 MasterMind", command=self.open_mastermind).pack(side="right", padx=4)
        ttk.Button(top, text="🏭 Factory", command=self.open_factory).pack(side="right", padx=4)
        ttk.Button(top, text="🎬 Studio", command=self.open_creator_studio).pack(side="right", padx=4)
        ttk.Button(top, text="Reconnect", command=lambda: threading.Thread(
            target=self.refresh_connection, daemon=True).start()).pack(side="right", padx=4)
        ttk.Button(top, text="Launch Comfy Desktop",
                   command=self.launch_comfy).pack(side="right", padx=4)

