        self.ai_history = tk.Text(self.tab_ai, height=12, bg=self.INPUT_BG, fg=self.FG, wrap="word", state="disabled")
        self.ai_history.pack(fill="both", expand=True, pady=4)
        
        ai_input_frame = tk.Frame(self.tab_ai, bg=self.PANEL)
        ai_input_frame.pack(fill="x")
        self.ai_input = tk.Entry(ai_input_frame, bg=self.INPUT_BG, fg=self.FG)
        self.ai_input.pack(side="left", fill="x", expand=True, padx=(0, 4))
        
        def _send_ai_msg(*_):
            msg = self.ai_input.get().strip()
            if not msg: return
            self.ai_input.delete(0, "end")
            self.ai_history.config(state="normal")
            self.ai_history.insert("end", f"You: {msg}\n")
            self.ai_history.config(state="disabled")
            self.ai_history.see("end")
            
            def _ai_worker():
                sys_prompt = "You are a helpful AI."
                if IS_KIDS_MODE:
                    sys_prompt = ("You are a friendly, encouraging art assistant for children. "
                        "Keep every reply wholesome, positive and age-appropriate. "
                        "Use simple, clear language. Never produce profanity, violence, "
                        "gore, scary content, romance, or any adult theme. If a request "
                        "is not appropriate for a child, kindly decline and suggest a "
                        "fun, creative alternative instead.")
                else:
                    sys_prompt = ("You are an expert creative assistant for an AI art studio. "
                        "Help the user design characters, scenes and prompts. "
                        "Be direct and practical. You will not produce sexual content involving minors, "
                        "instructions for real-world harm, or content targeting real private individuals.")
                
                try:
                    import requests
                    # If Pro mode, try uncensored 8080 first
                    endpoint = "http://127.0.0.1:11434/api/chat"
                    model = getattr(self.quotes, 'model', None) or LLM_FALLBACK_MODEL
                    payload = {
                        "model": model,
                        "messages": [
                            {"role": "system", "content": sys_prompt},
                            {"role": "user", "content": msg}
                        ],
                        "stream": False
                    }
                    if not IS_KIDS_MODE:
                        # Uncensored OpenAI compatible
                        try:
                            r = requests.post("http://127.0.0.1:8080/v1/chat/completions", json=payload, timeout=2)
                            if r.status_code == 200:
                                reply = r.json()["choices"][0]["message"]["content"]
                                self.after(0, _append_reply, reply)
                                return
                        except: pass
                    
                    # Fallback to Ollama
                    r = requests.post(endpoint, json=payload, timeout=10)
                    if r.status_code == 200:
                        reply = r.json()["message"]["content"]
                    else:
                        reply = "Error: Could not reach LLM."
                except Exception as e:
                    reply = f"Error: {e}"
                
                self.after(0, _append_reply, reply)

            def _append_reply(reply):
                self.ai_history.config(state="normal")
                self.ai_history.insert("end", f"AI: {reply}\n\n")
                self.ai_history.config(state="disabled")
                self.ai_history.see("end")
                
            import threading
            threading.Thread(target=_ai_worker, daemon=True).start()
            
        self.ai_input.bind("<Return>", _send_ai_msg)
        ttk.Button(ai_input_frame, text="Send", command=_send_ai_msg).pack(side="right")


