            self.style_var.set(style)
            self.sampler_var.set(sampler)
            self.sched_var.set(sched)
            if extra_prompt:
                curr = self.pos_text.get("1.0", "end").strip()
                if extra_prompt not in curr:
                    self.pos_text.insert("end", f", {extra_prompt}")
            self.update_preview()
            self.log(f"⚡ Preset Applied: {mode} | {style}")

