    def _print_export_worker(self, src_path, product, cutout, upscale):
        """cutout -> upscale -> fit to print area -> 300 DPI PNG."""
        from PIL import Image
        self.busy = True
        start = time.time()
        try:
            work = Path(src_path)
            server_ok = bool(self.client.base_url)
            if cutout and server_ok and self.caps.get("bg_removal"):
                self.log("Print export: removing background...")
                name = self._upload_ref(work)
                wf = self.client.build_cutout_workflow(
                    name, self.bg_removal_model)
                entry = self._queue_and_wait(wf)
                img_info = next(i for o in entry["outputs"].values()
                                for i in o.get("images", []))
                data = self.client.download_image(
                    img_info["filename"], img_info.get("subfolder", ""),
                    img_info.get("type", "output"))
                work = self.output_dir / "_print_tmp_cut.png"
                work.write_bytes(data)
            elif cutout:
                self.log("Cut Out unavailable - exporting with background")

            if upscale and server_ok and self.upscale_models:
                self.log("Print export: 4x AI upscale...")
                name = self._upload_ref(work)
                wf = self.client.build_upscale_workflow(
                    name, self.upscale_models[0])
                entry = self._queue_and_wait(wf)
                img_info = next(i for o in entry["outputs"].values()
                                for i in o.get("images", []))
                data = self.client.download_image(
                    img_info["filename"], img_info.get("subfolder", ""),
                    img_info.get("type", "output"))
                work = self.output_dir / "_print_tmp_up.png"
                work.write_bytes(data)

            W, H = PRINT_SIZES[product]
            img = Image.open(work)
            has_alpha = img.mode == "RGBA"
            if has_alpha:
                # contain on transparent canvas (no cropping the subject)
                img.thumbnail((W, H), Image.LANCZOS)
                canvas = Image.new("RGBA", (W, H), (0, 0, 0, 0))
                canvas.paste(img, ((W - img.width) // 2,
                                   (H - img.height) // 2), img)
            else:
                canvas = fit_exact(img.convert("RGB"), W, H)

            out_dir = self.output_dir / "printify_export"
            out_dir.mkdir(exist_ok=True)
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            safe = re.sub(r"[^\w\-]+", "_", product.split(" (")[0])
            out = out_dir / f"{stamp}_{safe}_{W}x{H}.png"
            if self.brand.cfg.get("brand_products"):
                canvas = self.brand.apply(canvas)
            canvas.save(out, dpi=(300, 300))
            self.show_preview(out)
            self.log(f"Print file ready: printify_export/{out.name} "
                     f"({W}x{H} @300DPI, {time.time() - start:.0f}s)")
        except Exception as e:
            self.log(f"Print export ERROR: {e}")
            self.root.after(0, lambda: messagebox.showerror(
                "Print export failed", str(e)))
        finally:
            self.busy = False

    # ── v3.4: Adaptive Engine (VRAM guard / self-healing / factory) ────────
    def _vram_preflight(self, width: int, height: int, batch: int) -> tuple:
        """Free the LLM, then clamp settings that this GPU can't survive.
        Returns possibly-downshifted (width, height, batch)."""
        self.quotes.release_vram()
        _, total = self._get_gpu_vram_usage()
        if 0 < total <= 8.5:  # small-VRAM card: be conservative
            if batch > 1:
                self.log(f"VRAM guard: batch {batch} -> 1 "
                         f"({total:.0f}GB card)")
                batch = 1
            if width * height > 832 * 1216:
                self.log(f"VRAM guard: {width}x{height} -> 832x1216")
                width, height = (832, 1216) if height >= width else (1216, 832)
        return width, height, batch

    def _heal_backend(self, reason: str = "", error_type: str = "") -> bool:
        """Smart adaptive self-healing engine.
        Classifies the error type and chooses the best recovery strategy:
        - OOM / CUDA errors: flush VRAM cache instead of full restart
        - Connection drops: fast reconnect probe before restart
        - Full crashes: restart Comfy Desktop with exponential backoff
        Logs all heals to heal_journal.json for learning.
        """
        # -- Classify error type for smart recovery strategy --
        reason_lower = (reason + error_type).lower()
        is_oom = any(k in reason_lower for k in ("out of memory", "oom", "cuda", "vram", "cudaerror"))
        is_conn = any(k in reason_lower for k in ("urlerror", "connectionerror", "remotedisconnected", "timeout"))
        is_http = any(k in reason_lower for k in ("httperror", "rejected", "400", "422"))

        # -- Update heal journal --
        journal_path = self.output_dir / "heal_journal.json"
        try:
            journal = json.loads(journal_path.read_text(encoding="utf-8")) if journal_path.exists() else []
        except Exception:
            journal = []
        journal.append({
            "time": datetime.now().isoformat(),
            "reason": reason,
            "error_type": error_type,
            "strategy": "oom_flush" if is_oom else ("reconnect" if is_conn else "full_restart")
        })
        try:
            journal_path.write_text(json.dumps(journal[-50:], indent=2), encoding="utf-8")
        except Exception:
            pass

        # Strategy 1: OOM / CUDA -> wait briefly and re-probe before a
        # full restart. v6.9: this used to also call torch.cuda.empty_cache()
        # here and log "VRAM cache cleared successfully" - that call only
        # affects this companion app's own (unused) torch context, not
        # ComfyUI's separate process where the actual VRAM lives, so it
        # never did anything real - removed as a fake-success message a
        # tool evaluation flagged, alongside its transitive torch import
        # (which was bloating the PyInstaller build from ~73MB to ~2.9GB).
        # The actual useful behavior - waiting out a transient OOM and
        # re-probing before assuming a full restart is needed - is real
        # and kept.
        if is_oom:
            self.log("🧠 Smart Heal: VRAM OOM detected - waiting before restart")
            time.sleep(3)
            if self.client.detect():
                self.log("✅ Smart Heal: Backend still alive")
                return True

        # Strategy 2: Connection drop → fast reconnect probe (no restart)
        if is_conn:
            self.log("🔌 Smart Heal: Connection drop - fast reconnect probe (15s)...")
            deadline = time.time() + 15
            while time.time() < deadline:
                if self.client.detect():
                    self.log("✅ Smart Heal: Reconnected to backend without restart")
                    return True
                time.sleep(2)

        # Strategy 3: HTTP workflow rejection → non-recoverable, skip restart
        if is_http:
            self.log("⚠️ Smart Heal: Workflow rejected by backend (HTTP error) - skipping restart")
            return False

        # Strategy 4: Full crash → restart Comfy Desktop
        self.log(f"🔧 Smart Heal: Backend down ({reason}) - restarting Comfy Desktop...")
        _no_win = getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000)
        try:
            subprocess.run(["taskkill", "/IM", "Comfy Desktop.exe", "/F"],
                           capture_output=True, timeout=20, creationflags=_no_win)
        except Exception:
            pass
        time.sleep(5)
        try:
            if not Path(COMFY_DESKTOP_EXE).exists():
                self.log("⚠️ Smart Heal: Comfy Desktop exe not found - cannot self-heal")
                return False
            subprocess.Popen([COMFY_DESKTOP_EXE],
                             creationflags=getattr(subprocess, 'DETACHED_PROCESS', 0x00000008))
        except Exception as e:
            self.log(f"❌ Smart Heal: Launch failed: {e}")
            return False
        # Exponential backoff probe: 8s, 16s, 24s... up to 5 min
        wait = 8
        deadline = time.time() + 300
        while time.time() < deadline:
            if self.client.detect():
                try:
                    self._probe_capabilities()
                except Exception:
                    pass
                self.log("✅ Smart Heal: Backend is serving again")
                return True
            time.sleep(min(wait, 30))
            wait = min(wait + 8, 30)
        self.log("❌ Smart Heal: Timed out (5 min) - giving up")
        return False

    # -- Adaptive resolution stepping for VRAM OOM recovery --
    _ADAPT_STEPS = [
        (1024, 1024), (832, 1216), (768, 1024), (640, 896), (512, 768)
    ]
    _adapt_res_idx: int = 0  # index into _ADAPT_STEPS; advances on OOM

    def _adapt_workflow_for_retry(self, workflow: dict, attempt: int) -> dict:
        """On OOM/CUDA failure, step resolution down by one tier and reduce
        steps by 20% per attempt. Returns a modified workflow copy."""
        import copy
        wf = copy.deepcopy(workflow)
        # Advance resolution tier
        self._adapt_res_idx = min(self._adapt_res_idx + 1, len(self._ADAPT_STEPS) - 1)
        w, h = self._ADAPT_STEPS[self._adapt_res_idx]
        for node in wf.values():
            inp = node.get("inputs", {})
            if "width" in inp and "height" in inp:
                inp["width"] = w
                inp["height"] = h
            if "steps" in inp:
                inp["steps"] = max(6, int(inp["steps"] * 0.8))
        self.log(f"🔄 Smart Adapt: Retry attempt {attempt} with resolution {w}x{h}")
        return wf

    def _prevent_sleep(self):
        """Tell Windows not to sleep/hibernate while a generation is in
        flight. Found missing app-wide in a full-system audit: unattended
        Batch/Auto-Pilot sessions left running overnight have no wake-lock
        at all, so Windows' normal power-plan sleep timeout can suspend
        (or, on some machines/drivers, hard-kill) the whole process mid-run
        - explaining reports of the app "just vanishing" partway through a
        long session with zero crash.log entry and no batch_meta.json ever
        written (a true OS-level suspend/kill skips Python's finally
        blocks entirely, unlike a normal exception). Display is allowed to
        sleep/lock (battery-friendly); only system sleep is blocked."""
        try:
            import ctypes
            ES_CONTINUOUS = 0x80000000
            ES_SYSTEM_REQUIRED = 0x00000001
            ctypes.windll.kernel32.SetThreadExecutionState(
                ES_CONTINUOUS | ES_SYSTEM_REQUIRED)
        except Exception:
            pass

    def _allow_sleep(self):
        """Release the wake-lock set by _prevent_sleep()."""
        try:
            import ctypes
            ES_CONTINUOUS = 0x80000000
            ctypes.windll.kernel32.SetThreadExecutionState(ES_CONTINUOUS)
        except Exception:
            pass

    def _queue_and_wait(self, workflow: dict, on_tick=None, on_queued=None,
                        retries: int = 2) -> dict:
        """queue_prompt + wait_for_result with smart adaptive crash recovery.
        - HTTP 4xx/5xx: workflow validation error, don't restart
        - OOM/CUDA: flush VRAM + adaptive resolution stepping + retry
        - Connection drop: fast reconnect probe then backend restart
        - Full crash: restart Comfy Desktop with exponential backoff
        """
        self._prevent_sleep()
        try:
            return self._queue_and_wait_impl(workflow, on_tick, on_queued, retries)
        finally:
            self._allow_sleep()

    def _queue_and_wait_impl(self, workflow: dict, on_tick=None, on_queued=None,
                             retries: int = 2) -> dict:
        attempt = 0
        active_workflow = workflow
        while True:
            if getattr(self, "stop_flag", False):
                raise RuntimeError("Aborted by user")
            try:
                pid = self.client.queue_prompt(active_workflow)
                self.log(f"🚀 Prompt Queued (ID: {pid[:8]}...) | ComfyUI is processing...")
                if on_queued:
                    on_queued(pid)
                result = self.client.wait_for_result(
                    pid, on_tick=on_tick, stop_check=lambda: getattr(self, "stop_flag", False)
                )
                # Successful generation - reset adaptive resolution index
                self._adapt_res_idx = max(0, self._adapt_res_idx - 1)
                return result
            except urllib.error.HTTPError as e:
                try:
                    body = e.read().decode("utf-8", errors="replace")
                except Exception:
                    body = str(e)
                raise RuntimeError(
                    f"ComfyUI rejected the workflow (HTTP {e.code}): "
                    f"{body[:500]}") from e
            except RuntimeError as e:
                err_str = str(e).lower()
                # v8.7/v10.1: self-healing bad-checkpoint blocklist - a
                # junk file (VAE/LoRA/corrupt download) sitting in
                # checkpoints/ that isn't in _is_not_a_checkpoint's
                # hardcoded list yet. Blocklist it now so it's never
                # auto-picked again on this machine, regardless of
                # whether this attempt gets retried.
                _detect_and_mark_bad_checkpoint(str(e), log=self.log)
                if attempt >= retries:
                    raise
                # Detect OOM/CUDA in runtime errors from ComfyUI node execution
                is_oom = any(k in err_str for k in ("out of memory", "cuda", "vram", "oom"))
                attempt += 1
                if is_oom:
                    active_workflow = self._adapt_workflow_for_retry(active_workflow, attempt)
                    self._heal_backend(str(e), "OOM")
                else:
                    raise
            except (urllib.error.URLError, ConnectionError, OSError,
                    TimeoutError) as e:
                if attempt >= retries:
                    raise
                attempt += 1
                if not self._heal_backend(type(e).__name__, str(e)):
                    raise
                self.log(f"🔄 Smart Retry: Attempt {attempt + 1} of {retries + 1}...")

    # ── v3.7: Designer Suite ────────────────────────────────────────────────
    def open_design_tools(self):
        """Palette, colorways, multi-export, moodboard, tiling, converter."""
        win = tk.Toplevel(self.root)
        win.title("Design Tools")
        self._clamp_window(win, 560, 560)
        win.configure(bg=self.PANEL)
        design_dir = self.output_dir / "design"
        design_dir.mkdir(exist_ok=True)
        src = {"img": self.last_preview_path}

        srow = tk.Frame(win, bg=self.PANEL)
        srow.pack(fill="x", padx=12, pady=(12, 6))
        tk.Label(srow, text="Image:", bg=self.PANEL, fg=self.FG,
                 width=7, anchor="w").pack(side="left")
        src_lbl = tk.Label(srow, text=(src["img"].name[:32] if src["img"]
                                       else "(none)"),
                           bg=self.PANEL,
                           fg=self.SUCCESS_TEXT if src["img"] else self.FG_MUTED,
                           width=34, anchor="w")
        src_lbl.pack(side="left")

        def pick():
            p = filedialog.askopenfilename(
                title="Choose image", initialdir=self.output_dir,
                filetypes=self.IMG_FILETYPES, parent=win)
            if p:
                src["img"] = Path(p)
                src_lbl.config(text=src["img"].name[:32], fg=self.SUCCESS_TEXT)

        def use_last():
            if self.last_preview_path:
                src["img"] = self.last_preview_path
                src_lbl.config(text=src["img"].name[:32], fg=self.SUCCESS_TEXT)

        ttk.Button(srow, text="Browse", command=pick).pack(side="left",
                                                           padx=2)
        ttk.Button(srow, text="Last Gen", command=use_last).pack(
            side="left", padx=2)

        def need_src():
            if not src["img"] or not Path(src["img"]).exists():
                messagebox.showinfo("No image", "Pick an image first.",
                                    parent=win)
                return None
            return Path(src["img"])

        stamp = lambda: datetime.now().strftime("%Y%m%d_%H%M%S")

        def section(title):
            tk.Label(win, text=title, bg=self.PANEL, fg=self.ACCENT,
                     font=self.font_body_bold).pack(anchor="w",
                                                        padx=12,
                                                        pady=(10, 2))
            f = tk.Frame(win, bg=self.PANEL)
            f.pack(fill="x", padx=12)
            return f

        # ── palette ──
        f = section("🎨 COLOR PALETTE")

        def do_palette():
            p = need_src()
            if not p:
                return
            from PIL import Image
            colors = extract_palette(Image.open(p), 6)
            card = render_palette_card(colors, p.stem)
            out = design_dir / f"{stamp()}_palette.png"
            card.save(out)
            ex = palette_exports(colors)
            out.with_suffix(".txt").write_text(
                f"{ex['text']}\n\n{ex['css']}\n", encoding="utf-8")
            self.root.clipboard_clear()
            self.root.clipboard_append(" ".join(ex["hex"]))
            self.show_preview(out)
            self.log(f"Palette: {' '.join(ex['hex'])} (hex copied, "
                     f"card + CSS saved)")

        ttk.Button(f, text="Extract palette (card + CSS + clipboard)",
                   command=do_palette).pack(side="left")

        # ── colorways ──
        f = section("🌈 COLORWAYS (hue-shifted variants)")
        cw_n = tk.IntVar(value=5)
        ttk.Spinbox(f, textvariable=cw_n, from_=2, to=12,
                    width=4).pack(side="left")

        def do_colorways():
            p = need_src()
            if not p:
                return
            from PIL import Image
            base = Image.open(p)
            n = int(cw_n.get())
            outs = []
            for i in range(1, n + 1):
                cw = make_colorway(base, 360 * i / (n + 1))
                out = design_dir / f"{stamp()}_cw{i}.png"
                cw.save(out)
                outs.append(out)
            board = make_moodboard([p] + outs, cols=3, cell=360)
            bpath = design_dir / f"{stamp()}_colorways_sheet.png"
            board.save(bpath)
            self.show_preview(bpath)
            self.log(f"Colorways: {n} variants + contact sheet saved")

        ttk.Button(f, text="Generate variants + sheet",
                   command=do_colorways).pack(side="left", padx=6)

        # ── export everywhere ──
        f = section("📤 EXPORT EVERYWHERE (all platform sizes)")
        webp_var = tk.BooleanVar(value=True)
        tk.Checkbutton(f, text="+ WEBP web copies", variable=webp_var,
                       bg=self.PANEL, fg=self.FG_DIM, selectcolor=self.INPUT_BG,
                       activebackground=self.PANEL).pack(side="left",
                                                         padx=(0, 6))

        def do_export_all():
            p = need_src()
            if not p:
                return
            from PIL import Image
            base = Image.open(p).convert("RGB")
            pack = design_dir / f"{stamp()}_{p.stem[:24]}_pack"
            pack.mkdir(exist_ok=True)
            count = 0
            for name, (_, final) in PLATFORMS.items():
                safe = re.sub(r"[^\w]+", "_", name.split(" (")[0])
                img = fit_exact(base, *final)
                img.save(pack / f"{safe}_{final[0]}x{final[1]}.png")
                if webp_var.get():
                    img.save(pack / f"{safe}_{final[0]}x{final[1]}.webp",
                             quality=88)
                count += 1
            base.save(pack / f"original_{base.width}x{base.height}.png")
            self.log(f"Export pack: {count} platform sizes -> "
                     f"design/{pack.name}/")

        ttk.Button(f, text="Export all sizes",
                   command=do_export_all).pack(side="left")

        # ── moodboard ──
        f = section("🖼 MOODBOARD (pick multiple images)")
        mb_cols = tk.IntVar(value=3)
        ttk.Spinbox(f, textvariable=mb_cols, from_=2, to=6,
                    width=4).pack(side="left")

        def do_moodboard():
            paths = filedialog.askopenfilenames(
                title="Choose images for the moodboard",
                initialdir=self.output_dir, filetypes=self.IMG_FILETYPES,
                parent=win)
            if not paths:
                return
            board = self.brand.apply(
                make_moodboard(list(paths), cols=int(mb_cols.get())))
            out = design_dir / f"{stamp()}_moodboard.png"
            board.save(out)
            self.show_preview(out)
            self.log(f"Moodboard: {len(paths)} images -> {out.name}")

        ttk.Button(f, text="Build moodboard",
                   command=do_moodboard).pack(side="left", padx=6)

        # ── tile + convert ──
        f = section("🧩 SEAMLESS TILE CHECK   /   🔁 CONVERT")

        def do_tile():
            p = need_src()
            if not p:
                return
            from PIL import Image
            out = design_dir / f"{stamp()}_tile2x2.png"
            tile_preview(Image.open(p), 2).save(out)
            self.show_preview(out)
            self.log("Tile preview saved - visible seams mean the design "
                     "does not repeat cleanly")

        ttk.Button(f, text="2x2 tile preview",
                   command=do_tile).pack(side="left")
        q_var = tk.IntVar(value=85)
        ttk.Spinbox(f, textvariable=q_var, from_=50, to=100,
                    width=4).pack(side="left", padx=(12, 2))

        def do_convert(fmt):
            p = need_src()
            if not p:
                return
            from PIL import Image
            img = Image.open(p).convert("RGB")
            out = design_dir / f"{p.stem}.{fmt}"
            img.save(out, quality=int(q_var.get()))
            ratio = out.stat().st_size / p.stat().st_size * 100
            self.log(f"Converted -> {out.name} "
                     f"({out.stat().st_size / 1024:.0f} KB, "
                     f"{ratio:.0f}% of original)")

        ttk.Button(f, text="→ JPG",
                   command=lambda: do_convert("jpg")).pack(side="left",
                                                           padx=2)
        ttk.Button(f, text="→ WEBP",
                   command=lambda: do_convert("webp")).pack(side="left",
                                                            padx=2)

        self.log("Opened Design Tools")

    # ── v3.8: Music Studio ──────────────────────────────────────────────────
    def open_music_studio(self):
        """Album artwork generator + audio-reactive visualizer renderer."""
        win = tk.Toplevel(self.root)
        win.title("Music Studio - covers & visualizers")
        self._clamp_window(win, 600, 540)
        win.configure(bg=self.PANEL)
        nb = ttk.Notebook(win)
        nb.pack(fill="both", expand=True, padx=8, pady=8)
        music_dir = self.output_dir / "music"
        music_dir.mkdir(exist_ok=True)

        # ══ Tab 1: Album Artwork ══
        t1 = tk.Frame(nb, bg=self.PANEL)
        nb.add(t1, text="💿 Album Art")

        def mrow(parent, label):
            rr = tk.Frame(parent, bg=self.PANEL)
            rr.pack(fill="x", padx=12, pady=3)
            tk.Label(rr, text=label, bg=self.PANEL, fg=self.FG,
                     width=8, anchor="w").pack(side="left")
            return rr

        rr = mrow(t1, "Genre")
        genre_var = tk.StringVar(value=list(ALBUM_GENRES)[0])
        ttk.Combobox(rr, textvariable=genre_var, state="readonly",
                     values=list(ALBUM_GENRES), width=24).pack(side="left")
        layout_var = tk.StringVar(value="classic")
        tk.Label(rr, text="Text:", bg=self.PANEL, fg=self.FG,
                 padx=8).pack(side="left")
        ttk.Combobox(rr, textvariable=layout_var, state="readonly",
                     values=["classic", "minimal", "none"],
                     width=8).pack(side="left")

        rr = mrow(t1, "Artist")
        artist_var = tk.StringVar()
        ttk.Entry(rr, textvariable=artist_var, width=34).pack(side="left")
        rr = mrow(t1, "Title")
        title_var = tk.StringVar()
        ttk.Entry(rr, textvariable=title_var, width=34).pack(side="left")

        tk.Label(t1, text="Art direction (editable):", bg=self.PANEL,
                 fg=self.ACCENT, font=self.font_body_bold).pack(
            anchor="w", padx=12, pady=(8, 2))
        art_text = tk.Text(t1, height=3, bg=self.INPUT_BG, fg=self.FG,
                           wrap="word", insertbackground=self.FG,
                           borderwidth=0)
        art_text.pack(fill="x", padx=12)
        art_text.insert("1.0", ALBUM_GENRES[genre_var.get()])

        def on_genre(*_):
            art_text.delete("1.0", "end")
            art_text.insert("1.0", ALBUM_GENRES[genre_var.get()])
        genre_var.trace_add("write", on_genre)

        def glm_concept():
            if self.quotes.backend is None and not self.quotes.detect():
                messagebox.showinfo("No local LLM", "Start Ollama first.",
                                    parent=win)
                return
            concept_btn.configure(text="Thinking...", state="disabled")
            genre = genre_var.get()

            def _w():
                try:
                    data = self.quotes.complete_json(
                        f"Invent an album concept for the {genre} genre. "
                        'Reply ONLY JSON: {"title": "album title max 4 '
                        'words", "art": "one-line visual scene for the '
                        'cover, comma-separated tags"}',
                        temperature=0.95, max_tokens=200) or {}
                    data = {k.lower(): v for k, v in data.items()}
                    def _apply():
                        if data.get("title"):
                            title_var.set(str(data["title"]))
                        if data.get("art"):
                            art_text.delete("1.0", "end")
                            art_text.insert("1.0", str(data["art"]))
                    self.root.after(0, _apply)
                finally:
                    self.root.after(0, lambda: concept_btn.configure(
                        text="🎲 GLM Concept", state="normal"))
            threading.Thread(target=_w, daemon=True).start()

        up_var = tk.BooleanVar(value=True)
        crow = tk.Frame(t1, bg=self.PANEL)
        crow.pack(fill="x", padx=12, pady=8)
        concept_btn = ttk.Button(crow, text="🎲 GLM Concept",
                                 command=glm_concept)
        concept_btn.pack(side="left")
        tk.Checkbutton(crow, text="4x upscale (3000px master)",
                       variable=up_var, bg=self.PANEL, fg=self.FG_DIM,
                       selectcolor=self.INPUT_BG,
                       activebackground=self.PANEL).pack(side="left",
                                                         padx=8)
        cover_btn = ttk.Button(crow, text="🎨 GENERATE COVER")
        cover_btn.pack(side="right")
        tk.Label(t1, text="Output: music/ - 3000x3000 JPG (distribution "
                 "standard) + clean PNG without text.",
                 bg=self.PANEL, fg=self.FG_MUTED,
                 font=self.font_small).pack(anchor="w", padx=12)

        def gen_cover():
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI is not connected.",
                                     parent=win)
                return
            cover_btn.configure(state="disabled", text="Generating...")
            prompt = art_text.get("1.0", "end").strip()
            artist, title = artist_var.get().strip(), title_var.get().strip()
            layout = layout_var.get()
            upscale = up_var.get()

            def _w():
                try:
                    self.busy = True
                    from PIL import Image
                    positive = self.wildcards.expand(
                        f"{QUALITY}, album cover art, {prompt}, "
                        f"centered composition, iconic")
                    ckpt = self.ckpt_var.get()
                    w, h, b = self._vram_preflight(1024, 1024, 1)
                    wf = self.client.build_txt2img_workflow(
                        ckpt=ckpt, positive=positive,
                        negative=DEFAULT_NEGATIVE + ", text, watermark, "
                        "letters, typography",
                        width=1024, height=1024, batch_size=1,
                        steps=int(self.steps_var.get()),
                        cfg=float(self.cfg_var.get()),
                        sampler=self.sampler_var.get(),
                        scheduler=self.sched_var.get(),
                        seed=random.randint(0, 2**48),
                        lora=self._current_lora(),
                        lora_strength=float(self.lora_str_var.get()),
                        **self._reference_kwargs(ckpt))
                    entry = self._queue_and_wait(wf)
                    info = next(x for o in entry["outputs"].values()
                                for x in o.get("images", []))
                    raw = self.client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
                    base_p = music_dir / f"{stamp}_cover_raw.png"
                    base_p.write_bytes(raw)

                    if upscale and self.upscale_models:
                        self.log("Cover: 4x upscaling...")
                        name = self._upload_ref(base_p)
                        wfu = self.client.build_upscale_workflow(
                            name, self.upscale_models[0])
                        entry = self._queue_and_wait(wfu)
                        info = next(x for o in entry["outputs"].values()
                                    for x in o.get("images", []))
                        raw = self.client.download_image(
                            info["filename"], info.get("subfolder", ""),
                            info.get("type", "output"))
                        base_p.write_bytes(raw)

                    art = Image.open(base_p).convert("RGB")
                    master = fit_exact(art, 3000, 3000)
                    clean_p = music_dir / f"{stamp}_cover_clean.png"
                    master.save(clean_p)
                    final = master
                    if layout != "none" and (artist or title):
                        final = render_cover_text(master, artist, title,
                                                  layout)
                    out = music_dir / f"{stamp}_cover_3000.jpg"
                    final.save(out, quality=95, dpi=(300, 300))
                    base_p.unlink(missing_ok=True)
                    self.show_preview(out)
                    self.log(f"Album cover ready: music/{out.name} "
                             f"(+ clean master PNG)")
                except Exception as e:
                    self.log(f"Cover ERROR: {e}")
                finally:
                    self.busy = False
                    self.root.after(0, lambda: cover_btn.configure(
                        state="normal", text="🎨 GENERATE COVER"))
            threading.Thread(target=_w, daemon=True).start()

        cover_btn.configure(command=gen_cover)

        # ══ Tab 2: Visualizer ══
        t2 = tk.Frame(nb, bg=self.PANEL)
        nb.add(t2, text="🎵 Visualizer")
        vsrc = {"audio": None, "img": self.last_preview_path}

        rr = mrow(t2, "Audio")
        audio_lbl = tk.Label(rr, text="(none)", bg=self.PANEL,
                             fg=self.FG_MUTED, width=28, anchor="w")
        audio_lbl.pack(side="left")

        def pick_audio():
            p = filedialog.askopenfilename(
                title="Choose audio", parent=win,
                filetypes=[("Audio", "*.mp3 *.wav *.flac *.m4a *.ogg"),
                           ("All files", "*.*")])
            if p:
                vsrc["audio"] = Path(p)
                audio_lbl.config(text=vsrc["audio"].name[:26],
                                 fg=self.SUCCESS_TEXT)
        ttk.Button(rr, text="Browse", command=pick_audio).pack(side="left")

        rr = mrow(t2, "Artwork")
        vsrc["imgs"] = [vsrc["img"]] if vsrc["img"] else []
        vimg_lbl = tk.Label(rr, text=(vsrc["img"].name[:26] if vsrc["img"]
                                      else "(none)"),
                            bg=self.PANEL,
                            fg=self.SUCCESS_TEXT if vsrc["img"] else self.FG_MUTED,
                            width=28, anchor="w")
        vimg_lbl.pack(side="left")

        def _show_imgs():
            n = len(vsrc["imgs"])
            if n == 0:
                vimg_lbl.config(text="(none)", fg=self.FG_MUTED)
            elif n == 1:
                vimg_lbl.config(text=Path(vsrc["imgs"][0]).name[:26],
                                fg=self.SUCCESS_TEXT)
            else:
                vimg_lbl.config(text=f"{n} images (music video mode)",
                                fg=self.SUCCESS_TEXT)

        def pick_vimg():
            # multi-select: 1 image = classic visualizer, several = a
            # beat-synced slideshow music video
            paths = filedialog.askopenfilenames(
                title="Choose artwork (select SEVERAL for a music video)",
                initialdir=self.output_dir,
                filetypes=self.IMG_FILETYPES, parent=win)
            if paths:
                vsrc["imgs"] = [Path(p) for p in paths]
                _show_imgs()
        ttk.Button(rr, text="Browse", command=pick_vimg).pack(side="left")

        rr = mrow(t2, "Style")
        vstyle = tk.StringVar(value="bars")
        ttk.Combobox(rr, textvariable=vstyle, state="readonly",
                     values=["bars", "ring", "galaxy", "waveform"],
                     width=10).pack(side="left")
        vsrc["lyrics"] = ""
        lyr_btn_text = tk.StringVar(value="Lyrics...")
        vfont = tk.StringVar(value=list(TYPOGRAPHY)[0])

        def edit_lyrics():
            lw = tk.Toplevel(win)
            lw.title("Lyrics - one line per lyric, blank line = pause")
            lw.configure(bg=self.PANEL)
            txt = tk.Text(lw, width=52, height=18, bg=self.INPUT_BG,
                          fg=self.FG, wrap="word",
                          insertbackground=self.FG, borderwidth=0)
            txt.pack(padx=10, pady=8)
            txt.insert("1.0", vsrc["lyrics"])
            fr = tk.Frame(lw, bg=self.PANEL)
            fr.pack(fill="x", padx=10, pady=(0, 8))
            tk.Label(fr, text="Font:", bg=self.PANEL,
                     fg=self.FG).pack(side="left")
            ttk.Combobox(fr, textvariable=vfont, state="readonly",
                         values=list(TYPOGRAPHY),
                         width=26).pack(side="left", padx=6)

            def save_l():
                vsrc["lyrics"] = txt.get("1.0", "end").strip()
                n = len([l for l in vsrc["lyrics"].splitlines()
                         if l.strip()])
                lyr_btn_text.set(f"Lyrics ({n})" if n else "Lyrics...")
                lw.destroy()
            ttk.Button(fr, text="Save", command=save_l).pack(side="right")
        ttk.Button(rr, textvariable=lyr_btn_text,
                   command=edit_lyrics).pack(side="left", padx=6)
        vsize = tk.StringVar(value="1280x720 (YouTube)")
        ttk.Combobox(rr, textvariable=vsize, state="readonly",
                     values=["1280x720 (YouTube)",
                             "1080x1080 (square social)",
                             "1080x1920 (Shorts/TikTok)"],
                     width=22).pack(side="left", padx=6)
        preview_var = tk.BooleanVar(value=True)
        tk.Checkbutton(t2, text="15-second preview render (uncheck for "
                       "the full track)", variable=preview_var,
                       bg=self.PANEL, fg=self.FG_DIM,
                       selectcolor=self.INPUT_BG,
                       activebackground=self.PANEL).pack(anchor="w",
                                                         padx=12, pady=4)
        vstatus = tk.Label(t2, text="Pick audio + artwork, then render.",
                           bg=self.PANEL, fg=self.SUCCESS_TEXT,
                           font=self.font_body, wraplength=540,
                           justify="left")
        vstatus.pack(anchor="w", padx=12, pady=6)

        def render_now():
            if not vsrc["audio"] or not vsrc["audio"].exists():
                messagebox.showinfo("No audio", "Pick an audio file first.",
                                    parent=win)
                return
            vsrc["imgs"] = [p for p in vsrc["imgs"] if Path(p).exists()]
            if not vsrc["imgs"]:
                messagebox.showinfo("No artwork", "Pick artwork first.",
                                    parent=win)
                return
            if not find_ffmpeg():
                messagebox.showerror("ffmpeg missing",
                                     "Place ffmpeg.exe next to the app.",
                                     parent=win)
                return
            render_btn.configure(state="disabled", text="Rendering...")
            size = tuple(int(x) for x in
                         vsize.get().split(" ")[0].split("x"))
            max_s = 15 if preview_var.get() else None

            def setv(text):
                self.root.after(0, lambda: vstatus.config(text=text))

            def _w():
                self.busy = True
                try:
                    stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
                    tag = "musicvideo" if len(vsrc["imgs"]) > 1 else "visualizer"
                    out = music_dir / f"{stamp}_{tag}.mp4"
                    render_visualizer(
                        vsrc["audio"],
                        vsrc["imgs"] if len(vsrc["imgs"]) > 1
                        else vsrc["imgs"][0], out,
                        style=vstyle.get(), size=size, fps=30,
                        max_seconds=max_s,
                        log=lambda m: (self.log(m), setv(m)),
                        brand=self.brand if self.brand.active() else None,
                        lyrics=vsrc.get("lyrics") or None,
                        lyric_font=vfont.get())
                    setv(f"DONE: music/{out.name}")
                except Exception as e:
                    setv(f"Render failed: {e}")
                    self.log(f"Visualizer ERROR: {e}")
                finally:
                    self.busy = False
                    self.root.after(0, lambda: render_btn.configure(
                        state="normal", text="🎵 RENDER VISUALIZER"))
            threading.Thread(target=_w, daemon=True).start()

        render_btn = ttk.Button(t2, text="🎵 RENDER VISUALIZER",
                                command=render_now)
        render_btn.pack(pady=8)

        self.log("Opened Music Studio")

    # ── v3.9: Nintendo roster batch pack ────────────────────────────────────
    def open_nintendo_pack(self):
        """Run every persona in a named collection through the full
        pipeline: taste-guided style pick, auto-matched real LoRA stack,
        optional hi-res fix, quality scoring."""
        win = tk.Toplevel(self.root)
        win.title("Character Collection Pack")
        self._clamp_window(win, 480, 420)
        win.configure(bg=self.PANEL)

        collections = sorted({p.get("collection") for p in
                              self.prompts.personas.values()
                              if p.get("collection")})
        if not collections:
            collections = ["nintendo"]

        tk.Label(win, text="Collection:", bg=self.PANEL, fg=self.FG).pack(
            anchor="w", padx=12, pady=(12, 2))
        coll_var = tk.StringVar(value=("nintendo" if "nintendo" in
                                       collections else collections[0]))
        ttk.Combobox(win, textvariable=coll_var, state="readonly",
                    values=collections, width=20).pack(anchor="w", padx=12)

        count_lbl = tk.Label(win, text="", bg=self.PANEL, fg=self.SUCCESS_TEXT)
        count_lbl.pack(anchor="w", padx=12, pady=4)

        def refresh_count(*_):
            n = sum(1 for p in self.prompts.personas.values()
                   if p.get("collection") == coll_var.get())
            count_lbl.config(text=f"{n} characters in this collection")
        coll_var.trace_add("write", refresh_count)
        refresh_count()

        mode_var = tk.StringVar(value="Portrait")
        mrow = tk.Frame(win, bg=self.PANEL)
        mrow.pack(fill="x", padx=12, pady=6)
        tk.Label(mrow, text="Mode:", bg=self.PANEL, fg=self.FG,
                width=8, anchor="w").pack(side="left")
        ttk.Combobox(mrow, textvariable=mode_var, state="readonly",
                    values=["Exact", "Variant", "Portrait"],
                    width=14).pack(side="left")

        hires_var = tk.BooleanVar(value=True)
        tk.Checkbutton(win, text="Hi-Res Fix (sharper, ~30% slower)",
                      variable=hires_var, bg=self.PANEL, fg=self.FG_DIM,
                      selectcolor=self.INPUT_BG,
                      activebackground=self.PANEL).pack(anchor="w", padx=12)
        stack_var = tk.BooleanVar(value=True)
        tk.Checkbutton(win, text="Stack up to 2 auto-matched LoRAs",
                      variable=stack_var, bg=self.PANEL, fg=self.FG_DIM,
                      selectcolor=self.INPUT_BG,
                      activebackground=self.PANEL).pack(anchor="w", padx=12)

        status = tk.Label(win, text="Ready", bg=self.PANEL, fg=self.SUCCESS_TEXT,
                          wraplength=440, justify="left")
        status.pack(anchor="w", padx=12, pady=10)

        def start():
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI is not connected.",
                                     parent=win)
                return
            start_btn.configure(state="disabled", text="Running...")
            self.stop_flag = False

            def set_status(t):
                self.root.after(0, lambda: status.config(text=t))

            def done():
                self.root.after(0, lambda: start_btn.configure(
                    state="normal", text="🎮 START PACK"))
            threading.Thread(
                target=self._pack_worker,
                args=(coll_var.get(), mode_var.get(), hires_var.get(),
                      stack_var.get(), set_status, done),
                daemon=True).start()

        btnrow = tk.Frame(win, bg=self.PANEL)
        btnrow.pack(fill="x", padx=12, pady=8)
        start_btn = ttk.Button(btnrow, text="🎮 START PACK", command=start)
        start_btn.pack(side="left")
        ttk.Button(btnrow, text="Stop",
                  command=self.request_stop).pack(side="left", padx=8)

    def _pack_worker(self, collection, mode, use_hires, use_stack,
                     set_status, done_cb):
        self.busy = True
        t0 = time.time()
        try:
            members = [(k, p) for k, p in self.prompts.personas.items()
                      if p.get("collection") == collection]
            if not members:
                set_status(f"No characters tagged '{collection}'")
                return
            ckpt = self.ckpt_var.get()
            available = [v for v in self.lora_box["values"] if v != "(none)"]
            out_dir = (self.output_dir / f"{collection}_pack" /
                      datetime.now().strftime("%Y%m%d_%H%M"))
            out_dir.mkdir(parents=True, exist_ok=True)
            made = 0
            for idx, (key, persona) in enumerate(members, 1):
                if self.stop_flag:
                    set_status(f"Stopped at {idx}/{len(members)}")
                    return
                name = persona.get("name", key)
                set_status(f"[{idx}/{len(members)}] {name}...")
                try:
                    style = self.taste.pick_style(collection, ART_STYLES)
                    positive = self.wildcards.expand(
                        self.prompts.build(mode, persona, style))
                    negative = DEFAULT_NEGATIVE

                    lora_stack = []
                    match1 = pick_lora_for_style(style, available)
                    if match1:
                        lora_stack.append(match1)
                        if use_stack:
                            for entries in load_lora_registry().values():
                                for entry in entries:
                                    # v6.6: this manual second-LoRA scan
                                    # bypassed the base_model filter that
                                    # pick_lora_for_style (used for match1
                                    # just above) already applies - a
                                    # non-SDXL-tagged LoRA (e.g. the
                                    # registry's own ZIT_CPA_FREE.safetensors,
                                    # base_model "ZImageTurbo") could get
                                    # stacked onto this app's all-SDXL
                                    # checkpoints, the same corrupted-
                                    # output risk fixed elsewhere today.
                                    base = str(entry.get(
                                        "base_model", "")).lower()
                                    if base and "sdxl" not in base:
                                        continue
                                    if entry["file"] != match1[0] and \
                                            entry["file"] in available and \
                                            len(lora_stack) < 2:
                                        hits = sum(
                                            1 for s in entry.get(
                                                "recommended_styles", [])
                                            if s.lower() in style.lower())
                                        if hits:
                                            lora_stack.append(
                                                (entry["file"],
                                                 entry.get(
                                                     "recommended_strength",
                                                     0.6)))

                    w, h, b = self._vram_preflight(832, 1216, 1)
                    hires_kw = ({"hires_fix": True, "hires_scale": 1.4,
                                "hires_denoise": 0.4} if use_hires else {})
                    wf = self.client.build_txt2img_workflow(
                        ckpt=ckpt, positive=positive, negative=negative,
                        width=w, height=h, batch_size=b,
                        steps=int(self.steps_var.get()),
                        cfg=float(self.cfg_var.get()),
                        sampler=self.sampler_var.get(),
                        scheduler=self.sched_var.get(),
                        seed=random.randint(0, 2**48),
                        lora=lora_stack or None, **hires_kw)
                    entry = self._queue_and_wait(wf)
                    info = next(x for o in entry["outputs"].values()
                               for x in o.get("images", []))
                    raw = self.client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    safe_name = re.sub(r"[^\w\-]+", "_", key)
                    out_path = out_dir / f"{idx:03d}_{safe_name}.png"
                    out_path.write_bytes(raw)
                    if self.brand.active():
                        from PIL import Image
                        self.brand.apply(Image.open(out_path)).save(out_path)

                    score = self.quality_calculator.\
                        calculate_overall_quality_score(
                            self.quality_calculator.
                            calculate_image_quality(out_path))
                    self.taste.record(collection, style, score)
                    out_path.with_suffix(".json").write_text(
                        json.dumps({
                            "character": name, "style": style,
                            "lora_stack": lora_stack, "hires_fix": use_hires,
                            "score": score, "mode": mode,
                        }, indent=1, ensure_ascii=False), encoding="utf-8")
                    made += 1
                    self.log(f"[{collection}] {name}: {style.split(',')[0]}"
                             f" | lora={[l[0] for l in lora_stack]} "
                             f"| score={score:.1f}")
                except Exception as e:
                    self.log(f"[{collection}] {name} FAILED: {e}")
            mins = (time.time() - t0) / 60
            set_status(f"DONE - {made}/{len(members)} in {mins:.0f} min\n"
                      f"{out_dir}")
            self.log(f"{collection} pack complete: {made}/{len(members)} "
                    f"in {mins:.0f} min")
        finally:
            self.busy = False
            done_cb()

    # ── v3.6: MasterMind dashboard ──────────────────────────────────────────
    def open_mastermind(self):
        """Goal editor, buffer status, approval gate, cycle control."""
        mm = MasterMind()
        win, body = self._new_toplevel(
            "MasterMind - production orchestrator", 680, 600)

        # goals row
        grow = tk.Frame(body, bg=self.PANEL)
        grow.pack(fill="x", padx=12, pady=(12, 4))
        tk.Label(grow, text="Buffer target / niche:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        target_var = tk.IntVar(value=mm.goals["buffer_target"])
        ttk.Spinbox(grow, textvariable=target_var, from_=3, to=50,
                    width=4).pack(side="left", padx=4)
        tk.Label(grow, text="Max items / cycle:", bg=self.PANEL,
                 fg=self.FG, padx=8).pack(side="left")
        cap_var = tk.IntVar(value=mm.goals["max_items_per_cycle"])
        ttk.Spinbox(grow, textvariable=cap_var, from_=3, to=40,
                    width=4).pack(side="left", padx=4)

        tk.Label(body, text="ACTIVE NICHES", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_body_bold).pack(anchor="w", padx=12)
        nlist = tk.Listbox(body, selectmode="multiple", height=5,
                           bg=self.INPUT_BG, fg=self.FG, exportselection=False,
                           selectbackground=self.ACCENT)
        all_niches = list(NICHES)
        for i, n in enumerate(all_niches):
            nlist.insert("end", n)
            if n in mm.goals["niches"]:
                nlist.selection_set(i)
        nlist.pack(fill="x", padx=12)

        status_txt = tk.Text(body, height=7, bg=self.CONSOLE_BG, fg=self.FG,
                             font=self.font_mono_body, borderwidth=0)
        status_txt.pack(fill="x", padx=12, pady=6)

        tk.Label(body, text="AWAITING APPROVAL (approve trains taste UP, "
                 "reject trains it DOWN)", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_body_bold).pack(anchor="w", padx=12)
        pend = tk.Listbox(body, height=8, bg=self.INPUT_BG, fg=self.FG,
                          selectbackground=self.ACCENT, exportselection=False)
        pend.pack(fill="both", expand=True, padx=12, pady=4)
        pend_ids = []

        def refresh():
            nonlocal mm, pend_ids
            mm = MasterMind()
            status_txt.configure(state="normal")
            status_txt.delete("1.0", "end")
            status_txt.insert("1.0", mm.stats_text() +
                              f"\napproved queue ready to post: "
                              f"{len(mm.approved_queue())}")
            status_txt.configure(state="disabled")
            pend.delete(0, "end")
            pend_ids = []
            for a in mm.pending_approval():
                score = f" [{a['score']:.1f}]" if a.get("score") else ""
                pend.insert("end", f"{a['niche']:<16} {a['type']:<11}"
                                   f"{score}  {Path(a['file']).name}")
                pend_ids.append(a["id"])

        def save_goals():
            mm.goals["buffer_target"] = int(target_var.get())
            mm.goals["max_items_per_cycle"] = int(cap_var.get())
            sel = [nlist.get(i) for i in nlist.curselection()]
            if sel:
                mm.goals["niches"] = sel
            mm.save_goals()
            self.log("MasterMind goals saved")
            refresh()

        def selected_asset():
            sel = pend.curselection()
            if not sel:
                return None
            return next((a for a in mm.ledger
                         if a["id"] == pend_ids[sel[0]]), None)

        def preview_asset():
            a = selected_asset()
            if a and Path(a["file"]).exists():
                self.show_preview(a["file"])

        def decide(stage, teach_score):
            a = selected_asset()
            if not a:
                return
            mm.set_stage(a["id"], stage)
            if a.get("style"):
                self.taste.record(a["niche"], a["style"], teach_score)
            self.log(f"MasterMind: {Path(a['file']).name} -> {stage}")
            refresh()

        def mark_posted():
            # promote oldest approved asset in the selected niche list
            queue = mm.approved_queue()
            if not queue:
                messagebox.showinfo("Empty", "No approved assets to mark.",
                                    parent=win)
                return
            a = queue[0]
            mm.set_stage(a["id"], "posted")
            self.log(f"MasterMind: posted {Path(a['file']).name}")
            refresh()

        def post_via_api():
            """Post the oldest approved asset to Pinterest - always asks
            for confirmation before anything leaves this machine."""
            keys = load_api_keys()
            tok = keys.get("pinterest_token", "")
            board = keys.get("pinterest_board_id", "")
            if not tok or not board:
                messagebox.showinfo(
                    "No API keys",
                    "Add your Pinterest token and board ID in Settings > "
                    "APIs first.", parent=win)
                return
            queue = mm.approved_queue()
            if not queue:
                messagebox.showinfo("Empty", "No approved assets in the "
                                    "queue.", parent=win)
                return
            a = queue[0]
            img = Path(a["file"])
            if not img.exists():
                mm.set_stage(a["id"], "rejected")
                refresh()
                return
            title, desc = img.stem, ""
            pin_txt = img.with_suffix(".pin.txt")
            if pin_txt.exists():
                raw = pin_txt.read_text(encoding="utf-8")
                sections = {}
                cur = None
                for ln in raw.splitlines():
                    if ln.strip().endswith(":") and ln.strip().isupper() is False and ln.strip() in ("TITLE:", "DESCRIPTION:", "HASHTAGS:"):
                        cur = ln.strip()[:-1]
                        sections[cur] = []
                    elif cur:
                        sections[cur].append(ln)
                title = " ".join(sections.get("TITLE", [])).strip() or title
                desc = (" ".join(sections.get("DESCRIPTION", [])).strip() +
                        " " + " ".join(sections.get("HASHTAGS", [])).strip()
                        ).strip()
            if not messagebox.askyesno(
                    "Post to Pinterest?",
                    f"This will publish to your Pinterest board "
                    f"{board}:\n\n{img.name}\nTitle: {title[:80]}\n\n"
                    "Proceed?", parent=win):
                return

            def _w():
                try:
                    pin_id = PinterestClient(tok).create_pin(
                        board, img, title, desc)
                    mm.set_stage(a["id"], "posted")
                    self.log(f"Pinterest: pinned {img.name} (id {pin_id})")
                    self.root.after(0, refresh)
                except Exception as e:
                    self.log(f"Pinterest post failed: {e}")
                    self.root.after(0, lambda: messagebox.showerror(
                        "Post failed", str(e), parent=win))
            threading.Thread(target=_w, daemon=True).start()

        def run_cycle():
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            cyc_btn.configure(state="disabled", text="Running...")

            def _w():
                try:
                    self.busy = True
                    run_mastermind_cycle(log=self.log)
                finally:
                    self.busy = False
                    self.root.after(0, lambda: (
                        cyc_btn.configure(state="normal",
                                          text="▶ RUN CYCLE NOW"),
                        refresh()))
            threading.Thread(target=_w, daemon=True).start()

        def schedule_nightly():
            exe = sys.executable if getattr(sys, "frozen", False) else None
            if not exe:
                messagebox.showinfo(
                    "Use the exe", "Nightly scheduling works from the "
                    "built exe (comfy_companion.exe).", parent=win)
                return
            if not messagebox.askyesno(
                    "Schedule nightly cycle",
                    "Create a Windows scheduled task that runs a "
                    "MasterMind production cycle every night at 3:00 AM?",
                    parent=win):
                return

            # v6.7: this used to call subprocess.run(...) directly on the
            # Tk main thread - schtasks can take several seconds (longer
            # under a loaded Task Scheduler), freezing the whole app's UI
            # for the duration, unlike run_cycle/post_via_api in this same
            # window which both already thread their blocking calls.
            def _w():
                try:
                    r = subprocess.run(
                        ["schtasks", "/Create", "/F",
                         "/TN", "ComfyCompanion MasterMind",
                         "/TR", f'"{exe}" --mastermind',
                         "/SC", "DAILY", "/ST", "03:00"],
                        capture_output=True, text=True, timeout=30)
                    if r.returncode == 0:
                        self.root.after(0, lambda: (
                            self.log("MasterMind: nightly 3AM task scheduled"),
                            messagebox.showinfo(
                                "Scheduled",
                                "Nightly cycle scheduled (3:00 AM).",
                                parent=win)))
                    else:
                        err = r.stderr[:300]
                        self.root.after(0, lambda: messagebox.showerror(
                            "Failed", err, parent=win))
                except Exception as e:
                    err = str(e)
                    self.root.after(0, lambda: messagebox.showerror(
                        "Failed", err, parent=win))
            threading.Thread(target=_w, daemon=True).start()

        brow = tk.Frame(body, bg=self.PANEL)
        brow.pack(fill="x", padx=12, pady=8)
        ttk.Button(brow, text="Save Goals",
                   command=save_goals).pack(side="left")
        ttk.Button(brow, text="Preview",
                   command=preview_asset).pack(side="left", padx=4)
        ttk.Button(brow, text="✓ Approve",
                   command=lambda: decide("approved", 9.0)).pack(
            side="left", padx=4)
        ttk.Button(brow, text="✗ Reject",
                   command=lambda: decide("rejected", 3.5)).pack(
            side="left", padx=4)
        ttk.Button(brow, text="Mark oldest posted",
                   command=mark_posted).pack(side="left", padx=4)
        ttk.Button(brow, text="📌 Post via API",
                   command=post_via_api).pack(side="left", padx=4)
        cyc_btn = ttk.Button(brow, text="▶ RUN CYCLE NOW",
                             command=run_cycle)
        cyc_btn.pack(side="right")
        ttk.Button(brow, text="🌙 Schedule 3AM",
                   command=schedule_nightly).pack(side="right", padx=6)

        refresh()
        self.log("Opened MasterMind")

    # ── v3.4: Overnight Content Factory ─────────────────────────────────────
    def open_factory(self):
        """Plan with GLM, unload it, then generate + score + curate
        unattended. Phase-separated so LLM and diffusion never share VRAM."""
        win, body = self._new_toplevel(
            "Content Factory - plan, generate, score, curate", 520, 520)

        tk.Label(body, text="NICHES (multi-select)", bg=self.PANEL,
                 fg=self.ACCENT, font=self.font_body_bold).pack(
            anchor="w", padx=12, pady=(12, 2))
        niche_list = tk.Listbox(body, selectmode="multiple", height=8,
                                bg=self.INPUT_BG, fg=self.FG, exportselection=False,
                                selectbackground=self.ACCENT)
        for n in NICHES:
            niche_list.insert("end", n)
        niche_list.selection_set(0)
        niche_list.pack(fill="x", padx=12)

        opt = tk.Frame(body, bg=self.PANEL)
        opt.pack(fill="x", padx=12, pady=8)
        tk.Label(opt, text="Items per niche:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        n_var = tk.IntVar(value=4)
        ttk.Spinbox(opt, textvariable=n_var, from_=2, to=10,
                    width=4).pack(side="left", padx=6)

        mix = {"quote_card": tk.BooleanVar(value=True),
               "art_pin": tk.BooleanVar(value=True),
               "meme": tk.BooleanVar(value=True)}
        for label, key in (("Quote cards", "quote_card"),
                           ("Art pins", "art_pin"), ("Memes", "meme")):
            tk.Checkbutton(opt, text=label, variable=mix[key],
                           bg=self.PANEL, fg=self.FG_DIM,
                           selectcolor=self.INPUT_BG,
                           activebackground=self.PANEL).pack(side="left",
                                                             padx=6)

        info = tk.Label(body, text=(
            "Phase 1: GLM plans every quote, caption and pin metadata,\n"
            "then unloads from VRAM.\n"
            "Phase 2: diffusion generates art (VRAM-guarded, self-healing).\n"
            "Phase 3: quality scoring sorts winners/ vs review/ and the\n"
            "taste memory learns which styles scored best."),
            bg=self.PANEL, fg=self.FG_MUTED, justify="left",
            font=self.font_small)
        info.pack(anchor="w", padx=12, pady=4)

        status = tk.Label(body, text="Ready", bg=self.PANEL, fg=self.SUCCESS_TEXT,
                          font=self.font_body, wraplength=480,
                          justify="left")
        status.pack(anchor="w", padx=12, pady=6)

        def set_status(text):
            self.root.after(0, lambda: status.config(text=text))

        def start():
            niches = [niche_list.get(i) for i in niche_list.curselection()]
            types = [k for k, v in mix.items() if v.get()]
            if not niches or not types:
                messagebox.showinfo("Pick options",
                                    "Select at least one niche and one "
                                    "content type.", parent=win)
                return
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self._llm_ready(win):
                return
            start_btn.configure(state="disabled")
            self.stop_flag = False
            threading.Thread(
                target=self._factory_worker,
                args=(niches, int(n_var.get()), types, set_status,
                      lambda: self.root.after(0, lambda: start_btn.configure(
                          state="normal"))),
                daemon=True).start()

        btnrow = tk.Frame(body, bg=self.PANEL)
        btnrow.pack(fill="x", padx=12, pady=8)
        start_btn = ttk.Button(btnrow, text="🏭 START FACTORY",
                               command=start)
        start_btn.pack(side="left")
        ttk.Button(btnrow, text="Stop", command=self.request_stop).pack(
            side="left", padx=8)

        def show_taste():
            rows = self.taste.report(top=10)
            text = "TOP PERFORMING (context | style -> avg score, runs):\n"
            text += "\n".join(f"  {k}  ->  {e:.2f}  ({n} runs)"
                              for k, e, n in rows) if rows else "  (no data yet)"
            messagebox.showinfo("Taste Memory", text, parent=win)
        ttk.Button(btnrow, text="📊 Taste report",
                   command=show_taste).pack(side="right")

    def _factory_worker(self, niches, per_niche, types, set_status, done_cb):
        self.busy = True
        run_start = time.time()
        try:
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M')}"
            base = self.output_dir / "factory_output" / stamp
            personas = list(self.prompts.personas.values())

            # ── Phase 1: GLM plans everything, then unloads ──
            plan = []
            for niche in niches:
                if self.stop_flag:
                    return
                set_status(f"Phase 1/3 - GLM planning {niche}...")
                # top-up loop: GLM often under-delivers; keep asking for
                # the remainder until the quota is filled (max 3 rounds)
                items, attempts = [], 0
                while len(items) < per_niche and attempts < 3:
                    want = per_niche - len(items)
                    raw = self.quotes.complete(
                        f"Create {want} Pinterest content plans for the "
                        f"{niche} niche (tone: {NICHES[niche]['tone']}). "
                        'Reply ONLY JSON: {"items": [{"text": "a short '
                        'original quote max 20 words", "top": "meme top '
                        'max 8 words", "bottom": "meme bottom max 8 '
                        'words", "title": "pin title max 90 chars", '
                        '"description": "pin description max 300 chars", '
                        '"hashtags": ["6 hashtags"]}]} '
                        f"with exactly {want} items.",
                        temperature=0.95,
                        max_tokens=400 * want + 300, json_format=True)
                    batch = []
                    try:
                        data = json.loads(
                            re.search(r"\{.*\}", raw, re.DOTALL).group(0))
                        data = {k.lower(): v for k, v in data.items()}
                        batch = data.get("items", [])
                    except Exception:
                        pass
                    if not batch and raw:
                        # salvage complete objects from truncated JSON
                        for m in re.finditer(r"\{[^{}]*\}", raw):
                            try:
                                batch.append(json.loads(m.group(0)))
                            except Exception:
                                continue
                        if batch:
                            self.log(f"Factory: salvaged {len(batch)} "
                                     f"items from truncated {niche} plan")
                    items.extend(batch)
                    attempts += 1
                    if len(items) < per_niche:
                        set_status(f"Phase 1/3 - {niche}: {len(items)}/"
                                   f"{per_niche}, topping up...")
                for i, item in enumerate(items[:per_niche]):
                    item = {k.lower(): v for k, v in item.items()}
                    item["text"] = str(item.get("text", "")).strip(
                        ' "“”')
                    item["hashtags"] = [t for t in item.get("hashtags", [])
                                        if str(t).strip()]
                    ctype = types[i % len(types)]
                    persona = random.choice(personas) if personas else {}
                    style = self.taste.pick_style(niche, ART_STYLES)
                    plan.append({"niche": niche, "type": ctype,
                                 "item": item, "style": style,
                                 "persona": persona.get("name", "")})
                self.log(f"Factory plan: {len(items)} items for {niche}")
            if not plan:
                set_status("GLM returned no plan - aborting")
                return
            base.mkdir(parents=True, exist_ok=True)
            (base / "plan.json").write_text(
                json.dumps(plan, indent=1, ensure_ascii=False)[:200000],
                encoding="utf-8")
            self.quotes.release_vram()
            self.log(f"Factory: {len(plan)} items planned, GLM unloaded")

            # ── Phase 2+3: generate, render, score, curate ──
            ckpt = self.ckpt_var.get()
            # Same class of problem as Remix: this app's LoRA registry is
            # all SDXL-derivative - an SD1.5 checkpoint here would send
            # ComfyUI an invalid LoRA+checkpoint combo (HTTP 400) for
            # every single art_pin/meme item in the run, not a clean
            # per-item error.
            factory_lora_ok = not self._is_sd15(ckpt)
            if not factory_lora_ok and self._current_lora():
                self.log("Factory: LoRA needs an SDXL checkpoint - "
                         "skipped for this run (current is SD1.5)")
            made = 0
            for idx, job in enumerate(plan, 1):
                if self.stop_flag:
                    set_status(f"Stopped - {made} items completed")
                    return
                niche, ctype = job["niche"], job["type"]
                item, style = job["item"], job["style"]
                ndir = base / re.sub(r"[^\w\-]+", "_", niche)
                for sub in ("winners", "review"):
                    (ndir / sub).mkdir(parents=True, exist_ok=True)
                set_status(f"Phase 2/3 - [{idx}/{len(plan)}] {niche} "
                           f"{ctype}...")
                try:
                    art_path, score = None, None
                    if ctype in ("art_pin", "meme") and self.client.base_url:
                        persona = self.prompts.by_name(job["persona"]) or {}
                        positive = self.wildcards.expand(self.prompts.build(
                            "Variant", persona, style)) if persona else \
                            self.wildcards.expand(
                                f"{QUALITY}, __pose__, __setting__, {style}")
                        w, h, b = self._vram_preflight(832, 1216, 1)
                        wf = self.client.build_txt2img_workflow(
                            ckpt=ckpt, positive=positive,
                            negative=DEFAULT_NEGATIVE, width=w, height=h,
                            batch_size=b, steps=int(self.steps_var.get()),
                            cfg=float(self.cfg_var.get()),
                            sampler=self.sampler_var.get(),
                            scheduler=self.sched_var.get(),
                            seed=random.randint(0, 2**48),
                            lora=self._current_lora() if factory_lora_ok else None,
                            lora_strength=float(self.lora_str_var.get()))
                        entry = self._queue_and_wait(wf)
                        img_info = next(
                            i for o in entry["outputs"].values()
                            for i in o.get("images", []))
                        raw = self.client.download_image(
                            img_info["filename"],
                            img_info.get("subfolder", ""),
                            img_info.get("type", "output"))
                        art_path = ndir / f"_{idx:02d}_art.png"
                        art_path.write_bytes(raw)
                        score = self.quality_calculator.\
                            calculate_overall_quality_score(
                                self.quality_calculator.
                                calculate_image_quality(art_path))
                        self.taste.record(niche, style, score)

                    if ctype == "quote_card":
                        text = str(item.get("text", "")).strip()
                        if not text:
                            continue
                        card_style = random.choice(
                            list(QUOTE_CARD_STYLES))
                        img = self.brand.apply(
                            render_quote_card(text, "", card_style))
                        out = ndir / "review" / f"{idx:02d}_card.png"
                        img.save(out)
                        final = out
                    elif ctype == "meme" and art_path:
                        top = str(item.get("top", "")).strip()
                        bottom = str(item.get("bottom", "")).strip()
                        if not top and not bottom:
                            # GLM reliably fills "text" but very often
                            # leaves the dedicated meme top/bottom fields
                            # blank (observed live: 3/3 items in a test
                            # run) - fall back to it rather than saving
                            # a caption-less "meme" that's just the art.
                            top = str(item.get("text", "")).strip()
                        img = self.brand.apply(render_meme(
                            art_path, top, bottom))
                        final = ndir / "review" / f"{idx:02d}_meme.png"
                        img.save(final)
                    elif ctype == "art_pin" and art_path:
                        from PIL import Image
                        pin = self.brand.apply(fit_exact(
                            Image.open(art_path).convert("RGB"),
                            1000, 1500))
                        final = ndir / "review" / f"{idx:02d}_pin.png"
                        pin.save(final)
                    else:
                        continue

                    # curate by score when we have one
                    if score is not None and score >= 7.5:
                        winner = ndir / "winners" / final.name
                        final.replace(winner)
                        final = winner

                    # pin metadata from the PLAN (no LLM needed now)
                    tags = list(dict.fromkeys(
                        [str(t).lstrip("#") for t in
                         item.get("hashtags", [])] +
                        NICHES[niche]["hashtags"]))[:15]
                    meta_txt = (
                        f"TITLE:\n{item.get('title', '')}\n\n"
                        f"DESCRIPTION:\n{item.get('description', '')}\n\n"
                        f"HASHTAGS:\n{' '.join('#' + t for t in tags)}\n")
                    final.with_suffix(".pin.txt").write_text(
                        meta_txt, encoding="utf-8")
                    made += 1
                    if art_path and art_path.exists() and ctype != "meme":
                        art_path.unlink(missing_ok=True)
                except Exception as e:
                    self.log(f"Factory item {idx} failed: {e}")

            mins = (time.time() - run_start) / 60
            set_status(f"DONE - {made}/{len(plan)} items in {mins:.0f} min\n"
                       f"Output: factory_output/{stamp}/")
            self.log(f"Factory complete: {made} items, {mins:.0f} min, "
                     f"taste memory updated")
        except Exception as e:
            set_status(f"Factory error: {e}")
            self.log(f"Factory ERROR: {e}")
        finally:
            self.busy = False
            done_cb()

    # ── Quote generator ─────────────────────────────────────────────────────
    def generate_quote(self):
        persona = self.selected_persona()
        if not persona:
            messagebox.showinfo("No persona", "Select a persona in the list first.")
            return
        self.quote_btn.configure(text="Thinking...", state="disabled")
        threading.Thread(target=self._quote_worker, args=(persona,), daemon=True).start()

    def _quote_worker(self, persona: dict):
        try:
            override = self._jesus_quote_override()
            if override:
                quote, source = override
            else:
                if self.quotes.backend is None:
                    self.quotes.detect()
                quote, source = self.quotes.generate(persona)
            name = persona.get("name", "")

            def _show():
                self.quote_text.delete("1.0", "end")
                self.quote_text.insert("1.0", f'"{quote}"\n\n- {name}')
            self.root.after(0, _show)
            self.log(f"Quote for {name} ({source})")
        except Exception as e:
            self.log(f"Quote generation failed: {e}")
        finally:
            self.root.after(0, lambda: self.quote_btn.configure(
                text="Generate Quote", state="normal"))

    def copy_quote(self):
        text = self.quote_text.get("1.0", "end").strip()
        self.root.clipboard_clear()
        self.root.clipboard_append(text)
        self.log("Quote copied to clipboard")

    def save_quote(self):
        text = self.quote_text.get("1.0", "end").strip()
        if not text or text.startswith("Select a persona"):
            return
        path = self.output_dir / "quotes.txt"
        with open(path, "a", encoding="utf-8") as f:
            f.write(f"[{datetime.now():%Y-%m-%d %H:%M}]\n{text}\n\n")
        self.log(f"Quote saved to {path.name}")

    def _current_upscale_model(self):
        """Return the upscale model to use for 4K output, or None."""
        if not self.output_var.get().startswith("4K"):
            return None
        if not self.upscale_models:
            self.log("4K requested but no upscale model installed - using Standard")
            return None
        for m in self.upscale_models:
            if "anime" in m.lower():
                return m
        return self.upscale_models[0]

    # ── v4.9: LoRA Trainer (kohya sd-scripts, 6GB-safe SDXL profile) ───────
    KOHYA_DIR = Path(r"C:\Users\phase\Desktop\anime\kohya")

    def open_lora_trainer(self):
        """Train your own character LoRA overnight: build a dataset from
        your generations, then run kohya sd-scripts with a 6GB-safe
        SDXL profile."""
        win = tk.Toplevel(self.root)
        win.title("LoRA Trainer - your own character, permanently")
        self._clamp_window(win, 600, 560)
        win.configure(bg=self.PANEL)

        env_py = self.KOHYA_DIR / "venv" / "Scripts" / "python.exe"
        scripts = self.KOHYA_DIR / "sd-scripts"
        installed = env_py.exists() and scripts.exists()

        tk.Label(win, text=("Training engine: INSTALLED" if installed else
                            "Training engine: not installed (one-time "
                            "~3GB setup)"),
                 bg=self.PANEL,
                 fg=self.SUCCESS_TEXT if installed else self.WARN_TEXT,
                 font=self.font_body_bold).pack(anchor="w", padx=12,
                                                    pady=(12, 4))

        def install_engine():
            script = self.KOHYA_DIR / "setup_kohya.ps1"
            self.KOHYA_DIR.mkdir(parents=True, exist_ok=True)
            script.write_text(
                "$ErrorActionPreference='Stop'\n"
                f"Set-Location '{self.KOHYA_DIR}'\n"
                "if (-not (Test-Path sd-scripts)) {\n"
                "  git clone --depth 1 "
                "https://github.com/kohya-ss/sd-scripts.git\n}\n"
                "if (-not (Test-Path venv)) { python -m venv venv }\n"
                ".\\venv\\Scripts\\python.exe -m pip install --upgrade pip\n"
                ".\\venv\\Scripts\\pip.exe install torch torchvision "
                "--index-url https://download.pytorch.org/whl/cu121\n"
                ".\\venv\\Scripts\\pip.exe install -r "
                "sd-scripts\\requirements.txt\n"
                ".\\venv\\Scripts\\pip.exe install xformers --index-url "
                "https://download.pytorch.org/whl/cu121\n"
                "Write-Host 'KOHYA SETUP COMPLETE'\n",
                encoding="utf-8")
            subprocess.Popen(
                ["powershell", "-ExecutionPolicy", "Bypass",
                 "-NoProfile", "-File", str(script)],
                creationflags=subprocess.CREATE_NEW_CONSOLE)
            self.log("Kohya setup launched in a new console (~3GB "
                     "download, 10-30 min). Reopen this window after "
                     "'KOHYA SETUP COMPLETE'.")
        if not installed:
            ttk.Button(win, text="⬇ Install training engine (new console)",
                       command=install_engine).pack(anchor="w", padx=12)

        def trow(label):
            rr = tk.Frame(win, bg=self.PANEL)
            rr.pack(fill="x", padx=12, pady=3)
            tk.Label(rr, text=label, bg=self.PANEL, fg=self.FG,
                     width=12, anchor="w").pack(side="left")
            return rr

        rr = trow("Trigger word")
        trig_var = tk.StringVar(value="mychar")
        ttk.Entry(rr, textvariable=trig_var, width=20).pack(side="left")
        tk.Label(rr, text="(unique token you'll use in prompts)",
                 bg=self.PANEL, fg=self.FG_MUTED,
                 font=self.font_small).pack(side="left", padx=6)

        rr = trow("Description")
        desc_var = tk.StringVar(value="1girl, silver hair, blue eyes")
        ttk.Entry(rr, textvariable=desc_var, width=44).pack(side="left")

        imgs = {"paths": []}
        rr = trow("Images")
        img_lbl = tk.Label(rr, text="(none - pick 15-40 of the SAME "
                           "character)", bg=self.PANEL, fg=self.FG_MUTED,
                           anchor="w")
        img_lbl.pack(side="left")

        def pick_imgs():
            paths = filedialog.askopenfilenames(
                title="15-40 images of the same character",
                initialdir=self.output_dir, filetypes=self.IMG_FILETYPES,
                parent=win)
            if paths:
                imgs["paths"] = [Path(p) for p in paths]
                img_lbl.config(text=f"{len(imgs['paths'])} images selected",
                               fg=self.SUCCESS_TEXT)
        ttk.Button(rr, text="Browse", command=pick_imgs).pack(side="left",
                                                              padx=4)

        rr = trow("Steps")
        steps_var = tk.IntVar(value=1600)
        ttk.Spinbox(rr, textvariable=steps_var, from_=400, to=4000,
                    increment=200, width=6).pack(side="left")
        tk.Label(rr, text="~1600 = 2-4h overnight on this GPU",
                 bg=self.PANEL, fg=self.FG_MUTED,
                 font=self.font_small).pack(side="left", padx=6)

        status = tk.Label(win, text="Flow: pick images -> BUILD DATASET "
                          "-> START TRAINING (close ComfyUI first - "
                          "training needs the whole GPU).\nResult lands "
                          "in ComfyUI's loras folder automatically.",
                          bg=self.PANEL, fg=self.FG_MUTED, wraplength=560,
                          justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def build_dataset():
            if len(imgs["paths"]) < 5:
                messagebox.showinfo("Too few", "Pick at least 5 images "
                                    "(15-40 recommended).", parent=win)
                return
            trig = re.sub(r"[^\w]+", "", trig_var.get()) or "mychar"
            ds = self.KOHYA_DIR / "datasets" / trig / f"10_{trig}"
            ds.mkdir(parents=True, exist_ok=True)
            from PIL import Image
            n = 0
            for p in imgs["paths"]:
                try:
                    im = Image.open(p).convert("RGB")
                    im.thumbnail((1024, 1024), Image.LANCZOS)
                    im.save(ds / f"{trig}_{n:03d}.png")
                    (ds / f"{trig}_{n:03d}.txt").write_text(
                        f"{trig}, {desc_var.get().strip()}",
                        encoding="utf-8")
                    n += 1
                except Exception as e:
                    self.log(f"Dataset build: skipped {p.name} ({e})")
                    continue
            status.config(text=f"Dataset built: {n} images + captions in "
                          f"{ds}\nNow close ComfyUI, then START TRAINING.")
            self.log(f"LoRA dataset: {n} images -> {ds}")

        def start_training():
            trig = re.sub(r"[^\w]+", "", trig_var.get()) or "mychar"
            ds_root = self.KOHYA_DIR / "datasets" / trig
            if not (self.KOHYA_DIR / "venv" / "Scripts" /
                    "python.exe").exists():
                messagebox.showinfo("Engine missing", "Install the "
                                    "training engine first.", parent=win)
                return
            if not ds_root.exists():
                messagebox.showinfo("No dataset", "BUILD DATASET first.",
                                    parent=win)
                return
            ckpt_dir = Path(r"C:\Users\phase\AppData\Local\Comfy-Desktop"
                            r"\ComfyUI-Shared\models\checkpoints")
            base = ckpt_dir / "animagine-xl-4.0.safetensors"
            if not base.exists():
                messagebox.showinfo(
                    "Base checkpoint missing",
                    f"{base.name} not found in {ckpt_dir}.\nInstall it "
                    "(or rename your SDXL checkpoint to match) before "
                    "starting an overnight training run.", parent=win)
                return
            out_lora = Path(r"C:\Users\phase\AppData\Local\Comfy-Desktop"
                            r"\ComfyUI-Shared\models\loras")
            if not messagebox.askyesno(
                    "Start overnight training?",
                    f"Trains '{trig}' for {steps_var.get()} steps "
                    "(hours). ComfyUI should be CLOSED so the GPU is "
                    "free. Start now?", parent=win):
                return
            log_p = self.KOHYA_DIR / f"train_{trig}.log"
            args = [
                str(self.KOHYA_DIR / "venv" / "Scripts" / "python.exe"),
                str(self.KOHYA_DIR / "sd-scripts" /
                    "sdxl_train_network.py"),
                "--pretrained_model_name_or_path", str(base),
                "--train_data_dir", str(ds_root),
                "--output_dir", str(out_lora),
                "--output_name", f"{trig}_lora",
                "--network_module", "networks.lora",
                "--network_dim", "8", "--network_alpha", "4",
                "--resolution", "1024,1024",
                "--train_batch_size", "1",
                "--max_train_steps", str(int(steps_var.get())),
                "--learning_rate", "1e-4",
                "--optimizer_type", "AdamW",
                "--mixed_precision", "fp16",
                "--save_precision", "fp16",
                "--gradient_checkpointing",
                "--cache_latents", "--cache_latents_to_disk",
                "--network_train_unet_only",
                "--lowram",
                "--save_model_as", "safetensors",
            ]
            with open(log_p, "w") as lf:
                subprocess.Popen(args, stdout=lf, stderr=lf,
                                 cwd=str(self.KOHYA_DIR / "sd-scripts"),
                                 creationflags=subprocess.CREATE_NEW_CONSOLE)
            status.config(text=f"TRAINING LAUNCHED - log: {log_p}\n"
                          f"Result: {out_lora / (trig + '_lora.safetensors')}"
                          "\nReconnect ComfyUI tomorrow and it appears in "
                          "your LoRA dropdown.")
            self.log(f"LoRA training started: {trig} "
                     f"({steps_var.get()} steps) - log {log_p.name}")

        brow = tk.Frame(win, bg=self.PANEL)
        brow.pack(fill="x", padx=12, pady=8)
        ttk.Button(brow, text="1) BUILD DATASET",
                   command=build_dataset).pack(side="left")
        ttk.Button(brow, text="2) START TRAINING (overnight)",
                   command=start_training).pack(side="left", padx=8)
        self.log("Opened LoRA Trainer")

    # ── v4.7: Listing Packager (Etsy / KDP bundles) ────────────────────────
    def open_listing_packager(self):
        """Turn any product folder (coloring book, wallpaper pack,
        storybook, art set) into an upload-ready listing bundle: zip of
        files, GLM sales copy, preview images."""
        win = tk.Toplevel(self.root)
        win.title("Listing Packager - Etsy / KDP")
        self._clamp_window(win, 540, 420)
        win.configure(bg=self.PANEL)
        src = {"dir": None}

        rr = tk.Frame(win, bg=self.PANEL)
        rr.pack(fill="x", padx=12, pady=(12, 4))
        tk.Label(rr, text="Product folder:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        dir_lbl = tk.Label(rr, text="(none)", bg=self.PANEL,
                           fg=self.FG_MUTED, width=30, anchor="w")
        dir_lbl.pack(side="left", padx=6)

        def pick_dir():
            p = filedialog.askdirectory(
                title="Folder containing the product files",
                initialdir=self.output_dir, parent=win)
            if p:
                src["dir"] = Path(p)
                dir_lbl.config(text=src["dir"].name[:28],
                               fg=self.SUCCESS_TEXT)
        ttk.Button(rr, text="Browse", command=pick_dir).pack(side="left")

        rr = tk.Frame(win, bg=self.PANEL)
        rr.pack(fill="x", padx=12, pady=4)
        tk.Label(rr, text="Product type:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        type_var = tk.StringVar(value="Coloring Book (printable PDF)")
        ttk.Combobox(rr, textvariable=type_var, state="readonly",
                     values=["Coloring Book (printable PDF)",
                             "Wallpaper Pack (digital download)",
                             "Storybook (illustrated PDF)",
                             "Art Print Set (printable)"],
                     width=32).pack(side="left", padx=6)

        rr = tk.Frame(win, bg=self.PANEL)
        rr.pack(fill="x", padx=12, pady=4)
        tk.Label(rr, text="Platform:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        plat_var = tk.StringVar(value="Etsy (digital download)")
        ttk.Combobox(rr, textvariable=plat_var, state="readonly",
                     values=["Etsy (digital download)",
                             "Amazon KDP (print book)"],
                     width=26).pack(side="left", padx=6)

        status = tk.Label(win, text="Creates _listing/ inside the product "
                          "folder:\n- product files zip\n- listing.txt "
                          "(GLM title, description, tags)\n- preview "
                          "images (hero + grid collage)",
                          bg=self.PANEL, fg=self.FG_MUTED, wraplength=500,
                          justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def start():
            if not src["dir"] or not src["dir"].exists():
                messagebox.showinfo("No folder", "Pick the product folder "
                                    "first.", parent=win)
                return
            if self.busy:
                # v6.6: this dialog never checked - unlike every other
                # tool - so it could launch a GLM call (_listing_worker)
                # concurrently with an active diffusion job, the exact
                # VRAM-contention scenario the app is otherwise built
                # to avoid.
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if self.quotes.backend is None and not self.quotes.detect():
                messagebox.showinfo("No local LLM", "Start Ollama first.",
                                    parent=win)
                return
            go_btn.configure(state="disabled", text="Packaging...")

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def done():
                self.root.after(0, lambda: go_btn.configure(
                    state="normal", text="🏷 PACKAGE LISTING"))
            threading.Thread(
                target=self._listing_worker,
                args=(src["dir"], type_var.get(), plat_var.get(), setv,
                      done),
                daemon=True).start()

        go_btn = ttk.Button(win, text="🏷 PACKAGE LISTING", command=start)
        go_btn.pack(pady=8)
        self.log("Opened Listing Packager")

    def _listing_worker(self, folder, ptype, platform, set_status, done_cb):
        self.busy = True
        try:
            import zipfile
            from PIL import Image
            folder = Path(folder)
            out = folder / "_listing"
            out.mkdir(exist_ok=True)

            pdfs = sorted(folder.glob("*.pdf"))
            pngs = sorted(p for p in folder.rglob("*.png")
                          if "_listing" not in p.parts and
                          not p.name.startswith("_"))
            product_files = pdfs if pdfs else pngs
            if not product_files:
                set_status("No PDFs or PNGs found in that folder")
                return

            # 1) GLM sales copy
            set_status("GLM writing the listing copy...")
            inventory = ", ".join(p.name for p in product_files[:12])
            data = self.quotes.complete_json(
                f"Write an {platform} listing for this digital product: "
                f"{ptype} titled '{folder.name}'. Files: {inventory}. "
                'Reply ONLY JSON: {"title": "SEO listing title max 130 '
                'chars", "description": "3 paragraphs: hook, what you '
                'get, how to use", "tags": ["13 short tags, each max 20 '
                'chars"]}', temperature=0.8, max_tokens=700) or {}
            data = {k.lower(): v for k, v in data.items()}
            self.quotes.release_vram()
            tags = [str(t)[:20] for t in data.get("tags", []) if str(t).strip()]
            # GLM often under-delivers tag counts - pad from a per-type pool
            POOLS = {
                "Coloring": ["coloring book", "printable pdf", "kids activity",
                             "adult coloring", "instant download", "digital print",
                             "coloring pages", "art therapy", "diy craft",
                             "party activity", "homeschool", "gift idea",
                             "relaxing art"],
                "Wallpaper": ["wallpaper pack", "digital wallpaper", "desktop art",
                              "phone wallpaper", "4k wallpaper", "anime art",
                              "instant download", "digital art", "screen art",
                              "aesthetic decor", "art bundle", "hd background",
                              "gift idea"],
                "Storybook": ["kids story book", "picture book", "printable pdf",
                              "bedtime story", "instant download", "children gift",
                              "story pdf", "read aloud", "kids activity",
                              "homeschool", "digital book", "gift idea",
                              "illustrated book"],
                "Art": ["art print", "printable art", "wall art", "digital print",
                        "instant download", "anime poster", "home decor",
                        "gift idea", "digital art", "print set", "poster art",
                        "wall decor", "art bundle"],
            }
            pool = next((v for k, v in POOLS.items() if k in ptype),
                        POOLS["Art"])
            for t in pool:
                if len(tags) >= 13:
                    break
                if t not in tags:
                    tags.append(t)
            tags = tags[:13]
            listing_txt = (
                f"PLATFORM: {platform}\nPRODUCT: {ptype}\n\n"
                f"TITLE:\n{data.get('title', folder.name)}\n\n"
                f"DESCRIPTION:\n{data.get('description', '')}\n\n"
                f"TAGS ({len(tags)}):\n{', '.join(tags)}\n\n"
                f"FILES INCLUDED:\n" +
                "\n".join(f"  - {p.name}" for p in product_files) + "\n")
            (out / "listing.txt").write_text(listing_txt, encoding="utf-8")

            # 2) preview images
            set_status("Rendering listing previews...")
            previews = [p for p in pngs if "page" in p.name.lower() or
                        "cover" in p.name.lower()] or pngs
            if previews:
                hero_src = Image.open(previews[0])
                hero = render_banner(
                    hero_src, "X/Twitter Header",
                    folder.name.replace("_", " ").title(),
                    ptype.split(" (")[0],
                    "Georgia (elegant serif)")
                hero.save(out / "preview_1_hero.png")
                grid = make_moodboard(previews[:6], cols=3, cell=420)
                grid.save(out / "preview_2_grid.png")

            # 3) product zip (Etsy digital downloads cap at ~20MB/file,
            # so note oversize files rather than silently bundling)
            set_status("Zipping product files...")
            safe_name = re.sub(r"[^\w\-]+", "_", folder.name)
            zp = out / f"{safe_name}_files.zip"
            oversize = []
            with zipfile.ZipFile(zp, "w", zipfile.ZIP_DEFLATED) as z:
                for p in product_files:
                    z.write(p, p.name)
                    if p.stat().st_size > 19_000_000:
                        oversize.append(p.name)
            note = ""
            if oversize and "Etsy" in platform:
                note = (f"\nNOTE: {len(oversize)} file(s) exceed Etsy's "
                        "20MB per-file limit - upload those individually "
                        f"or via a link: {', '.join(oversize)}")
                (out / "listing.txt").write_text(listing_txt + note,
                                                 encoding="utf-8")
            set_status(f"DONE - {out}\nzip: {zp.stat().st_size//1024}KB, "
                       f"{len(product_files)} files{note}")
            self.log(f"Listing packaged: {folder.name} -> _listing/")
        except Exception as e:
            self.log(f"Listing ERROR: {e}")
            set_status(f"Failed: {e}")
        finally:
            self.busy = False
            done_cb()

    # ── v4.6: Semantic gallery search ──────────────────────────────────────
    def open_semantic_search(self):
        """Search your entire generated library by meaning."""
        win = tk.Toplevel(self.root)
        win.title("Semantic Search - find images by meaning")
        self._clamp_window(win, 640, 520)
        win.configure(bg=self.PANEL)

        qrow = tk.Frame(win, bg=self.PANEL)
        qrow.pack(fill="x", padx=12, pady=(12, 4))
        q_var = tk.StringVar()
        ent = ttk.Entry(qrow, textvariable=q_var, width=44)
        ent.pack(side="left", fill="x", expand=True)
        ent.focus_set()

        info = tk.Label(win, text=f"{len(self.embeddings.data)} images "
                        "indexed. Use 'Index library' to backfill older "
                        "generations.", bg=self.PANEL, fg=self.FG_MUTED,
                        wraplength=600, justify="left")
        info.pack(anchor="w", padx=12, fill="x")
        # v9.16: wraplength was a static 600px, so resizing the window
        # narrower than that clipped/overflowed the label instead of
        # rewrapping. Track the window's live width instead.
        win.bind("<Configure>",
                lambda e: info.configure(wraplength=max(200, win.winfo_width() - 24)))

        results = tk.Listbox(win, bg=self.INPUT_BG, fg=self.FG, height=16,
                             selectbackground=self.ACCENT,
                             exportselection=False,
                             font=self.font_mono_body)
        results.pack(fill="both", expand=True, padx=12, pady=6)
        hits = []

        def do_search(*_):
            # v6.6: probe() used to run synchronously on the main thread
            # right here - a live HTTP call to Ollama with up to a 60s
            # timeout, freezing the whole app if Ollama is slow/unreachable.
            # Moved inside the background thread below.
            query = q_var.get().strip()
            if not query:
                return
            results.delete(0, "end")
            results.insert("end", "Searching...")
            win.update()

            def _w():
                if not self.embeddings.probe():
                    self.root.after(0, lambda: (
                        results.delete(0, "end"),
                        messagebox.showinfo(
                            "Embeddings offline",
                            "Ollama with nomic-embed-text is required.",
                            parent=win)))
                    return
                found = self.embeddings.search(query)

                def _show():
                    nonlocal hits
                    hits = found
                    results.delete(0, "end")
                    if not found:
                        results.insert("end", "(no results - index the "
                                       "library first?)")
                    for score, path, text in found:
                        results.insert(
                            "end", f"{score:.2f}  {Path(path).name[:34]:<36}"
                                   f" {text[:40]}")
                self.root.after(0, _show)
            threading.Thread(target=_w, daemon=True).start()
        ent.bind("<Return>", do_search)

        def show_hit(*_):
            sel = results.curselection()
            if sel and sel[0] < len(hits):
                self.show_preview(hits[sel[0]][1])
        results.bind("<<ListboxSelect>>", show_hit)

        def backfill():
            # v6.6: same probe()-on-main-thread freeze risk as do_search -
            # moved inside the background thread.
            bf_btn.configure(state="disabled", text="Indexing...")

            def _w():
                if not self.embeddings.probe():
                    self.root.after(0, lambda: (
                        bf_btn.configure(state="normal",
                                        text="Index library"),
                        messagebox.showinfo(
                            "Embeddings offline",
                            "Ollama with nomic-embed-text is required.",
                            parent=win)))
                    return
                added = 0
                try:
                    added = self.embeddings.backfill(self.output_dir)
                finally:
                    self.root.after(0, lambda: (
                        bf_btn.configure(state="normal",
                                         text="Index library"),
                        info.config(text=f"{len(self.embeddings.data)} "
                                    f"images indexed (+{added} new)")))
                    self.log(f"Semantic index: +{added} "
                             f"({len(self.embeddings.data)} total)")
            threading.Thread(target=_w, daemon=True).start()

        brow = tk.Frame(win, bg=self.PANEL)
        brow.pack(fill="x", padx=12, pady=(0, 10))
        ttk.Button(brow, text="🔎 Search", command=do_search).pack(side="left")
        bf_btn = ttk.Button(brow, text="Index library", command=backfill)
        bf_btn.pack(side="left", padx=6)
        tk.Label(brow, text="click a result to preview it", bg=self.PANEL,
                 fg=self.FG_MUTED, font=self.font_small).pack(side="left",
                                                              padx=8)
        self.log("Opened Semantic Search")

    # ── v4.4: Inpainting - paint a mask, regenerate just that region ───────
    def open_inpaint(self, src_path=None):
        """Regional editing: paint over the part to change, describe what
        should be there, regenerate only that region."""
        src = Path(src_path) if src_path else self.last_preview_path
        if not src or not Path(src).exists():
            p = filedialog.askopenfilename(
                title="Image to edit", initialdir=self.output_dir,
                filetypes=self.IMG_FILETYPES)
            if not p:
                return
            src = Path(p)
        from PIL import Image, ImageDraw, ImageTk

        win = tk.Toplevel(self.root)
        win.title(f"Inpaint - {src.name}")
        win.configure(bg=self.PANEL)

        img = Image.open(src).convert("RGB")
        maxdim = 680
        scale = min(maxdim / img.width, maxdim / img.height, 1.0)
        disp = img.resize((int(img.width * scale), int(img.height * scale)),
                          Image.LANCZOS)
        mask = Image.new("L", img.size, 0)
        mask_draw = ImageDraw.Draw(mask)

        tk.Label(win, text="Paint over what you want to REPLACE, then "
                 "describe the replacement below.", bg=self.PANEL,
                 fg=self.WARN_TEXT).pack(anchor="w", padx=12, pady=(10, 4))
        canvas = tk.Canvas(win, width=disp.width, height=disp.height,
                           bg=self.BG, highlightthickness=0,
                           cursor="crosshair")
        canvas.pack(padx=12)
        photo = ImageTk.PhotoImage(disp)
        canvas.create_image(0, 0, image=photo, anchor="nw")
        canvas._photo = photo  # keep reference

        brush_var = tk.IntVar(value=36)

        def paint(event):
            r = brush_var.get()
            canvas.create_oval(event.x - r, event.y - r,
                               event.x + r, event.y + r,
                               fill="#ff4477", outline="", stipple="gray50")
            fr = r / scale
            fx, fy = event.x / scale, event.y / scale
            mask_draw.ellipse([fx - fr, fy - fr, fx + fr, fy + fr],
                              fill=255)
        canvas.bind("<B1-Motion>", paint)
        canvas.bind("<Button-1>", paint)

        crow = tk.Frame(win, bg=self.PANEL)
        crow.pack(fill="x", padx=12, pady=4)
        tk.Label(crow, text="Brush:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        tk.Scale(crow, variable=brush_var, from_=8, to=120,
                 orient="horizontal", length=140, bg=self.PANEL,
                 fg=self.FG, highlightthickness=0,
                 troughcolor=self.INPUT_BG).pack(side="left", padx=6)

        def clear_mask():
            mask_draw.rectangle([0, 0, mask.width, mask.height], fill=0)
            canvas.delete("all")
            canvas.create_image(0, 0, image=photo, anchor="nw")
        ttk.Button(crow, text="Clear mask",
                   command=clear_mask).pack(side="left", padx=6)
        tk.Label(crow, text="Denoise:", bg=self.PANEL,
                 fg=self.FG).pack(side="left", padx=(12, 0))
        den_var = tk.DoubleVar(value=0.9)
        tk.Scale(crow, variable=den_var, from_=0.5, to=1.0,
                 resolution=0.05, orient="horizontal", length=120,
                 bg=self.PANEL, fg=self.FG, highlightthickness=0,
                 troughcolor=self.INPUT_BG).pack(side="left", padx=6)

        prow = tk.Frame(win, bg=self.PANEL)
        prow.pack(fill="x", padx=12, pady=4)
        tk.Label(prow, text="Replace with:", bg=self.PANEL,
                 fg=self.FG).pack(side="left")
        prompt_var = tk.StringVar()
        ttk.Entry(prow, textvariable=prompt_var, width=48).pack(
            side="left", fill="x", expand=True, padx=6)

        status = tk.Label(win, text="", bg=self.PANEL,
                          fg=self.SUCCESS_TEXT, wraplength=640,
                          justify="left")
        status.pack(anchor="w", padx=12)

        def run():
            if not prompt_var.get().strip():
                messagebox.showinfo("Empty prompt",
                                    "Describe what the masked area should "
                                    "become.", parent=win)
                return
            if mask.getbbox() is None:
                messagebox.showinfo("No mask", "Paint over the area to "
                                    "replace first.", parent=win)
                return
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI not connected.",
                                     parent=win)
                return
            go_btn.configure(state="disabled", text="Inpainting...")

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def _w():
                try:
                    self.busy = True
                    from PIL import ImageFilter
                    # feather the mask so the seam blends
                    soft = mask.filter(ImageFilter.GaussianBlur(6))
                    mask_p = self.output_dir / "_inpaint_mask.png"
                    soft.convert("RGB").save(mask_p)
                    img_name = self._upload_ref(src)
                    # mask changes every run - upload without cache
                    mask_name = self.client.upload_image(mask_p)
                    wf = self.client.build_inpaint_workflow(
                        ckpt=self.ckpt_var.get(),
                        positive=f"{QUALITY}, {prompt_var.get().strip()}",
                        negative=self.neg_text.get(
                            "1.0", "end").strip() or DEFAULT_NEGATIVE,
                        image_name=img_name, mask_name=mask_name,
                        denoise=float(den_var.get()),
                        steps=int(self.steps_var.get()),
                        cfg=float(self.cfg_var.get()),
                        sampler=self.sampler_var.get(),
                        scheduler=self.sched_var.get(),
                        seed=random.randint(0, 2**48))
                    setv("Regenerating masked region...")
                    entry = self._queue_and_wait(wf)
                    info = next(x for o in entry["outputs"].values()
                                for x in o.get("images", []))
                    raw = self.client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
                    out = self.output_dir / \
                        f"{stamp}_inpaint_{src.stem[:30]}.png"
                    out.write_bytes(raw)
                    self.show_preview(out)
                    setv(f"DONE: {out.name} - reopen Inpaint to keep "
                         "editing the result")
                    self.log(f"Inpaint: {src.name} -> {out.name}")
                except Exception as e:
                    setv(f"Failed: {e}")
                    self.log(f"Inpaint ERROR: {e}")
                finally:
                    self.busy = False
                    self.root.after(0, lambda: go_btn.configure(
                        state="normal", text="🎨 INPAINT"))
            threading.Thread(target=_w, daemon=True).start()

        go_btn = ttk.Button(win, text="🎨 INPAINT", command=run)
        go_btn.pack(pady=8)
        self.log(f"Opened Inpaint for {src.name}")

    # ── v4.3: Storybook Creator ────────────────────────────────────────────
    # ── v5.1: Fashion Designer ───────────────────────────────────────────────
    def open_fashion_designer(self):
        """Clothes/fashion design tool: concept art, technical flats
        (front/back/side spec sheet), pose study sheets, and editorial
        model photography - all from one garment description."""
        win = tk.Toplevel(self.root)
        win.title("Fashion Designer")
        self._clamp_window(win, 580, 480)
        win.configure(bg=self.PANEL)

        def frow(label):
            rr = tk.Frame(win, bg=self.PANEL)
            rr.pack(fill="x", padx=12, pady=3)
            tk.Label(rr, text=label, bg=self.PANEL, fg=self.FG,
                     width=10, anchor="w").pack(side="left")
            return rr

        tk.Label(win, text="Garment description:", bg=self.PANEL,
                 fg=self.ACCENT, font=self.font_body_bold).pack(
            anchor="w", padx=12, pady=(12, 2))
        garment_text = tk.Text(win, height=3, bg=self.INPUT_BG, fg=self.FG,
                               wrap="word", insertbackground=self.FG,
                               borderwidth=0)
        garment_text.pack(fill="x", padx=12)
        garment_text.insert("1.0", "an asymmetric black leather jacket "
                            "with silver hardware and a high collar")

        rr = frow("Mode")
        mode_var = tk.StringVar(value=list(FASHION_MODES)[0])
        ttk.Combobox(rr, textvariable=mode_var, state="readonly",
                     values=list(FASHION_MODES), width=32).pack(side="left")

        rr = frow("Style")
        style_var = tk.StringVar(value=list(FASHION_STYLES)[0])
        ttk.Combobox(rr, textvariable=style_var, state="readonly",
                     values=list(FASHION_STYLES), width=28).pack(side="left")

        rr = frow("Poses")
        poses_var = tk.IntVar(value=4)
        ttk.Spinbox(rr, textvariable=poses_var, from_=2, to=6,
                    width=4).pack(side="left")
        tk.Label(rr, text="(Pose Study Sheet mode only)", bg=self.PANEL,
                 fg=self.FG_MUTED, font=self.font_small).pack(side="left",
                                                              padx=6)

        status = tk.Label(win, text="Output: fashion_designs/<garment>/",
                          bg=self.PANEL, fg=self.FG_MUTED, wraplength=540,
                          justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def start():
            garment = garment_text.get("1.0", "end").strip()
            if not garment:
                messagebox.showinfo("No description",
                                    "Describe the garment first.",
                                    parent=win)
                return
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI not connected.",
                                     parent=win)
                return
            if self._is_sd15(self.ckpt_var.get()) or \
                    self._is_turbo_distilled(self.ckpt_var.get()):
                # v6.6: FASHION_MODES' fixed resolutions (832x1216 etc.)
                # and the main window's normal CFG/steps both assume
                # SDXL - an SD1.5 checkpoint at 4x its native training
                # resolution produces mangled anatomy, and Turbo needs a
                # completely different CFG/step regime this dialog has
                # no way to apply. Same class of guard as Auto Character
                # Designer/Auto-Fix/Tiled Upscale.
                messagebox.showinfo("Needs standard SDXL",
                                    "Fashion Designer needs a standard "
                                    "SDXL checkpoint selected in Model.",
                                    parent=win)
                return
            go_btn.configure(state="disabled", text="Designing...")

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def done():
                self.root.after(0, lambda: go_btn.configure(
                    state="normal", text="👗 DESIGN"))
            self.stop_flag = False  # v7.1: see start_generation's note
            threading.Thread(
                target=self._fashion_worker,
                args=(garment, mode_var.get(), style_var.get(),
                      int(poses_var.get()), setv, done),
                daemon=True).start()

        go_btn = ttk.Button(win, text="👗 DESIGN", command=start)
        go_btn.pack(pady=8)
        self.log("Opened Fashion Designer")

    def _run_fashion_pipeline(self, garment, mode_name, style_name, n_poses,
                              set_status=None):
        """v6.8: busy-flag-free, done_cb-free core - extracted from
        _fashion_worker so Auto-Pilot's Fashion cycles can call it
        directly without the outer worker's finally-block flipping
        self.busy back off mid Auto-Pilot session (same precedent as
        _run_cinematic_pipeline/_run_character_blueprint_pipeline).
        Returns (out_dir, preview_path) on success, (None, None) on any
        failure - never raises. All 4 modes still supported (unchanged
        from the pre-extraction body) since the manual dialog needs all
        4; Auto-Pilot's Fashion cycles restrict themselves to the
        "Concept Art"/"Editorial Model Shoot" modes at their own call
        site, not here."""
        set_status = set_status or (lambda t: None)
        t0 = time.time()
        try:
            from PIL import Image
            import io
            mode = FASHION_MODES[mode_name]
            style = FASHION_STYLES[style_name]
            w, h = mode["size"]
            ckpt = self.ckpt_var.get()
            if self._is_sd15(ckpt) or self._is_turbo_distilled(ckpt):
                self.log("Fashion Designer: needs a standard SDXL "
                         "checkpoint - aborted")
                set_status("Needs a standard SDXL checkpoint - aborted")
                return None, None
            safe = re.sub(r"[^\w\-]+", "_", garment)[:40]
            out_dir = self.output_dir / "fashion_designs" / \
                f"{datetime.now():%Y%m%d_%H%M}_{safe}"
            out_dir.mkdir(parents=True, exist_ok=True)

            def gen(positive, negative, tag):
                wf = self.client.build_txt2img_workflow(
                    ckpt=ckpt, positive=positive, negative=negative,
                    width=w, height=h, batch_size=1,
                    steps=int(self.steps_var.get()),
                    cfg=float(self.cfg_var.get()),
                    sampler=self.sampler_var.get(),
                    scheduler=self.sched_var.get(),
                    seed=random.randint(0, 2**48))
                entry = self._queue_and_wait(wf)
                info = next(x for o in entry["outputs"].values()
                           for x in o.get("images", []))
                raw = self.client.download_image(
                    info["filename"], info.get("subfolder", ""),
                    info.get("type", "output"))
                img = Image.open(io.BytesIO(raw))
                img.save(out_dir / f"{tag}.png")
                return img

            preview_path = None
            if mode_name == "Technical Flats (front/back/side)":
                views = ["front", "back", "side"]
                imgs = {}
                for i, view in enumerate(views, 1):
                    if self.stop_flag:
                        break
                    set_status(f"Drawing {view} view ({i}/3)...")
                    positive = mode["prompt"].format(garment=garment,
                                                     view=view)
                    imgs[view] = gen(positive, mode["negative"], view)
                sheet = render_flats_sheet(
                    imgs.get("front"), imgs.get("back"), imgs.get("side"),
                    title=garment[:60])
                sheet.save(out_dir / "spec_sheet.png", dpi=(300, 300))
                preview_path = out_dir / "spec_sheet.png"
                self.log(f"Fashion flats: {out_dir.name}/spec_sheet.png")

            elif mode_name == "Pose Study Sheet":
                poses = random.sample(FASHION_POSES,
                                      min(n_poses, len(FASHION_POSES)))
                paths = []
                for i, pose in enumerate(poses, 1):
                    if self.stop_flag:
                        break
                    set_status(f"Pose {i}/{len(poses)}: {pose[:30]}...")
                    positive = mode["prompt"].format(
                        garment=garment, pose=pose, style=style)
                    gen(positive, mode["negative"], f"pose_{i:02d}")
                    paths.append(out_dir / f"pose_{i:02d}.png")
                if paths:
                    sheet = make_moodboard(paths, cols=min(3, len(paths)),
                                           cell=420, bg=(250, 250, 250))
                    sheet.save(out_dir / "pose_sheet.png", dpi=(300, 300))
                    preview_path = out_dir / "pose_sheet.png"
                    self.log(f"Pose sheet: {out_dir.name}/pose_sheet.png "
                            f"({len(paths)} poses)")

            else:  # Concept Art / Editorial Model Shoot - single hero shot
                set_status(f"Rendering {mode_name}...")
                positive = mode["prompt"].format(garment=garment,
                                                 style=style)
                img = gen(positive, mode["negative"], "hero")
                if self.brand.active():
                    img = self.brand.apply(img)
                    img.save(out_dir / "hero.png")
                preview_path = out_dir / "hero.png"
                self.log(f"Fashion design: {out_dir.name}/hero.png")

            elapsed = time.time() - t0
            set_status(f"DONE ({elapsed:.0f}s) -> {out_dir}")
            return out_dir, preview_path
        except Exception as e:
            self.log(f"Fashion Designer ERROR: {e}")
            set_status(f"Failed: {e}")
            return None, None

    def _fashion_worker(self, garment, mode_name, style_name, n_poses,
                        set_status, done_cb):
        self.busy = True
        try:
            out_dir, preview_path = self._run_fashion_pipeline(
                garment, mode_name, style_name, n_poses, set_status)
            if preview_path:
                self.show_preview(preview_path)
        finally:
            self.busy = False
            done_cb()

