        ttk.Combobox(rr, textvariable=mode_var, state="readonly",
                     values=list(CINEMATIC_MODES), width=32).pack(side="left")

        rr = frow("Style")
        style_var = tk.StringVar(value=ART_STYLES[0])
        ttk.Combobox(rr, textvariable=style_var, state="readonly",
                     values=ART_STYLES, width=32).pack(side="left")

        rr = frow("Character")
