    def _pack_cover_worker(self, brief, set_status, done_cb):
        """Thin busy-flag-managed wrapper around _run_pack_cover_pipeline,
        matching every other generation entry point's established
        thread/busy-flag/done_cb convention in this file."""
        self.busy = True
        try:
            out_dir = self._run_pack_cover_pipeline(brief, set_status)
            if out_dir:
                self.show_preview(out_dir / "cover_3000x3000.png")
        finally:
            self.busy = False
