    def _run_cinematic_pipeline(self, scene, mode_name, style, persona,
                                aspect_name, set_status=None):
        """v6.8: busy-flag-free, done_cb-free core - extracted from
        _cinematic_worker so Auto-Pilot's Cinematic cycles can call it
        directly without the outer worker's finally-block flipping
        self.busy back off mid Auto-Pilot session (the same class of bug
        already found and fixed once this session for
        _character_designer_worker/_run_character_blueprint_pipeline).
        Returns the final cropped image Path on success, None on any
        failure (never raises - matches that same precedent)."""
        set_status = set_status or (lambda t: None)
        t0 = time.time()
        try:
            from PIL import Image
            import io
            mode = CINEMATIC_MODES[mode_name]
            target_w, target_h = CINEMATIC_ASPECTS[aspect_name]
            ckpt = self.ckpt_var.get()
            if self._is_sd15(ckpt) or self._is_turbo_distilled(ckpt):
                self.log("Cinematic Scene Studio: needs a standard "
                         "SDXL checkpoint - aborted")
                set_status("Needs a standard SDXL checkpoint - aborted")
                return None
            steps = max(24, int(self.steps_var.get()))
            cfg = float(self.cfg_var.get())
            sampler, sched = auto_sampler(style)

            character_clause = f"{persona.get('name','')}, " \
                f"{persona.get('visual_details','')[:120]}, " if persona else ""
            positive = mode["prompt"].format(
                scene=scene, character=character_clause, style=style)
            negative = CHAR_BLUEPRINT_NEGATIVE + ", " + mode["negative"]

            # No face-lock here: personas don't carry a stored reference
            # image (face-lock elsewhere in this app always generates a
            # fresh hero portrait first specifically to serve as one, but
            # a single wide scene has no natural "hero" to anchor to) -
            # character representation comes from visual_details tags
            # in the prompt, the same mechanism plain Generate/Wallpaper
            # Lab/Batch already use without face-lock.

            # Generate at a safe capped SDXL bucket (matches Wallpaper
            # Lab's own _hifi_master pattern) then crop into the actual
            # cinematic aspect - never ask for a native ultra-wide latent.
            orientation = "landscape" if target_w >= target_h else "portrait"
            w, h = (1216, 832) if orientation == "landscape" else (832, 1216)
            set_status(f"Directing ({mode_name})...")
            wf = self.client.build_txt2img_workflow(
                ckpt=ckpt, positive=positive, negative=negative,
                width=w, height=h, batch_size=1, steps=steps, cfg=cfg,
                sampler=sampler, scheduler=sched,
                seed=random.randint(0, 2**48),
                hires_fix=True, hires_scale=1.4, hires_denoise=0.45)
            entry = self._queue_and_wait(wf)
            outputs = entry.get("outputs", {}) if (entry and isinstance(entry, dict)) else {}
            images = [x for o in outputs.values() for x in o.get("images", [])]
            if not images:
                self.log(f"Cinematic '{mode_name}': No image output found in result")
                return None
            info = images[0]
            raw = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))
            master = Image.open(io.BytesIO(raw))
            final = fit_exact(master, target_w, target_h)

            safe_name = re.sub(r"[^\w\-]+", "_", scene)[:30]
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            out_dir = self.output_dir / "cinematic_scenes" / f"{stamp}_{safe_name}"
            out_dir.mkdir(parents=True, exist_ok=True)
            out_path = out_dir / "scene.png"
            final.save(out_path)
            elapsed = time.time() - t0
            self.log(f"Cinematic Scene Studio: {out_dir.name}/scene.png "
                     f"({aspect_name}, {elapsed:.0f}s)")
            set_status(f"DONE ({elapsed:.0f}s) -> {out_dir.name}")
            return out_path
        except Exception as e:
            self.log(f"Cinematic Scene Studio ERROR: {e}")
            set_status(f"Failed: {e}")
            return None

    def _run_photography_pilot_pipeline(self, persona, style=None,
                                        set_status=None):
        """v9.13: dedicated Auto-Pilot cycle for the new photography
        styles (ART_STYLES entries tagged "photography", e.g. street/
        film-noir/macro/golden-hour) - a SEPARATE function from the
        other cycle pipelines (_run_cinematic_pipeline/_run_fashion_
        pipeline/etc) rather than folding into any of them, since a
        photography-style portrait is its own distinct shot type (a
        close-up Portrait-mode build via _hifi_master, not a wide scene
        or a garment flat). Busy-flag-free, done_cb-free core matching
        this project's established Auto-Pilot pipeline shape - returns
        (image_path, positive_prompt) on success so a caller that scores/
        curates the result (Auto-Pilot's finish-item helper) can log the
        exact prompt actually used rather than recomputing a fresh,
        differently-wildcard-expanded one; (None, None) on any failure
        (never raises)."""
        set_status = set_status or (lambda t: None)
        style = style or random.choice(PHOTOGRAPHY_STYLES)
        name = persona.get("name", "unknown")
        positive = self.wildcards.expand(
            self.prompts.build("Portrait", persona, style))
        negative = self.neg_text.get("1.0", "end").strip() \
            if hasattr(self, "neg_text") else DEFAULT_NEGATIVE
        set_status(f"Photography Pilot: {name} ({style[:30]})")
        try:
            tmp = self._hifi_master(
                positive, negative, orientation="portrait", hifi=True,
                ckpt=self.ckpt_var.get(), log=self.log)
        except Exception as e:
            self.log(f"Photography Pilot ERROR: {e}")
            set_status(f"Failed: {e}")
            return None, None
        stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        safe_style = re.sub(r"[^\w\-]+", "_", style.split(",")[0])[:30]
        out_dir = self.output_dir / "photography_pilot"
        out_dir.mkdir(parents=True, exist_ok=True)
        out_path = out_dir / f"{stamp}_{safe_style}.png"
        tmp.replace(out_path)
        self.log(f"Photography Pilot: {name} ({style[:40]}) -> "
                 f"{out_path.name}")
        set_status(f"DONE -> {out_path.name}")
        return out_path, positive

    def _run_waifu_specialty_pipeline(self, persona, set_status=None):
        """v10.4: dedicated Auto-Pilot cycle for Mature Content Mode -
        same busy-flag-free/done_cb-free shape as
        _run_photography_pilot_pipeline (single _hifi_master portrait
        pass, no best-of-N). Gated on _mature_allowed() BOTH here
        (defensive - never generate mature content if the toggle is off
        or this is the Kids build) and at the cfg/checkbox level in the
        Auto-Pilot dialog - belt-and-braces, matching this app's
        established safety-gate convention. Reuses the same rotating
        MATURE_ATTIRE_VARIATIONS/MATURE_SCENE_VARIATIONS pools as the
        mature-mode character-invention prompt, so a long session gets
        real variety here too. The always-on SAFETY_FLOOR_NEGATIVE is
        untouched - enforced unconditionally inside build_txt2img_
        workflow regardless of this toggle's state."""
        set_status = set_status or (lambda t: None)
        if not self._mature_allowed():
            return None, None
        name = persona.get("name", "unknown")
        visual = persona.get("visual_details", "")
        attire = random.choice(MATURE_ATTIRE_VARIATIONS)
        scene = random.choice(MATURE_SCENE_VARIATIONS)
        style = self.taste.pick_style("autopilot_waifu", ART_STYLES)
        positive = self.wildcards.expand(
            f"{QUALITY}, {name}, {visual}, wearing {attire}, {scene}, "
            f"alluring pose, beautiful anime waifu, {style}")
        negative = self.neg_text.get("1.0", "end").strip() \
            if hasattr(self, "neg_text") else DEFAULT_NEGATIVE
        set_status(f"Waifu Specialty: {name} ({attire})")
        try:
            tmp = self._hifi_master(
                positive, negative, orientation="portrait", hifi=True,
                ckpt=self.ckpt_var.get(), log=self.log)
        except Exception as e:
            self.log(f"Waifu Specialty ERROR: {e}")
            set_status(f"Failed: {e}")
            return None, None
        stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        safe_name = re.sub(r"[^\w\-]+", "_", name)[:30]
        out_dir = self.output_dir / "waifu_specialty_pilot"
        out_dir.mkdir(parents=True, exist_ok=True)
        out_path = out_dir / f"{stamp}_{safe_name}.png"
        tmp.replace(out_path)
        self.log(f"Waifu Specialty: {name} ({attire}) -> {out_path.name}")
        set_status(f"DONE -> {out_path.name}")
        return out_path, positive

    def _cinematic_worker(self, scene, mode_name, style, persona,
                          aspect_name, set_status, done_cb):
        self.busy = True
        try:
            out_path = self._run_cinematic_pipeline(
                scene, mode_name, style, persona, aspect_name, set_status)
            if out_path:
                self.show_preview(out_path)
        finally:
            self.busy = False
            done_cb()

    # ── v9.7: Pack Cover Studio - sample-pack box art ────────────────────────
    def _build_pack_emblem_prompt(self, brief: dict) -> tuple:
        """Pure string assembly - no GLM call needed for the emblem
        prompt itself (deterministic template assembly is enough, per
        the spec's own example prompt shape). GLM/template copy for
        title/subtitle stays separate, matching _listing_worker's
        existing division of labor (marketing copy vs. rendered pixels).
        Returns (positive, negative)."""
        subject = brief.get("visual_subject", "abstract emblem")
        mood = brief.get("mood", "dark")
        genre = brief.get("genre", "")
        positive = (
            f"{QUALITY}, high-end visual identity artwork, a {mood} "
            f"{subject}, premium sound-design aesthetic, cinematic "
            f"studio render, sharp material details, high contrast, "
            f"centered icon composition, square format"
            + (f", {genre} mood" if genre else "")
        )
        negative = DEFAULT_NEGATIVE + PACK_EMBLEM_NEGATIVE_SUFFIX
        return positive, negative

    def _run_pack_emblem_generation(self, brief: dict, set_status=None):
        """Busy-flag-free core (matches _run_cinematic_pipeline's
        convention): generates the central emblem/art via ComfyUI with
        no text requested from the model. Returns a PIL Image on
        success, None on any failure."""
        set_status = set_status or (lambda t: None)
        try:
            from PIL import Image
            import io
            ckpt = self.ckpt_var.get()
            if self._is_sd15(ckpt) or self._is_turbo_distilled(ckpt):
                self.log("Pack Cover Studio: needs a standard SDXL "
                         "checkpoint - aborted")
                set_status("Needs a standard SDXL checkpoint - aborted")
                return None
            positive, negative = self._build_pack_emblem_prompt(brief)
            set_status("Generating emblem art...")
            wf = self.client.build_txt2img_workflow(
                ckpt=ckpt, positive=positive, negative=negative,
                width=1024, height=1024, batch_size=1,
                steps=max(24, int(self.steps_var.get())),
                cfg=float(self.cfg_var.get()),
                sampler=self.sampler_var.get(),
                scheduler=self.sched_var.get(),
                seed=int(brief.get("seed") or random.randint(0, 2**48)))
            entry = self._queue_and_wait(wf)
            outputs = entry.get("outputs", {}) if (entry and isinstance(entry, dict)) else {}
            images = [x for o in outputs.values() for x in o.get("images", [])]
            if not images:
                self.log("Pack Cover Studio: no image output from emblem generation")
                set_status("Failed: no image output")
                return None
            info = images[0]
            raw = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))
            return Image.open(io.BytesIO(raw)).convert("RGBA")
        except Exception as e:
            self.log(f"Pack Cover Studio emblem ERROR: {e}")
            set_status(f"Failed: {e}")
            return None

    def _build_pack_box_face(self, emblem, accent_color, size=900):
        """Composits the emblem onto a plain colored box-face square
        before perspective/shadow/glow are applied - a flat rectangle
        with the emblem centered at ~70% scale."""
        from PIL import Image
        face = Image.new("RGBA", (size, size), (*accent_color, 255))
        emblem_size = int(size * 0.7)
        emblem_fit = fit_exact(emblem.convert("RGB"), emblem_size, emblem_size).convert("RGBA")
        face.paste(emblem_fit, ((size - emblem_size) // 2, (size - emblem_size) // 2))
        return face

    def _run_pack_cover_pipeline(self, brief: dict, set_status=None):
        """Busy-flag-free core (matches _run_cinematic_pipeline's
        convention): emblem generation -> box compositing -> stacking ->
        title/badges -> multi-format export. Returns the pack's output
        directory Path on success, None on any failure."""
        set_status = set_status or (lambda t: None)
        t0 = time.time()
        try:
            template_id = brief.get("template", "neon_trinity_stack")
            template = PACK_TEMPLATES.get(template_id, PACK_TEMPLATES["neon_trinity_stack"])
            palette = PACK_PALETTES.get(brief.get("palette", "violet_chrome"),
                                        PACK_PALETTES["violet_chrome"])

            emblem = self._run_pack_emblem_generation(brief, set_status)
            if emblem is None:
                return None

            set_status("Compositing box art...")
            box_count = template["box_count"]
            face_size = 900
            face = self._build_pack_box_face(emblem, palette["accent"], size=face_size)
            box = apply_box_perspective(face, skew_pct=0.12)
            box = render_rim_glow(box, color=palette["rim"],
                                  blur_radius=template["glow_blur"])
            box = render_drop_shadow(box, opacity=template["shadow_opacity"])
            boxes = [box] * box_count

            canvas_w, canvas_h = template["canvas"]
            # content_width=face_size (the pre-effects box width) so the
            # overlap is computed against visible content, not the much
            # wider glow/shadow-padded image - see stack_boxes' own
            # docstring for why this matters (a live render without it
            # showed clear gaps between boxes instead of a stack).
            stacked = stack_boxes(boxes, (canvas_w, canvas_h),
                                  bg_color=template["bg_color"],
                                  overlap_pct=0.32, content_width=face_size)

            # faint floor reflection under the stack
            reflection = render_reflection(stacked, height_pct=0.22)
            reflection.putalpha(reflection.split()[-1].point(
                lambda a: int(a * template["reflection_opacity"])))
            stacked.alpha_composite(reflection, (0, canvas_h - reflection.height // 2))

            cover = self._render_pack_title_and_badges(stacked, brief, template)

            product_name = brief.get("product_name", "Untitled Pack")
            safe_name = re.sub(r"[^\w\-]+", "_", product_name)[:40]
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            out_dir = self.output_dir / "pack_covers" / f"{stamp}_{safe_name}"
            out_dir.mkdir(parents=True, exist_ok=True)

            manifest = self._export_pack_cover_set(cover, emblem, out_dir)

            pack_json = {
                "brief": brief, "template": template_id,
                "palette": brief.get("palette", "violet_chrome"),
                "created": datetime.now().isoformat(timespec="seconds"),
                "files": manifest,
            }
            safe_json_save(out_dir / "pack.json", pack_json)

            elapsed = time.time() - t0
            self.log(f"Pack Cover Studio: {out_dir.name} ({elapsed:.0f}s)")
            set_status(f"DONE ({elapsed:.0f}s) -> {out_dir.name}")
            return out_dir
        except Exception as e:
            self.log(f"Pack Cover Studio ERROR: {e}")
            set_status(f"Failed: {e}")
            return None

    def _render_pack_title_and_badges(self, cover, brief: dict, template: dict):
        """Renders title/subtitle/brand + content-count badges directly
        onto the composited cover via PIL - reuses the bold-uppercase-
        stroke text pattern already established in render_meme/
        render_banner rather than inventing new text-rendering code."""
        from PIL import ImageDraw
        draw = ImageDraw.Draw(cover, "RGBA")
        W, H = cover.size
        title = brief.get("product_name", "UNTITLED PACK").upper()
        subtitle = brief.get("subtitle", "")
        brand = brief.get("brand", "")

        title_size = max(48, H // 14)
        font = find_bold_font(title_size)
        while draw.textbbox((0, 0), title, font=font)[2] > W * 0.85 and title_size > 30:
            title_size -= 4
            font = find_bold_font(title_size)
        tw, th = draw.textbbox((0, 0), title, font=font)[2:4]
        ty = int(H * 0.80)
        pad = title_size // 2
        draw.rounded_rectangle(
            [(W - tw) // 2 - pad, ty - pad // 2, (W + tw) // 2 + pad, ty + th + pad // 2],
            radius=pad // 2, fill=(0, 0, 0, 130))
        draw.text(((W - tw) // 2, ty), title, font=font, fill=(255, 255, 255),
                  stroke_width=max(2, title_size // 16), stroke_fill=(0, 0, 0))

        y = ty + th + pad
        if subtitle:
            sub_font = find_bold_font(max(20, title_size // 3))
            sw = draw.textbbox((0, 0), subtitle, font=sub_font)[2]
            draw.text(((W - sw) // 2, y), subtitle, font=sub_font,
                      fill=(220, 220, 220), stroke_width=1, stroke_fill=(0, 0, 0))
            y += sub_font.size + 10
        if brand:
            brand_font = find_bold_font(max(16, title_size // 4))
            bw = draw.textbbox((0, 0), brand, font=brand_font)[2]
            draw.text(((W - bw) // 2, y), brand, font=brand_font,
                      fill=(180, 180, 180), stroke_width=1, stroke_fill=(0, 0, 0))

        # content-count badges: small pill row above the title block
        labels = list(brief.get("contents", []))[:4]
        if labels:
            badge_w, badge_h, gap = 220, 60, 16
            total_w = badge_w * len(labels) + gap * (len(labels) - 1)
            bx = (W - total_w) // 2
            by = ty - pad - badge_h - 20
            for label in labels:
                badge = render_badge(label.upper(), size=(badge_w, badge_h))
                cover.alpha_composite(badge, (bx, by))
                bx += badge_w + gap
        return cover

    def _export_pack_cover_set(self, cover, emblem, out_dir):
        """Exports the multi-format set every approved pack gets, per
        the spec's own export list. Follows this file's established
        '<name>_<w>x<h>.<ext>' naming convention (comfy_companion.py's
        existing multi-resolution export helper uses the same shape)."""
        manifest = {}
        cover_rgb = cover.convert("RGB")

        p = out_dir / "cover_3000x3000.png"
        fit_exact(cover_rgb, 3000, 3000).save(p)
        manifest["cover"] = p.name

        p = out_dir / "social_1080x1080.png"
        fit_exact(cover_rgb, 1080, 1080).save(p)
        manifest["social"] = p.name

        p = out_dir / "story_1080x1920.png"
        fit_exact(cover_rgb, 1080, 1920).save(p)
        manifest["story"] = p.name

        p = out_dir / "store_card_1600x1600.webp"
        fit_exact(cover_rgb, 1600, 1600).save(p, quality=92)
        manifest["store_card"] = p.name

        p = out_dir / "logo_transparent.png"
        emblem.save(p)
        manifest["logo"] = p.name

        return manifest

    # ── v6.2: Auto Character Designer ────────────────────────────────────────
    def _character_designer_worker(self, concept, set_status, done_cb):
        """Thin UI-facing wrapper around _run_character_blueprint_pipeline:
        owns self.busy for the manual Auto Character Designer dialog and
        translates the return tuple into the done_cb callback the dialog
        expects. Auto-Pilot's "infinite characters" feature (v6.3) calls
        the pipeline directly instead, since it manages its own busy/
        session lifecycle and would double-manage self.busy through this
        wrapper."""
        self.busy = True
        try:
            blueprint, hero_p, out_dir = self._run_character_blueprint_pipeline(
                concept, set_status)
            done_cb(blueprint, hero_p, out_dir)
        except Exception as e:
            self.log(f"Auto Character Designer ERROR: {e}")
            set_status(f"Failed: {e}")
            done_cb(None, None, None)
        finally:
            self.busy = False

    def _run_character_blueprint_pipeline(self, concept, set_status, *,
                                          force_style=None, quality_boost=False):
        """GLM invents a character + wardrobe; the app's own taste system
        picks the art styles; a hero portrait establishes an IP-Adapter
        face-lock reused across a face-locked turnaround, an alt outfit,
        and two style-variant showcases - ~7 generations assembled into
        one PDF blueprint. Returns (blueprint, hero_path, out_dir) on
        success, (None, None, None) on failure. Does NOT manage
        self.busy - callers own that (see _character_designer_worker and
        Auto-Pilot's invent branch in _autopilot_worker).

        force_style: use this as primary_style instead of a taste pick
        (Auto-Pilot forces its cinematic-poster showcase look here).
        quality_boost: apply FreeU/PAG (cheap, no extra pass) to every
        generation, and - VRAM/resolution permitting - hires-fix to the
        hero portrait only (the one image expensive enough to matter for
        a "poster" showcase; applying it to all 7 would double this
        pipeline's already-substantial ~5min/character cost)."""
        t0 = time.time()
        try:
            from PIL import Image
            import io

            set_status("GLM is designing the character...")
            blueprint = self._build_character_blueprint(concept)
            if not blueprint:
                set_status("GLM did not return a character - try again")
                return None, None, None
            name = blueprint["name"]
            self.log(f"Auto Character Designer: designing '{name}'")
            self.quotes.release_vram()  # free LLM VRAM before diffusion

            taste = self.director.taste
            primary_style = force_style or \
                taste.pick_style("auto_character_designer", ART_STYLES)
            variant_style_1 = taste.pick_style("auto_character_designer", ART_STYLES)
            for _ in range(5):
                if variant_style_1 != primary_style:
                    break
                variant_style_1 = random.choice(ART_STYLES)
            variant_style_2 = taste.pick_style("auto_character_designer", ART_STYLES)
            for _ in range(5):
                if variant_style_2 not in (primary_style, variant_style_1):
                    break
                variant_style_2 = random.choice(ART_STYLES)

            available = [v for v in self.lora_box["values"] if v != "(none)"]
            lora_match = pick_lora_for_style(primary_style, available)
            lora_kwargs = {"lora": [lora_match]} if lora_match else {}

            ckpt = self.ckpt_var.get()
            if self._is_sd15(ckpt):
                # Belt-and-suspenders: open_character_designer's dialog
                # already gates this, but the worker is also callable
                # directly - an SDXL-only IP-Adapter/CLIP-Vision pair
                # wired onto an SD1.5 UNet produces garbage output, not
                # a clean error, so this must never be silently skipped.
                self.log("Auto Character Designer: needs an SDXL "
                         "checkpoint (current is SD1.5) - aborted")
                set_status("Needs an SDXL checkpoint - aborted")
                return None, None, None
            if self._is_turbo_distilled(ckpt):
                # Same class of problem as SD1.5: this worker reuses the
                # main window's general steps/cfg sliders across 7 fixed
                # generations - a Turbo/Lightning/LCM checkpoint needs a
                # very different CFG (~1-2) and step count (~4-8), so
                # running it here would blow every image out into static.
                self.log("Auto Character Designer: needs a standard SDXL "
                         "checkpoint (current is Turbo-distilled) - aborted")
                set_status("Needs a standard (non-Turbo) SDXL checkpoint - aborted")
                return None, None, None
            steps = int(self.steps_var.get())
            cfg = float(self.cfg_var.get())

            safe_name = re.sub(r"[^\w\-]+", "_", name)[:40]
            out_dir = (self.output_dir / "character_blueprints" /
                      f"{datetime.now():%Y%m%d_%H%M}_{safe_name}")
            out_dir.mkdir(parents=True, exist_ok=True)
            (out_dir / "blueprint.json").write_text(
                json.dumps({**blueprint, "primary_style": primary_style,
                           "variant_style_1": variant_style_1,
                           "variant_style_2": variant_style_2,
                           "lora_match": lora_match},
                          indent=2, ensure_ascii=False), encoding="utf-8")

            visual = blueprint.get("visual_details", "")
            hero_pose = blueprint.get("hero_pose_description", "")
            hero_outfit = blueprint.get("hero_outfit", "")
            wardrobe_alt = blueprint.get("wardrobe_alt", "")
            face_kwargs = {}

            # v6.3: quality_boost - FreeU/PAG are cheap (no extra sampling
            # pass), apply to every generation for a consistently sharper
            # look across the whole blueprint.
            qb_kwargs = {}
            if quality_boost:
                if self.caps.get("freeu"):
                    qb_kwargs["freeu_enabled"] = True
                if self.caps.get("pag"):
                    qb_kwargs["pag_enabled"] = True

            def gen(positive, negative, width, height, sampler, scheduler,
                   use_lora=True, use_face=True, face_weight_override=None,
                   extra=None):
                fk = dict(face_kwargs) if use_face else {}
                if fk and face_weight_override is not None:
                    fk["face_weight"] = face_weight_override
                wf = self.client.build_txt2img_workflow(
                    ckpt=ckpt, positive=positive, negative=negative,
                    width=width, height=height, batch_size=1, steps=steps,
                    cfg=cfg, sampler=sampler, scheduler=scheduler,
                    seed=random.randint(0, 2**48),
                    **(lora_kwargs if use_lora else {}), **fk,
                    **qb_kwargs, **(extra or {}))
                entry = self._queue_and_wait(wf)
                info = next(x for o in entry["outputs"].values()
                           for x in o.get("images", []))
                raw = self.client.download_image(
                    info["filename"], info.get("subfolder", ""),
                    info.get("type", "output"))
                return Image.open(io.BytesIO(raw))

            # ── Step 1: hero portrait (establishes the face reference) ──
            set_status("Drawing hero portrait...")
            samp, sched = auto_sampler(primary_style)
            hero_extra = {}
            if quality_boost:
                # Same VRAM-headroom gate the Smart Director's own
                # auto-hires logic uses (~1.5GB free required) - checked
                # fresh here rather than assumed, since VRAM state can
                # drift hours into an unattended Auto-Pilot session. The
                # resolution cap is relaxed to this pipeline's own fixed
                # 1024x1024 (vs. the Director's 832x1216) since that's
                # already the size 3 of these 7 generations run at
                # without incident - reusing the stricter 832x1216 cap
                # verbatim would make hires-fix a dead branch here (the
                # hero is always 1024x1024, always over that cap).
                used, total = self._get_gpu_vram_usage()
                if total > 0 and (total - used) >= 1.5 and steps <= 32:
                    scale = 1.4 if total <= 8.5 else 1.5
                    hero_extra = {"hires_fix": True, "hires_scale": scale,
                                 "hires_denoise": 0.4}
                    self.log(f"Blueprint hero: hires-fix auto-enabled "
                             f"(scale {scale})")
                else:
                    self.log("Blueprint hero: skipping hires-fix "
                             "(insufficient VRAM headroom) - FreeU/PAG only")
            try:
                hero_img = gen(
                    f"{QUALITY}, {name}, {visual}, {hero_pose}, "
                    f"character portrait, centered, simple background, "
                    f"{primary_style}",
                    CHAR_BLUEPRINT_NEGATIVE, 1024, 1024, samp, sched,
                    use_lora=True, use_face=False, extra=hero_extra)
            except Exception as e:
                self.log(f"Blueprint step 'hero' failed: {e}")
                set_status(f"Failed to generate hero portrait: {e}")
                return None, None, None
            hero_p = out_dir / "hero.png"
            hero_img.save(hero_p)

            if self.caps.get("ipadapter") and self.ipadapter_file and \
                    self.clip_vision_file:
                try:
                    face_kwargs = {
                        "face_ref": self._upload_ref(hero_p),
                        "face_weight": 0.6,
                        "ipadapter_file": self.ipadapter_file,
                        "clip_vision_file": self.clip_vision_file,
                    }
                    self.log("Auto Character Designer: face locked for "
                            "turnaround/variants")
                except Exception as e:
                    self.log(f"Face lock skipped: {e}")
            else:
                self.log("Auto Character Designer: IP-Adapter unavailable "
                         "- turnaround/variants will vary in face detail "
                         "(seed-only)")

            # ── Steps 2-4: face-locked turnaround (front/back/side) ──
            # NOT the Fashion Designer "Technical Flats" template - that
            # template's negative prompt explicitly excludes
            # "model, person, face" (it's built for garment-only flats
            # with no model), which would fight a character turnaround.
            views_imgs = {}
            for view in ("front", "back", "side"):
                if self.stop_flag:
                    break
                set_status(f"Turnaround: {view} view...")
                try:
                    img = gen(
                        f"{QUALITY}, {name}, {visual}, wearing "
                        f"{hero_outfit}, {view} view, full body, "
                        f"character reference sheet, simple background",
                        CHAR_BLUEPRINT_NEGATIVE, 832, 1216, samp, sched,
                        use_lora=True, use_face=True)
                    views_imgs[view] = img
                    img.save(out_dir / f"turnaround_{view}.png")
                except Exception as e:
                    self.log(f"Blueprint step 'turnaround_{view}' failed: {e}")
            turnaround_sheet = render_flats_sheet(
                views_imgs.get("front"), views_imgs.get("back"),
                views_imgs.get("side"), title=name[:60])
            turnaround_p = out_dir / "turnaround.png"
            turnaround_sheet.save(turnaround_p, dpi=(300, 300))

            # ── Step 5: alternate outfit ──
            alt_p = None
            if not self.stop_flag:
                set_status("Alt outfit...")
                try:
                    alt_img = gen(
                        f"{QUALITY}, {name}, {visual}, wearing "
                        f"{wardrobe_alt}, full body, {primary_style}",
                        CHAR_BLUEPRINT_NEGATIVE, 832, 1216, samp, sched,
                        use_lora=True, use_face=True)
                    alt_p = out_dir / "alt_outfit.png"
                    alt_img.save(alt_p)
                except Exception as e:
                    self.log(f"Blueprint step 'alt_outfit' failed: {e}")

            # ── Steps 6-7: art-style showcase variants (no LoRA - the ──
            # ── point is showing style-only variation) ──
            variant_paths = []
            for i, vstyle in enumerate((variant_style_1, variant_style_2), 1):
                if self.stop_flag:
                    break
                set_status(f"Style variant {i}/2: {vstyle[:30]}...")
                try:
                    vsamp, vsched = auto_sampler(vstyle)
                    # Lower face_weight here (vs. the 0.6 default): at full
                    # strength the IP-Adapter reference visibly dominated
                    # the style prompt in testing (a "pastel dreamcore"
                    # variant rendered nearly identical to the primary
                    # neon-cyberpunk look) - these two steps exist
                    # specifically to showcase style variation, so identity
                    # should nudge through without suppressing it.
                    vimg = gen(
                        f"{QUALITY}, {name}, {visual}, {hero_pose}, ({vstyle}:1.3)",
                        CHAR_BLUEPRINT_NEGATIVE, 1024, 1024, vsamp, vsched,
                        use_lora=False, use_face=True, face_weight_override=0.35)
                    vp = out_dir / f"style_variant_{i}.png"
                    vimg.save(vp)
                    variant_paths.append(vp)
                except Exception as e:
                    self.log(f"Blueprint step 'style_variant_{i}' failed: {e}")

            set_status("Assembling blueprint sheet...")
            render_character_blueprint_sheet(
                hero_img, turnaround_p, alt_p, variant_paths, blueprint,
                out_dir, name)

            self.show_preview(hero_p)
            elapsed = time.time() - t0
            self.log(f"Auto Character Designer: '{name}' blueprint "
                     f"complete ({elapsed:.0f}s) -> {out_dir.name}")
            set_status(f"DONE ({elapsed:.0f}s) -> {out_dir.name}")
            return blueprint, hero_p, out_dir
        except Exception as e:
            self.log(f"Auto Character Designer ERROR: {e}")
            set_status(f"Failed: {e}")
            return None, None, None

    def _confirm_and_save_blueprint_persona(self, blueprint, hero_path, out_dir):
        """Review-and-edit confirm gate before writing to personas.json -
        the dialog IS the exact entry that gets saved, editable in place,
        mirroring the manual Character Builder's own AI-Build-then-edit
        flow (the fields stay plain text widgets right up to Save)."""
        win, body = self._new_toplevel(
            "Save as Persona - Auto Character Designer", 560, 640)
        tk.Label(body, text="Review before saving to personas.json:",
                bg=self.PANEL, fg=self.ACCENT,
                font=self.font_body_bold).pack(anchor="w", padx=12,
                                                   pady=(10, 4))
        try:
            img = tk.PhotoImage(file=str(hero_path))
            factor = max(1, -(-img.width() // 220), -(-img.height() // 220))
            if factor > 1:
                img = img.subsample(factor, factor)
            thumb = tk.Label(body, image=img, bg=self.PANEL)
            thumb.image = img
            thumb.pack(pady=(0, 8))
        except Exception:
            pass

        def frow(label, height=1):
            tk.Label(body, text=label, bg=self.PANEL, fg=self.FG_DIM,
                    font=self.font_small).pack(anchor="w", padx=12,
                                               pady=(4, 0))
            if height == 1:
                w = ttk.Entry(body)
            else:
                w = tk.Text(body, height=height, bg=self.INPUT_BG,
                           fg=self.FG, wrap="word",
                           insertbackground=self.FG, borderwidth=0)
            w.pack(fill="x", padx=12)
            return w

        def get_val(w):
            return w.get("1.0", "end").strip() if isinstance(w, tk.Text) \
                else w.get().strip()

        def set_val(w, text):
            if isinstance(w, tk.Text):
                w.delete("1.0", "end")
                w.insert("1.0", text)
            else:
                w.delete(0, "end")
                w.insert(0, text)

        fields = {}
        fields["name"] = frow("Name")
        set_val(fields["name"], blueprint.get("name", ""))
        visual = blueprint.get("visual_details", "")
        if blueprint.get("hero_outfit"):
            visual = f"{visual}, {blueprint['hero_outfit']}"
        fields["visual_details"] = frow("Visual details", 4)
        set_val(fields["visual_details"], visual)
        fields["psychology"] = frow("Personality", 3)
        set_val(fields["psychology"], blueprint.get("psychology", ""))
        fields["backstory"] = frow("Backstory", 3)
        set_val(fields["backstory"], blueprint.get("backstory", ""))
        fields["signature_quote"] = frow("Signature quote")
        set_val(fields["signature_quote"], blueprint.get("signature_quote", ""))
        fields["signature_pose"] = frow("Signature pose", 2)
        set_val(fields["signature_pose"], blueprint.get("hero_pose_description", ""))

        def save():
            name = get_val(fields["name"])
            if not name:
                messagebox.showinfo("Missing name", "Character needs a name.",
                                    parent=win)
                return
            entry = {k: get_val(w) for k, w in fields.items()}
            entry["active"] = True
            self._save_persona(name, entry)
            self.log(f"Auto Character Designer: saved '{name}' as a persona")
            win.destroy()

        btn_row = tk.Frame(body, bg=self.PANEL)
        btn_row.pack(pady=14)
        ttk.Button(btn_row, text="SAVE AS PERSONA", command=save).pack(
            side="left", padx=4)
        ttk.Button(btn_row, text="Discard (keep files only)",
                  command=win.destroy).pack(side="left", padx=4)

    def open_character_designer(self):
        """Auto-generate a complete character blueprint: GLM invents the
        character + wardrobe, the app's own taste system picks the art
        styles, and a face-locked turnaround/alt-outfit/style-showcase
        gets assembled into a PDF - optionally saved as a new persona."""
        win, body = self._new_toplevel("Auto Character Designer", 600, 440)
        tk.Label(body, text="Concept (optional - leave blank to "
                "surprise-me):", bg=self.PANEL, fg=self.ACCENT,
                font=self.font_body_bold).pack(anchor="w", padx=12,
                                                   pady=(12, 2))
        concept_entry = ttk.Entry(body)
        concept_entry.pack(fill="x", padx=12)
        tk.Label(body, text="Generates ~7 images: hero portrait, "
                "face-locked turnaround, an alt outfit, and 2 art-style "
                "variants, plus a bio - assembled into a PDF blueprint "
                "sheet. You'll get to review and optionally save the "
                "result as a new persona.",
                bg=self.PANEL, fg=self.FG_MUTED, wraplength=560,
                justify="left").pack(anchor="w", padx=12, pady=(4, 8))
        status = tk.Label(body, text="Output: character_blueprints/<name>/",
                          bg=self.PANEL, fg=self.FG_MUTED, wraplength=560,
                          justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def start():
            concept = concept_entry.get().strip()
            if self.busy:
                messagebox.showinfo("Busy", "A generation is already "
                                    "running.", parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI is not connected.",
                                     parent=win)
                return
            if self._is_sd15(self.ckpt_var.get()):
                # This feature leans on SDXL-only pieces throughout (the
                # installed IP-Adapter/CLIP-Vision face-lock files, and
                # typically the LoRA registry) - not just face-lock, so it
                # gets the same hard gate as Auto-Fix/Tiled Upscale rather
                # than a silent per-step degrade.
                messagebox.showinfo("Needs SDXL", "Auto Character Designer "
                                    "needs an SDXL checkpoint selected in "
                                    "Model (the current one is SD1.5).",
                                    parent=win)
                return
            if self._is_turbo_distilled(self.ckpt_var.get()):
                messagebox.showinfo("Needs a standard SDXL checkpoint",
                                    "Auto Character Designer reuses this "
                                    "window's Steps/CFG across 7 fixed "
                                    "generations - a Turbo/Lightning/LCM "
                                    "checkpoint needs very different "
                                    "settings and would produce broken "
                                    "output. Pick a standard SDXL "
                                    "checkpoint in Model.", parent=win)
                return
            if not self.quotes.backend:
                self.quotes.detect()
            if not self.quotes.backend:
                messagebox.showinfo("No LLM", "Start Ollama or Locally "
                                    "Uncensored first.", parent=win)
                return
            go_btn.configure(state="disabled", text="Designing...")

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def done(blueprint=None, hero_p=None, out_dir=None):
                def _finish():
                    go_btn.configure(state="normal", text="✨ DESIGN")
                    if blueprint:
                        self._confirm_and_save_blueprint_persona(
                            blueprint, hero_p, out_dir)
                self.root.after(0, _finish)
            self.stop_flag = False  # v7.1: see start_generation's note
            threading.Thread(target=self._character_designer_worker,
                            args=(concept, setv, done), daemon=True).start()

        go_btn = ttk.Button(body, text="✨ DESIGN", command=start)
        go_btn.pack(pady=8)
        self.log("Opened Auto Character Designer")

    # ── v8.0: Ensemble Cast Composer (two personas, each their own face) ───
    def _find_persona_face_ref(self, name: str):
        """Best-effort face reference lookup for a persona by name - not a
        persistent index, just a one-shot glob at call time (see the
        Ensemble Cast Composer's design notes). Checks, in order:
        1. The dedicated Face Library (face_library/<safe>.png) - the
           purpose-built reference generated by Build Face Library, always
           preferred when present. Always portrait (832x1216), so no
           orientation check needed.
        2. An Auto Character Designer hero.png (character_blueprints/*_<safe>/hero.png)
           - also always portrait by construction.
        3. The most recent existing generation output matching this
           persona's name anywhere under output_dir (broadens hit-rate for
           Autopilot Duo, which has no user to manually pick a face and
           needs most of the persona library to actually resolve). This
           tier alone can match a landscape/square image (Wallpaper Pilot,
           Cinematic Pilot, etc.) that happens to share the persona's name
           in its filename - a wide framing makes a poor IPAdapter face
           reference (small/off-center face), so this tier walks newest-
           first and skips non-portrait images rather than blindly taking
           whatever's newest.
        Returns the newest (portrait) match as a Path, or None if nothing
        was found."""
        safe = re.sub(r"[^\w\-]+", "_", name)[:40]
        library_path = self.output_dir / "face_library" / f"{safe}.png"
        if library_path.exists():
            return library_path
        blueprint_dir = self.output_dir / "character_blueprints"
        if blueprint_dir.exists():
            matches = sorted(blueprint_dir.glob(f"*_{safe}/hero.png"),
                             key=lambda p: p.stat().st_mtime, reverse=True)
            if matches:
                return matches[0]
        candidates = sorted(
            (p for p in self.output_dir.glob(f"*_{safe}_*.png")
             if p.is_file() and not p.name.endswith("_meta.json")),
            key=lambda p: p.stat().st_mtime, reverse=True)
        from PIL import Image
        for cand in candidates:
            try:
                with Image.open(cand) as im:
                    if im.height >= im.width:  # portrait or square only
                        return cand
            except Exception:
                continue
        return None

    def open_3d_export(self):
        """Package a persona's best reference images for manual upload to
        a cloud image-to-3D service (Meshy, Tripo, etc.). Local 3D
        generation (e.g. Microsoft TRELLIS.2) needs 24GB+ VRAM and is not
        feasible on this 6GB card - this is the honest alternative: no
        local 3D inference, just a clean export folder + a pointer to
        where to actually do the conversion."""
        win, body = self._new_toplevel("Export for 3D", 520, 420)

        def crow(label):
            rr = tk.Frame(body, bg=self.PANEL)
            rr.pack(fill="x", padx=12, pady=4)
            tk.Label(rr, text=label, bg=self.PANEL, fg=self.FG,
                     width=10, anchor="w").pack(side="left")
            return rr

        tk.Label(body, text="No local 3D model is installed on this "
                 "machine - image-to-3D (e.g. TRELLIS.2) needs 24GB+ "
                 "VRAM. This instead collects the best reference images "
                 "for a persona so you can upload them to a cloud "
                 "service yourself (Meshy.ai, Tripo3D, Kaedim, etc.).",
                 bg=self.PANEL, fg=self.FG_MUTED, wraplength=480,
                 justify="left").pack(anchor="w", padx=12, pady=(10, 6))

        rr = crow("Persona")
        names = [p.get("name", "") for p in self.visible_personas()
                if p.get("name")]
        current = self.selected_persona()
        persona_var = tk.StringVar(
            value=current.get("name", "") if current else
            (names[0] if names else ""))
        ttk.Combobox(rr, textvariable=persona_var, state="readonly",
                     values=names, width=32).pack(side="left")

        status = tk.Label(body, text="", bg=self.PANEL, fg=self.FG_MUTED,
                          wraplength=480, justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def do_export():
            name = persona_var.get().strip()
            if not name:
                messagebox.showinfo("No persona", "Pick a persona first.",
                                    parent=win)
                return
            ref = self._find_persona_face_ref(name)
            if ref is None:
                status.config(text=f"No reference image found for "
                              f"'{name}' yet - generate at least one "
                              "portrait first (or run Build Face "
                              "Library).")
                return
            import shutil
            safe = re.sub(r"[^\w\-]+", "_", name)[:40]
            out_dir = self.output_dir / "3d_export" / safe
            out_dir.mkdir(parents=True, exist_ok=True)
            copied = []
            dest = out_dir / "reference.png"
            shutil.copy2(ref, dest)
            copied.append(dest.name)
            # bonus: an Auto Character Designer turnaround, if one exists,
            # gives the cloud service extra angles to work from
            blueprint_dir = self.output_dir / "character_blueprints"
            if blueprint_dir.exists():
                matches = sorted(
                    blueprint_dir.glob(f"*_{safe}/turnaround.png"),
                    key=lambda p: p.stat().st_mtime, reverse=True)
                if matches:
                    dest2 = out_dir / "turnaround.png"
                    shutil.copy2(matches[0], dest2)
                    copied.append(dest2.name)
            status.config(text=f"Exported {', '.join(copied)} -> "
                          f"{out_dir}\n\nUpload 'reference.png' (or "
                          "turnaround.png for a service that supports "
                          "multi-view input) to Meshy.ai, Tripo3D, or "
                          "Kaedim to get a 3D mesh.")
            self.log(f"3D export: {name} -> {out_dir}")
            try:
                os.startfile(out_dir)
            except Exception:
                pass

        ttk.Button(body, text="📦 EXPORT REFERENCE IMAGES",
                  command=do_export).pack(anchor="w", padx=12, pady=6)
        self.log("Opened Export for 3D")

    def _face_library_worker(self, personas: list, set_status):
        """Generates one portrait per persona and saves it to
        face_library/<safe_name>.png - a dedicated, purpose-built face
        reference so Autopilot Duo (and manual Ensemble Cast Composer use)
        can resolve almost the entire persona library instead of only the
        handful that happen to have prior generation output or an Auto
        Character Designer blueprint. Resumable: personas that already
        have a library entry are skipped, so stopping and restarting
        picks up where it left off rather than re-doing finished work."""
        self.busy = True
        self.root.after(0, lambda: (
            self.stop_btn.configure(state="normal"),
            self.gen_btn.configure(state="disabled")))
        lib_dir = self.output_dir / "face_library"
        lib_dir.mkdir(parents=True, exist_ok=True)
        ckpt = self.ckpt_var.get()
        total = len(personas)
        done_count = skipped = failed = 0
        try:
            for i, persona in enumerate(personas, 1):
                if self.stop_flag:
                    self.log(f"Face Library: stopped at {i - 1}/{total}")
                    break
                name = persona.get("name", "unknown")
                safe = re.sub(r"[^\w\-]+", "_", name)[:40]
                out_path = lib_dir / f"{safe}.png"
                if out_path.exists():
                    skipped += 1
                    continue
                set_status(f"Face Library {i}/{total}: {name}")
                try:
                    self.quotes.release_vram()
                    style = self.taste.pick_style("face_library", ART_STYLES)
                    # Bespoke framing, not the shared "Portrait" mode: that
                    # mode's "close-up portrait, detailed eyes" wording was
                    # found (via visual inspection of a test batch) to
                    # sometimes crop to a single extreme close-up eye -
                    # useless as an IP-Adapter face reference, which needs
                    # a full face reliably in frame. Best identity-lock
                    # accuracy comes from a face-centered portrait (large,
                    # clear face) that still keeps the WHOLE face in
                    # frame - not an eye-only extreme close-up, and not a
                    # wide/upper-body shot that shrinks the face too much.
                    persona_name = persona.get("name", "anime character")
                    visual = persona.get("visual_details", "")
                    positive = self.wildcards.expand(", ".join(p for p in [
                        QUALITY, persona_name, visual,
                        "portrait, head and shoulders, front facing, "
                        "entire face clearly visible, symmetrical face, "
                        "looking directly at viewer, simple background",
                        style] if p))
                    negative = (self.neg_text.get("1.0", "end").strip() +
                               ", extreme close-up, cropped face, "
                               "close-up eye, eye close-up, partial face, "
                               "out of frame, full body, wide shot")
                    width, height, batch = self._vram_preflight(832, 1216, 1)
                    wf = self.client.build_txt2img_workflow(
                        ckpt=ckpt, positive=positive, negative=negative,
                        width=width, height=height, batch_size=batch,
                        steps=int(self.steps_var.get()),
                        cfg=float(self.cfg_var.get()),
                        sampler=self.sampler_var.get(),
                        scheduler=self.sched_var.get(),
                        seed=random.randint(0, 2**48))
                    entry = self._queue_and_wait(wf)
                    outputs = entry.get("outputs", {}) if (entry and isinstance(entry, dict)) else {}
                    images = [x for o in outputs.values() for x in o.get("images", [])]
                    if not images:
                        self.log(f"Face Library [{i}/{total}] {name}: no image output")
                        failed += 1
                        continue
                    info = images[0]
                    data = self.client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    out_path.write_bytes(data)
                    done_count += 1
                    self.log(f"Face Library [{i}/{total}] {name}: saved")
                    if done_count % 10 == 0:
                        self.show_preview(out_path)
                except Exception as e:
                    if self.stop_flag:
                        self.log(f"Face Library [{i}/{total}] {name}: aborted")
                        break
                    self.log(f"Face Library [{i}/{total}] {name}: ERROR: {e}")
                    failed += 1
                    continue
        finally:
            self.log(f"=== Face Library DONE: {done_count} generated, "
                     f"{skipped} already had one, {failed} failed "
                     f"({total} total) ===")
            set_status(f"Face Library: {done_count} generated, "
                       f"{skipped} skipped, {failed} failed")
            self.busy = False
            self.root.after(0, lambda: (
                self.stop_btn.configure(state="disabled"),
                self.gen_btn.configure(state="normal")))

    def start_build_face_library(self):
        """One-click: generate a reference portrait for every active
        persona that doesn't already have one in face_library/, so
        Autopilot Duo and Ensemble Cast Composer can resolve nearly the
        whole persona library instead of only characters with prior
        generation history."""
        if self.busy:
            messagebox.showinfo("Busy", "A generation is already running.")
            return
        if not self.client.base_url:
            messagebox.showerror("Offline", "ComfyUI is not connected.\n"
                                 "Launch Comfy Desktop and click Reconnect.")
            return
        active = [p for p in self.prompts.personas.values()
                 if p.get("active", True) and p.get("name")]
        lib_dir = self.output_dir / "face_library"
        already = len(list(lib_dir.glob("*.png"))) if lib_dir.exists() else 0
        remaining = len(active) - already
        if remaining <= 0:
            messagebox.showinfo("Already complete",
                                "Every active persona already has a face "
                                "library entry.")
            return
        # ~60-90s per portrait on a 6GB card, matching this session's
        # measured Ensemble/Batch generation times - be honest about the
        # real time cost of a library this size before committing to it.
        est_minutes = int(remaining * 1.2)
        if not messagebox.askyesno(
                "Build Face Library",
                f"{len(active)} active personas, {already} already have a "
                f"face reference. This will generate the remaining "
                f"{remaining}.\n\nEstimated time: ~{est_minutes} minutes "
                f"(~1-1.5 min/portrait) - this can run for a long time "
                f"unattended. You can Stop it at any point and resume "
                f"later; already-generated faces are never redone.\n\n"
                f"Start now?"):
            return
        self.stop_flag = False
        self.log(f"Face Library: building {remaining} portraits "
                 f"(~{est_minutes} min estimated)")
        threading.Thread(target=self._face_library_worker,
                        args=(active, lambda t: self.set_status(t, self.ACCENT)),
                        daemon=True).start()

    def start_autopilot_duo(self):
        """One-click Ensemble Cast Composer: auto-picks two distinct
        random active personas, auto-resolves a face reference for each
        via _find_persona_face_ref, auto-picks a style, and launches
        _ensemble_worker directly - no dialog. Retries a few random pairs
        if a pick can't resolve both faces (most personas already have
        prior generation output to use as a reference, so this should
        succeed within a handful of tries)."""
        if self.busy:
            messagebox.showinfo("Busy", "A generation is already running.")
            return
        if not self.client.base_url:
            messagebox.showerror("Offline", "ComfyUI is not connected.\n"
                                 "Launch Comfy Desktop and click Reconnect.")
            return
        if not self.caps.get("ipadapter"):
            messagebox.showinfo("Face lock unavailable",
                                "Autopilot Duo needs IP-Adapter (Face lock "
                                "ready). Check the connection log for why "
                                "it's not ready.")
            return
        if self._is_sd15(self.ckpt_var.get()):
            messagebox.showinfo("Needs SDXL", "Autopilot Duo needs an SDXL "
                                "checkpoint selected in Model (the current "
                                "one is SD1.5).")
            return
        if self._is_turbo_distilled(self.ckpt_var.get()):
            messagebox.showinfo("Needs a standard SDXL checkpoint",
                                "A Turbo/Lightning/LCM checkpoint needs very "
                                "different settings - pick a standard SDXL "
                                "checkpoint in Model.")
            return

        active = [p for p in self.prompts.personas.values()
                 if p.get("active", True) and p.get("name")]
        if len(active) < 2:
            messagebox.showinfo("Not enough personas",
                                "Need at least 2 active personas.")
            return

        persona_a = persona_b = None
        face_a = face_b = None
        for _ in range(15):
            pa, pb = random.sample(active, 2)
            fa = self._find_persona_face_ref(pa.get("name", ""))
            fb = self._find_persona_face_ref(pb.get("name", ""))
            if fa and fb:
                persona_a, persona_b, face_a, face_b = pa, pb, fa, fb
                break
        if not persona_a:
            messagebox.showinfo(
                "No face references found",
                "Couldn't auto-find face references for any random "
                "persona pair after 15 tries. Generate a few images for "
                "your personas first (Autopilot Duo needs at least one "
                "existing image per character), or use Ensemble Cast "
                "Composer's manual picker instead.")
            return

        style = self.taste.pick_style("autopilot_duo", ART_STYLES) \
            if hasattr(self, "taste") else random.choice(ART_STYLES)
        self.log(f"Autopilot Duo: '{persona_a['name']}' + "
                 f"'{persona_b['name']}' (auto-picked)")
        self.duo_pilot_btn.configure(state="disabled", text="Composing...")

        def setv(t):
            self.root.after(0, lambda: self.set_status(t, self.ACCENT))

        def done(image_path=None, meta=None):
            self.root.after(0, lambda: self.duo_pilot_btn.configure(
                state="normal", text="🤖 AUTOPILOT DUO"))

        self.stop_flag = False
        threading.Thread(
            target=self._ensemble_worker,
            args=(persona_a, persona_b, style, face_a, face_b, setv, done),
            daemon=True).start()

    # ── v8.2: individual standalone pilots per Auto-Pilot category ──────────
    # (combined Auto-Pilot dialog kept as-is for power users - these are
    # simpler, focused, single-purpose alternatives, mirroring the
    # Quote Pilot / Autopilot Duo pattern already established.)
    def _open_pilot_dialog(self, title, description, worker_target, *,
                           needs_two_personas=False, extra_guard=None):
        """Shared dialog builder for every simple standalone pilot: the
        same stop-condition (count/minutes/infinite) UI, the same
        busy/offline/personas guards, launched against whatever
        worker_target is. `extra_guard()` returning a non-None string
        aborts with that message (e.g. an SDXL-only check)."""
        if self.busy:
            messagebox.showinfo("Busy", "A generation is already running.")
            return
        if not self.client.base_url:
            messagebox.showerror("Offline", "ComfyUI is not connected.\n"
                                 "Launch Comfy Desktop and click Reconnect.")
            return
        active = [p for p in self.prompts.personas.values()
                 if p.get("active", True) and p.get("name")]
        if needs_two_personas and len(active) < 2:
            messagebox.showerror("Not enough personas",
                                 "Need at least 2 active personas.")
            return
        if not needs_two_personas and not active:
            messagebox.showerror("No personas", "No personas in the list.")
            return
        if extra_guard:
            msg = extra_guard()
            if msg:
                messagebox.showinfo("Can't start", msg)
                return

        win, body = self._new_toplevel(title, 520, 340)
        tk.Label(body, text=title, bg=self.PANEL, fg=self.ACCENT,
                font=self.font_heading).pack(anchor="w", padx=12,
                                                    pady=(12, 2))
        tk.Label(body, text=description, bg=self.PANEL, fg=self.FG_MUTED,
                wraplength=480, justify="left").pack(anchor="w", padx=12,
                                                     pady=(0, 10))
        tk.Label(body, text="🎯 STOP CONDITION", bg=self.PANEL,
                fg=self.ACCENT, font=self.font_body_bold).pack(
            anchor="w", padx=12, pady=(4, 2))
        stop_var = tk.StringVar(value="count")
        crow = tk.Frame(body, bg=self.PANEL)
        crow.pack(fill="x", padx=12, pady=2)
        tk.Radiobutton(crow, text="Images:", variable=stop_var,
                      value="count", bg=self.PANEL, fg=self.FG,
                      selectcolor=self.INPUT_BG,
                      activebackground=self.PANEL).pack(side="left")
        count_var = tk.IntVar(value=10)
        ttk.Spinbox(crow, textvariable=count_var, from_=1, to=200,
                   width=6).pack(side="left", padx=6)
        mrow = tk.Frame(body, bg=self.PANEL)
        mrow.pack(fill="x", padx=12, pady=2)
        tk.Radiobutton(mrow, text="Minutes:", variable=stop_var,
                      value="minutes", bg=self.PANEL, fg=self.FG,
                      selectcolor=self.INPUT_BG,
                      activebackground=self.PANEL).pack(side="left")
        minutes_var = tk.IntVar(value=60)
        ttk.Spinbox(mrow, textvariable=minutes_var, from_=5, to=480,
                   width=6).pack(side="left", padx=6)
        tk.Radiobutton(body, text="Until Stop (runs forever)",
                      variable=stop_var, value="infinite", bg=self.PANEL,
                      fg=self.FG, selectcolor=self.INPUT_BG,
                      activebackground=self.PANEL).pack(anchor="w", padx=12)

        status = tk.Label(body, text="Ready", bg=self.PANEL,
                          fg=self.FG_MUTED, wraplength=480, justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def start():
            cfg = {
                "stop_mode": stop_var.get(),
                "target_count": int(count_var.get()),
                "target_minutes": int(minutes_var.get()),
            }
            go_btn.configure(state="disabled", text="Running...")
            self.stop_flag = False
            threading.Thread(
                target=worker_target,
                args=(active, cfg,
                     lambda t: self.root.after(
                         0, lambda: status.config(text=t))),
                daemon=True).start()

        go_btn = ttk.Button(body, text="▶ START", command=start)
        go_btn.pack(pady=8)
        self.log(f"Opened {title}")

    def _pilot_loop_worker(self, personas, cfg, set_status, *, pilot_name,
                          item_fn, needs_two_personas=False):
        """Shared loop shell for every simple standalone pilot: busy
        flag, stop-condition (count/minutes/infinite/stop_flag), persona
        queue shuffling/refill, logging, preview. `item_fn(persona,
        style, other_persona_or_None)` does the actual generation and
        returns a Path (or None on failure) - this shell doesn't know or
        care what kind of pipeline that is."""
        self.busy = True
        self.root.after(0, lambda: (
            self.stop_btn.configure(state="normal"),
            self.gen_btn.configure(state="disabled")))
        t0 = time.time()
        made = 0
        queue = list(personas)
        random.shuffle(queue)
        try:
            while True:
                if self.stop_flag:
                    self.log(f"{pilot_name}: stopped at {made} made")
                    break
                if cfg["stop_mode"] == "count" and made >= cfg["target_count"]:
                    break
                if cfg["stop_mode"] == "minutes" and \
                        (time.time() - t0) >= cfg["target_minutes"] * 60:
                    break
                if needs_two_personas:
                    if len(queue) < 2:
                        queue = list(personas)
                        random.shuffle(queue)
                    persona = queue.pop()
                    other = next((p for p in queue if p is not persona),
                                random.choice(personas))
                else:
                    if not queue:
                        queue = list(personas)
                        random.shuffle(queue)
                    persona = queue.pop() if queue else None
                    other = None
                name = persona.get("name", "unknown") if persona else "?"
                set_status(f"{pilot_name} {made + 1}"
                          f"{'/' + str(cfg['target_count']) if cfg['stop_mode'] == 'count' else ''}"
                          f": {name}")
                try:
                    style = self.taste.pick_style(
                        pilot_name.lower().replace(" ", "_"), ART_STYLES)
                    path = item_fn(persona, style, other)
                    if path is None:
                        self.log(f"{pilot_name}: '{name}' failed, continuing")
                        continue
                    made += 1
                    self.log(f"{pilot_name} [{made}]: '{name}' -> {path.name}")
                    self.show_preview(path)
                except Exception as e:
                    if self.stop_flag:
                        self.log(f"{pilot_name}: '{name}' aborted")
                        break
                    self.log(f"{pilot_name}: '{name}' failed: {e}")
                    continue
        finally:
            elapsed = time.time() - t0
            self.log(f"=== {pilot_name} DONE: {made} made in "
                     f"{elapsed / 60:.1f} min ===")
            set_status(f"{pilot_name} done: {made} made")
            self.busy = False
            self.root.after(0, lambda: (
                self.stop_btn.configure(state="disabled"),
                self.gen_btn.configure(state="normal")))

    # v9.9: the 9 standalone pilots below used to each be a separate
    # open_*_pilot method containing an item_fn closure + a worker
    # closure + an _open_pilot_dialog call - ~20 lines of near-identical
    # wrapper boilerplate per pilot, with the only genuinely distinct
    # part being item_fn's body. Collapsed into: one item_fn per pilot as
    # a real named method (below, unchanged logic), one PILOTS registry
    # holding title/description/guards, and one generic open_pilot(key)
    # launcher. Adding a future pilot is now a registry entry + one
    # method, not a full ~20-line wrapper copy.

    def _pilot_item_portrait(self, persona, style, other):
        choice = self.director.direct(persona)
        mode = choice["mode"]
        width, height = self._vram_preflight(
            choice["width"], choice["height"], 1)[:2]
        sampler, sched = auto_sampler(choice["style"])
        positive = self.wildcards.expand(
            self.prompts.build(mode, persona, choice["style"]))
        if choice.get("extra_tags"):
            positive += ", " + choice["extra_tags"]
        plan = {
            "ckpt": choice.get("model") or self.ckpt_var.get(),
            "positive": positive,
            "negative": self.neg_text.get("1.0", "end").strip(),
            "width": width, "height": height,
            "steps": int(self.steps_var.get()),
            "cfg": float(self.cfg_var.get()),
            "sampler": sampler, "sched": sched,
            "mode": mode, "style": choice["style"],
        }
        safe_name = re.sub(r"[^\w\-]+", "_", persona.get("name", ""))[:20]
        path, metrics, score = self._gen_candidate(
            plan, random.randint(0, 2**48), safe_name)
        return path

    def _pilot_item_invent(self, persona, style, other):
        blueprint, hero_p, out_dir = \
            self._run_character_blueprint_pipeline(
                "", lambda t: None, force_style=POSTER_STYLE,
                quality_boost=True)
        if not blueprint:
            return None
        cname = blueprint.get("name", "Unnamed")
        visual = blueprint.get("visual_details", "")
        if blueprint.get("hero_outfit"):
            visual = f"{visual}, {blueprint['hero_outfit']}"
        entry = {
            "name": cname, "visual_details": visual,
            "psychology": blueprint.get("psychology", ""),
            "backstory": blueprint.get("backstory", ""),
            "signature_quote": blueprint.get("signature_quote", ""),
            "signature_pose": blueprint.get("hero_pose_description", ""),
            "active": True,
        }
        key = re.sub(r"[^\w]+", "_", cname.lower()).strip("_")
        if key in self.prompts.personas:
            cname = f"{cname} (new)"
            entry["name"] = cname
        self.root.after(0, lambda n=cname, e=entry: self._save_persona(n, e))
        return hero_p

    def _pilot_item_fusion(self, persona, style, other):
        name = f"{persona.get('name', '?')} x {other.get('name', '?')}"
        safe_name = re.sub(r"[^\w\-]+", "_", name)[:20]
        sampler, sched = auto_sampler(style)
        positive = self.wildcards.expand(
            self.prompts.build("Fusion", persona, style, other=other))
        width, height = self._vram_preflight(832, 1216, 1)[:2]
        plan = {
            "ckpt": self.ckpt_var.get(), "positive": positive,
            "negative": self.neg_text.get("1.0", "end").strip(),
            "width": width, "height": height,
            "steps": int(self.steps_var.get()),
            "cfg": float(self.cfg_var.get()),
            "sampler": sampler, "sched": sched,
            "mode": "Fusion", "style": style,
        }
        path, metrics, score = self._gen_candidate(
            plan, random.randint(0, 2**48), safe_name)
        return path

    def _pilot_item_wallpaper(self, persona, style, other):
        positive = self.wildcards.expand(
            self.prompts.build("Scene", persona, style))
        orientation = random.choice(["landscape", "portrait"])
        tmp = self._hifi_master(
            positive, self.neg_text.get("1.0", "end").strip(),
            orientation, hifi=True, ckpt=self.ckpt_var.get(),
            log=self.log)
        safe_name = re.sub(r"[^\w\-]+", "_", persona.get("name", ""))[:20]
        dest = (self.output_dir / "wallpaper_pilot" /
               f"{datetime.now():%Y%m%d_%H%M%S}_{safe_name}.png")
        dest.parent.mkdir(parents=True, exist_ok=True)
        tmp.replace(dest)
        return dest

    def _pilot_item_cinematic(self, persona, style, other):
        active_snapshot = [p for p in self.prompts.personas.values()
                          if p.get("active", True) and p.get("name")]
        scene = random.choice(
            self.wildcards.categories.get("setting") or SETTINGS)
        mode_name = random.choice(list(CINEMATIC_MODES))
        aspect_name = random.choice(list(CINEMATIC_ASPECTS))
        scene_persona = (random.choice(active_snapshot)
                        if random.random() < 0.5 else None)
        path = self._run_cinematic_pipeline(
            scene, mode_name, style, scene_persona, aspect_name)
        if path is None:
            return None
        safe_name = re.sub(r"[^\w\-]+", "_", scene[:20])
        dest = (self.output_dir / "cinematic_pilot" /
               f"{datetime.now():%Y%m%d_%H%M%S}_{safe_name}.png")
        dest.parent.mkdir(parents=True, exist_ok=True)
        path.replace(dest)
        return dest

    def _pilot_item_fashion(self, persona, style, other):
        garment = persona.get("hero_outfit") or \
            random.choice(AP_GARMENT_POOL)
        mode_name = random.choice(["Concept Art", "Editorial Model Shoot"])
        style_name = random.choice(list(FASHION_STYLES))
        out_dir, preview_path = self._run_fashion_pipeline(
            garment, mode_name, style_name, 4)
        if preview_path is None:
            return None
        safe_name = re.sub(r"[^\w\-]+", "_", persona.get("name", ""))[:20]
        dest = (self.output_dir / "fashion_pilot" /
               f"{datetime.now():%Y%m%d_%H%M%S}_{safe_name}.png")
        dest.parent.mkdir(parents=True, exist_ok=True)
        preview_path.replace(dest)
        return dest

    def _pilot_item_storyboard(self, persona, style, other):
        return self._run_storyboard_pipeline(persona, style_override=style)

    def _pilot_item_coloring(self, persona, style, other):
        name = persona.get("name", "a character")
        trait = (persona.get("visual_details", "").split(",")[0].strip()
                 or "simple pose")
        subject = f"{name}, {trait}"[:80]
        complexity = random.choice(list(COLORING_MODES))
        psize_name = random.choice(list(COLORING_PAGE_SIZES))
        page = self._run_coloring_page_pipeline(
            subject, complexity, psize_name)
        if page is None:
            return None
        safe_name = re.sub(r"[^\w\-]+", "_", name)[:20]
        dest = (self.output_dir / "coloring_pilot" /
               f"{datetime.now():%Y%m%d_%H%M%S}_{safe_name}.png")
        dest.parent.mkdir(parents=True, exist_ok=True)
        page.save(dest, dpi=(300, 300))
        return dest

    def _pilot_item_lofi(self, persona, style, other):
        active_snapshot = [p for p in self.prompts.personas.values()
                          if p.get("active", True) and p.get("name")]
        # most cycles use one of the built-in diverse archetypes (covers
        # more character types than the persona library alone, which
        # skews toward one aesthetic); sometimes pull a real persona in
        # instead for variety tied to the roster
        p = (random.choice(active_snapshot)
            if (active_snapshot and random.random() < 0.3) else None)
        return self._run_lofi_loop_pipeline(p)

