    def _quote_pilot_worker(self, personas: list, cfg: dict, set_status):
        """Standalone unattended loop - not an Auto-Pilot cycle. Each
        iteration: pop a random persona, build a hi-fi wallpaper master
        (_hifi_master, same core Wallpaper Lab uses), get a quote for
        that persona, stamp it on via render_quote_wallpaper, export a
        wallpaper-size and a social-square version. No curation/scoring -
        every output is kept (this isn't a quality-gated pipeline, it's a
        content-production loop)."""
        self.busy = True
        self.root.after(0, lambda: (
            self.stop_btn.configure(state="normal"),
            self.gen_btn.configure(state="disabled")))
        t0 = time.time()
        out_dir = (self.output_dir / "quote_wallpapers" /
                  f"{datetime.now():%Y%m%d_%H%M}")
        out_dir.mkdir(parents=True, exist_ok=True)
        ckpt = self.ckpt_var.get()
        negative = self.neg_text.get("1.0", "end").strip()
        queue = list(personas)
        random.shuffle(queue)
        made = 0
        try:
            i = 0
            while True:
                if self.stop_flag:
                    self.log(f"Quote Pilot: stopped at {made} wallpaper(s)")
                    break
                if cfg["stop_mode"] == "count" and made >= cfg["target_count"]:
                    break
                if cfg["stop_mode"] == "minutes" and \
                        (time.time() - t0) >= cfg["target_minutes"] * 60:
                    break
                if not queue:
                    queue = list(personas)
                    random.shuffle(queue)
                persona = queue.pop()
                name = persona.get("name", "unknown")
                i += 1
                set_status(f"Quote Pilot {made + 1}"
                          f"{'/' + str(cfg['target_count']) if cfg['stop_mode'] == 'count' else ''}"
                          f": {name}")
                try:
                    style = self.taste.pick_style("quote_pilot", ART_STYLES)
                    positive = self.wildcards.expand(
                        self.prompts.build("Scene", persona, style))
                    orientation = random.choice(["landscape", "portrait"])
                    self.quotes.release_vram()
                    tmp = self._hifi_master(
                        positive, negative, orientation, hifi=True,
                        ckpt=ckpt, log=self.log)
                    if not self.quotes.backend:
                        self.quotes.detect()
                    quote_text, quote_src = (
                        self.quotes.generate(persona)
                        if self.quotes.backend else
                        (persona.get("signature_quote") or
                         f"{name}, in one's own words.", "fallback"))
                    from PIL import Image
                    with Image.open(tmp) as raw:
                        raw = raw.convert("RGB")
                        wall_w, wall_h = ((1920, 1080) if
                            orientation == "landscape" else (1080, 1920))
                        hero_stamped = render_quote_wallpaper(
                            raw, quote_text, name, wall_w, wall_h)
                        social_stamped = render_quote_wallpaper(
                            raw, quote_text, name, 1080, 1080)
                    tmp.unlink(missing_ok=True)
                    safe_name = re.sub(r"[^\w\-]+", "_", name)[:40]
                    hero_path = out_dir / f"{i:03d}_{safe_name}_wallpaper.png"
                    hero_stamped.save(hero_path)
                    social_path = out_dir / f"{i:03d}_{safe_name}_social.png"
                    social_stamped.save(social_path)
                    made += 1
                    self.log(f"Quote Pilot [{made}]: '{name}' ({quote_src}) "
                            f"-> {hero_path.name} + {social_path.name}")
                    self.show_preview(hero_path)
                except Exception as e:
                    if self.stop_flag:
                        self.log(f"Quote Pilot: '{name}' aborted")
                        break
                    self.log(f"Quote Pilot: '{name}' failed: {e}")
                    continue
        finally:
            elapsed = time.time() - t0
            self.log(f"=== Quote Pilot DONE: {made} wallpaper(s) in "
                     f"{elapsed / 60:.1f} min -> {out_dir} ===")
            set_status(f"Quote Pilot done: {made} wallpaper(s)")
            self.busy = False
            self.root.after(0, lambda: (
                self.stop_btn.configure(state="disabled"),
                self.gen_btn.configure(state="normal")))

    def _ensemble_worker(self, persona_a, persona_b, style, face_a, face_b,
                         set_status, done_cb):
        """Thin busy-flag-managing wrapper around _run_ensemble_pipeline,
        mirroring _character_designer_worker's shape."""
        self.busy = True
        try:
            image_path, meta = self._run_ensemble_pipeline(
                persona_a, persona_b, style, set_status,
                face_a=face_a, face_b=face_b)
            done_cb(image_path, meta)
        except Exception as e:
            self.log(f"Ensemble Cast Composer ERROR: {e}")
            set_status(f"Failed: {e}")
            done_cb(None, None)
        finally:
            self.busy = False

    def _run_ensemble_pipeline(self, persona_a, persona_b, style, set_status,
                               *, face_a=None, face_b=None):
        """Busy-flag-free core: two personas in one scene, each keeping
        their own true consistent face via a dual regional IP-Adapter +
        regional-conditioning graph (build_ensemble_workflow). Returns
        (image_path, metadata_dict) on success, (None, None) on failure."""
        t0 = time.time()
        try:
            if not face_a or not Path(face_a).exists():
                set_status("Missing face reference for Character A")
                self.log("Ensemble: no face reference for Character A - pick one")
                return None, None
            if not face_b or not Path(face_b).exists():
                set_status("Missing face reference for Character B")
                self.log("Ensemble: no face reference for Character B - pick one")
                return None, None

            name_a = persona_a.get("name", "Character A")
            name_b = persona_b.get("name", "Character B")
            self.log(f"Ensemble Cast Composer: '{name_a}' + '{name_b}'")

            ckpt = self.ckpt_var.get()
            width = int(self.width_var.get())
            height = int(self.height_var.get())
            steps = int(self.steps_var.get())
            cfg = float(self.cfg_var.get())
            sampler = self.sampler_var.get()
            scheduler = self.sched_var.get()
            seed = random.randint(0, 2**48)

            set_status("Uploading face references...")
            self.quotes.release_vram()
            face_ref_a = self._upload_ref(face_a)
            face_ref_b = self._upload_ref(face_b)

            positive_a = self.wildcards.expand(
                self.prompts.build("Exact", persona_a, style))
            positive_b = self.wildcards.expand(
                self.prompts.build("Exact", persona_b, style))
            negative = self.neg_text.get("1.0", "end").strip()

            set_status(f"Composing '{name_a}' + '{name_b}'...")
            wf = self.client.build_ensemble_workflow(
                ckpt=ckpt, positive_a=positive_a, positive_b=positive_b,
                negative=negative, width=width, height=height, steps=steps,
                cfg=cfg, sampler=sampler, scheduler=scheduler, seed=seed,
                face_ref_a=face_ref_a, face_ref_b=face_ref_b,
                ipadapter_file=self.ipadapter_file,
                clip_vision_file=self.clip_vision_file)
            entry = self._queue_and_wait(wf)
            outputs = entry.get("outputs", {}) if (entry and isinstance(entry, dict)) else {}
            images = [x for o in outputs.values() for x in o.get("images", [])]
            if not images:
                set_status("No image output found in result")
                self.log("Ensemble Cast Composer: no image output found in result")
                return None, None
            info = images[0]
            data = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))

            safe_a = re.sub(r"[^\w\-]+", "_", name_a)[:30]
            safe_b = re.sub(r"[^\w\-]+", "_", name_b)[:30]
            out_dir = (self.output_dir / "ensemble_casts" /
                      f"{datetime.now():%Y%m%d_%H%M}_{safe_a}_{safe_b}")
            out_dir.mkdir(parents=True, exist_ok=True)
            image_path = out_dir / "ensemble.png"
            image_path.write_bytes(data)

            meta = {
                "personas": [
                    {"name": name_a, "position": "left", "face_ref": str(face_a)},
                    {"name": name_b, "position": "right", "face_ref": str(face_b)},
                ],
                "layout": "side_by_side", "feather_pct": 0.12, "style": style,
                "model": ckpt, "steps": steps, "cfg": cfg, "sampler": sampler,
                "scheduler": scheduler, "seed": seed,
                "width": width, "height": height,
            }
            self.meta_manager.save_image_metadata(image_path, meta)
            elapsed = time.time() - t0
            self.log(f"Ensemble Cast Composer done ({elapsed:.0f}s) -> "
                     f"{image_path}")
            set_status(f"Done in {elapsed:.0f}s")
            self.show_preview(image_path)
            return image_path, meta
        except Exception as e:
            set_status(f"Failed: {e}")
            self.log(f"Ensemble Cast Composer ERROR: {e}")
            return None, None

    def open_ensemble_composer(self):
        """Put two of your own personas in ONE scene, each keeping their
        own true, consistent face - not a blended/averaged identity.
        Uses a dual regional IP-Adapter + regional-conditioning graph
        (build_ensemble_workflow) verified live against this exact
        ComfyUI install. v1: fixed left/right layout only, 2 characters."""
        win, body = self._new_toplevel("Ensemble Cast Composer", 620, 480)
        tk.Label(body, text="Ensemble Cast Composer", bg=self.PANEL,
                fg=self.ACCENT, font=self.font_heading).pack(
                anchor="w", padx=12, pady=(12, 2))
        tk.Label(body, text="Put two of your own characters in one scene, "
                "each keeping their real, consistent face - not a blended "
                "identity. v1 layout is a fixed left/right split.",
                bg=self.PANEL, fg=self.FG_MUTED, wraplength=580,
                justify="left").pack(anchor="w", padx=12, pady=(0, 10))

        names = sorted({p.get("name", "") for p in self.prompts.personas.values()
                        if p.get("active", True) and p.get("name")})

        state = {"face_a": None, "face_b": None}

        def persona_row(label_text, side):
            row = tk.Frame(body, bg=self.PANEL)
            row.pack(fill="x", padx=12, pady=4)
            tk.Label(row, text=label_text, bg=self.PANEL, fg=self.FG,
                    width=14, anchor="w").pack(side="left")
            var = tk.StringVar(value=names[0] if names else "")
            combo = ttk.Combobox(row, textvariable=var, values=names,
                                 state="readonly", width=28)
            combo.pack(side="left", padx=(0, 8))

            face_lbl = tk.Label(row, text="(none)", bg=self.PANEL,
                                fg=self.FG_MUTED, width=20, anchor="w")

            def auto_detect(*_):
                # v8.0: one-shot best-effort face-ref lookup (see
                # _find_persona_face_ref) - not a persistent index, just a
                # convenience prefill; always overridable/clearable.
                name = var.get()
                match = self._find_persona_face_ref(name)
                if match:
                    state[side] = match
                    face_lbl.config(text=match.name[:20] if match.stem != "hero"
                                    else match.parent.name[:20],
                                    fg=self.SUCCESS_TEXT)
                else:
                    state[side] = None
                    face_lbl.config(text="(none - pick manually)",
                                    fg=self.FG_MUTED)

            combo.bind("<<ComboboxSelected>>", auto_detect)
            auto_detect()

            def pick(side=side, face_lbl=face_lbl):
                path = filedialog.askopenfilename(
                    title=f"Choose a face reference for {label_text}",
                    initialdir=self.output_dir, filetypes=self.IMG_FILETYPES)
                if path:
                    state[side] = Path(path)
                    face_lbl.config(text=Path(path).name[:20],
                                    fg=self.SUCCESS_TEXT)

            def clear(side=side, face_lbl=face_lbl):
                state[side] = None
                face_lbl.config(text="(none)", fg=self.FG_MUTED)

            face_lbl.pack(side="left", padx=(0, 6))
            ttk.Button(row, text="Pick...", command=pick).pack(side="left", padx=2)
            ttk.Button(row, text="Clear", command=clear).pack(side="left", padx=2)
            return var

        var_a = persona_row("Character A", "face_a")
        var_b = persona_row("Character B", "face_b")

        layout_row = tk.Frame(body, bg=self.PANEL)
        layout_row.pack(fill="x", padx=12, pady=4)
        tk.Label(layout_row, text="Layout", bg=self.PANEL, fg=self.FG,
                width=14, anchor="w").pack(side="left")
        layout_var = tk.StringVar(value="Side by Side (v1)")
        ttk.Combobox(layout_row, textvariable=layout_var,
                    values=["Side by Side (v1)"], state="readonly",
                    width=28).pack(side="left")

        style_row = tk.Frame(body, bg=self.PANEL)
        style_row.pack(fill="x", padx=12, pady=4)
        tk.Label(style_row, text="Style", bg=self.PANEL, fg=self.FG,
                width=14, anchor="w").pack(side="left")
        style_var = tk.StringVar(value=self.style_var.get() or ART_STYLES[0])
        ttk.Combobox(style_row, textvariable=style_var, values=ART_STYLES,
                    state="readonly", width=45).pack(side="left")

        status = tk.Label(body, text="Ready", bg=self.PANEL,
                          fg=self.FG_MUTED, wraplength=580, justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def start():
            if self.busy:
                messagebox.showinfo("Busy", "A generation is already "
                                    "running.", parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI is not connected.",
                                     parent=win)
                return
            if not self.caps.get("ipadapter"):
                messagebox.showinfo("Face lock unavailable",
                                    "Ensemble Cast Composer needs IP-Adapter "
                                    "(Face lock ready). Check the connection "
                                    "log for why it's not ready.", parent=win)
                return
            if self._is_sd15(self.ckpt_var.get()):
                messagebox.showinfo("Needs SDXL", "Ensemble Cast Composer "
                                    "needs an SDXL checkpoint selected in "
                                    "Model (the current one is SD1.5).",
                                    parent=win)
                return
            if self._is_turbo_distilled(self.ckpt_var.get()):
                messagebox.showinfo("Needs a standard SDXL checkpoint",
                                    "A Turbo/Lightning/LCM checkpoint needs "
                                    "very different settings than this "
                                    "window's Steps/CFG - pick a standard "
                                    "SDXL checkpoint in Model.", parent=win)
                return
            name_a, name_b = var_a.get(), var_b.get()
            if not name_a or not name_b or name_a == name_b:
                messagebox.showinfo("Pick two different characters",
                                    "Choose two distinct personas for "
                                    "Character A and Character B.", parent=win)
                return
            persona_a = self.prompts.by_name(name_a)
            persona_b = self.prompts.by_name(name_b)
            go_btn.configure(state="disabled", text="Composing...")

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def done(image_path=None, meta=None):
                def _finish():
                    go_btn.configure(state="normal", text="✨ GENERATE ENSEMBLE")
                self.root.after(0, _finish)
            self.stop_flag = False
            threading.Thread(
                target=self._ensemble_worker,
                args=(persona_a, persona_b, style_var.get(),
                     state["face_a"], state["face_b"], setv, done),
                daemon=True).start()

        go_btn = ttk.Button(body, text="✨ GENERATE ENSEMBLE", command=start)
        go_btn.pack(pady=8)
        self.log("Opened Ensemble Cast Composer")

    # ── v5.2: Qwen-Image Studio (split-file DiT checkpoints) ────────────────
    def _qwen_image_files(self):
        """Best-guess match of installed Qwen-Image family files. Returns
        (unet, clip, vae) names or (None, None, None) if not found - this
        architecture uses UNETLoader/CLIPLoader/VAELoader instead of
        CheckpointLoaderSimple, so it can't appear in the normal checkpoint
        dropdown."""
        unets = self.client.get_diffusion_models()
        clips = self.client.get_text_encoders()
        vaes = self.client.get_vae_files()
        unet = next((u for u in unets if "oneObsessionAnima" in u), None)
        clip = next((c for c in clips
                     if "oneObsessionAnima" in c and "_txt" in c), None)
        vae = next((v for v in vaes if "qwen_image_vae" in v), None)
        return unet, clip, vae

    def _wan_video_files(self):
        """Best-guess match of installed Wan 2.1 T2V files. Returns
        (model, t5, vae) names or (None, None, None) if not found. The T5
        encoder must NOT be a "scaled" fp8 variant - WanVideoWrapper's
        loader rejects those explicitly (confirmed live this session)."""
        models = self.client.get_diffusion_models()
        t5s = self.client.get_text_encoders()
        vaes = self.client.get_vae_files()
        model = next((m for m in models if "wan2.1_t2v" in m.lower()), None)
        t5 = next((t for t in t5s if "umt5" in t.lower()
                   and "scaled" not in t.lower()), None)
        vae = next((v for v in vaes if "wan_2.1_vae" in v.lower()
                    or "wan2.1_vae" in v.lower()), None)
        return model, t5, vae

    def _wan_i2v_model(self):
        """v9.11: separate from _wan_video_files - confirmed live this
        session that the installed wan2.1_t2v_1.3B checkpoint is
        text-to-video ONLY (WanVideoSampler explicitly rejects encoded
        image conditioning against it: "T2V model detected, encoded
        images only work with I2V models"). Real local I2V needs a
        genuinely different checkpoint file (Wan 2.1's I2V release is
        only shipped at 14B by Alibaba - not installed here, and likely
        too large for 6GB VRAM regardless). Returns the model filename
        if one is ever installed, else None - the Image-to-Video option
        in the dialog is disabled with an honest explanation until then,
        rather than letting a user hit this exact cryptic sampler error."""
        models = self.client.get_diffusion_models()
        return next((m for m in models if "i2v" in m.lower()
                    and "wan" in m.lower()), None)

    def _download_upscale_model(self, parent_win=None):
        """v9.11: one-click download of a small real upscale model
        (UPSCALE_MODEL_DOWNLOAD) so Maximum Mode's tiled-upscale stage
        actually has something to load - models/upscale_models/ is
        empty by default. Much smaller than the Wan I2V/Krea downloads
        (~67MB), so a single confirm + simple progress dialog is enough,
        no multi-file complexity needed."""
        parent_win = parent_win or self.root
        opt = UPSCALE_MODEL_DOWNLOAD
        if self.busy:
            messagebox.showinfo("Busy", "Finish or stop the current "
                                "generation first.", parent=parent_win)
            return
        dest = Path(SHARED_MODELS_DIR) / "upscale_models" / opt["filename"]
        if not messagebox.askyesno(
            "Download Upscale Model",
            f"Download {opt['filename']}?\n\n"
            f"Size: ~{opt['size_mb']:.1f} MB\n"
            f"Destination: {dest}\n\n"
            "Enables Maximum Mode's tiled-upscale stage. Continue?",
            parent=parent_win):
            return

        win, body = self._new_toplevel("Downloading Upscale Model", 420, 130,
                                       scrollable=False)
        lbl = ttk.Label(body, text="Starting download...", font=self.font_body)
        lbl.pack(pady=(16, 8), padx=16)
        pbar = ttk.Progressbar(body, mode="determinate", maximum=100)
        pbar.pack(fill="x", padx=16, pady=8)

        def _progress(done, total):
            pct = int(done * 100 / total) if total else 0
            mb_done = done / 1e6
            self.root.after(0, lambda: (
                pbar.configure(value=pct),
                lbl.configure(text=f"Downloading... {mb_done:.1f} MB")))

        def _worker():
            ok = _download_with_progress(opt["url"], dest,
                                         on_progress=_progress, timeout=60.0)
            def _finish():
                win.destroy()
                if ok:
                    messagebox.showinfo(
                        "Download Complete",
                        f"{opt['filename']} downloaded. Restart ComfyUI "
                        "so it picks up the new file - Maximum Mode's "
                        "tiled upscale stage will then run automatically.",
                        parent=self.root)
                    self.log(f"Upscale model downloaded: {opt['filename']}")
                else:
                    messagebox.showerror(
                        "Download Failed",
                        f"Could not download {opt['filename']}. "
                        "Check your connection and disk space.",
                        parent=self.root)
                    self.log(f"Upscale model download failed: {opt['filename']}")
            self.root.after(0, _finish)

        threading.Thread(target=_worker, daemon=True).start()

    def _download_wan_i2v_model(self, parent_win, key: str):
        """v9.11: reuses _download_with_progress (built for the v9.10
        self-update feature) to fetch a real Wan I2V checkpoint from
        Kijai/WanVideo_comfy - a big, opt-in, explicitly-confirmed
        download for machines with more VRAM than this dev machine's
        6GB card, not something that ever runs silently."""
        opt = WAN_I2V_DOWNLOAD_OPTIONS[key]
        if self.busy:
            messagebox.showinfo("Busy", "Finish or stop the current "
                                "generation first.", parent=parent_win)
            return
        dest = Path(SHARED_MODELS_DIR) / "diffusion_models" / opt["filename"]
        if not messagebox.askyesno(
            "Download Wan I2V Model",
            f"Download {opt['filename']}?\n\n"
            f"Size: ~{opt['size_gb']:.1f} GB\n"
            f"Destination: {dest}\n\n"
            "This is a large download and needs significantly more "
            "VRAM than this app's other Wan features to actually run "
            "(see the label for the recommended minimum). It will not "
            "be usable on a 6-8GB card. Continue?",
            parent=parent_win):
            return

        win, body = self._new_toplevel("Downloading Wan I2V Model", 460, 150,
                                       scrollable=False)
        lbl = ttk.Label(body, text="Starting download...", font=self.font_body)
        lbl.pack(pady=(16, 8), padx=16)
        pbar = ttk.Progressbar(body, mode="determinate", maximum=100)
        pbar.pack(fill="x", padx=16, pady=8)

        def _progress(done, total):
            pct = int(done * 100 / total) if total else 0
            gb_done = done / 1e9
            self.root.after(0, lambda: (
                pbar.configure(value=pct),
                lbl.configure(text=f"Downloading... {gb_done:.2f} / "
                             f"{opt['size_gb']:.1f} GB")))

        def _worker():
            ok = _download_with_progress(opt["url"], dest,
                                         on_progress=_progress, timeout=60.0)
            def _finish():
                win.destroy()
                if ok:
                    messagebox.showinfo(
                        "Download Complete",
                        f"{opt['filename']} downloaded.\n\n"
                        "Restart ComfyUI so it picks up the new file, "
                        "then reopen Wan Video Studio - Image-to-Video "
                        "will be selectable once ComfyUI reports it.",
                        parent=self.root)
                    self.log(f"Wan I2V model downloaded: {opt['filename']}")
                else:
                    messagebox.showerror(
                        "Download Failed",
                        f"Could not download {opt['filename']}. "
                        "Check your connection and disk space.",
                        parent=self.root)
                    self.log(f"Wan I2V model download failed: {opt['filename']}")
            self.root.after(0, _finish)

        threading.Thread(target=_worker, daemon=True).start()

    def _krea_files(self):
        """v9.11: returns (unet, clip_l, t5, vae) filenames if a Krea GGUF
        checkpoint + all 3 shared FLUX support files are present, else
        (None, None, None, None). Live query, same convention as
        _wan_video_files."""
        models = self.client.get_diffusion_models()
        unet = next((m for m in models if "krea" in m.lower()
                    and m.lower().endswith(".gguf")), None)
        t5s = self.client.get_text_encoders()
        clip_l = next((t for t in t5s if t == KREA_SHARED_FILES["clip_l"]["filename"]), None)
        t5 = next((t for t in t5s if t == KREA_SHARED_FILES["t5xxl"]["filename"]), None)
        vaes = self.client.get_vae_files()
        vae = next((v for v in vaes if v == KREA_SHARED_FILES["vae"]["filename"]), None)
        if unet and clip_l and t5 and vae:
            return unet, clip_l, t5, vae
        return None, None, None, None

    def _download_krea_files(self, parent_win, quant_key: str):
        """v9.11: sequential multi-file download (Krea GGUF diffusion
        model + the 3 shared FLUX support files, each possibly already
        present from a prior download or another FLUX feature), single
        combined progress dialog. Reuses _download_with_progress per
        file, same as every other download in this app - never a
        silent/automatic download, one explicit confirm naming every
        file, every size, and the combined total up front."""
        opt = KREA_DOWNLOAD_OPTIONS[quant_key]
        if self.busy:
            messagebox.showinfo("Busy", "Finish or stop the current "
                                "generation first.", parent=parent_win)
            return
        files = [opt] + list(KREA_SHARED_FILES.values())
        total_gb = sum(f["size_gb"] for f in files)
        listing = "\n".join(f"  - {f['filename']} (~{f['size_gb']:.2f} GB)"
                            for f in files)
        if not messagebox.askyesno(
            "Download Krea (FLUX) Model Set",
            f"Download {len(files)} files, ~{total_gb:.1f} GB total?\n\n"
            f"{listing}\n\n"
            "This needs a real ComfyUI-GGUF custom node pack "
            "(city96/ComfyUI-GGUF) for UnetLoaderGGUF, not verified on "
            "this server - install it if generation later fails to "
            "find that node.\n\n"
            "This is a large download and needs significantly more "
            "VRAM than this card has (see the label for the "
            "recommended minimum). Continue?",
            parent=parent_win):
            return

        win, body = self._new_toplevel("Downloading Krea Model Set", 460, 150,
                                       scrollable=False)
        lbl = ttk.Label(body, text="Starting download...", font=self.font_body)
        lbl.pack(pady=(16, 8), padx=16)
        pbar = ttk.Progressbar(body, mode="determinate", maximum=100)
        pbar.pack(fill="x", padx=16, pady=8)

        def _worker():
            for i, f in enumerate(files, 1):
                dest = Path(SHARED_MODELS_DIR) / f["subfolder"] / f["filename"]
                if dest.exists():
                    self.root.after(0, lambda f=f, i=i: lbl.configure(
                        text=f"({i}/{len(files)}) {f['filename']} already present"))
                    continue

                def _progress(done, total, f=f, i=i):
                    pct = int(done * 100 / total) if total else 0
                    gb_done = done / 1e9
                    self.root.after(0, lambda: (
                        pbar.configure(value=pct),
                        lbl.configure(
                            text=f"({i}/{len(files)}) {f['filename']}: "
                                 f"{gb_done:.2f} / {f['size_gb']:.1f} GB")))

                ok = _download_with_progress(f["url"], dest,
                                             on_progress=_progress,
                                             timeout=60.0)
                if not ok:
                    def _fail(f=f):
                        win.destroy()
                        messagebox.showerror(
                            "Download Failed",
                            f"Could not download {f['filename']}. "
                            "Check your connection and disk space.",
                            parent=self.root)
                    self.root.after(0, _fail)
                    self.log(f"Krea model set download failed: {f['filename']}")
                    return

            def _done():
                win.destroy()
                messagebox.showinfo(
                    "Download Complete",
                    "All Krea model files downloaded.\n\n"
                    "Restart ComfyUI so it picks up the new files "
                    "(and install city96/ComfyUI-GGUF if not already "
                    "present), then reopen Krea Studio.",
                    parent=self.root)
                self.log("Krea model set downloaded")
            self.root.after(0, _done)

        threading.Thread(target=_worker, daemon=True).start()

    def open_krea_studio(self):
        """v9.11: standalone Krea (FLUX-Krea-dev) window, mirroring
        open_qwen_studio's "different architecture, separate window"
        precedent - shows the download picker when no Krea checkpoint
        is present, generate controls once one is. Not usable on this
        6GB dev machine by design (see KREA_DOWNLOAD_OPTIONS) - built
        for machines with more VRAM."""
        unet, clip_l, t5, vae = self._krea_files()
        win, body = self._new_toplevel("Krea Studio (FLUX, experimental)",
                                       600, 560)

        if not unet:
            tk.Label(body, text="No Krea checkpoint installed.", bg=self.PANEL,
                     fg=self.WARN_TEXT, font=self.font_body_bold).pack(
                anchor="w", padx=12, pady=(16, 4))
            tk.Label(body, text="Krea (FLUX-Krea-dev) is a large model - "
                    "even the smallest quantization here needs "
                    "significantly more VRAM than this 6GB dev machine "
                    "has. Pick a quantization below for a more capable "
                    "machine.", bg=self.PANEL, fg=self.FG_MUTED,
                    wraplength=540, justify="left").pack(
                anchor="w", padx=12, pady=(0, 10))
            dl_var = tk.StringVar(
                value=next(iter(KREA_DOWNLOAD_OPTIONS.values()))["label"])
            ttk.Combobox(body, textvariable=dl_var, state="readonly",
                        values=[o["label"] for o in
                               KREA_DOWNLOAD_OPTIONS.values()],
                        width=56).pack(anchor="w", padx=12)
            label_to_key = {o["label"]: k for k, o in
                            KREA_DOWNLOAD_OPTIONS.items()}

            def do_download():
                key = label_to_key.get(dl_var.get())
                if key:
                    self._download_krea_files(win, key)
            ttk.Button(body, text="📥 Download",
                      command=do_download).pack(anchor="w", padx=12, pady=8)
            self.log("Krea Studio: no checkpoint installed")
            return

        tk.Label(body, text=f"Model: {unet}", bg=self.PANEL,
                 fg=self.FG_MUTED, font=self.font_small).pack(
            anchor="w", padx=12, pady=(10, 0))

        def frow(label):
            rr = tk.Frame(body, bg=self.PANEL)
            rr.pack(fill="x", padx=12, pady=3)
            tk.Label(rr, text=label, bg=self.PANEL, fg=self.FG,
                     width=10, anchor="w").pack(side="left")
            return rr

        tk.Label(body, text="Prompt:", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_body_bold).pack(anchor="w", padx=12,
                                                    pady=(10, 2))
        pos_text = tk.Text(body, height=3, bg=self.INPUT_BG, fg=self.FG,
                           wrap="word", insertbackground=self.FG,
                           borderwidth=0)
        pos_text.pack(fill="x", padx=12)
        pos_text.insert("1.0", "a girl standing in a sunlit garden, "
                        "detailed illustration")

        tk.Label(body, text="Negative:", bg=self.PANEL, fg=self.FG_MUTED,
                 font=self.font_small).pack(anchor="w", padx=12, pady=(6, 0))
        neg_text = tk.Text(body, height=2, bg=self.INPUT_BG, fg=self.FG,
                           wrap="word", insertbackground=self.FG,
                           borderwidth=0)
        neg_text.pack(fill="x", padx=12)
        neg_text.insert("1.0", "blurry, low quality, distorted, watermark")

        rr = frow("Size")
        size_var = tk.StringVar(value="1024x1024")
        ttk.Combobox(rr, textvariable=size_var, state="readonly",
                     values=["1024x1024", "832x1216", "1216x832"],
                     width=14).pack(side="left")

        rr = frow("Steps")
        steps_var = tk.IntVar(value=20)
        ttk.Spinbox(rr, textvariable=steps_var, from_=4, to=50,
                    width=6).pack(side="left")
        tk.Label(rr, text="Guidance", bg=self.PANEL, fg=self.FG).pack(
            side="left", padx=(16, 4))
        guidance_var = tk.DoubleVar(value=3.5)
        ttk.Spinbox(rr, textvariable=guidance_var, from_=1.0, to=10.0,
                    increment=0.5, width=6).pack(side="left")

        status = tk.Label(body, text="Experimental: first run validates the "
                          "node graph against this server (UnetLoaderGGUF/"
                          "DualCLIPLoader/FluxGuidance not yet confirmed "
                          "live here).", bg=self.PANEL, fg=self.FG_MUTED,
                          wraplength=540, justify="left")
        status.pack(anchor="w", padx=12, pady=8)

        def start():
            positive = pos_text.get("1.0", "end").strip()
            if not positive:
                messagebox.showinfo("No prompt", "Enter a prompt first.",
                                    parent=win)
                return
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI not connected.",
                                     parent=win)
                return
            negative = neg_text.get("1.0", "end").strip()
            w, h = (int(x) for x in size_var.get().split("x"))
            go_btn.configure(state="disabled", text="Generating...")

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def done():
                self.root.after(0, lambda: go_btn.configure(
                    state="normal", text="🎨 GENERATE"))
            self.stop_flag = False
            threading.Thread(
                target=self._krea_worker,
                args=(unet, clip_l, t5, vae, positive, negative, w, h,
                      int(steps_var.get()), float(guidance_var.get()),
                      setv, done),
                daemon=True).start()

        go_btn = ttk.Button(body, text="🎨 GENERATE", command=start)
        go_btn.pack(pady=8)
        self.log("Opened Krea Studio")

    def _krea_worker(self, unet, clip_l, t5, vae, positive, negative,
                     width, height, steps, guidance, set_status, done_cb):
        self.busy = True
        t0 = time.time()
        try:
            seed = random.randint(0, 2**48)
            set_status("Building workflow...")
            self.quotes.release_vram()
            wf = self.client.build_krea_workflow(
                unet_name=unet, clip_l_name=clip_l, t5_name=t5,
                vae_name=vae, positive=positive, negative=negative,
                width=width, height=height, steps=steps, seed=seed,
                guidance=guidance)
            set_status("Rendering (Krea, slow on any card without "
                       "significant VRAM)...")
            entry = self._queue_and_wait(wf, on_tick=lambda: set_status(
                f"Rendering... ({time.time()-t0:.0f}s)"))
            outputs = entry.get("outputs", {}) if (entry and isinstance(entry, dict)) else {}
            images = [x for o in outputs.values() for x in o.get("images", [])]
            if not images:
                self.log("Krea Studio: No image output found in result")
                set_status("Failed: no output")
                return
            info = images[0]
            raw = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))
            out_dir = self.output_dir / "krea_studio"
            out_dir.mkdir(parents=True, exist_ok=True)
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            out_path = out_dir / f"{stamp}_krea.png"
            out_path.write_bytes(raw)
            meta = {"prompt": positive, "negative": negative, "seed": seed,
                    "width": width, "height": height, "steps": steps,
                    "guidance": guidance, "unet": unet,
                    "architecture": "krea_flux"}
            safe_json_save(out_path.with_suffix(".json"), meta)
            self.show_preview(out_path)
            elapsed = time.time() - t0
            set_status(f"DONE ({elapsed:.0f}s) -> {out_path.name}")
            self.log(f"Krea Studio: {out_path.name} ({elapsed:.0f}s)")
        except Exception as e:
            self.log(f"Krea Studio ERROR: {e}")
            set_status(f"Failed: {e}")
        finally:
            self.busy = False
            done_cb()

