        rr = frow("CFG")
        cfg_var = tk.DoubleVar(value=6.0)
        ttk.Spinbox(rr, textvariable=cfg_var, from_=1.0, to=15.0,
                    increment=0.5, width=6).pack(side="left")

        # v9.11: seed + sampler/scheduler - previously missing entirely,
