            w, h = (int(x) for x in size_var.get().split("x"))
            seed_txt = seed_var.get().strip()
            seed = (random.randint(0, 2**48) if seed_txt.lower() == "random"
                    else int(seed_txt) if seed_txt.isdigit()
                    else random.randint(0, 2**48))
