    def _storybook_worker(self, hero, theme, n_pages, style, size_name,
                          face_lock, coloring_ed, set_status, done_cb):
        self.busy = True
        t0 = time.time()
        try:
            from PIL import Image, ImageOps
            import io
            page_size = STORYBOOK_SIZES[size_name]
            ckpt = self.ckpt_var.get()

            # ── Phase 1: GLM writes the story (top-up until quota) ──
            set_status("GLM is writing the story...")
            pages_plan, title, attempts = [], "", 0
            while len(pages_plan) < n_pages and attempts < 3:
                want = n_pages - len(pages_plan)
                cont = ""
                if pages_plan:
                    last = str(pages_plan[-1].get("text", ""))[:120]
                    cont = (f" Continue the story after this moment: "
                            f"'{last}'. Write the NEXT {want} pages only.")
                data = self.quotes.complete_json(
                    f"Write a children's picture book. Hero: {hero}. "
                    f"Theme: {theme}.{cont} Reply ONLY JSON: "
                    '{"title": "book title max 6 words", "pages": '
                    '[{"text": "1-3 short sentences of story text", '
                    '"scene": "visual description of the illustration, '
                    f'max 15 words"}}]}} with exactly {want} page objects.',
                    temperature=0.9, max_tokens=220 * want + 400) or {}
                data = {k.lower(): v for k, v in data.items()}
                batch = [p for p in data.get("pages", [])
                         if isinstance(p, dict)]
                if not title:
                    title = str(data.get("title", "")).strip()
                pages_plan.extend(batch)
                attempts += 1
                if len(pages_plan) < n_pages:
                    set_status(f"Story: {len(pages_plan)}/{n_pages} pages, "
                               "GLM continuing...")
            pages_plan = pages_plan[:n_pages]
            title = title or "A Little Story"
            if not pages_plan:
                set_status("GLM returned no story - try again")
                return
            self.log(f"Storybook: '{title}' - {len(pages_plan)} pages")
            self.quotes.release_vram()

            safe_title = re.sub(r"[^\w\-]+", "_", title)[:40]
            out_dir = self.output_dir / "storybooks" / \
                f"{datetime.now():%Y%m%d_%H%M}_{safe_title}"
            out_dir.mkdir(parents=True, exist_ok=True)
            (out_dir / "story.json").write_text(
                json.dumps({"title": title, "hero": hero, "theme": theme,
                            "pages": pages_plan}, indent=1,
                           ensure_ascii=False), encoding="utf-8")

            # ── Phase 2: hero portrait (becomes the face reference) ──
            set_status("Drawing the hero...")
            neg = DEFAULT_NEGATIVE + ", text, watermark, signature"
            wf = self.client.build_txt2img_workflow(
                ckpt=ckpt,
                positive=f"{QUALITY}, {hero}, character portrait, "
                         f"centered, simple background, {style}",
                negative=neg, width=1024, height=1024, batch_size=1,
                steps=int(self.steps_var.get()),
                cfg=float(self.cfg_var.get()),
                sampler=self.sampler_var.get(),
                scheduler=self.sched_var.get(),
                seed=random.randint(0, 2**48))
            entry = self._queue_and_wait(wf)
            info = next(x for o in entry["outputs"].values()
                        for x in o.get("images", []))
            hero_raw = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))
            hero_p = out_dir / "hero.png"
            hero_p.write_bytes(hero_raw)

            face_kwargs = {}
            if face_lock and self.caps.get("ipadapter") and \
                    self.ipadapter_file and self.clip_vision_file:
                try:
                    face_kwargs = {
                        "face_ref": self._upload_ref(hero_p),
                        "face_weight": 0.55,
                        "ipadapter_file": self.ipadapter_file,
                        "clip_vision_file": self.clip_vision_file,
                    }
                    self.log("Storybook: hero face locked for all pages")
                except Exception as e:
                    self.log(f"Face lock skipped: {e}")

            # ── Phase 3: draw + compose each page ──
            w, h = (1024, 1024) if page_size[0] == page_size[1] \
                else (832, 1216)
            color_pages, art_paths = [], []
            for i, p in enumerate(pages_plan, 1):
                if self.stop_flag:
                    set_status(f"Stopped at page {i}")
                    break
                scene = str(p.get("scene", ""))[:180]
                text = str(p.get("text", "")).strip()
                set_status(f"Page {i}/{len(pages_plan)}: {scene[:50]}")
                try:
                    wf = self.client.build_txt2img_workflow(
                        ckpt=ckpt,
                        positive=f"{QUALITY}, {hero}, {scene}, "
                                 f"storybook illustration, {style}",
                        negative=neg, width=w, height=h, batch_size=1,
                        steps=int(self.steps_var.get()),
                        cfg=float(self.cfg_var.get()),
                        sampler=self.sampler_var.get(),
                        scheduler=self.sched_var.get(),
                        seed=random.randint(0, 2**48), **face_kwargs)
                    entry = self._queue_and_wait(wf)
                    info = next(x for o in entry["outputs"].values()
                                for x in o.get("images", []))
                    raw = self.client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    art_p = out_dir / f"art_{i:02d}.png"
                    art_p.write_bytes(raw)
                    art_paths.append(art_p)
                    page = render_story_page(
                        Image.open(art_p), text, page_size, i)
                    page.save(out_dir / f"page_{i:02d}.png", dpi=(300, 300))
                    color_pages.append(page)
                    self.log(f"Storybook page {i} done")
                except Exception as e:
                    self.log(f"Storybook page {i} failed: {e}")

            if not color_pages:
                set_status("No pages produced")
                return

            # ── Phase 4: cover + PDFs ──
            set_status("Assembling the book...")
            cover = render_story_cover(title, "", Image.open(hero_p),
                                       page_size)
            cover.save(out_dir / "cover.png", dpi=(300, 300))
            pdf = out_dir / f"{safe_title}.pdf"
            cover.save(pdf, save_all=True, append_images=color_pages,
                       resolution=300)

            if coloring_ed and not self.stop_flag:
                set_status("Tracing the coloring edition...")
                letter = COLORING_PAGE_SIZES["US Letter 8.5x11 (2550x3300)"]
                c_pages = []
                for i, art_p in enumerate(art_paths, 1):
                    try:
                        name = self._upload_ref(art_p)
                        wfc = self.client.build_canny_workflow(
                            name, 0.30, 0.70)
                        entry = self._queue_and_wait(wfc)
                        info = next(x for o in entry["outputs"].values()
                                    for x in o.get("images", []))
                        edge_raw = self.client.download_image(
                            info["filename"], info.get("subfolder", ""),
                            info.get("type", "output"))
                        edges = Image.open(io.BytesIO(edge_raw))
                        art = to_coloring_page(ImageOps.invert(
                            edges.convert("L")).convert("RGB"), thicken=2)
                        c_pages.append(make_coloring_canvas(art, letter))
                    except Exception as e:
                        self.log(f"Coloring page {i} failed: {e}")
                if c_pages:
                    c_cover = render_book_cover(
                        title + " - Coloring Book", theme.title(), letter,
                        art_bw=c_pages[0])
                    c_pdf = out_dir / f"{safe_title}_coloring.pdf"
                    c_cover.save(c_pdf, save_all=True,
                                 append_images=c_pages, resolution=300)
                    self.log(f"Coloring edition: {c_pdf.name}")

            self.show_preview(out_dir / "page_01.png")
            mins = (time.time() - t0) / 60
            set_status(f"DONE - '{title}': {len(color_pages)} pages"
                       + (" + coloring edition" if coloring_ed else "")
                       + f" in {mins:.1f} min\n{out_dir}")
            self.log(f"Storybook complete: {pdf}")
        except Exception as e:
            self.log(f"Storybook ERROR: {e}")
            set_status(f"Failed: {e}")
        finally:
            self.busy = False
            done_cb()

    # ── v4.2: Coloring Book Creator ────────────────────────────────────────
    def open_coloring_book(self):
        """Themed coloring books: GLM plans the pages, SDXL draws clean
        line art, output is per-page PNGs + one print-ready PDF."""
        win = tk.Toplevel(self.root)
        win.title("Coloring Book Creator")
        self._clamp_window(win, 560, 600)
        win.configure(bg=self.PANEL)

        def crow(label):
            rr = tk.Frame(win, bg=self.PANEL)
            rr.pack(fill="x", padx=12, pady=3)
            tk.Label(rr, text=label, bg=self.PANEL, fg=self.FG,
                     width=10, anchor="w").pack(side="left")
            return rr

        rr = crow("Title")
        title_var = tk.StringVar(value="My Coloring Book")
        ttk.Entry(rr, textvariable=title_var, width=34).pack(side="left")

        rr = crow("Theme")
        theme_var = tk.StringVar(value="magical forest animals")
        ttk.Entry(rr, textvariable=theme_var, width=34).pack(side="left")

        rr = crow("Pages")
        pages_var = tk.IntVar(value=8)
        ttk.Spinbox(rr, textvariable=pages_var, from_=3, to=30,
                    width=4).pack(side="left")
        complexity_var = tk.StringVar(value=list(COLORING_MODES)[0])
        ttk.Combobox(rr, textvariable=complexity_var, state="readonly",
                     values=list(COLORING_MODES),
                     width=24).pack(side="left", padx=6)

        rr = crow("Page size")
        psize_var = tk.StringVar(value=list(COLORING_PAGE_SIZES)[0])
        ttk.Combobox(rr, textvariable=psize_var, state="readonly",
                     values=list(COLORING_PAGE_SIZES),
                     width=28).pack(side="left")

        tk.Label(win, text="PAGE SUBJECTS (one per line - use 🎲 GLM Plan "
                 "or write your own):", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_body_bold).pack(anchor="w", padx=12,
                                                    pady=(8, 2))
        subjects_text = tk.Text(win, height=9, bg=self.INPUT_BG, fg=self.FG,
                                wrap="word", insertbackground=self.FG,
                                borderwidth=0)
        subjects_text.pack(fill="both", expand=True, padx=12)

        def glm_plan():
            if self.quotes.backend is None and not self.quotes.detect():
                messagebox.showinfo("No local LLM", "Start Ollama first.",
                                    parent=win)
                return
            plan_btn.configure(text="Planning...", state="disabled")
            theme, n = theme_var.get().strip(), int(pages_var.get())

            def _w():
                try:
                    data = self.quotes.complete_json(
                        f"Plan {n} coloring book pages for the theme "
                        f"'{theme}'. Each page is one drawable subject, "
                        "described in a short visual phrase (max 10 words, "
                        'no colors). Reply ONLY JSON: {"pages": '
                        f'["subject", ...]}} with exactly {n} entries.',
                        temperature=0.9, max_tokens=90 * n + 200) or {}
                    data = {k.lower(): v for k, v in data.items()}
                    pages = [str(p).strip() for p in data.get("pages", [])
                             if str(p).strip()][:n]
                    if pages:
                        self.root.after(0, lambda: (
                            subjects_text.delete("1.0", "end"),
                            subjects_text.insert("1.0", "\n".join(pages))))
                    self.quotes.release_vram()
                finally:
                    self.root.after(0, lambda: plan_btn.configure(
                        text="🎲 GLM Plan Pages", state="normal"))
            threading.Thread(target=_w, daemon=True).start()

        status = tk.Label(win, text="Output: coloring_books/<title>/",
                          bg=self.PANEL, fg=self.FG_MUTED, wraplength=520,
                          justify="left")
        status.pack(anchor="w", padx=12, pady=4)

        def start():
            subjects = [s.strip() for s in
                        subjects_text.get("1.0", "end").splitlines()
                        if s.strip()]
            if not subjects:
                messagebox.showinfo("No pages", "Plan or write page "
                                    "subjects first.", parent=win)
                return
            if self.busy:
                messagebox.showinfo("Busy", "A generation is running.",
                                    parent=win)
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI not connected.",
                                     parent=win)
                return
            make_btn.configure(state="disabled", text="Drawing...")
            self.stop_flag = False

            def setv(t):
                self.root.after(0, lambda: status.config(text=t))

            def done():
                self.root.after(0, lambda: make_btn.configure(
                    state="normal", text="🖍 CREATE BOOK"))
            threading.Thread(
                target=self._coloring_book_worker,
                args=(title_var.get().strip() or "Coloring Book",
                      theme_var.get().strip(), subjects,
                      complexity_var.get(), psize_var.get(), setv, done),
                daemon=True).start()

        def convert_existing():
            """Any image -> coloring page via server-side edge extraction."""
            p = filedialog.askopenfilename(
                title="Image to convert", initialdir=self.output_dir,
                filetypes=self.IMG_FILETYPES, parent=win)
            if not p:
                return
            if not self.client.base_url:
                messagebox.showerror("Offline", "ComfyUI not connected.",
                                     parent=win)
                return

            def _w():
                try:
                    from PIL import Image, ImageOps
                    name = self._upload_ref(Path(p))
                    wf = self.client.build_canny_workflow(name)
                    entry = self._queue_and_wait(wf)
                    info = next(x for o in entry["outputs"].values()
                                for x in o.get("images", []))
                    raw = self.client.download_image(
                        info["filename"], info.get("subfolder", ""),
                        info.get("type", "output"))
                    import io
                    edges = Image.open(io.BytesIO(raw))
                    # canny: white lines on black -> invert for coloring
                    page_art = to_coloring_page(
                        ImageOps.invert(edges.convert("L")).convert("RGB"),
                        thicken=1)
                    size = COLORING_PAGE_SIZES[psize_var.get()]
                    page = make_coloring_canvas(page_art, size)
                    out_dir = self.output_dir / "coloring_books"
                    out_dir.mkdir(exist_ok=True)
                    out = out_dir / (f"{datetime.now():%Y%m%d_%H%M%S}"
                                     f"_converted.png")
                    page.save(out, dpi=(300, 300))
                    self.show_preview(out)
                    self.log(f"Converted to coloring page: {out.name}")
                except Exception as e:
                    self.log(f"Convert ERROR: {e}")
            threading.Thread(target=_w, daemon=True).start()

        brow = tk.Frame(win, bg=self.PANEL)
        brow.pack(fill="x", padx=12, pady=8)
        plan_btn = ttk.Button(brow, text="🎲 GLM Plan Pages",
                              command=glm_plan)
        plan_btn.pack(side="left")
        ttk.Button(brow, text="Convert existing image...",
                   command=convert_existing).pack(side="left", padx=6)
        make_btn = ttk.Button(brow, text="🖍 CREATE BOOK", command=start)
        make_btn.pack(side="right")
        self.log("Opened Coloring Book Creator")

    def _run_coloring_page_pipeline(self, subject, complexity, psize_name):
        """Busy-flag-free core: one subject -> one finished coloring-book
        page (vivid txt2img draw -> canny trace -> colorable outlines ->
        composed onto the chosen page size). Returns a PIL Image, or None
        on failure. No self.busy/done_cb management - callers (the book
        worker's per-page loop, and the standalone Coloring Pilot) each
        manage their own session lifecycle around this."""
        from PIL import Image, ImageOps
        import io
        mode = COLORING_MODES[complexity]
        page_size = COLORING_PAGE_SIZES[psize_name]
        ckpt = self.ckpt_var.get()
        try:
            # 1) draw ordinary vivid art (the model's strength)
            wf = self.client.build_txt2img_workflow(
                ckpt=ckpt,
                positive=QUALITY + ", " +
                mode["prompt"].format(subject=subject),
                negative=mode["negative"], width=832, height=1216,
                batch_size=1, steps=int(self.steps_var.get()),
                cfg=float(self.cfg_var.get()),
                sampler=self.sampler_var.get(),
                scheduler=self.sched_var.get(),
                seed=random.randint(0, 2**48))
            entry = self._queue_and_wait(wf)
            info = next(x for o in entry["outputs"].values()
                        for x in o.get("images", []))
            raw = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))
            raw_img = Image.open(io.BytesIO(raw))
            # 2) trace it into colorable outlines
            tmp = self.output_dir / "_page_raw.png"
            raw_img.save(tmp)
            name = self._upload_ref(tmp)
            tmp.unlink(missing_ok=True)  # bridge file only - don't litter output_dir
            low, high = mode["canny"]
            wfc = self.client.build_canny_workflow(name, low, high)
            entry = self._queue_and_wait(wfc)
            info = next(x for o in entry["outputs"].values()
                        for x in o.get("images", []))
            edge_raw = self.client.download_image(
                info["filename"], info.get("subfolder", ""),
                info.get("type", "output"))
            edges = Image.open(io.BytesIO(edge_raw))
            art = to_coloring_page(
                ImageOps.invert(edges.convert("L")).convert("RGB"),
                thicken=mode["thicken"])
            return make_coloring_canvas(art, page_size)
        except Exception as e:
            self.log(f"Coloring page '{subject}' failed: {e}")
            return None

    def _coloring_book_worker(self, title, theme, subjects, complexity,
                              psize_name, set_status, done_cb):
        self.busy = True
        t0 = time.time()
        try:
            page_size = COLORING_PAGE_SIZES[psize_name]
            safe_title = re.sub(r"[^\w\-]+", "_", title)[:40]
            out_dir = self.output_dir / "coloring_books" / \
                f"{datetime.now():%Y%m%d_%H%M}_{safe_title}"
            out_dir.mkdir(parents=True, exist_ok=True)
            pages = []
            # release the local LLM's VRAM once before this multi-page
            # diffusion run starts - established pattern on this 6GB card,
            # was missing here (found in a full-system audit)
            self.quotes.release_vram()
            for i, subject in enumerate(subjects, 1):
                if self.stop_flag:
                    set_status(f"Stopped at page {i}")
                    break
                set_status(f"Drawing page {i}/{len(subjects)}: {subject}")
                page = self._run_coloring_page_pipeline(
                    subject, complexity, psize_name)
                if page is None:
                    continue
                p = out_dir / f"page_{i:02d}.png"
                page.save(p, dpi=(300, 300))
                pages.append(page)
                self.log(f"Coloring page {i}: {subject}")
            if pages:
                cover = render_book_cover(
                    title, theme.title() if theme else "", page_size,
                    art_bw=pages[0])
                cover.save(out_dir / "cover.png", dpi=(300, 300))
                pdf = out_dir / f"{safe_title}.pdf"
                cover.save(pdf, save_all=True, append_images=pages,
                           resolution=300)
                self.show_preview(out_dir / "page_01.png")
                mins = (time.time() - t0) / 60
                set_status(f"DONE - {len(pages)} pages + cover -> "
                           f"{pdf.name} ({mins:.1f} min)")
                self.log(f"Coloring book: {len(pages)} pages -> {pdf}")
            else:
                set_status("No pages were produced")
        except Exception as e:
            self.log(f"Coloring book ERROR: {e}")
            set_status(f"Failed: {e}")
        finally:
            self.busy = False
            done_cb()

    # ── v4.1: Wallpaper Lab (hi-fi masters + live visualizer wallpapers) ───
    def _hifi_master(self, positive, negative, orientation="landscape",
                     hifi=True, ckpt=None, lora=None, log=None, *,
                     face_ref=None, face_weight=0.6, ipadapter_file=None,
                     clip_vision_file=None):
        """Generate one maximum-fidelity master image:
        txt2img + hires-fix second pass, then 4x AI upscale (with graceful
        fallback if the upscaler OOMs on this GPU). Returns a Path.

        v9.10: optional face_ref/ipadapter_file/clip_vision_file kwargs -
        build_txt2img_workflow already supports these, this just exposes
        them here so a World Bible with a locked reference portrait gets
        real character consistency in its base still. All default None
        (no behavior change for the existing Wallpaper Lab/Auto-Pilot
        callers)."""
        log = log or self.log
        ckpt = ckpt or self.ckpt_var.get()
        w, h = (1216, 832) if orientation == "landscape" else (832, 1216)
        hires_kw = ({"hires_fix": True, "hires_scale": 1.5,
                     "hires_denoise": 0.45} if hifi else {})
        # release the local LLM's VRAM before this hi-fi (txt2img +
        # hires-fix + 4x upscale) pass - the heaviest generation path in
        # the app - was missing here (found in a full-system audit); every
        # caller (Wallpaper Lab, Auto-Pilot's wallpaper cycles) benefits
        # from a single fix at this shared core.
        self.quotes.release_vram()
        wf = self.client.build_txt2img_workflow(
            ckpt=ckpt, positive=positive,
            negative=negative + ", text, watermark, signature",
            width=w, height=h, batch_size=1,
            steps=max(24, int(self.steps_var.get())),
            cfg=float(self.cfg_var.get()),
            sampler=self.sampler_var.get(), scheduler=self.sched_var.get(),
            seed=random.randint(0, 2**48), lora=lora,
            face_ref=face_ref, face_weight=face_weight,
            ipadapter_file=ipadapter_file, clip_vision_file=clip_vision_file,
            **hires_kw)
        entry = self._queue_and_wait(wf)
        outputs = entry.get("outputs", {}) if (entry and isinstance(entry, dict)) else {}
        images = [x for o in outputs.values() for x in o.get("images", [])]
        if not images:
            raise RuntimeError("No image output returned from master workflow")
        info = images[0]
        raw = self.client.download_image(
            info["filename"], info.get("subfolder", ""),
            info.get("type", "output"))
        tmp = self.output_dir / f"_master_{orientation}.png"
        tmp.write_bytes(raw)
        if hifi and self.upscale_models:
            log("Wallpaper Lab: 4x AI upscale of master...")
            try:
                name = self._upload_ref(tmp)
                wfu = self.client.build_upscale_workflow(
                    name, self.upscale_models[0])
                entry = self._queue_and_wait(wfu)
                info = next(x for o in entry["outputs"].values()
                            for x in o.get("images", []))
                tmp.write_bytes(self.client.download_image(
                    info["filename"], info.get("subfolder", ""),
                    info.get("type", "output")))
            except Exception as e:
                log(f"Upscale fallback (base master kept): {e}")
        return tmp

    def open_wallpaper_lab(self):
        """High-fidelity wallpapers for every screen + live music-reactive
        video wallpapers (Wallpaper Engine / Lively compatible MP4s)."""
        win = tk.Toplevel(self.root)
        win.title("Wallpaper Lab - hi-fi art for every screen")
        self._clamp_window(win, 580, 640)
        win.configure(bg=self.PANEL)

        tk.Label(win, text="TARGET SCREENS (multi-select)", bg=self.PANEL,
                 fg=self.ACCENT, font=self.font_body_bold).pack(
            anchor="w", padx=12, pady=(12, 2))
        size_list = tk.Listbox(win, selectmode="multiple", height=7,
                               bg=self.INPUT_BG, fg=self.FG,
                               exportselection=False,
                               selectbackground=self.ACCENT)
        for name in WALLPAPER_SIZES:
            size_list.insert("end", name)
        size_list.selection_set(0, 2)  # FHD/QHD/4K by default
        size_list.pack(fill="x", padx=12)

        prow = tk.Frame(win, bg=self.PANEL)
        prow.pack(fill="x", padx=12, pady=(8, 2))
        tk.Label(prow, text="Subject:", bg=self.PANEL, fg=self.FG,
                 width=8, anchor="w").pack(side="left")
        subj_var = tk.StringVar(value="Current persona + style")
        ttk.Combobox(prow, textvariable=subj_var, state="readonly",
                     values=["Current persona + style", "Custom prompt"],
                     width=24).pack(side="left")
        hifi_var = tk.BooleanVar(value=True)
        tk.Checkbutton(prow, text="High Fidelity (hires + 4x AI)",
                       variable=hifi_var, bg=self.PANEL, fg=self.WARN_TEXT,
                       selectcolor=self.INPUT_BG,
                       activebackground=self.PANEL).pack(side="left", padx=8)

