    def synthesize_instant_brain_prompt(self):
        """Synthesize a high-aesthetic anime prompt in 0.1ms using the built-in Neural Tag Brain."""
        persona = self.selected_persona()
        style = self.style_var.get()
        mode = self.mode_var.get()
        
        if getattr(self, "neural_brain", None):
            t0 = time.perf_counter()
            prompt = self.neural_brain.synthesize(persona, style=style, mode=mode)
            dur_ms = (time.perf_counter() - t0) * 1000.0
            
            self.pos_text.delete("1.0", "end")
            self.pos_text.insert("1.0", prompt)
            self.update_preview()
            self.log(f"🧠 Instant Brain Synthesized Prompt in {dur_ms:.3f}ms (VRAM Used: 0 MB)")
        else:
            self.log("Built-in Neural Tag Brain engine unavailable.")

    def generate_manga_script(self):
        """Use local Ollama connection to write light novel / manga dialogue for active persona."""
        persona = self.selected_persona()
        pname = persona.get("name", "Original Character")
        visual = persona.get("visual_details", "Anime character")
        
        prompt = (
            f"Write a short dramatic 3-line Manga dialogue scene for {pname}.\n"
            f"Character Visuals: {visual}\n"
            "Format:\n"
            "PANEL 1 [Setting]: Line\n"
            "PANEL 2 [Close-up]: Line\n"
            "PANEL 3 [Action]: Line\n"
            "Keep it intense, emotional, and captivating."
        )
        self.quote_text.delete("1.0", "end")
        self.quote_text.insert("1.0", "Ollama is writing Manga Script...")
        
        def _w():
            try:
                script = self.quotes.complete(prompt, temperature=0.8, max_tokens=250)
                if not script:
                    script = f"PANEL 1 [{pname}]: 'I won't let this world break me...'\nPANEL 2 [Close-up]: 'Watch me prove them wrong!'\nPANEL 3 [Climax]: 'NOW!'"
                self.root.after(0, lambda: [
                    self.quote_text.delete("1.0", "end"),
                    self.quote_text.insert("1.0", script)
                ])
            except Exception as e:
                self.root.after(0, lambda: self.log(f"Manga Script error: {e}"))
                
        threading.Thread(target=_w, daemon=True).start()

    def export_lofi_mp4_video(self):
        """Use local ffmpeg.exe to render 1080p MP4 video from last generated image."""
        if not self.last_preview_path or not Path(self.last_preview_path).exists():
            messagebox.showinfo("No Image", "Generate an image first.")
            return
            
        ffmpeg_bin = app_dir() / "ffmpeg.exe"
        if not ffmpeg_bin.exists():
            ffmpeg_bin = Path("dist/ffmpeg.exe")
            
        stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        out_video = self.output_dir / f"video_{stamp}.mp4"
        
        if ffmpeg_bin.exists():
            # v8.4: build the argument list directly instead of a shell
            # string with shell=True - self.last_preview_path can
            # originate from a user file-picker (Remix/Color Grade/
            # Convert Existing Image), so a crafted filename containing
            # shell metacharacters (&, |, ^, %) previously had a real
            # command-injection path on Windows cmd.exe.
            cmd = [str(ffmpeg_bin), "-loop", "1", "-i",
                   str(self.last_preview_path), "-c:v", "libx264", "-t", "5",
                   "-pix_fmt", "yuv420p", "-vf",
                   "scale=1080:1920:force_original_aspect_ratio=decrease,"
                   "pad=1080:1920:(ow-iw)/2:(oh-ih)/2", "-y", str(out_video)]
            try:
                subprocess.Popen(cmd, shell=False)
                self.log(f"🎵 Video Exporting to {out_video.name} via FFmpeg...")
                messagebox.showinfo("Exporting Video", f"FFmpeg is rendering MP4 video to:\n{out_video.name}")
            except Exception as e:
                self.log(f"FFmpeg error: {e}")
        else:
            self.log("ffmpeg.exe not found - image saved as video frame ready for render.")

    def start_animatediff_video(self):
        """Run AnimateDiff 16-frame animation loop using local ComfyUI engine."""
        if self.busy:
            messagebox.showinfo("Busy", "A generation is running.")
            return
        if not self.client.base_url:
            messagebox.showerror("Offline", "ComfyUI is not connected.")
            return
            
        persona = self.selected_persona()
        style = self.style_var.get()
        positive = self.prompts.build("Scene", persona, style) + ", (motion, subtle hair movement, wind blowing:1.2)"
        negative = self.neg_text.get("1.0", "end").strip() or DEFAULT_NEGATIVE
        # v10.3: mm_sdxl_v10_beta.ckpt is a second, higher-resolution
        # motion model already sitting on disk unused - offer it as an
        # opt-in alternate to the SD1.5 default rather than switching the
        # default itself (SD1.5 is the proven, tested path; SDXL motion
        # models are newer/less battle-tested for this app's use).
        use_sdxl_motion = getattr(self, "sdxl_motion_var", None) and self.sdxl_motion_var.get()
        motion_model = "mm_sdxl_v10_beta.ckpt" if use_sdxl_motion else "mm_sd_v15_v2.ckpt"
        width, height = (768, 1152) if use_sdxl_motion else (512, 768)

        def _w():
            try:
                self.busy = True
                self.log(f"🎬 Queuing AnimateDiff 16-Frame Animation Loop ({motion_model})...")
                wf = self.client.build_animatediff_workflow(
                    sd15_ckpt=self.ckpt_var.get(),
                    motion_model=motion_model,
                    positive=positive, negative=negative,
                    width=width, height=height, frames=16, steps=15, cfg=7.0,
                    seed=random.randint(0, 2**48)
                )
                entry = self._queue_and_wait(wf)
                self.log("🎬 AnimateDiff Render Complete!")
            except Exception as e:
                self.log(f"AnimateDiff error: {e}")
            finally:
                self.busy = False
                
        threading.Thread(target=_w, daemon=True).start()

    def start_1_click_power_ai(self):
        """Autonomously dreams a concept and instantly generates it."""
        self.log("⚡ 1-Click Power AI Activated: Dreaming up a concept...")
        
        def _worker():
            try:
                import requests, random
                prompt = "Write a high-quality, vivid text-to-image prompt for a highly detailed anime character in a dynamic scene. Respond with ONLY the comma-separated prompt text, no pleasantries or explanation."
                sys_prompt = "You are an expert anime prompt engineer."
                if IS_KIDS_MODE:
                    sys_prompt += " Ensure the concept is extremely family friendly, safe, and wholesome."
                
                model = getattr(self.quotes, 'model', None) or LLM_FALLBACK_MODEL
                payload = {
                    "model": model,
                    "messages": [
                        {"role": "system", "content": sys_prompt},
                        {"role": "user", "content": prompt}
                    ],
                    "stream": False
                }
                
                reply = None
                if not IS_KIDS_MODE:
                    try:
                        r = requests.post("http://127.0.0.1:8080/v1/chat/completions", json=payload, timeout=5)
                        if r.status_code == 200:
                            reply = r.json()["choices"][0]["message"]["content"].strip()
                    except: pass
                
                if not reply:
                    try:
                        r = requests.post("http://127.0.0.1:11434/api/chat", json=payload, timeout=10)
                        if r.status_code == 200:
                            reply = r.json()["message"]["content"].strip()
                    except: pass
                    
                if not reply:
                    reply = "1girl, solo, epic fantasy, cinematic lighting, highly detailed, masterpiece, looking at viewer, dynamic pose"
                
                # Apply to UI and hit generate
                def _apply():
                    self.pos_text.delete("1.0", "end")
                    self.pos_text.insert("1.0", reply)
                    if getattr(self, "style_var", None):
                        styles = ["Cyberpunk", "Dark Fantasy", "Studio Ghibli", "Neon Mecha", "Pastel Pop", "chibi_kawaii", "90s Retro Anime"]
                        self.style_var.set(random.choice(styles))
                    self.log(f"⚡ 1-Click Power AI Generated: {reply}")
                    self.start_generation()
                
                self.root.after(0, _apply)
            except Exception as e:
                # v6.9: was self.after(...) - CompanionApp isn't a Tk
                # widget (only self.root is), so this raised an
                # unhandled AttributeError every time, silently killing
                # the worker thread before the prompt/generation ever
                # fired.
                self.root.after(0, lambda: self.log(f"⚡ Power AI Error: {e}"))
                
        import threading
        threading.Thread(target=_worker, daemon=True).start()

    # ── v4.0: menubar - organized home for every window & tool ─────────────
    def _build_menubar(self):
        """Replace the old 29-button top strip with a standard menubar so
        every feature is reachable at any window size."""
        bar = tk.Menu(self.root)

        def menu(label, items):
            # v9.8: entries may be (text, cmd) or (text, cmd, accelerator).
            # The app had 10 working keyboard shortcuts that appeared
            # nowhere in the UI - the only way to discover them was to
            # already know Ctrl+H. accelerator= just draws the hint; the
            # actual binding still lives in _bind_shortcuts.
            m = tk.Menu(bar, tearoff=0)
            for entry in items:
                if entry is None:
                    m.add_separator()
                elif len(entry) == 3:
                    text, cmd, accel = entry
                    m.add_command(label=text, command=cmd, accelerator=accel)
                else:
                    text, cmd = entry
                    m.add_command(label=text, command=cmd)
            bar.add_cascade(label=label, menu=m)
            return m

