        def export_session_dialog():
            try:
                sessions = self.session_manager.list_sessions()
                if not sessions:
                    messagebox.showinfo("No Sessions", "No saved sessions to export")
                    return

                session_names = [s["name"] for s in sessions]
                session_name = simpledialog.askstring("Export Session",
                                                       f"Session name:\n{chr(10).join(session_names)}")
                if not session_name:
                    return

                path = filedialog.asksaveasfilename(
                    defaultextension=".json",
                    filetypes=[("JSON", "*.json"), ("All", "*.*")]
                )
                if path:
                    if self.session_manager.export_session(session_name, Path(path)):
                        self.log(f"Session exported: {session_name}")
                        messagebox.showinfo("Success", f"Exported to {Path(path).name}")
                    else:
                        messagebox.showerror("Error", "Failed to export session")
            except Exception as e:
                messagebox.showerror("Error", str(e))

        def import_session_dialog():
            try:
                path = filedialog.askopenfilename(
                    filetypes=[("JSON", "*.json"), ("All", "*.*")]
                )
                if path:
                    name = Path(path).stem
                    if self.session_manager.import_session(Path(path), name):
                        self.log(f"Session imported: {name}")
                        self.refresh_sessions()
                        messagebox.showinfo("Success", f"Imported as '{name}'")
                    else:
                        messagebox.showerror("Error", "Failed to import session")
            except Exception as e:
                messagebox.showerror("Error", str(e))

        ttk.Button(session_frame, text="Export Session", command=export_session_dialog).pack(fill="x", padx=12, pady=4)
        ttk.Button(session_frame, text="Import Session", command=import_session_dialog).pack(fill="x", padx=12, pady=4)

