        # Live VRAM usage
        live_panel = self.create_glass_frame(gpu_frame)
        live_panel.pack(fill="x", padx=12, pady=(0, 8))

        self.gpu_status_lbl = tk.Label(live_panel, text="Refreshing GPU info...", bg=self.GLASS_BG, fg=self.FG,
                                       font=self.font_mono_body)
        self.gpu_status_lbl.pack(anchor="w", padx=12, pady=12)

        def update_gpu_status():
            # v6.6: this rescheduled itself forever with no way to stop -
            # closing Settings left the chain running, and every 2s it
            # would hit .config() on a destroyed widget (TclError spam),
            # with a new chain stacking up on every re-open. Bail out
            # once the window is gone instead.
            if not settings_win.winfo_exists():
                return
            used_gb, total_gb = self._get_gpu_vram_usage()
            if total_gb > 0:
                vram_pct = (used_gb / total_gb) * 100
                status = f"VRAM: {used_gb:.1f}GB / {total_gb:.1f}GB ({vram_pct:.0f}%)"
            else:
                status = "VRAM: Unknown (nvidia-smi not available)"
            self.gpu_status_lbl.config(text=status)
            # Refresh every 2 seconds
            self.root.after(2000, update_gpu_status)

        self.root.after(500, update_gpu_status)

        # GPU Configuration
        tk.Label(gpu_frame, text="⚙️  GPU CONFIGURATION", bg=self.PANEL, fg=self.ACCENT,
                font=self.font_subheading).pack(anchor="w", padx=12, pady=(8, 4))

