    def build_lora_library_tab(self, parent):
        """Build LoRA discovery & installation UI."""
        search_frame = tk.Frame(parent, bg=self.PANEL)
        search_frame.pack(fill="x", padx=6, pady=6)

        tk.Label(search_frame, text="Search Civitai:", bg=self.PANEL, fg=self.FG).pack(side="left", padx=4)
        search_var = tk.StringVar()
        search_entry = ttk.Entry(search_frame, textvariable=search_var, width=30)
        search_entry.pack(side="left", padx=4, fill="x", expand=True)
        search_entry.focus_set()

        results_frame = tk.Frame(parent, bg=self.PANEL)
        results_frame.pack(fill="both", expand=True, padx=6, pady=6)

        results_list = tk.Listbox(results_frame, bg=self.BG, fg=self.FG, selectmode="single", height=20, width=80)
        results_list.pack(fill="both", expand=True)
        # v10.1: was a blank Listbox with zero explanation of what to do
        # here - a real user reported it as a confusing empty window.
        results_list.insert("end", "  Type a LoRA name above and press "
                            "Search (or Enter) to browse Civitai.")
        results_list.itemconfig(0, fg=self.FG_MUTED)

        current_results = []

        def do_search():
            # v6.6: CivitaiClient.search_loras ran directly on the Tk main
            # thread - a slow/unreachable Civitai search froze the whole
            # app, unlike every other network call elsewhere in the file.
            nonlocal current_results
            query = search_var.get().strip()
            if not query:
                results_list.delete(0, "end")
                return
            results_list.delete(0, "end")
            results_list.insert("end", "Searching...")

            def _w():
                found = CivitaiClient.search_loras(query)

                def _show():
                    nonlocal current_results
                    current_results = found
                    results_list.delete(0, "end")
                    for result in current_results:
                        text = (f"{result['name']} ({result['downloads']} "
                               f"dl, ⭐{result['rating']:.1f})")
                        results_list.insert("end", text)
                self.root.after(0, _show)
            threading.Thread(target=_w, daemon=True).start()

        def install_selected():
            # v6.6: same freeze risk - urlretrieve has no timeout at all
            # and a multi-hundred-MB LoRA download ran on the main thread.
            selection = results_list.curselection()
            if not selection or not current_results:
                messagebox.showinfo("Select", "Pick a LoRA to install", parent=parent)
                return
            lora = current_results[selection[0]]
            install_btn.config(state="disabled", text="Installing...")
            filename = re.sub(r"[^\w\-]+", "_", lora["name"]) + ".safetensors"
            lora_dir = Path(SHARED_MODELS_DIR) / "loras"

            def _w():
                ok = CivitaiClient.download_lora(
                    lora["download_url"], filename, lora_dir)

                def _done():
                    if ok:
                        self.log(f"LoRA installed: {lora['name']} "
                                f"({lora['size_mb']:.0f}MB)")
                        messagebox.showinfo("Success",
                                            f"Installed {lora['name']}",
                                            parent=parent)
                    else:
                        messagebox.showerror("Error", "Download failed",
                                             parent=parent)
                    install_btn.config(state="normal", text="Install LoRA")
                self.root.after(0, _done)
            threading.Thread(target=_w, daemon=True).start()

        # v10.1: was self.install_btn - never assigned anywhere in the
        # file, so clicking Install LoRA always raised a silent
        # AttributeError inside a background thread (Python routes that
        # through threading.excepthook, not the visible messagebox path -
        # confirmed live, this button has never worked). Also bind Enter
        # in the search box - previously Search only fired on click.
        search_entry.bind("<Return>", lambda e: do_search())
        ttk.Button(search_frame, text="Search", command=do_search).pack(side="left", padx=4)
        install_btn = ttk.Button(parent, text="Install LoRA", command=install_selected)
        install_btn.pack(pady=6)

    # ── PHASE 3, TIER 1: Image Rating Dialog ─────────────────────────────────
    def rate_image_dialog(self, image_path: Path = None):
        """Rate a generated image (1-5 stars)."""
        if not image_path and not self.last_gen:
            messagebox.showinfo("No Image", "Generate an image first", parent=self.root)
            return

        if not image_path:
            # Try to find the last generated image
            gallery_dir = self.output_dir
            if not gallery_dir.exists():
                return
            images = sorted(gallery_dir.glob("*.png"), key=lambda p: p.stat().st_mtime, reverse=True)
            if not images:
                messagebox.showinfo("No Images", "No generated images found", parent=self.root)
                return
            image_path = images[0]

        rate_win = tk.Toplevel(self.root)
        rate_win.title("Rate Image")
        self._clamp_window(rate_win, 400, 300)
        rate_win.configure(bg=self.PANEL)

        tk.Label(rate_win, text="How would you rate this generation?", bg=self.PANEL, fg=self.ACCENT,
                font=self.font_subheading).pack(anchor="w", padx=12, pady=8)

        rating_var = tk.IntVar(value=5)
        tk.Label(rate_win, text="Rating:", bg=self.PANEL, fg=self.FG).pack(anchor="w", padx=12, pady=(8, 2))

        stars_frame = tk.Frame(rate_win, bg=self.PANEL)
        stars_frame.pack(anchor="w", padx=12, pady=4)
        for i in range(1, 6):
            rb = tk.Radiobutton(stars_frame, text="⭐" * i, variable=rating_var, value=i,
                               bg=self.PANEL, fg=self.ACCENT, selectcolor=self.PANEL)
            rb.pack(side="left", padx=4)

        tk.Label(rate_win, text="Comment (optional):", bg=self.PANEL, fg=self.FG).pack(anchor="w", padx=12, pady=(12, 2))
        comment_text = tk.Text(rate_win, height=5, width=45, bg=self.BG, fg=self.FG)
        comment_text.pack(fill="both", expand=True, padx=12, pady=2)

        def submit_rating():
            try:
                self.meta_manager.update_image_rating(image_path, rating_var.get())
                self.log(f"Image rated: {rating_var.get()}⭐")
                messagebox.showinfo("Success", f"Thank you for rating! ({rating_var.get()}⭐)", parent=rate_win)
                rate_win.destroy()
            except Exception as e:
                messagebox.showerror("Error", f"Failed to save rating: {e}", parent=rate_win)

        ttk.Button(rate_win, text="Submit Rating", command=submit_rating).pack(fill="x", padx=12, pady=12)

    # ── PHASE 3, TIER 2: Model Comparison Dialog ─────────────────────────────
    def open_model_comparison(self):
        """Compare all models side-by-side with quality metrics."""
        comp_win = tk.Toplevel(self.root)
        comp_win.title("Model Comparison")
        self._clamp_window(comp_win, 900, 600)
        comp_win.configure(bg=self.PANEL)

        tk.Label(comp_win, text="Model Quality Comparison", bg=self.PANEL, fg=self.ACCENT,
                font=self.font_heading).pack(anchor="w", padx=12, pady=8)

        # Create frame for table
        table_frame = tk.Frame(comp_win, bg=self.BG)
        table_frame.pack(fill="both", expand=True, padx=12, pady=8)

        # Header
        header = tk.Frame(table_frame, bg=self.ACCENT)
        header.pack(fill="x", padx=0, pady=0)
        for col_name in ["Model", "Tier", "Quality", "Speed", "Rating", "Time (sec)"]:
            tk.Label(header, text=col_name, bg=self.ACCENT, fg=self.PANEL, width=15,
                    font=self.font_body_bold).pack(side="left", fill="x", expand=True)

        # Load models from registry
        try:
            registry = safe_json_load(app_dir() / "config" / "model_registry.json", {})
            models = registry.get("models", {})

            for model_key, model_data in sorted(models.items())[:10]:  # Show top 10
                row = tk.Frame(table_frame, bg=self.BG)
                row.pack(fill="x", padx=0, pady=2)

                model_name = model_data.get("type", "Unknown")
                quality_tier = model_data.get("quality_tier", 5)
                metrics = model_data.get("quality_metrics", {})
                avg_quality = sum(metrics.values()) / len(metrics) if metrics else 7.0
                rating = model_data.get("community_rating", 0.0)
                benchmarks = model_data.get("performance_benchmarks", {})
                gen_time = benchmarks.get("avg_generation_time_sec", 0.0)

                tk.Label(row, text=model_name, bg=self.BG, fg=self.FG, width=15).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=str(quality_tier), bg=self.BG, fg=self.FG, width=15).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=f"{avg_quality:.1f}", bg=self.BG, fg=self.FG, width=15).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=f"{10-quality_tier}/10", bg=self.BG, fg=self.FG, width=15).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=f"{'⭐'*int(rating)}", bg=self.BG, fg=self.FG, width=15).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=f"{gen_time:.1f}", bg=self.BG, fg=self.FG, width=15).pack(side="left", fill="x", expand=True)
        except Exception as e:
            tk.Label(comp_win, text=f"Error loading models: {e}", bg=self.PANEL, fg=self.FG).pack()

        ttk.Button(comp_win, text="Close", command=comp_win.destroy).pack(fill="x", padx=12, pady=8)

    # ── PHASE 3, TIER 2: Sampler Comparison Dialog ───────────────────────────
    def open_sampler_comparison(self):
        """Compare samplers with quality trade-offs."""
        samp_win = tk.Toplevel(self.root)
        samp_win.title("Sampler Comparison")
        self._clamp_window(samp_win, 700, 500)
        samp_win.configure(bg=self.PANEL)

        tk.Label(samp_win, text="Sampler Performance & Quality", bg=self.PANEL, fg=self.ACCENT,
                font=self.font_heading).pack(anchor="w", padx=12, pady=8)

        # Create frame for table
        table_frame = tk.Frame(samp_win, bg=self.BG)
        table_frame.pack(fill="both", expand=True, padx=12, pady=8)

        # Header
        header = tk.Frame(table_frame, bg=self.ACCENT)
        header.pack(fill="x", padx=0, pady=0)
        for col_name in ["Sampler", "Quality", "Speed", "Stability", "Best For"]:
            tk.Label(header, text=col_name, bg=self.ACCENT, fg=self.PANEL, width=14,
                    font=self.font_body_bold).pack(side="left", fill="x", expand=True)

        # Load samplers from benchmarks
        try:
            benchmarks = safe_json_load(Path(app_dir()) / "sampler_benchmarks.json", {})
            samplers = benchmarks.get("samplers", {})

            for sampler_key, sampler_data in samplers.items():
                row = tk.Frame(table_frame, bg=self.BG)
                row.pack(fill="x", padx=0, pady=2)

                name = sampler_data.get("name", sampler_key)
                quality_tier = sampler_data.get("quality_tier", 5)
                speed_tier = sampler_data.get("speed_tier", 5)
                bench = sampler_data.get("benchmarks", {})
                stability = bench.get("stability", 0.9)
                best_for = ", ".join(sampler_data.get("best_for", [])[:2])

                tk.Label(row, text=name, bg=self.BG, fg=self.FG, width=14).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=str(quality_tier), bg=self.BG, fg=self.FG, width=14).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=str(speed_tier), bg=self.BG, fg=self.FG, width=14).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=f"{stability:.2f}", bg=self.BG, fg=self.FG, width=14).pack(side="left", fill="x", expand=True)
                tk.Label(row, text=best_for, bg=self.BG, fg=self.FG, width=14).pack(side="left", fill="x", expand=True)
        except Exception as e:
            tk.Label(samp_win, text=f"Error loading samplers: {e}", bg=self.PANEL, fg=self.FG).pack()

        ttk.Button(samp_win, text="Close", command=samp_win.destroy).pack(fill="x", padx=12, pady=8)

