    # widget option -> tk widget classes it's meaningful to reconfigure on
    _RETHEME_OPTS = ("bg", "fg", "background", "foreground", "selectcolor",
                     "activebackground", "activeforeground",
                     "highlightbackground", "highlightcolor",
                     "insertbackground", "troughcolor",
                     "selectbackground", "selectforeground")

    def apply_ui_scale(self, scale: float, save: bool = True):
        """v9.16: rescale every named font by `scale` off its true base
        point size (self._BASE_FONT_SIZES), never off the current size -
        that would compound on repeated calls (e.g. Apply clicked twice
        would double-scale). Because every widget in the app takes
        `font=self.font_X` (a live tkFont.Font reference, per the v9.6
        comment above), reconfiguring these objects updates every widget
        on screen immediately - no widget tree walk needed, unlike
        retheme_live()'s color pass."""
        scale = max(0.75, min(2.0, float(scale)))
        for attr, base_size in self._BASE_FONT_SIZES.items():
            font_obj = getattr(self, attr, None)
            if font_obj is not None:
                try:
                    font_obj.configure(size=max(6, round(base_size * scale)))
                except Exception:
                    pass
        self.ui_scale = scale
        if save:
            self.llm_config["ui_scale"] = scale
            save_llm_config(self.llm_config)

    def apply_theme(self, theme: str = "dark"):
        """Apply the full, WCAG-AA-checked color palette for light or dark
        mode. Every semantic role used anywhere in the UI is set here so
        no widget is left using a stale, un-themed literal color."""
        for role, value in self.THEMES.get(theme, self.THEMES["dark"]).items():
            setattr(self, role, value)
        self.llm_config["theme"] = theme
        save_llm_config(self.llm_config)

    def retheme_live(self, old_theme: str, new_theme: str):
        """Walk every widget currently on screen (main window + any open
        Toplevels) and reconfigure colors that match a known role from the
        OLD theme to that same role's value in the NEW theme. This is what
        actually makes the Settings 'Apply Theme' button do something -
        apply_theme() alone only updates Python-side self.X variables,
        which existing widgets never read again after construction."""
        old_map = self.THEMES.get(old_theme, self.THEMES["dark"])
        new_map = self.THEMES.get(new_theme, self.THEMES["dark"])
        # reverse: literal old color -> role name (case-insensitive hex)
        reverse = {v.lower(): k for k, v in old_map.items()}

        def visit(widget):
            try:
                for opt in self._RETHEME_OPTS:
                    try:
                        current = str(widget.cget(opt))
                    except (tk.TclError, Exception):
                        continue
                    role = reverse.get(current.lower())
                    if role:
                        try:
                            widget.configure(**{opt: new_map[role]})
                        except tk.TclError:
                            pass
            except Exception:
                pass
            try:
                children = widget.winfo_children()
            except Exception:
                children = []
            for child in children:
                visit(child)

        try:
            self.root.configure(bg=self.BG)
        except Exception:
            pass
        visit(self.root)
        # ttk widgets (Combobox/Entry/Spinbox/Button/Notebook/...) are
        # styled via ttk.Style, not per-widget bg/fg - retheme the shared
        # style too. v9.6: extended to cover every class _build_ui now
        # configures (TLabelframe/TScrollbar/TScale/TCheckbutton/
        # TRadiobutton/TMenubutton/TPanedwindow were previously skipped
        # here, so switching themes left them showing the OLD theme's
        # colors even though every other widget updated) plus the
        # hover/pressed/disabled state maps, so a theme switch is
        # complete rather than partial.
        try:
            style = ttk.Style()
            style.configure("TFrame", background=self.PANEL)
            style.configure("TLabel", background=self.PANEL, foreground=self.FG)
            style.configure("TButton", background=self.PANEL_LIGHT, foreground=self.FG)
            style.map("TButton",
                     background=[("disabled", self.DISABLED_BG),
                                 ("pressed", self.PRESSED), ("active", self.HOVER)],
                     foreground=[("disabled", self.DISABLED_FG),
                                 ("pressed", self.FG), ("active", self.FG)])
            style.configure("TNotebook", background=self.PANEL)
            style.configure("TNotebook.Tab", background=self.PANEL_LIGHT,
                           foreground=self.FG_DIM)
            style.map("TNotebook.Tab",
                     background=[("selected", self.PANEL_HIGHLIGHT), ("active", self.HOVER)],
                     foreground=[("selected", self.ACCENT_LIGHT), ("active", self.FG)])
            style.configure("TCombobox", fieldbackground=self.INPUT_BG,
                           foreground=self.FG, background=self.INPUT_BG)
            style.map("TCombobox",
                     fieldbackground=[("disabled", self.DISABLED_BG), ("readonly", self.INPUT_BG)],
                     foreground=[("disabled", self.DISABLED_FG), ("readonly", self.FG)],
                     background=[("active", self.HOVER)])
            style.configure("TSpinbox", fieldbackground=self.INPUT_BG,
                           foreground=self.FG, background=self.PANEL_LIGHT)
            style.map("TSpinbox",
                     fieldbackground=[("disabled", self.DISABLED_BG)],
                     foreground=[("disabled", self.DISABLED_FG)])
            style.configure("TEntry", fieldbackground=self.BG, foreground=self.FG)
            style.map("TEntry",
                     fieldbackground=[("disabled", self.DISABLED_BG)],
                     foreground=[("disabled", self.DISABLED_FG)])
            style.configure("TLabelframe", background=self.PANEL, foreground=self.FG)
            style.configure("TLabelframe.Label", background=self.PANEL,
                           foreground=self.ACCENT_LIGHT)
            style.configure("TScrollbar", background=self.PANEL_LIGHT,
                           troughcolor=self.BG, darkcolor=self.PANEL_LIGHT,
                           lightcolor=self.PANEL_HIGHLIGHT)
            style.configure("TScale", background=self.PANEL, troughcolor=self.BG,
                           lightcolor=self.PANEL_HIGHLIGHT, darkcolor=self.PANEL_LIGHT)
            style.configure("TCheckbutton", background=self.PANEL, foreground=self.FG)
            style.map("TCheckbutton",
                     background=[("active", self.PANEL_HIGHLIGHT)],
                     foreground=[("disabled", self.DISABLED_FG), ("active", self.ACCENT_LIGHT)],
                     indicatorcolor=[("selected", self.ACCENT), ("!selected", self.INPUT_BG)])
            style.configure("TRadiobutton", background=self.PANEL, foreground=self.FG)
            style.map("TRadiobutton",
                     background=[("active", self.PANEL_HIGHLIGHT)],
                     foreground=[("disabled", self.DISABLED_FG), ("active", self.ACCENT_LIGHT)],
                     indicatorcolor=[("selected", self.ACCENT), ("!selected", self.INPUT_BG)])
            style.configure("TMenubutton", background=self.PANEL_LIGHT, foreground=self.FG)
            style.map("TMenubutton",
                     background=[("active", self.HOVER), ("disabled", self.DISABLED_BG)],
                     foreground=[("disabled", self.DISABLED_FG)])
            style.configure("TPanedwindow", background=self.PANEL)
        except Exception:
            pass

    # ── Connection ──────────────────────────────────────────────────────────
    def refresh_connection(self):
        self.set_status("Checking for ComfyUI...", self.WARN_TEXT)
        if not self.client.detect():
            self.set_status("ComfyUI OFFLINE - launch it, then click Reconnect", self.ERR)
            self.log("No ComfyUI server found on ports " +
                     ", ".join(str(p) for p in CANDIDATE_PORTS))
            return
        try:
            # ── PHASE 2: Profile system hardware ──
            self.system_profile = self.profiler.profile_from_comfyui()
            gpu_name = self.system_profile.get("gpu_name", "Unknown")
            vram_gb = self.system_profile.get("vram_gb", 4)
            self.log(f"System: {gpu_name} ({vram_gb:.1f} GB VRAM)")

            # v7.0: drop auxiliary files (VAEs/ControlNets/CLIP-vision/text
            # encoders) that live in ComfyUI's checkpoints/ folder. ComfyUI
            # lists them as valid ckpt_names and ACCEPTS a workflow naming
            # one, then dies at execution with "Could not detect model type
            # of: <file>" - which is what made generations abort. Filtering
            # here cleans the Model dropdown, the default selection, and the
            # Smart Director's candidate pool in one place.
            ckpts = [c for c in self.client.get_checkpoints()
                     if not self._is_not_a_checkpoint(c)]
            samplers, scheds = self.client.get_sampler_options()
            self.upscale_models = self.client.get_upscale_models()
            self.qwen_files = self._qwen_image_files()
            self.wan_files = self._wan_video_files()
            self.director.models = [c for c in ckpts if not self._is_sd15(c)
                                    and not self._is_turbo_distilled(c)]
            loras = self.client.get_loras()
            self.motion_models = self.client.get_motion_models()

            # ── v3.2: capability probe for reference conditioning ──
            self._probe_capabilities()

            # ── PHASE 2: Refresh quality orchestrator ──
            self.quality_orchestrator.refresh_available()
        except Exception as e:
            self.set_status(f"Connected, but API error: {e}", self.ERR)
            return

        def _apply():
            self.ckpt_box.configure(values=ckpts)
            if ckpts:
                # Default to a normal SDXL checkpoint, not just whatever
                # sorts first from the server - "Counterfeit-V3.0" (SD1.5,
                # reserved for AnimateDiff video) sorts alphabetically
                # ahead of the SDXL checkpoints on this install, silently
                # defaulting every fresh connection onto a checkpoint most
                # features (Auto-Fix, Remix+LoRA, Tiled Upscale, Auto
                # Character Designer) correctly refuse to run on - not a
                # bug in those guards, just the wrong default upstream.
                default_ckpt = next(
                    (c for c in ckpts if not self._is_sd15(c)
                     and not self._is_turbo_distilled(c)), ckpts[0])
                self.ckpt_var.set(default_ckpt)
            self.sampler_box.configure(values=samplers)
            if "euler_ancestral" in samplers:
                self.sampler_var.set("euler_ancestral")
            elif "euler" in samplers:
                self.sampler_var.set(samplers[samplers.index("euler")])
            elif samplers:
                self.sampler_var.set(samplers[0])
            self.sched_box.configure(values=scheds)
            if "karras" in scheds:
                self.sched_var.set("karras")
            elif scheds:
                self.sched_var.set(scheds[0])
            self.lora_box.configure(values=["(none)"] + loras)
            for box in getattr(self, "lora_stack_boxes", []):
                box.configure(values=["(none)"] + loras)
        self.root.after(0, _apply)

        self.set_status(f"Connected: {self.client.base_url}  |  {len(ckpts)} models", self.OK)
        self.log(f"Connected to ComfyUI at {self.client.base_url}")
        self.log(f"Found {len(ckpts)} checkpoint(s)")
        if not ckpts:
            self.log("WARNING: no checkpoints installed - add a model in ComfyUI first")
        if self.upscale_models:
            self.log(f"4K upscaler ready: {self.upscale_models[0]}")
        else:
            self.log("No upscale model found - 4K output unavailable")
        if loras:
            self.log(f"LoRAs available: {len(loras)}")
        if self.motion_models:
            self.log(f"Video ready: AnimateDiff + {len(self.motion_models)} "
                     f"motion model(s)")
        else:
            self.log("Video not ready (AnimateDiff nodes not loaded - "
                     "restart Comfy Desktop if just installed)")
        if self.quotes.detect():
            backend_name = ("Ollama" if self.quotes.backend == "ollama"
                            else "Locally Uncensored")
            self.log(f"LLM online: {backend_name} / {self.quotes.model}")
        else:
            self.log("No local LLM found (Ollama or Locally Uncensored) - "
                     "using signature quotes & heuristics")

    def _probe_capabilities(self):
        """Detect optional server features and pick their model files."""
        classes = self.client.get_node_classes()

        ipa_nodes = {"IPAdapterModelLoader", "IPAdapterAdvanced",
                     "CLIPVisionLoader"} <= classes
        adapters = self.client.get_ipadapter_files() if ipa_nodes else []
        clips = self.client.get_clip_vision_files() if ipa_nodes else []
        self.ipadapter_file = next(
            (a for a in adapters
             if "plus-face" in a.lower() and "sdxl" in a.lower()),
            next((a for a in adapters if "sdxl" in a.lower()), None))
        self.clip_vision_file = next(
            (c for c in clips if "vit-h" in c.lower()),
            clips[0] if clips else None)
        self.caps["ipadapter"] = bool(
            ipa_nodes and self.ipadapter_file and self.clip_vision_file)

        cn_nodes = {"ControlNetLoader", "ControlNetApplyAdvanced"} <= classes
        cns = self.client.get_controlnets() if cn_nodes else []
        self.openpose_cn = next((c for c in cns if "openpose" in c.lower()), None)
        self.canny_cn = next((c for c in cns if "canny" in c.lower()), None)
        self.depth_cn = next((c for c in cns if "depth" in c.lower()), None)
        self.lineart_cn = next((c for c in cns if "lineart" in c.lower() or
                                "mistoline" in c.lower()), None)
        self.tile_cn = next((c for c in cns if "tile" in c.lower()), None)
        self.caps["openpose_preproc"] = "OpenposePreprocessor" in classes
        self.caps["canny"] = "Canny" in classes
        self.caps["controlnet_depth"] = bool(
            self.depth_cn and "DepthAnythingV2Preprocessor" in classes)
        self.caps["controlnet_lineart"] = bool(
            self.lineart_cn and "AnimeLineArtPreprocessor" in classes)
        self.caps["controlnet_tile"] = bool(
            self.tile_cn and "TilePreprocessor" in classes)
        self.caps["controlnet"] = bool(cn_nodes and (
            (self.openpose_cn and self.caps["openpose_preproc"]) or
            (self.canny_cn and self.caps["canny"]) or self.openpose_cn or
            self.caps["controlnet_depth"] or self.caps["controlnet_lineart"] or
            self.caps["controlnet_tile"]))

        bg_nodes = {"LoadBackgroundRemovalModel", "RemoveBackground",
                    "JoinImageWithAlpha"} <= classes
        bg_models = []
        if bg_nodes:
            try:
                spec = self.client.get_node_spec("LoadBackgroundRemovalModel")
                bg_models = self.client._combo_options(
                    spec["input"]["required"]["bg_removal_name"])
            except Exception:
                bg_models = []
        self.bg_removal_model = bg_models[0] if bg_models else None
        self.caps["bg_removal"] = bool(bg_nodes and self.bg_removal_model)

        # v6.0: quality-booster model-patch nodes (ship in vanilla ComfyUI
        # core - should be present on any stock install, but always probe)
        self.caps["freeu"] = bool({"FreeU", "FreeUV2"} & classes)
        self.caps["pag"] = "PerturbedAttentionGuidance" in classes
        self.caps["sag"] = "SelfAttentionGuidance" in classes

        # v6.0: Impact Pack face/hand detailer
        detailer_nodes = {"UltralyticsDetectorProvider", "SAMLoader",
                          "FaceDetailer"} <= classes
        bbox_models = self.client.get_ultralytics_models() if detailer_nodes else []
        sam_models = self.client.get_sam_models() if detailer_nodes else []
        self.bbox_face_model = next(
            (m for m in bbox_models if "face" in m.lower()), None)
        self.bbox_hand_model = next(
            (m for m in bbox_models if "hand" in m.lower()), None)
        self.sam_model_name = sam_models[0] if sam_models else None
        self.caps["detailer"] = bool(
            detailer_nodes and self.bbox_face_model and self.sam_model_name)
        # v6.0 Stage 5: wire the anatomy detector into the quality
        # calculator only after capability detection has resolved it -
        # quality_calculator is constructed before this method ever runs,
        # same init-order fix as SmartDirector.taste in v5.0.
        self.quality_calculator.client = self.client if self.caps["detailer"] else None
        self.quality_calculator.bbox_model = (
            self.bbox_face_model if self.caps["detailer"] else None)

        # v6.0: Ultimate SD Upscale (tiled, real per-tile diffusion).
        # Require an actual upscale model file too, matching every other
        # capability's node-class-AND-model-file check (found inconsistent
        # in a full-system audit - node-only would report "ready" even
        # with zero upscale models installed, producing a confusing
        # runtime error instead of a clean "not available" state).
        self.caps["tiled_upscale"] = bool(
            "UltimateSDUpscale" in classes and self.upscale_models)

        self.log("Face lock ready (IP-Adapter)" if self.caps["ipadapter"] else
                 "Face Ref unavailable (IP-Adapter nodes/models not loaded - "
                 "restart Comfy Desktop if just installed)")
        if self.caps["controlnet"]:
            modes = []
            if self.openpose_cn and self.caps["openpose_preproc"]:
                modes.append("openpose")
            if self.canny_cn and self.caps["canny"]:
                modes.append("canny")
            if self.caps["controlnet_depth"]:
                modes.append("depth")
            if self.caps["controlnet_lineart"]:
                modes.append("lineart")
            if self.caps["controlnet_tile"]:
                modes.append("tile")
            if self.openpose_cn:
                modes.append("direct skeleton")
            self.log(f"Pose control ready ({'/'.join(modes)})")
        else:
            self.log("Pose Ref unavailable (ControlNet nodes/models missing)")
        self.log("Cut Out ready (background removal)" if self.caps["bg_removal"]
                 else "Cut Out unavailable (no background-removal model - "
                      "add one to models/background_removal)")
        boosters = [n for n, k in (("FreeU", "freeu"), ("PAG", "pag"),
                                   ("SAG", "sag")) if self.caps[k]]
        if boosters:
            self.log(f"Quality boosters ready ({'/'.join(boosters)})")
        missing = [n for n, k in (("FreeU", "freeu"), ("PAG", "pag"),
                                  ("SAG", "sag")) if not self.caps[k]]
        if missing:
            self.log(f"Quality boosters unavailable ({'/'.join(missing)} - "
                     "nodes not found on this ComfyUI server)")
        if self.caps["detailer"]:
            targets = ["face"] + (["hand"] if self.bbox_hand_model else [])
            self.log(f"Auto-Fix ready ({'/'.join(targets)} detailer, "
                     f"{self.sam_model_name})")
        else:
            self.log("Auto-Fix unavailable (Impact Pack not detected)")
        self.log("Tiled upscale ready (Ultimate SD Upscale)"
                 if self.caps["tiled_upscale"] else
                 "Tiled upscale unavailable (Ultimate SD Upscale not "
                 "installed - falling back to single-pass 4K)")
        if getattr(self, "enable_upscale_btn", None):
            if self.upscale_models:
                self.enable_upscale_btn.pack_forget()
            else:
                self.enable_upscale_btn.pack(side="left", padx=(8, 2))

        def _enable(widgets, on):
            for w in widgets:
                if not on:
                    w.configure(state="disabled")
                elif isinstance(w, ttk.Combobox):
                    w.configure(state="readonly")
                else:
                    w.configure(state="normal")

        def _toggle():
            _enable(getattr(self, "_face_ref_widgets", []),
                    self.caps["ipadapter"])
            if getattr(self, "_face_lock_cb", None):
                self._face_lock_cb.configure(
                    state="normal" if self.caps["ipadapter"] else "disabled")
            _enable(getattr(self, "_pose_ref_widgets", []),
                    self.caps["controlnet"])
            # v6.0: widen the mode list to whichever structural-control
            # types actually have both model+preprocessor present
            modes = ["direct"]
            if self.openpose_cn and self.caps["openpose_preproc"]:
                modes.insert(0, "openpose")
            if self.canny_cn and self.caps["canny"]:
                modes.insert(-1 if "openpose" in modes else 0, "canny")
            if self.caps["controlnet_depth"]:
                modes.insert(-1, "depth")
            if self.caps["controlnet_lineart"]:
                modes.insert(-1, "lineart")
            if self.caps["controlnet_tile"]:
                modes.insert(-1, "tile")
            if getattr(self, "pose_mode_combo", None):
                self.pose_mode_combo.configure(values=modes)
            # default pose mode to the best available preprocessor
            if self.caps["controlnet"]:
                if self.openpose_cn and self.caps["openpose_preproc"]:
                    self.pose_mode_var.set("openpose")
                elif self.canny_cn and self.caps["canny"]:
                    self.pose_mode_var.set("canny")
                else:
                    self.pose_mode_var.set("direct")
            if hasattr(self, "cutout_btn"):
                self.cutout_btn.configure(
                    state="normal" if self.caps["bg_removal"] else "disabled")
            _enable(getattr(self, "_freeu_widgets", []), self.caps["freeu"])
            _enable(getattr(self, "_pag_widgets", []), self.caps["pag"])
            _enable(getattr(self, "_sag_widgets", []), self.caps["sag"])
            if hasattr(self, "detailer_btn"):
                self.detailer_btn.configure(
                    state="normal" if self.caps["detailer"] else "disabled")
            if hasattr(self, "tiled_upscale_btn"):
                self.tiled_upscale_btn.configure(
                    state="normal" if self.caps["tiled_upscale"]
                    else "disabled")
        self.root.after(0, _toggle)

    # ── Generation ──────────────────────────────────────────────────────────
    def _estimate_generation_time(self, steps, sampler, resolution):
        """Estimate generation time in seconds based on settings."""
        base_times = {
            "euler": 0.15, "heun": 0.25, "dpm": 0.20,
            "dpmpp": 0.22, "ipndm": 0.20, "pndm": 0.18
        }
        base = base_times.get(sampler.lower().split()[0][:3], 0.20)
        res_factor = resolution / (512 * 512)
        return steps * base * res_factor + 5

    def _get_gpu_vram_usage(self) -> tuple:
        """Get current GPU VRAM usage and total VRAM. Returns (used_gb, total_gb)."""
        try:
            flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000)
            result = subprocess.run(
                ["nvidia-smi", "--query-gpu=memory.used,memory.total", "--format=csv,noheader,nounits"],
                capture_output=True, text=True, timeout=2, creationflags=flags
            )
            if result.returncode == 0:
                used_mb, total_mb = map(int, result.stdout.strip().split(','))
                return (used_mb / 1024, total_mb / 1024)
        except Exception:
            pass
        return (0, 0)

    def _update_progress(self, start_time, steps, sampler, resolution, ticks):
        """Update progress bar and labels during generation."""
        estimated_total = self._estimate_generation_time(steps, sampler, resolution)
        elapsed = time.time() - start_time
        progress = min(95, (elapsed / estimated_total) * 100)
        eta_secs = max(0, estimated_total - elapsed)
        eta_text = f"{int(eta_secs // 60)}m {int(eta_secs % 60)}s" if eta_secs > 0 else "Done"

        # Terminal visual progress bar
        bar_len = 40
        filled_len = int(bar_len * (progress / 100))
        bar = '█' * filled_len + '-' * (bar_len - filled_len)
        print(f"\r🚀 Generation Progress: [{bar}] {progress:.1f}% | ETA: {eta_text}", end="", flush=True)

        def _update_ui():
            self.progress_var.set(progress)
            elapsed_text = f"{int(elapsed // 60)}m {int(elapsed % 60)}s"
            self.progress_lbl.config(text=f"{progress:.0f}%  |  Elapsed: {elapsed_text}  |  ETA: {eta_text}")

            # Update VRAM display
            used_gb, total_gb = self._get_gpu_vram_usage()
            if total_gb > 0:
                vram_pct = (used_gb / total_gb) * 100
                self.vram_lbl.config(text=f"VRAM: {used_gb:.1f}GB / {total_gb:.1f}GB ({vram_pct:.0f}%)")

        self.root.after(0, _update_ui)

    def _resolve_gen_plan(self) -> dict:
        """Resolve persona/Smart Director/auto-LoRA/wildcards into a plan
        dict, reflecting choices into the UI exactly as the plain generate
        path always did. Shared by the plain path and the v5.0 best-of-N /
        auto-pilot workers so taste-learning and Director v2 logic only
        live in one place."""
        persona = self.selected_persona()
        positive = self.pos_text.get("1.0", "end").strip()
        negative = self.neg_text.get("1.0", "end").strip()
        mode = self.mode_var.get()
        style = self.style_var.get()
        width = int(self.width_var.get())
        height = int(self.height_var.get())
        steps = int(self.steps_var.get())
        ckpt = self.ckpt_var.get()
        sampler = self.sampler_var.get()
        sched = self.sched_var.get()
        reason, brain = None, None
        if self.smart_var.get() and persona:
            self.log("Smart Director analyzing persona...")
            choice = self.director.direct(persona)
            mode, style = choice["mode"], choice["style"]
            width, height = choice["width"], choice["height"]
            if choice.get("model"):
                ckpt = choice["model"]
            sampler, sched = auto_sampler(style)
            partner = self.fusion_partner()
            if partner and mode not in ("Fusion", "Duo"):
                # user picked two personas - honor the pairing
                mode = "Duo"
            positive = self.prompts.build(mode, persona, style, other=partner)
            if partner:
                self.log(f"  partner: {partner.get('name')}")
            if choice["extra_tags"]:
                positive += ", " + choice["extra_tags"]
            self.log(f"Director[{choice['brain']}]: {mode} | "
                     f"{style.split(',')[0]} | {width}x{height}")
            self.log(f"  model: {ckpt} | sampler: {sampler}/{sched}")
            if choice["reason"]:
                self.log(f"  reason: {choice['reason']}")
            reason, brain = choice["reason"], choice["brain"]
            pos_final, ckpt_final = positive, ckpt
            samp_final, sched_final = sampler, sched

            def _reflect():
                self.mode_var.set(mode)
                self.style_var.set(style)
                self.width_var.set(width)
                self.height_var.set(height)
                self.ckpt_var.set(ckpt_final)
                self.sampler_var.set(samp_final)
                self.sched_var.set(sched_final)
                self.pos_text.delete("1.0", "end")
                self.pos_text.insert("1.0", pos_final)
            self.root.after(0, _reflect)

        # v4.0 auto-generate: with Smart Director on and no manual
        # LoRA chosen, auto-match the best real LoRA to the style the
        # director just picked (and reflect it in the UI)
        lora_choice = self._current_lora()
        if lora_choice and self._is_sd15(ckpt):
            # v6.7: this is the shared plan resolver behind the plain
            # GENERATE button (this app's single most-used path) - a
            # manually-selected SD1.5 checkpoint (Smart Director off, so
            # nothing here overrides it) combined with this app's all-
            # SDXL LoRA registry is the same invalid combination
            # _img2img_worker already guards against; _reference_kwargs
            # below already skips Face/Pose Ref for SD1.5 the same way.
            self.log("LoRA needs an SDXL checkpoint - skipped "
                     "(current is SD1.5)")
            lora_choice = None
        if self.smart_var.get() and not lora_choice:
            available = [v for v in self.lora_box["values"]
                         if v != "(none)"]
            match = pick_lora_for_style(style, available)
            if match:
                lora_choice = [match]
                self.log(f"  auto-LoRA: {match[0]} @ {match[1]}")
                self.root.after(0, lambda m=match: (
                    self.lora_var.set(m[0]),
                    self.lora_str_var.set(m[1])))

        # v5.0 Director v2: auto hi-res fix when VRAM headroom allows and
        # the user hasn't already turned it on manually
        hires_kwargs = self._hires_kwargs()
        if self.smart_var.get() and not hires_kwargs and \
                not getattr(self, "_hires_oom", False):
            used, total = self._get_gpu_vram_usage()
            if total > 0 and (total - used) >= 1.5 and \
                    width * height <= 832 * 1216 and steps <= 32:
                scale = 1.4 if total <= 8.5 else 1.5
                hires_kwargs = {"hires_fix": True, "hires_scale": scale,
                                "hires_denoise": 0.4}
                self.log(f"Director: hires-fix auto-enabled (scale {scale})")
                self.root.after(0, lambda: (
                    self.hires_var.set(True),
                    self.hires_scale_var.set(scale)))

        # v5.0 Director v2: session face-lock - clear a ref this feature
        # auto-set once the persona changes (never touches a ref the user
        # browsed for manually)
        persona_name = persona.get("name") if persona else None
        if self.face_lock_var.get() and self._face_auto["auto_set"] and \
                self._face_auto["persona"] != persona_name:
            self.clear_face_ref()
            self._face_auto = {"persona": None, "auto_set": False}

        upscale = self._current_upscale_model()

        # ── Artist Masterpiece Polish Injector ──
        if getattr(self, "masterpiece_polish_var", None) and self.masterpiece_polish_var.get():
            if "masterpiece" not in positive.lower():
                positive += ", masterpiece, top quality, ultra detailed 8k, professional digital art, volumetric lighting, Octane render depth"

        # ── Optics & Framing Modifier ──
        if getattr(self, "lens_framing_var", None):
            lens_choice = self.lens_framing_var.get()
            if lens_choice and lens_choice != "(None - Standard Camera)":
                optics_tag = lens_choice.split("(")[0].strip()
                positive += f", {optics_tag}, professional camera optics"

        # ── Dual-Style Blender ──
        if getattr(self, "secondary_style_var", None):
            sec_style = self.secondary_style_var.get()
            if sec_style and sec_style not in ("(none)", ""):
                positive += f", blended with {sec_style} aesthetic"

        positive = self.wildcards.expand(positive)
        negative = self.wildcards.expand(negative)

        # v6.7: this is the shared resolver behind the plain GENERATE
        # button, best-of-N (_gen_candidate), and Auto-Pilot's normal
        # branch - none of them clamped width/height/batch for this 6GB
        # card before now. Smart Director's own picks already stay within
        # the safe cap, but with Smart Director off the width/height
        # Comboboxes are manually editable and both offer 1216 - picking
        # 1216x1216 (1.48MP, ~46% over the 832x1216 safe cap) or a batch
        # >1 at any large size would previously go straight to ComfyUI
        # unclamped, risking a CUDA OOM mid-generation.
        width, height, batch = self._vram_preflight(
            width, height, int(self.batch_var.get()))

        return {
            "persona": persona, "positive": positive, "negative": negative,
            "mode": mode, "style": style, "width": width, "height": height,
            "steps": steps, "cfg": float(self.cfg_var.get()),
            "ckpt": ckpt, "sampler": sampler, "sched": sched,
            "lora": lora_choice,
            "lora_strength": float(self.lora_str_var.get()),
            "upscale": upscale, "hires_kwargs": hires_kwargs,
            "quality_kwargs": self._quality_kwargs(),
            "ref_kwargs": self._reference_kwargs(ckpt),
            "reason": reason, "brain": brain, "batch": batch,
        }

    def _apply_face_lock(self, persona, saved_path):
        """v5.0: after a successful save, auto-set the session face
        reference if the lock is on and nothing is set yet."""
        if not (self.face_lock_var.get() and self.caps.get("ipadapter")):
            return
        if self.face_ref_path is not None:
            return
        persona_name = persona.get("name") if persona else None
        self.root.after(0, lambda p=saved_path: self.set_face_ref(p))
        self._face_auto = {"persona": persona_name, "auto_set": True}

    def _generate_worker(self):
        self.busy = True
        self.root.after(0, lambda: self.gen_btn.configure(text="GENERATING..."))
        self.root.after(0, lambda: self.progress_lbl.config(text="Queuing..."))
        self.root.after(0, lambda: self.progress_bar.configure(maximum=100))
        self.root.after(0, lambda: self.progress_var.set(0))
        self.save_to_history()  # Save to generation history

        # ── PHASE 2: Track generation performance ──
        gen_start_time = time.time()

        try:
            seed = random.randint(0, 2**48)
            plan = self._resolve_gen_plan()
            persona = plan["persona"]
            positive, negative = plan["positive"], plan["negative"]
            mode, style = plan["mode"], plan["style"]
            width, height, steps = plan["width"], plan["height"], plan["steps"]
            ckpt, sampler, sched = plan["ckpt"], plan["sampler"], plan["sched"]
            upscale = plan["upscale"]
            resolution = width * height

            workflow = self.client.build_txt2img_workflow(
                ckpt=ckpt, positive=positive, negative=negative,
                width=width, height=height,
                batch_size=plan["batch"], steps=steps,
                cfg=plan["cfg"], sampler=sampler,
                scheduler=sched, seed=seed, upscale_model=upscale,
                lora=plan["lora"],
                lora_strength=plan["lora_strength"],
                **plan["ref_kwargs"],
                **plan["hires_kwargs"],
                **plan["quality_kwargs"],
            )
            if upscale:
                self.log(f"4K mode: upscaling with {upscale}")
            self.quotes.release_vram()  # free LLM VRAM before diffusion
            self.log(f"Queueing job (seed {seed})...")

            tick_count = [0]
            def progress_tick():
                tick_count[0] += 1
                self._update_progress(gen_start_time, steps, sampler, resolution, tick_count[0])

            # v6.7: this was the plain-GENERATE-button path (the single
            # most-used path in the app) calling queue_prompt/
            # wait_for_result directly - if ComfyUI died mid-job, the
            # exception went straight to the outer handler with no
            # self-heal retry, unlike every other worker in the file.
            prompt_id_box = [None]
            def _on_q(pid):
                prompt_id_box[0] = pid
                self.log(f"Queued: {pid[:8]}... waiting")

            entry = self._queue_and_wait(
                workflow, on_tick=progress_tick,
                on_queued=_on_q)
            prompt_id = prompt_id_box[0] or "unknown"

            saved = 0
            first_path = None
            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            for node_output in entry.get("outputs", {}).values():
                for img in node_output.get("images", []):
                    data = self.client.download_image(
                        img["filename"], img.get("subfolder", ""), img.get("type", "output"))
                    out_name = f"{stamp}_{saved}_{img['filename']}"
                    out_path = self.output_dir / out_name
                    out_path.write_bytes(data)
                    if self.brand.cfg.get("brand_generations") and \
                            self.brand.active():
                        try:
                            from PIL import Image as _PILImage
                            self.brand.apply(
                                _PILImage.open(out_path)).save(out_path)
                        except Exception:
                            pass
                    if first_path is None:
                        first_path = out_path
                    saved += 1
                    self.log(f"Saved: {out_name}")

                    # ── PHASE 3: Create per-image metadata ──
                    try:
                        persona_name = persona.get("name", "unknown") if persona else "unknown"
                        loras_used = self.lora_var.get().split(",") if self.lora_var.get() else []

                        # Create quality score
                        quality_score = self.quality_calculator.calculate_overall_quality_score(
                            self.quality_calculator.calculate_image_quality(out_path)
                        )
                        # v5.0: feed the taste model from ordinary
                        # single generations, not just Factory/packs
                        if persona:
                            self.taste.record(persona_name, style,
                                              quality_score)

                        # Create and save metadata
                        metadata = self.meta_manager.create_image_metadata(
                            out_path, persona_name, ckpt, sampler,
                            steps, float(self.cfg_var.get()), loras_used, quality_score
                        )
                        self.meta_manager.save_image_metadata(out_path, metadata)

                        # Update discovery index with recent image
                        self.ugc_manager.add_to_recent({
                            "content_id": metadata["content_id"],
                            "persona": persona_name,
                            "style": style if 'style' in locals() else "unknown",
                            "quality_score": quality_score
                        })
                    except Exception as e:
                        self.log(f"Note: Metadata creation skipped ({type(e).__name__})")

            if first_path:
                self.show_preview(first_path)
                self._apply_face_lock(persona, first_path)

            # v9.11: Maximum Mode - chain tiled upscale + face detailer
            # after the base pass. Runs after the base save/preview above
            # so a Maximum Mode failure never loses the base result -
            # first_path is only reassigned on success.
            if first_path and self.maximum_chain_var.get():
                finished = self._run_maximum_mode_finishing(
                    first_path, positive, negative, ckpt,
                    set_status=lambda t: self.root.after(
                        0, lambda: self.progress_lbl.config(text=t)))
                if finished != first_path:
                    first_path = finished
                    self.show_preview(first_path)

            # auto-caption in smart mode
            if self.smart_var.get() and persona and saved:
                quote, src = self.quotes.generate(persona)
                caption = f'"{quote}"\n\n- {persona.get("name", "")}'
                (self.output_dir / f"{stamp}_caption.txt").write_text(
                    caption, encoding="utf-8")
                self.log(f"Caption saved ({src})")

                def _showq():
                    self.quote_text.delete("1.0", "end")
                    self.quote_text.insert("1.0", caption)
                self.root.after(0, _showq)

            meta = {
                "timestamp": datetime.now().isoformat(),
                "persona": persona.get("name", "manual prompt"),
                "mode": self.mode_var.get(),
                "positive": positive, "negative": negative,
                "model": ckpt, "seed": seed,
                "steps": int(self.steps_var.get()), "cfg": float(self.cfg_var.get()),
                "size": f"{self.width_var.get()}x{self.height_var.get()}",
                "images_saved": saved, "prompt_id": prompt_id,
                "face_ref": (self.face_ref_path.name
                             if self.face_ref_path else None),
                "face_weight": float(self.face_weight_var.get()),
                "pose_ref": (self.pose_ref_path.name
                             if self.pose_ref_path else None),
                "pose_strength": float(self.pose_strength_var.get()),
                "pose_mode": self.pose_mode_var.get(),
                "lora_stack": self._current_lora(),
                "hires_fix": self._hires_kwargs() or None,
            }
            (self.output_dir / f"{stamp}_meta.json").write_text(
                json.dumps(meta, indent=2), encoding="utf-8")

            # v4.6: index this generation for semantic search (background,
            # only when the embedding model is known to be reachable)
            if first_path and self.embeddings.available is not False:
                emb_text = (f"{persona.get('name', '')} | {mode} | "
                            f"{positive[:300]}")
                threading.Thread(
                    target=lambda: self._safe_embed_add(first_path, emb_text),
                    daemon=True).start()

            # ── PHASE 2: Calculate and log generation time ──
            gen_elapsed = time.time() - gen_start_time
            self.log_analytics("single", persona.get("name", "manual"),
                               mode, "Success", saved, generation_time_sec=gen_elapsed)
            if persona:
                self.last_gen = {"persona": persona, "seed": seed,
                                 "mode": mode, "width": width,
                                 "height": height, "ckpt": ckpt,
                                 "style": style}
                self.root.after(0, lambda: self.remix_btn.configure(
                    state="normal"))
            self.log(f"Done - {saved} image(s) saved")
            gen_elapsed = time.time() - gen_start_time
            def _complete_progress():
                self.progress_var.set(100)
                self.progress_lbl.config(text=f"Complete in {int(gen_elapsed // 60)}m {int(gen_elapsed % 60)}s")
                self.vram_lbl.config(text="")
            self.root.after(0, _complete_progress)
        except Exception as e:
            self.log(f"ERROR: {e}")
            self.root.after(0, lambda: messagebox.showerror("Generation failed", str(e)))
            def _reset_progress():
                self.progress_var.set(0)
                self.progress_lbl.config(text="Ready")
                self.vram_lbl.config(text="")
            self.root.after(0, _reset_progress)
        finally:
            self.busy = False
            self.root.after(0, lambda: self.gen_btn.configure(text="GENERATE"))

    # ── v3.2: img2img Remix ─────────────────────────────────────────────────
    def start_img2img_remix(self, src_path=None):
        """Regenerate an existing image with a denoise slider."""
        if self.busy:
            messagebox.showinfo("Busy", "A generation is already running.")
            return
        if not self.client.base_url:
            messagebox.showerror("Offline", "ComfyUI is not connected.\n"
                                 "Launch Comfy Desktop and click Reconnect.")
            return
        src_path = Path(src_path) if src_path else self.last_preview_path
        if not src_path or not src_path.exists():
            messagebox.showinfo("No image",
                                "Generate or preview an image first.")
            return
        ckpt = self.ckpt_var.get()
        if not ckpt or ckpt.startswith("("):
            messagebox.showerror("No model", "No checkpoint selected.")
            return

        win = tk.Toplevel(self.root)
        win.title("Remix Image")
        self._clamp_window(win, 400, 480)
        win.configure(bg=self.PANEL)
        try:
            img = tk.PhotoImage(file=str(src_path))
            factor = max(1, -(-img.width() // 340), -(-img.height() // 280))
            if factor > 1:
                img = img.subsample(factor, factor)
            thumb = tk.Label(win, image=img, bg=self.PANEL)
            thumb.image = img  # keep reference
            thumb.pack(pady=8)
        except Exception:
            tk.Label(win, text=src_path.name, bg=self.PANEL,
                     fg=self.FG).pack(pady=8)
        tk.Label(win, text="Denoise - low = faithful, high = wild",
                 bg=self.PANEL, fg=self.FG_DIM,
                 font=self.font_body).pack()
        denoise_var = tk.DoubleVar(value=0.55)
        tk.Scale(win, variable=denoise_var, from_=0.30, to=0.80,
                 resolution=0.05, orient="horizontal", length=300,
                 bg=self.PANEL, fg=self.FG, highlightthickness=0,
                 troughcolor=self.INPUT_BG).pack(pady=4)

        def _go():
            win.destroy()
            self.stop_flag = False  # v7.1: see start_generation's note
            threading.Thread(target=self._img2img_worker,
                             args=(src_path, float(denoise_var.get())),
                             daemon=True).start()
        ttk.Button(win, text="REMIX", command=_go).pack(pady=10)

    def _img2img_worker(self, src_path, denoise):
        self.busy = True
        gen_start = time.time()
        self.root.after(0, lambda: self.gen_btn.configure(text="REMIXING..."))
        self.root.after(0, lambda: self.progress_var.set(0))
        self.root.after(0, lambda: self.progress_lbl.config(text="Uploading..."))
        try:
            image_name = self._upload_ref(src_path)
            positive = self.wildcards.expand(
                self.pos_text.get("1.0", "end").strip())
            negative = self.wildcards.expand(
                self.neg_text.get("1.0", "end").strip())
            ckpt = self.ckpt_var.get()
            seed = random.randint(0, 2**48)
            steps = int(self.steps_var.get())
            lora = self._current_lora()
            if lora and self._is_sd15(ckpt):
                # This app's LoRA registry is all SDXL-derivative - wiring
                # one onto an SD1.5 checkpoint is a shape mismatch that
                # ComfyUI's own validation correctly rejects (HTTP 400),
                # not a clean error. Degrade gracefully instead, matching
                # _reference_kwargs' established pattern for the same
                # SD1.5-incompatibility class of problem.
                self.log("Remix: LoRA needs an SDXL checkpoint - skipped "
                         "(current is SD1.5)")
                lora = None
            wf = self.client.build_img2img_workflow(
                ckpt=ckpt, positive=positive, negative=negative,
                image_name=image_name, denoise=denoise, steps=steps,
                cfg=float(self.cfg_var.get()),
                sampler=self.sampler_var.get(),
                scheduler=self.sched_var.get(), seed=seed,
                lora=lora, lora_strength=float(self.lora_str_var.get()))
            self.quotes.release_vram()  # free LLM VRAM before diffusion
            self.log(f"Remix of {src_path.name} @ denoise {denoise:.2f} "
                     f"(seed {seed})")
            pid = self.client.queue_prompt(wf)

            tick = [0]
            def _tick():
                tick[0] += 1
                self._update_progress(gen_start, steps,
                                      self.sampler_var.get(),
                                      1024 * 1024, tick[0])
            entry = self.client.wait_for_result(pid, on_tick=_tick)

            stamp = f"3klipz_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            saved = 0
            first = None
            for node_output in entry.get("outputs", {}).values():
                for img in node_output.get("images", []):
                    data = self.client.download_image(
                        img["filename"], img.get("subfolder", ""),
                        img.get("type", "output"))
                    out = self.output_dir / f"{stamp}_remix_{saved}.png"
                    out.write_bytes(data)
                    if first is None:
                        first = out
                    saved += 1
            if first:
                self.show_preview(first)
            meta = {"timestamp": datetime.now().isoformat(),
                    "source_image": str(src_path), "denoise": denoise,
                    "model": ckpt, "seed": seed, "positive": positive,
                    "images_saved": saved}
            (self.output_dir / f"{stamp}_remix_meta.json").write_text(
                json.dumps(meta, indent=2), encoding="utf-8")
            self.log_analytics("remix_img", src_path.stem, "img2img",
                               "Success", saved,
                               generation_time_sec=time.time() - gen_start)
            self.log(f"Remix done - {saved} image(s)")
            self.root.after(0, lambda: (
                self.progress_var.set(100),
                self.progress_lbl.config(text="Remix complete")))
        except Exception as e:
            # v10.1: Remix talks to ComfyUI directly (bypasses
            # _queue_and_wait), so it never fed the self-healing bad-
            # checkpoint blocklist before - a junk checkpoint file could
            # fail every single Remix attempt forever with no self-heal.
            _detect_and_mark_bad_checkpoint(str(e), log=self.log)
            self.log(f"Remix ERROR: {e}")
            self.root.after(0, lambda: messagebox.showerror(
                "Remix failed", str(e)))
            self.root.after(0, lambda: (
                self.progress_var.set(0),
                self.progress_lbl.config(text="Ready")))
        finally:
            self.busy = False
            self.root.after(0, lambda: self.gen_btn.configure(text="GENERATE"))

    # ── v5.3: Color Grade (cinematic LUTs, local PIL - no ComfyUI) ──────────
