        tk.Label(win, text="Targets", bg=self.PANEL, fg=self.ACCENT,
                 font=self.font_body_bold).pack(anchor="w", padx=16)
        face_var = tk.BooleanVar(value=True)
        tk.Checkbutton(win, text="Face", variable=face_var, bg=self.PANEL,
                       fg=self.FG, selectcolor=self.INPUT_BG,
                       activebackground=self.PANEL).pack(anchor="w", padx=16)
        hand_var = tk.BooleanVar(value=bool(self.bbox_hand_model))
        hand_cb = tk.Checkbutton(win, text="Hands", variable=hand_var,
                                 bg=self.PANEL, fg=self.FG,
                                 selectcolor=self.INPUT_BG,
                                 activebackground=self.PANEL)
        hand_cb.pack(anchor="w", padx=16)
